  var contactsAll = [];

  function contactMatches(c, q) {
    if (!q) return true;
    var hay = [c.name, c.email, c.telegram_username ? "@" + c.telegram_username : "", (c.aliases || []).join(" ")]
      .join(" ")
      .toLowerCase();
    return hay.indexOf(q) >= 0;
  }

  function paintContactsList() {
    var list = document.getElementById("contacts-list");
    var empty = document.getElementById("contacts-empty");
    var nothing = document.getElementById("contacts-nothing");
    var search = document.getElementById("contacts-search");
    var hint = document.getElementById("contacts-hint");
    if (!list) return;
    list.innerHTML = "";
    var q = String((search && search.value) || "").trim().toLowerCase();
    setHidden(empty, !!contactsAll.length);
    if (hint) setHidden(hint, !contactsAll.length);
    var items = contactsAll.filter(function (c) {
      return contactMatches(c, q);
    });
    setHidden(nothing, !contactsAll.length || !!items.length);
    // Группы по первой букве имени, как в адресной книге.
    var groups = [];
    var byLetter = {};
    items.forEach(function (c) {
      var name = String(c.name || c.email || c.telegram_username || "#").trim();
      var letter = name.charAt(0).toUpperCase();
      if (!/[A-ZА-ЯЁ]/.test(letter)) letter = "#";
      if (!byLetter[letter]) {
        byLetter[letter] = [];
        groups.push(letter);
      }
      byLetter[letter].push(c);
    });
    groups.forEach(function (letter) {
      var wrap = document.createElement("div");
      wrap.className = "pf-group";
      var h = document.createElement("p");
      h.className = "pf-letter";
      h.textContent = letter;
      var box = document.createElement("div");
      box.className = "pf-list";
      byLetter[letter].forEach(function (c) {
        box.appendChild(renderContactCard(c));
      });
      wrap.appendChild(h);
      wrap.appendChild(box);
      list.appendChild(wrap);
    });
  }

  async function loadContacts() {
    var list = document.getElementById("contacts-list");
    var err = document.getElementById("contacts-err");
    var teamsCount = document.getElementById("contacts-teams-count");
    if (!list) return;
    setHidden(err, true);
    if (!contactsAll.length) {
      list.innerHTML =
        '<div class="pf-list pf-skel-list">' + '<div class="pf-row"><span class="pf-row-body"></span></div>'.repeat(4) + "</div>";
    }
    apiFetch("/teams", { method: "GET" })
      .then(function (d) {
        if (teamsCount) teamsCount.textContent = String(((d && d.teams) || []).length || "Нет");
      })
      .catch(function () {
        if (teamsCount) teamsCount.textContent = "";
      });
    try {
      var data = await apiFetch("/contacts", { method: "GET" });
      contactsAll = (data.items || []).slice().sort(function (a, b) {
        return String(a.name || a.email || "").localeCompare(String(b.name || b.email || ""), "ru");
      });
      paintContactsList();
    } catch (e) {
      list.innerHTML = "";
      if (err) {
        err.textContent = humanProfileError(e.message || String(e));
        setHidden(err, false);
      }
    }
  }

  async function contactsSave() {
    var name = (document.getElementById("contacts-f-name").value || "").trim();
    var email = (document.getElementById("contacts-f-email").value || "").trim();
    var tg = (document.getElementById("contacts-f-tg").value || "").trim().replace(/^@/, "");
    var aliases = contactsParseAliases(
      document.getElementById("contacts-f-aliases").value || ""
    );
    if (!name || (!email && !tg)) {
      contactsShowFormMsg("", "Укажите имя и email или ник в Telegram");
      return;
    }
    contactsShowFormMsg("", "");
    var teamIds = selectedContactFormTeamIds();
    try {
      var savedEmail = email ? email.toLowerCase() : "tg:" + tg.toLowerCase();
      if (contactsEditingEmail) {
        var updated = await apiFetch(
          "/contacts/" + encodeURIComponent(contactsEditingEmail),
          {
            method: "PUT",
            body: JSON.stringify({
              name: name,
              email: email,
              telegram_username: tg || "",
              aliases: aliases,
              clear_telegram: !tg,
            }),
          }
        );
        if (updated && updated.item && (updated.item.key || updated.item.email)) {
          savedEmail = String(updated.item.key || updated.item.email).toLowerCase();
        }
      } else {
        var created = await apiFetch("/contacts", {
          method: "POST",
          body: JSON.stringify({
            name: name,
            email: email,
            telegram_username: tg || null,
            aliases: aliases.length ? aliases : null,
          }),
        });
        if (created && created.item && (created.item.key || created.item.email)) {
          savedEmail = String(created.item.key || created.item.email).toLowerCase();
        }
      }
      await setContactTeamsForEmail(savedEmail, teamIds);
      closeContactsFormModal();
      await loadContacts();
      await refreshProfileContactsCount();
      var tgApp = window.Telegram && window.Telegram.WebApp;
      if (tgApp && tgApp.HapticFeedback) tgApp.HapticFeedback.notificationOccurred("success");
    } catch (e) {
      contactsShowFormMsg("", e.message || String(e));
    }
  }

