  var HASHTAG_TOKEN_RE = /#([A-Za-zА-Яа-яЁё0-9_]{1,40})/g;

  function getUserTagsFromCache() {
    return (notesDataCache && notesDataCache.tags) || [];
  }

  var userTagsLoadPromise = null;

  function ensureUserTagsLoaded(force) {
    if (
      !force &&
      notesDataCache &&
      notesDataCache._tagsLoaded &&
      Array.isArray(notesDataCache.tags)
    ) {
      return Promise.resolve(notesDataCache.tags.slice());
    }
    if (
      !force &&
      notesDataCache &&
      Array.isArray(notesDataCache.tags) &&
      notesDataCache.tags.length
    ) {
      notesDataCache._tagsLoaded = true;
      return Promise.resolve(notesDataCache.tags.slice());
    }
    if (userTagsLoadPromise) return userTagsLoadPromise;
    userTagsLoadPromise = apiFetch("/tags", { method: "GET" })
      .then(function (data) {
        if (!notesDataCache) notesDataCache = {};
        notesDataCache.tags = (data && data.tags) || [];
        notesDataCache._tagsLoaded = true;
        return notesDataCache.tags.slice();
      })
      .catch(function () {
        return getUserTagsFromCache().slice();
      })
      .finally(function () {
        userTagsLoadPromise = null;
      });
    return userTagsLoadPromise;
  }

  function getUserHashtagsFromCache() {
    var fromBundle = (notesDataCache && notesDataCache.hashtags) || [];
    if (fromBundle.length) return fromBundle;
    var seen = {};
    var out = [];
    function collect(list) {
      (list || []).forEach(function (item) {
        noteHashtagsOf(item).forEach(function (h) {
          var key = String(h.name || "").toLowerCase();
          if (!key || seen[key]) return;
          seen[key] = true;
          out.push(h);
        });
      });
    }
    if (notesDataCache) {
      collect(notesDataCache.local_notes);
      collect(notesDataCache.transcriptions);
      collect(notesDataCache.summaries);
    }
    return out;
  }

  function noteTagsOf(item) {
    var project = noteProjectOf(item);
    if (project) return [project];
    return Array.isArray(item && item.tags) ? item.tags.slice(0, 1) : [];
  }

  function noteProjectOf(item) {
    if (item && item.project && item.project.id) return item.project;
    var tags = Array.isArray(item && item.tags) ? item.tags : [];
    return tags[0] || null;
  }

  function noteHashtagsOf(item) {
    return Array.isArray(item && item.hashtags) ? item.hashtags : [];
  }

  function parseNotesSearchQuery(raw) {
    var src = String(raw || "").trim();
    var hashtags = [];
    var seen = {};
    var text = src.replace(HASHTAG_TOKEN_RE, function (_, name) {
      var key = String(name || "").toLowerCase();
      if (key && !seen[key]) {
        seen[key] = true;
        hashtags.push(key);
      }
      return " ";
    });
    return { text: text.replace(/\s+/g, " ").trim().toLowerCase(), hashtags: hashtags };
  }

  // ---- Фильтр заметок: владелец / доступ / дата создания (хранится в браузере) ----
  var NOTES_FILTER_KEY = "leo_notes_filter";
  var NOTES_FILTER_DEFAULT = { owner: "all", access: "all", created: "all", from: "", to: "", sort: "updated" };
  var notesFilter = loadNotesFilter();

  function loadNotesFilter() {
    var f = Object.assign({}, NOTES_FILTER_DEFAULT);
    try {
      var raw = JSON.parse(localStorage.getItem(NOTES_FILTER_KEY) || "null");
      if (raw && typeof raw === "object") {
        Object.keys(NOTES_FILTER_DEFAULT).forEach(function (k) {
          if (typeof raw[k] === "string") f[k] = raw[k];
        });
      }
    } catch (e) {}
    return f;
  }

  function saveNotesFilter() {
    try {
      localStorage.setItem(NOTES_FILTER_KEY, JSON.stringify(notesFilter));
    } catch (e) {}
  }

  function notesFilterActiveCount(f) {
    f = f || notesFilter;
    var n = 0;
    if (f.owner !== "all") n++;
    if (f.access !== "all") n++;
    if (f.created !== "all" && (f.created !== "custom" || f.from || f.to)) n++;
    return n;
  }

  function noteIsPublic(item) {
    if (item && item.shared) return true;
    var members = (item && item.members) || [];
    return members.length > 1;
  }

  function localDayStart(d) {
    return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
  }

  function noteMatchesNotesFilter(item, f) {
    f = f || notesFilter;
    if (f.owner === "mine" && item.is_owner === false) return false;
    if (f.owner === "shared" && item.is_owner !== false) return false;
    if (f.access === "private" && noteIsPublic(item)) return false;
    if (f.access === "public" && !noteIsPublic(item)) return false;
    if (f.created !== "all") {
      var t = Date.parse(String(item.created_at || ""));
      if (!isFinite(t)) return false;
      var now = new Date();
      if (f.created === "today" && t < localDayStart(now)) return false;
      if (f.created === "7" && t < localDayStart(now) - 6 * 864e5) return false;
      if (f.created === "30" && t < localDayStart(now) - 29 * 864e5) return false;
      if (f.created === "custom") {
        if (f.from) {
          var from = Date.parse(f.from + "T00:00:00");
          if (isFinite(from) && t < from) return false;
        }
        if (f.to) {
          var to = Date.parse(f.to + "T00:00:00");
          if (isFinite(to) && t >= to + 864e5) return false;
        }
      }
    }
    return true;
  }

  function syncNotesFilterBtn() {
    var btn = document.getElementById("notes-filter-btn");
    var badge = document.getElementById("notes-filter-badge");
    var n = notesFilterActiveCount();
    if (btn) {
      btn.classList.toggle("is-active", n > 0);
      btn.setAttribute("aria-label", n ? "Фильтр заметок, активно: " + n : "Фильтр заметок");
    }
    if (badge) {
      badge.textContent = n ? String(n) : "";
      badge.classList.toggle("hidden", !n);
    }
  }

  // Черновик фильтра в шторке: применяется кнопкой «Показать».
  var notesFilterDraft = null;

  function notesFilterPreviewCount(f) {
    var data = notesDataCache || {};
    var transIds = {};
    ((data && data.transcriptions) || []).forEach(function (n) {
      var tid = localNoteIdFrom(n);
      if (tid != null) transIds[String(tid)] = true;
    });
    var saved = notesFilter;
    notesFilter = f;
    try {
      return ((data && data.local_notes) || []).filter(function (n) {
        var nid = localNoteIdFrom(n);
        if (nid != null && transIds[String(nid)]) return false;
        if (looksLikeTranscriptionNote(n)) return false;
        return noteItemMatchesFilter(n, "local");
      }).length;
    } finally {
      notesFilter = saved;
    }
  }

  function renderNotesFilterSheet() {
    var f = notesFilterDraft || notesFilter;
    document.querySelectorAll("#notes-filter-overlay .notes-filter-seg").forEach(function (seg) {
      var key = seg.getAttribute("data-key");
      seg.querySelectorAll("button[data-v]").forEach(function (b) {
        b.setAttribute("aria-pressed", String(b.getAttribute("data-v") === f[key]));
      });
    });
    var range = document.getElementById("notes-filter-range");
    if (range) range.classList.toggle("hidden", f.created !== "custom");
    var from = document.getElementById("notes-filter-from");
    var to = document.getElementById("notes-filter-to");
    if (from && from.value !== f.from) from.value = f.from;
    if (to && to.value !== f.to) to.value = f.to;
    var reset = document.getElementById("notes-filter-reset");
    if (reset) reset.disabled = !notesFilterActiveCount(f);
    var apply = document.getElementById("notes-filter-apply");
    if (apply) {
      var n = notesFilterPreviewCount(f);
      apply.textContent = n ? "Показать " + n + " " + pluralRu(n, "заметку", "заметки", "заметок") : "Ничего не найдено";
      apply.disabled = !n;
    }
  }

  function openNotesFilterSheet() {
    var ov = document.getElementById("notes-filter-overlay");
    if (!ov) return;
    notesFilterDraft = Object.assign({}, notesFilter);
    renderNotesFilterSheet();
    ov.classList.remove("hidden");
    ov.setAttribute("aria-hidden", "false");
    onModalSheetOpen();
    syncAppOverlay();
  }

  function closeNotesFilterSheet() {
    var ov = document.getElementById("notes-filter-overlay");
    if (!ov) return;
    notesFilterDraft = null;
    ov.classList.add("hidden");
    ov.setAttribute("aria-hidden", "true");
    onModalSheetClose();
    syncAppOverlay();
  }

  function applyNotesFilter(f) {
    notesFilter = Object.assign({}, NOTES_FILTER_DEFAULT, f);
    if (notesFilter.created !== "custom") {
      notesFilter.from = "";
      notesFilter.to = "";
    }
    saveNotesFilter();
    syncNotesFilterBtn();
    if (notesDataCache) renderNotesPanesFromData(notesDataCache);
  }

  // «Недавно удалённые»: заметки за 30 дней из снимков истории версий, «Вернуть» — новой заметкой.
  async function openNotesTrashSheet() {
    var ov = document.getElementById("notes-trash-overlay");
    var list = document.getElementById("notes-trash-list");
    if (!ov || !list) return;
    list.innerHTML = '<p class="notes-filter-hint">Загружаю…</p>';
    ov.classList.remove("hidden");
    ov.setAttribute("aria-hidden", "false");
    onModalSheetOpen();
    syncAppOverlay();
    try {
      var data = await apiFetch("/notes/trash", { method: "GET" });
      renderNotesTrash((data && data.items) || []);
    } catch (e) {
      list.innerHTML = "";
      var err = document.createElement("p");
      err.className = "notes-filter-hint";
      err.textContent = (e && e.message) || "Не удалось загрузить";
      list.appendChild(err);
    }
  }

  function closeNotesTrashSheet() {
    var ov = document.getElementById("notes-trash-overlay");
    if (!ov || ov.classList.contains("hidden")) return;
    ov.classList.add("hidden");
    ov.setAttribute("aria-hidden", "true");
    onModalSheetClose();
    syncAppOverlay();
  }

  function renderNotesTrash(items) {
    var list = document.getElementById("notes-trash-list");
    if (!list) return;
    list.innerHTML = "";
    if (!items.length) {
      var empty = document.createElement("p");
      empty.className = "nh-empty";
      empty.textContent = "За последние 30 дней ничего не удаляли.";
      list.appendChild(empty);
      return;
    }
    items.forEach(function (it) {
      var row = document.createElement("div");
      row.className = "notes-trash-row";
      var mid = document.createElement("div");
      mid.className = "notes-trash-mid";
      var t = document.createElement("div");
      t.className = "notes-trash-title";
      t.textContent = String(it.title || "(без названия)");
      var meta = document.createElement("div");
      meta.className = "notes-trash-meta";
      var d = new Date(String(it.saved_at || ""));
      meta.textContent =
        "удалена " + (isNaN(d.getTime()) ? "" : nhStamp(d)) +
        (it.sheets ? " · ещё " + it.sheets + " " + pluralRu(it.sheets, "лист", "листа", "листов") : "");
      var pv = document.createElement("div");
      pv.className = "notes-trash-preview";
      pv.textContent = String(it.preview || "");
      mid.appendChild(t);
      mid.appendChild(meta);
      if (it.preview) mid.appendChild(pv);
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "btn secondary notes-trash-restore";
      btn.textContent = "Вернуть";
      btn.addEventListener("click", function () {
        if (it._restoredId) {
          closeNotesTrashSheet();
          // Без текста: откроется только после загрузки полной версии с сервера.
          openLocalNoteDetail({ id: it._restoredId, title: it.title, body_preview_only: true });
          return;
        }
        restoreTrashedNote(it, btn, row);
      });
      row.appendChild(mid);
      row.appendChild(btn);
      list.appendChild(row);
    });
  }

  async function restoreTrashedNote(it, btn, row) {
    btn.disabled = true;
    btn.textContent = "Возвращаю…";
    try {
      var res = await apiFetch("/notes/trash/" + encodeURIComponent(String(it.note_id)) + "/restore", { method: "POST", body: "{}" });
      it._restoredId = res.note_id;
      row.classList.add("is-restored");
      btn.textContent = "Открыть";
      btn.disabled = false;
      showNoteToast("Заметка «" + String(it.title || "") + "» возвращена");
      loadNotes().catch(function () {});
    } catch (e) {
      btn.disabled = false;
      btn.textContent = "Вернуть";
      showNoteToast((e && e.message) || "Не удалось вернуть заметку");
    }
  }

  function bindNotesFilterUi() {
    var trashBtn = document.getElementById("notes-filter-trash");
    if (trashBtn) {
      trashBtn.addEventListener("click", function () {
        closeNotesFilterSheet();
        openNotesTrashSheet();
      });
    }
    var trashClose = document.getElementById("notes-trash-close");
    if (trashClose) trashClose.addEventListener("click", closeNotesTrashSheet);
    var trashOv = document.getElementById("notes-trash-overlay");
    if (trashOv) {
      trashOv.addEventListener("click", function (e) {
        if (e.target === trashOv) closeNotesTrashSheet();
      });
    }
    var btn = document.getElementById("notes-filter-btn");
    if (btn) btn.addEventListener("click", openNotesFilterSheet);
    var close = document.getElementById("notes-filter-close");
    if (close) close.addEventListener("click", closeNotesFilterSheet);
    var ov = document.getElementById("notes-filter-overlay");
    if (ov) {
      ov.addEventListener("click", function (e) {
        if (e.target === ov) closeNotesFilterSheet();
      });
      ov.querySelectorAll(".notes-filter-seg").forEach(function (seg) {
        seg.addEventListener("click", function (e) {
          var b = e.target && e.target.closest ? e.target.closest("button[data-v]") : null;
          if (!b || !notesFilterDraft) return;
          notesFilterDraft[seg.getAttribute("data-key")] = b.getAttribute("data-v");
          renderNotesFilterSheet();
        });
      });
    }
    ["notes-filter-from", "notes-filter-to"].forEach(function (id) {
      var inp = document.getElementById(id);
      if (!inp) return;
      inp.addEventListener("change", function () {
        if (!notesFilterDraft) return;
        notesFilterDraft[id === "notes-filter-from" ? "from" : "to"] = inp.value || "";
        renderNotesFilterSheet();
      });
    });
    var reset = document.getElementById("notes-filter-reset");
    if (reset) {
      reset.addEventListener("click", function () {
        notesFilterDraft = Object.assign({}, NOTES_FILTER_DEFAULT);
        renderNotesFilterSheet();
      });
    }
    var apply = document.getElementById("notes-filter-apply");
    if (apply) {
      apply.addEventListener("click", function () {
        if (notesFilterDraft) applyNotesFilter(notesFilterDraft);
        closeNotesFilterSheet();
      });
    }
    syncNotesFilterBtn();
  }

  function noteItemMatchesFilter(item, kind, opts) {
    if (!noteMatchesNotesFilter(item)) return false;
    var project = noteProjectOf(item);
    if (notesActiveProjectId === "none") {
      if (project) return false;
    } else if (notesActiveProjectId) {
      if (!project || Number(project.id) !== Number(notesActiveProjectId)) return false;
    }
    var parsed = parseNotesSearchQuery(notesSearchQuery);
    if (parsed.hashtags.length) {
      var itemHash = noteHashtagsOf(item).map(function (h) {
        return String(h.name || "").toLowerCase();
      });
      for (var hi = 0; hi < parsed.hashtags.length; hi++) {
        if (itemHash.indexOf(parsed.hashtags[hi]) < 0) return false;
      }
    }
    var q = parsed.text;
    if (!q || (opts && opts.skipText)) return true;
    var title = "";
    var preview = "";
    if (kind === "local") {
      title = sanitizeNoteTitle(item.title || item.content || "") || String(item.title || item.content || "");
      preview = notePlainExcerpt(item.description || item.body || "", 500);
    } else {
      title = journalCardTitle(item);
      preview = String(item.preview || "").trim();
    }
    var projectName = project ? String(project.name || "") : "";
    var hashNames = noteHashtagsOf(item)
      .map(function (t) {
        return "#" + String(t.name || "");
      })
      .join(" ");
    var hay = (title + " " + preview + " " + projectName + " " + hashNames).toLowerCase();
    return hay.indexOf(q) >= 0;
  }

  function setNotesSearchExpanded(open) {
    var wrap = document.getElementById("notes-search-wrap");
    var toggle = document.getElementById("notes-search-toggle");
    var input = document.getElementById("notes-search-input");
    if (!wrap) return;
    // На десктопе поле поиска видно всегда (не сворачивается после выхода из него).
    var shouldOpen = !!open || isDesktopLayout() || !!(input && String(input.value || "").trim());
    wrap.classList.toggle("notes-search-wrap--open", shouldOpen);
    if (toggle) toggle.setAttribute("aria-expanded", shouldOpen ? "true" : "false");
    if (!shouldOpen) closeNotesTagFilterMenu();
    if (shouldOpen && input && open) {
      window.requestAnimationFrame(function () {
        try {
          input.focus();
        } catch (_) {}
      });
    }
  }

  function applyNotesHashtagSearch(name) {
    var token = "#" + String(name || "").replace(/^#/, "");
    notesSearchQuery = token;
    var input = document.getElementById("notes-search-input");
    if (input) input.value = token;
    setNotesSearchExpanded(true);
    if (notesDataCache) renderNotesPanesFromData(notesDataCache);
  }

  function clearNotesHashtagSearch() {
    notesSearchQuery = "";
    var input = document.getElementById("notes-search-input");
    if (input) input.value = "";
    setNotesSearchExpanded(true);
    if (notesDataCache) renderNotesPanesFromData(notesDataCache);
  }

  function notesTagFilterMenuIsOpen() {
    var menu = document.getElementById("notes-tag-filter-menu");
    return !!(menu && !menu.classList.contains("hidden"));
  }

  function closeNotesTagFilterMenu() {
    var menu = document.getElementById("notes-tag-filter-menu");
    var btn = document.getElementById("notes-search-tag-btn");
    if (menu) menu.classList.add("hidden");
    if (btn) btn.setAttribute("aria-expanded", "false");
  }

  function fillNotesTagFilterMenu() {
    var menu = document.getElementById("notes-tag-filter-menu");
    if (!menu) return;
    menu.innerHTML = "";
    var tags = getUserHashtagsFromCache()
      .slice()
      .sort(function (a, b) {
        return String(a.name || "").localeCompare(String(b.name || ""), "ru", { sensitivity: "base" });
      });
    var active = {};
    parseNotesSearchQuery(notesSearchQuery).hashtags.forEach(function (h) {
      active[h] = true;
    });
    if (!tags.length) {
      var empty = document.createElement("p");
      empty.className = "notes-tag-filter-menu-empty";
      empty.textContent = "Хэштегов пока нет";
      menu.appendChild(empty);
      return;
    }
    tags.forEach(function (tag) {
      var name = String(tag.name || "").trim();
      if (!name) return;
      var key = name.toLowerCase();
      var isActive = !!active[key];
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className =
        "notes-tag-filter-menu-item" + (isActive ? " notes-tag-filter-menu-item--active" : "");
      btn.setAttribute("role", "option");
      btn.setAttribute("aria-selected", isActive ? "true" : "false");
      var label = document.createElement("span");
      label.className = "notes-tag-filter-menu-item-label";
      label.textContent = "#" + name;
      btn.appendChild(label);
      if (isActive) {
        var check = document.createElement("span");
        check.className = "notes-tag-filter-menu-item-check";
        check.textContent = "✓";
        check.setAttribute("aria-hidden", "true");
        btn.appendChild(check);
      }
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        if (isActive) {
          clearNotesHashtagSearch();
        } else {
          applyNotesHashtagSearch(name);
        }
        closeNotesTagFilterMenu();
      });
      menu.appendChild(btn);
    });
  }

  function openNotesTagFilterMenu() {
    var wrap = document.getElementById("notes-search-wrap");
    var menu = document.getElementById("notes-tag-filter-menu");
    var btn = document.getElementById("notes-search-tag-btn");
    if (!menu || !btn) return;
    setNotesSearchExpanded(true);
    fillNotesTagFilterMenu();
    menu.classList.remove("hidden");
    btn.setAttribute("aria-expanded", "true");
    if (wrap) wrap.classList.add("notes-search-wrap--open");
  }

  function toggleNotesTagFilterMenu(e) {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    if (notesTagFilterMenuIsOpen()) {
      closeNotesTagFilterMenu();
      return;
    }
    openNotesTagFilterMenu();
  }

  var notesTagFilterDocBound = false;
  function bindNotesTagFilterDocClickOnce() {
    if (notesTagFilterDocBound) return;
    notesTagFilterDocBound = true;
    document.addEventListener(
      "mousedown",
      function (e) {
        if (!notesTagFilterMenuIsOpen()) return;
        var field = document.getElementById("notes-search-field");
        if (field && field.contains(e.target)) return;
        closeNotesTagFilterMenu();
      },
      true
    );
  }

  function notesProjectCounts() {
    var out = { all: 0, none: 0, byId: {} };
    var data = notesDataCache;
    if (!data) return out;
    var list =
      notesSubTab === "transcriptions"
        ? data.transcriptions || []
        : (data.local_notes || []).filter(function (n) {
            return !looksLikeTranscriptionNote(n) && !isTranscriptionNoteItem(n);
          });
    list.forEach(function (n) {
      out.all++;
      var p = noteProjectOf(n);
      if (p && p.id != null) out.byId[String(p.id)] = (out.byId[String(p.id)] || 0) + 1;
      else out.none++;
    });
    return out;
  }

  function renderNotesTagFilterBar() {
    var row = document.getElementById("notes-project-chips");
    if (!row) return;
    row.innerHTML = "";
    var tags = getUserTagsFromCache();
    var counts = notesProjectCounts();
    function addChip(label, count, value) {
      var active = notesActiveProjectId === value || (value !== "none" && notesActiveProjectId !== "none" && Number(notesActiveProjectId || 0) === value);
      var chip = document.createElement("button");
      chip.type = "button";
      chip.className =
        "tag-chip tag-chip--filter notes-project-chip" + (active ? " tag-chip--active" : "");
      chip.setAttribute("role", "option");
      chip.setAttribute("aria-selected", active ? "true" : "false");
      var name = document.createElement("span");
      name.textContent = label;
      chip.appendChild(name);
      if (count) {
        var n = document.createElement("span");
        n.className = "notes-project-chip-count";
        n.textContent = String(count);
        chip.appendChild(n);
      }
      chip.addEventListener("click", function (e) {
        e.stopPropagation();
        notesActiveProjectId = active && value !== 0 ? 0 : value;
        renderNotesTagFilterBar();
        renderSidebarTrees();
        if (notesDataCache) renderNotesPanesFromData(notesDataCache);
      });
      row.appendChild(chip);
    }
    if (tags.length) addChip("Все", counts.all, 0);
    tags.forEach(function (tag) {
      addChip(String(tag.name || ""), counts.byId[String(tag.id)] || 0, Number(tag.id));
    });
    if (tags.length && counts.none) addChip("Без проекта", counts.none, "none");
    var pLabel = document.getElementById("notes-project-btn-label");
    if (pLabel) {
      var at = activeNotesProjectTag();
      pLabel.textContent = notesActiveProjectId === "none" ? "Без проекта" : at ? String(at.name || "") : "Все проекты";
      var pbtn = document.getElementById("notes-project-btn");
      if (pbtn) {
        pbtn.classList.toggle("is-active", !!notesActiveProjectId);
        pbtn.title = pLabel.textContent;
      }
    }
    var manage = document.createElement("button");
    manage.type = "button";
    manage.className = "notes-project-manage";
    manage.setAttribute("aria-label", "Управление проектами");
    manage.title = "Проекты";
    manage.innerHTML =
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" aria-hidden="true"><path d="M12 5v14M5 12h14" stroke-linecap="round"/></svg>';
    manage.addEventListener("click", function (e) {
      e.stopPropagation();
      openTagsManageSheet();
    });
    row.appendChild(manage);
  }

  function noteMatchesPickerProjectFilter(item, activeProjectId) {
    if (!activeProjectId) return true;
    var project = noteProjectOf(item);
    return !!(project && Number(project.id) === Number(activeProjectId));
  }

  function renderNotePickerProjectChips(container, getActiveId, setActiveId, onChange) {
    if (!container) return;
    container.innerHTML = "";
    container.className = "notes-project-chips note-picker-project-chips";
    container.setAttribute("role", "listbox");
    container.setAttribute("aria-label", "Проекты");
    var tags = getUserTagsFromCache();
    if (!tags.length) {
      setHidden(container, true);
      return;
    }
    setHidden(container, false);
    var activeProjectId = getActiveId();
    tags.forEach(function (tag) {
      var tid = Number(tag.id);
      var active = Number(activeProjectId) === tid;
      var chip = document.createElement("button");
      chip.type = "button";
      chip.className =
        "tag-chip tag-chip--filter notes-project-chip" + (active ? " tag-chip--active" : "");
      chip.setAttribute("role", "option");
      chip.setAttribute("aria-selected", active ? "true" : "false");
      chip.textContent = String(tag.name || "");
      chip.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        setActiveId(active ? 0 : tid);
        renderNotePickerProjectChips(container, getActiveId, setActiveId, onChange);
        if (typeof onChange === "function") onChange();
      });
      container.appendChild(chip);
    });
  }

  function appendTagChipsRow(parent, tags, opts) {
    opts = opts || {};
    var project = opts.project || null;
    var hashtags = opts.hashtags || [];
    if (!project && (!tags || !tags.length) && !hashtags.length) return;
    var row = document.createElement("div");
    row.className = parent.classList && parent.classList.contains("journal-card-main")
      ? "journal-card-tags"
      : "note-card-tags";
    if (opts.head) row.classList.add("note-card-tags--head");
    if (project) {
      var pchip = document.createElement("span");
      pchip.className = "tag-chip tag-chip--card tag-chip--project";
      pchip.textContent = String(project.name || "");
      row.appendChild(pchip);
    } else if (tags && tags.length) {
      tags.forEach(function (tag) {
        var chip = document.createElement("span");
        chip.className = "tag-chip tag-chip--card tag-chip--project";
        chip.textContent = String(tag.name || "");
        row.appendChild(chip);
      });
    }
    hashtags.forEach(function (tag) {
      var chip = document.createElement("button");
      chip.type = "button";
      chip.className = "tag-chip tag-chip--card tag-chip--hashtag";
      chip.textContent = String(tag.name || "");
      chip.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        applyNotesHashtagSearch(tag.name);
      });
      row.appendChild(chip);
    });
    if (!row.childNodes.length) return;
    if (opts.prepend) parent.insertBefore(row, parent.firstChild);
    else parent.appendChild(row);
  }

  function appendItemLabelChips(parent, item, opts) {
    appendTagChipsRow(parent, noteTagsOf(item), Object.assign({
      project: noteProjectOf(item),
      hashtags: noteHashtagsOf(item),
    }, opts || {}));
  }

  function updateItemTagsInCache(itemKind, itemId, tags) {
    var idStr = String(itemId);
    function patch(list) {
      if (!list) return;
      list.forEach(function (row) {
        if (String(row.id) === idStr) {
          row.tags = tags.slice();
          row.project = tags[0] || null;
        }
      });
    }
    if (itemKind === "local") {
      if (notesDataCache) {
        patch(notesDataCache.local_notes);
        patch(notesDataCache.transcriptions);
      }
      if (knowledgeDataCache) patch(knowledgeDataCache.notes);
    } else if (notesDataCache) {
      patch(notesDataCache.transcriptions);
      patch(notesDataCache.summaries);
      patch(notesDataCache.journal);
    }
  }

  async function saveItemTags(itemKind, itemId, tagIds) {
    var res = await apiFetch(
      "/notes/" + encodeURIComponent(itemKind) + "/" + encodeURIComponent(String(itemId)) + "/tags",
      {
        method: "PUT",
        body: JSON.stringify({ tag_ids: tagIds }),
      }
    );
    var tags = (res && res.tags) || [];
    if (res && res.project) tags = [res.project];
    updateItemTagsInCache(itemKind, itemId, tags);
    renderNotesTagFilterBar();
    if (notesDataCache) renderNotesPanesFromData(notesDataCache);
    return tags;
  }

  function bindTagPickerDocClickOnce() {
    if (tagPickerDocClickBound) return;
    tagPickerDocClickBound = true;
    document.addEventListener("click", function (e) {
      if (tagPickerActiveClose) tagPickerActiveClose();
      var more = document.getElementById("note-editor-more-wrap");
      if (more && e.target && more.contains(e.target)) return;
      closeNoteMoreMenu();
      if (
        e.target &&
        e.target.closest &&
        (e.target.closest(".note-card-actions") || e.target.closest(".note-card-menu"))
      ) {
        return;
      }
      if (
        e.target &&
        e.target.closest &&
        (e.target.closest(".chat-thread-more-wrap") || e.target.closest(".chat-thread-menu"))
      ) {
        return;
      }
      closeNoteCardMenus();
      closeChatThreadMenus();
    });
  }

  var TAG_PICKER_ICON_SVG =
    '<svg class="tag-picker-add-btn-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linejoin="round" aria-hidden="true">' +
    '<path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>' +
    "</svg>";
  var TAG_PICKER_CHEVRON_SVG =
    '<svg class="tag-picker-chevron" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true">' +
    '<path d="M6 9l6 6 6-6"/>' +
    "</svg>";

  function mountTagPicker(container, itemKind, itemId, currentTags, onChange) {
    container.innerHTML = "";
    container.classList.add("tag-picker", "tag-picker--dropdown");
    bindTagPickerDocClickOnce();

    var stateTags = (currentTags || []).slice(0, 1);
    var menuOpen = false;
    var menuEl = null;
    var addBtnEl = null;
    var menuPositionCleanup = null;
    var useFixedMenu = !!(container.closest && container.closest("#note-editor-overlay"));

    function resetMenuPosition() {
      if (!menuEl) return;
      menuEl.style.position = "";
      menuEl.style.left = "";
      menuEl.style.top = "";
      menuEl.style.transform = "";
      menuEl.style.zIndex = "";
    }

    function positionFixedMenu() {
      if (!useFixedMenu || !menuEl || menuEl.classList.contains("hidden") || !addBtnEl) return;
      var rect = addBtnEl.getBoundingClientRect();
      menuEl.style.position = "fixed";
      // По центру кнопки, но не за краем экрана (кнопка «Проект» теперь слева).
      var w = menuEl.offsetWidth || 160;
      var left = rect.left + rect.width / 2 - w / 2;
      left = Math.max(8, Math.min(left, window.innerWidth - w - 8));
      menuEl.style.left = Math.round(left) + "px";
      menuEl.style.top = rect.bottom + 6 + "px";
      menuEl.style.transform = "none";
      menuEl.style.zIndex = "120";
    }

    function unbindMenuPositionListeners() {
      if (!menuPositionCleanup) return;
      menuPositionCleanup();
      menuPositionCleanup = null;
    }

    function bindMenuPositionListeners() {
      unbindMenuPositionListeners();
      if (!useFixedMenu) return;
      var onReposition = function () {
        positionFixedMenu();
      };
      window.addEventListener("resize", onReposition);
      window.addEventListener("scroll", onReposition, true);
      menuPositionCleanup = function () {
        window.removeEventListener("resize", onReposition);
        window.removeEventListener("scroll", onReposition, true);
      };
    }

    function tagIds() {
      return stateTags.map(function (t) {
        return Number(t.id);
      });
    }

    function selectedIdMap() {
      var map = {};
      stateTags.forEach(function (t) {
        map[Number(t.id)] = true;
      });
      return map;
    }

    function updateTrigger() {
      if (!addBtnEl) return;
      addBtnEl.classList.remove("tag-picker-trigger--selected");
      addBtnEl.textContent = "";
      var inner = document.createElement("span");
      inner.className = "tag-picker-add-btn-inner";
      var count = stateTags.length;
      if (!count) {
        inner.insertAdjacentHTML("afterbegin", TAG_PICKER_ICON_SVG);
        var emptyLabel = document.createElement("span");
        emptyLabel.textContent = "Проект";
        inner.appendChild(emptyLabel);
      } else {
        addBtnEl.classList.add("tag-picker-trigger--selected");
        inner.insertAdjacentHTML("afterbegin", TAG_PICKER_ICON_SVG);
        var label = document.createElement("span");
        label.className = "tag-picker-trigger-label";
        label.textContent = String(stateTags[0].name || "");
        inner.appendChild(label);
        if (count > 1) {
          var more = document.createElement("span");
          more.className = "tag-picker-more";
          more.textContent = "+" + (count - 1);
          inner.appendChild(more);
        }
        inner.insertAdjacentHTML("beforeend", TAG_PICKER_CHEVRON_SVG);
      }
      addBtnEl.appendChild(inner);
      addBtnEl.setAttribute(
        "aria-expanded",
        menuOpen && menuEl && !menuEl.classList.contains("hidden") ? "true" : "false"
      );
    }

    function scheduleSave() {
      if (tagPickerSaveTimer) clearTimeout(tagPickerSaveTimer);
      tagPickerSaveTimer = setTimeout(async function () {
        try {
          // Новая заметка ещё без id — только локальный выбор, сохраним после create.
          if (!itemId) {
            if (typeof onChange === "function") onChange(stateTags.slice());
            updateTrigger();
            return;
          }
          var saved = await saveItemTags(itemKind, itemId, tagIds());
          stateTags = saved.slice();
          if (typeof onChange === "function") onChange(saved);
          updateTrigger();
          if (menuOpen) fillMenu();
        } catch (e) {
          alert(e.message || String(e));
        }
      }, 400);
    }

    function closeMenu() {
      menuOpen = false;
      if (menuEl) menuEl.classList.add("hidden");
      resetMenuPosition();
      unbindMenuPositionListeners();
      if (tagPickerActiveClose === closeMenu) tagPickerActiveClose = null;
      updateTrigger();
    }

    var TAG_ICO =
      '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" aria-hidden="true"><path d="M3.5 7.5a2 2 0 0 1 2-2h4l2 2h7a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2h-13a2 2 0 0 1-2-2z"/></svg>';
    var TAG_CHECK =
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>';
    var TAG_PLUS =
      '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>';

    function fillMenu() {
      if (!menuEl) return;
      menuEl.innerHTML = "";
      var head = document.createElement("p");
      head.className = "note-menu-label tag-picker-menu-head";
      head.textContent = "Проект";
      menuEl.appendChild(head);
      var selected = selectedIdMap();
      var allTags = getUserTagsFromCache().slice();
      if (!allTags.length) {
        var empty = document.createElement("p");
        empty.className = "tag-picker-menu-empty";
        empty.textContent = "Проектов пока нет";
        menuEl.appendChild(empty);
      } else {
        allTags.forEach(function (t) {
          var tid = Number(t.id);
          var btn = document.createElement("button");
          btn.type = "button";
          btn.className =
            "tag-picker-menu-item" + (selected[tid] ? " tag-picker-menu-item--selected" : "");
          btn.setAttribute("role", "option");
          btn.setAttribute("aria-selected", selected[tid] ? "true" : "false");
          var ico = document.createElement("span");
          ico.className = "tag-picker-menu-ico";
          ico.innerHTML = TAG_ICO;
          var name = document.createElement("span");
          name.className = "tag-picker-menu-label";
          name.textContent = String(t.name || "");
          var check = document.createElement("span");
          check.className = "tag-picker-menu-check";
          check.innerHTML = selected[tid] ? TAG_CHECK : "";
          check.setAttribute("aria-hidden", "true");
          btn.appendChild(ico);
          btn.appendChild(name);
          btn.appendChild(check);
          btn.addEventListener("click", function (e) {
            e.stopPropagation();
            if (selected[tid]) {
              stateTags = [];
            } else {
              stateTags = [{ id: t.id, name: t.name }];
            }
            updateTrigger();
            fillMenu();
            scheduleSave();
          });
          menuEl.appendChild(btn);
        });
      }
      var sep = document.createElement("div");
      sep.className = "note-menu-hr tag-picker-menu-sep";
      menuEl.appendChild(sep);
      var createBtn = document.createElement("button");
      createBtn.type = "button";
      createBtn.className = "tag-picker-menu-item tag-picker-menu-item--create";
      createBtn.innerHTML = '<span class="tag-picker-menu-ico">' + TAG_PLUS + "</span><span>Новый проект…</span>";
      createBtn.addEventListener("click", async function (e) {
        e.stopPropagation();
        closeMenu();
        var name = prompt("Название проекта");
        if (!name || !String(name).trim()) return;
        try {
          var res = await apiFetch("/tags", {
            method: "POST",
            body: JSON.stringify({ name: String(name).trim() }),
          });
          var created = (res && res.tag) || null;
          if (!created) return;
          if (!notesDataCache) notesDataCache = {};
          if (!notesDataCache.tags) notesDataCache.tags = [];
          notesDataCache.tags.push(created);
          notesDataCache.tags.sort(function (a, b) {
            return String(a.name || "").localeCompare(String(b.name || ""), "ru");
          });
          stateTags = [{ id: created.id, name: created.name }];
          renderNotesTagFilterBar();
          scheduleSave();
          updateTrigger();
        } catch (err) {
          alert(err.message || String(err));
        }
      });
      menuEl.appendChild(createBtn);
    }

    function openMenu() {
      if (tagPickerActiveClose && tagPickerActiveClose !== closeMenu) tagPickerActiveClose();
      menuOpen = true;
      tagPickerActiveClose = closeMenu;
      fillMenu();
      menuEl.classList.remove("hidden");
      updateTrigger();
      if (useFixedMenu) {
        positionFixedMenu();
        bindMenuPositionListeners();
      }
      ensureUserTagsLoaded().then(function () {
        if (!menuOpen) return;
        fillMenu();
        if (useFixedMenu) positionFixedMenu();
      });
    }

    var addWrap = document.createElement("div");
    addWrap.className = "tag-picker-add-wrap";
    addBtnEl = document.createElement("button");
    addBtnEl.type = "button";
    addBtnEl.className = "tag-picker-add-btn tag-picker-trigger";
    addBtnEl.setAttribute("aria-label", "Проект");
    addBtnEl.setAttribute("aria-haspopup", "listbox");
    addBtnEl.setAttribute("aria-expanded", "false");
    menuEl = document.createElement("div");
    menuEl.className = "tag-picker-menu hidden";
    menuEl.setAttribute("role", "listbox");
    if (useFixedMenu) menuEl.classList.add("tag-picker-menu--fixed");

    addBtnEl.addEventListener("click", function (e) {
      e.stopPropagation();
      if (menuOpen) closeMenu();
      else openMenu();
    });

    addWrap.appendChild(addBtnEl);
    addWrap.appendChild(menuEl);
    container.appendChild(addWrap);

    updateTrigger();

    container._tagPickerUnmount = closeMenu;
    container._tagPickerSetItemId = function (nextId) {
      itemId = nextId != null ? String(nextId) : "";
    };
    container._tagPickerGetTags = function () {
      return stateTags.slice();
    };
    container._tagPickerFlush = function () {
      if (!itemId) return Promise.resolve(stateTags.slice());
      return saveItemTags(itemKind, itemId, tagIds()).then(function (saved) {
        stateTags = saved.slice();
        if (typeof onChange === "function") onChange(saved);
        updateTrigger();
        return saved;
      });
    };
  }

  function openTagsManageSheet() {
    var ov = document.getElementById("tags-manage-overlay");
    if (!ov) return;
    ov.classList.remove("hidden");
    ov.setAttribute("aria-hidden", "false");
    renderTagsManageList();
    onModalSheetOpen();
    updateModalSheetForKeyboard();
    syncAppOverlay();
  }

  function closeTagsManageSheet() {
    var ov = document.getElementById("tags-manage-overlay");
    if (!ov) return;
    ov.classList.add("hidden");
    ov.setAttribute("aria-hidden", "true");
    onModalSheetClose();
    syncAppOverlay();
  }

  function renderTagsManageList() {
    var list = document.getElementById("tags-manage-list");
    if (!list) return;
    list.innerHTML = "";
    var tags = getUserTagsFromCache().slice();
    if (!tags.length) {
      list.innerHTML = '<p class="muted small">Проектов пока нет. Создайте первый ниже.</p>';
      return;
    }
    tags.forEach(function (tag) {
      var row = document.createElement("div");
      row.className = "tags-manage-row";
      var input = document.createElement("input");
      input.type = "text";
      input.className = "field-input tags-manage-row-input";
      input.value = String(tag.name || "");
      input.maxLength = 40;
      var del = document.createElement("button");
      del.type = "button";
      del.className = "tags-manage-row-del";
      del.textContent = "Удалить";
      input.addEventListener("change", async function () {
        var name = String(input.value || "").trim();
        if (!name || name === String(tag.name || "")) {
          input.value = String(tag.name || "");
          return;
        }
        try {
          var res = await apiFetch("/tags/" + encodeURIComponent(String(tag.id)), {
            method: "PATCH",
            body: JSON.stringify({ name: name }),
          });
          var updated = (res && res.tag) || { id: tag.id, name: name };
          if (notesDataCache && notesDataCache.tags) {
            notesDataCache.tags = notesDataCache.tags.map(function (t) {
              return Number(t.id) === Number(tag.id) ? updated : t;
            });
          }
          tag.name = updated.name;
          await loadNotes();
          renderTagsManageList();
        } catch (e) {
          alert(e.message || String(e));
          input.value = String(tag.name || "");
        }
      });
      del.addEventListener("click", async function () {
        if (!(await confirmDialog('Удалить проект «' + String(tag.name || "") + "»?"))) return;
        try {
          await apiFetch("/tags/" + encodeURIComponent(String(tag.id)), { method: "DELETE" });
          if (Number(notesActiveProjectId) === Number(tag.id)) notesActiveProjectId = 0;
          await loadNotes();
          renderTagsManageList();
        } catch (e) {
          alert(e.message || String(e));
        }
      });
      row.appendChild(input);
      row.appendChild(del);
      list.appendChild(row);
    });
  }

  function destroyActiveNoteRichEditor() {
    var body = getNoteEditorBodyEl();
    if (!body) return;
    var inst = body._noteRichEditor;
    if (inst && typeof inst.destroy === "function") {
      try {
        inst.destroy();
      } catch (_) {}
    }
    body._noteRichEditor = null;
  }

  function getNoteRichEditorApi() {
    var api = window.NoteRichEditor;
    if (!api && typeof globalThis !== "undefined") api = globalThis.NoteRichEditor;
    if (api && api.default && typeof api.default.mount === "function") return api.default;
    return api;
  }

  function mountFallbackNoteEditor(container, body, onUpdate) {
    if (!container) return null;
    container.innerHTML = "";
    var warn = document.createElement("p");
    warn.className = "muted small";
    warn.textContent = "Упрощённый редактор: полный не загрузился.";
    var ed = document.createElement("div");
    ed.className = "note-rich-editor-body note-editor-fallback";
    ed.contentEditable = "true";
    ed.setAttribute("role", "textbox");
    ed.innerHTML = body || "";
    ed.addEventListener("input", function () {
      if (typeof onUpdate === "function") onUpdate();
    });
    container.appendChild(warn);
    container.appendChild(ed);
    return {
      getHtml: function () {
        return ed.innerHTML || "";
      },
      setHtml: function (html) {
        ed.innerHTML = html || "";
      },
      getCursor: function () {
        return 0;
      },
      hasRangeSelection: function () {
        var sel = window.getSelection && window.getSelection();
        return !!(sel && !sel.isCollapsed && ed.contains(sel.anchorNode));
      },
      coordsAtPos: function () {
        return null;
      },
      appendText: function (text) {
        var raw = String(text || "").replace(/\s+$/, "");
        if (!raw) return;
        raw.split("\n").forEach(function (line) {
          var p = document.createElement("p");
          p.textContent = line;
          ed.appendChild(p);
        });
        if (typeof onUpdate === "function") onUpdate();
      },
      appendHtml: function (html) {
        var raw = String(html || "").trim();
        if (!raw) return;
        ed.insertAdjacentHTML("beforeend", raw);
        if (typeof onUpdate === "function") onUpdate();
      },
      prepareForSave: function () {},
      focus: function () {
        ed.focus();
      },
      bindTapFocus: function () {},
      destroy: function () {
        container.innerHTML = "";
      },
    };
  }

  function setNoteEditorTocOpen(page, open) {
    if (!page) return;
    page.classList.toggle("note-editor-page--toc-open", !!open);
    var btn = page.querySelector(".note-editor-toc-toggle");
    if (btn) btn.setAttribute("aria-expanded", open ? "true" : "false");
  }

  function bindNoteEditorTocControls(page) {
    var controls = {
      tocParent: page ? page.querySelector(".note-editor-toc-list") : null,
      close: function () {
        setNoteEditorTocOpen(page, false);
      },
    };
    if (!page) return controls;
    var toggle = page.querySelector(".note-editor-toc-toggle");
    if (toggle) {
      toggle.addEventListener("click", function () {
        setNoteEditorTocOpen(page, !page.classList.contains("note-editor-page--toc-open"));
      });
    }
    page.querySelectorAll("[data-note-toc-close]").forEach(function (el) {
      el.addEventListener("click", controls.close);
    });
    return controls;
  }

  function getActiveNoteEditorPage() {
    var body = getNoteEditorBodyEl();
    return body ? body.querySelector(".note-editor-page") : null;
  }

  function openActiveNoteEditorToc() {
    var page = getActiveNoteEditorPage();
    if (!page) return;
    setNoteEditorTocOpen(page, true);
  }

  // Проект — в строке свойств под названием (раньше — пунктирной плашкой по центру шапки).
  // Пикер монтируется в шапку как раньше (там его состояние и обработчики), а элемент переносим.
  function moveProjectPickerToMeta(page) {
    var slot = page && page.querySelector("#note-editor-meta-project");
    var tw = document.getElementById("note-editor-tags-wrap");
    if (!slot || !tw) return;
    Array.prototype.slice.call(tw.children).forEach(function (c) {
      if (c.id !== "note-editor-more-wrap") slot.appendChild(c);
    });
    slot.classList.add("tag-picker", "tag-picker--dropdown");
  }

  // Название по содержанию: для «Новый чат» / «Без названия» ИИ один раз предлагает своё — сам не переименовывает.
  var NOTE_DEFAULT_TITLES = /^(новый чат|без названия|\(без названия\)|новая заметка|заметка|)$/i;
  function maybeSuggestNoteTitle(noteId) {
    var input = document.getElementById("note-editor-title-input");
    var btn = document.getElementById("note-editor-title-suggest");
    if (!noteId || !input || !btn) return;
    if (!NOTE_DEFAULT_TITLES.test(String(input.value || "").trim())) return;
    var key = "leo_title_suggest_" + noteId;
    try {
      if (sessionStorage.getItem(key)) return;
      sessionStorage.setItem(key, "1");
    } catch (_) {}
    apiFetch("/notes/local/" + encodeURIComponent(String(noteId)) + "/suggest-title", { method: "POST", timeout: 30000 })
      .then(function (res) {
        var title = String((res && res.title) || "").trim();
        if (!title || document.getElementById("note-editor-title-suggest") !== btn) return;
        if (!NOTE_DEFAULT_TITLES.test(String(input.value || "").trim())) return;
        btn.textContent = "Назвать «" + title + "»?";
        btn.classList.remove("hidden");
        btn.onclick = function (e) {
          e.preventDefault();
          input.value = title;
          input.dispatchEvent(new Event("input", { bubbles: true }));
          btn.classList.add("hidden");
          showNoteToast("Название обновлено");
        };
      })
      .catch(function () {});
  }

  // «Сохраняю… / Сохранено» в строке свойств; ошибки по-прежнему — красной подсказкой.
  var noteSaveStateTimer = null;
  function setNoteSaveState(state) {
    var el = document.getElementById("note-editor-save-state");
    if (!el) return;
    clearTimeout(noteSaveStateTimer);
    el.classList.toggle("is-error", state === "error");
    if (state === "saving") el.textContent = "Сохраняю…";
    else if (state === "saved") el.textContent = "Сохранено";
    else if (state === "error") el.textContent = "Не сохранено";
    else el.textContent = "";
  }

  function noteEditorPageInnerHtml(titleLabel) {
    var titleAria = escapeHtml(titleLabel || "Заголовок");
    var mobileToc = isMobileNoteLayout();
    var tocToggle =
      '<button type="button" class="note-editor-toc-toggle" aria-controls="note-editor-toc-panel" aria-expanded="false" title="Оглавление" aria-label="Оглавление">' +
        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
        '<path d="M8 6h13M8 12h13M8 18h13"/><circle cx="4" cy="6" r="1" fill="currentColor" stroke="none"/><circle cx="4" cy="12" r="1" fill="currentColor" stroke="none"/><circle cx="4" cy="18" r="1" fill="currentColor" stroke="none"/>' +
        "</svg>" +
        "</button>";
    var tocPanel =
      '<aside class="note-editor-toc-panel" id="note-editor-toc-panel" aria-label="Оглавление">' +
      '<div class="note-editor-toc-head">' +
      "<span>Оглавление</span>" +
      '<button type="button" class="note-editor-toc-close" data-note-toc-close aria-label="Закрыть">x</button>' +
      "</div>" +
      '<div class="note-editor-toc-list"></div>' +
      "</aside>";
    // Кнопка оглавления — первой в строке вкладок; на телефоне панель выезжает слева.
    var tocInSheetsBar =
      '<div class="note-editor-toc-anchor">' + tocToggle + (mobileToc ? "" : tocPanel) + "</div>";
    var tocInLayout = mobileToc ? tocPanel : "";
    return (
      '<div class="note-editor-doc-layout">' +
      tocInLayout +
      '<div class="note-editor-toc-backdrop" data-note-toc-close aria-hidden="true"></div>' +
      '<div class="note-editor-main-column">' +
      '<div class="note-editor-pad note-editor-pad--title-in-body">' +
      '<textarea id="note-editor-title-input" class="note-editor-title vkui--font_title1--regular" ' +
      'placeholder="Заголовок" aria-label="' +
      titleAria +
      '" maxlength="500" rows="1" autocapitalize="sentences" spellcheck="true"></textarea>' +
      '<div class="note-editor-meta" id="note-editor-meta">' +
      '<div id="note-editor-meta-project" class="note-editor-meta-project"></div>' +
      '<div id="note-editor-teams" class="note-editor-teams hidden"></div>' +
      '<div id="note-editor-members" class="note-editor-members hidden"></div>' +
      '<span id="note-editor-save-state" class="note-editor-save-state" aria-live="polite"></span>' +
      '<button type="button" id="note-editor-title-suggest" class="note-editor-title-suggest hidden"></button>' +
      "</div>" +
      '<div class="note-editor-sheets-bar">' +
      tocInSheetsBar +
      '<div id="note-editor-sheets" class="note-editor-sheets hidden"></div>' +
      "</div>" +
      "</div>" +
      '<div class="note-editor-pad note-editor-pad--body"></div>' +
      "</div>" +
      "</div>"
    );
  }

  function mountNoteRichEditor(container, body, onUpdate, options) {
    options = options || {};
    var toolbarWrap = document.getElementById("note-editor-toolbar-wrap");
    var formatHost =
      options.toolbarParent !== undefined
        ? options.toolbarParent
        : document.getElementById("note-editor-format-toolbar-host");
    if (toolbarWrap && options.showSharedToolbar !== false) {
      setHidden(toolbarWrap, false);
      syncNoteFormatToolbarForComposer();
    }
    if (formatHost && options.clearToolbar !== false) formatHost.innerHTML = "";
    var mountPoint = document.createElement("div");
    mountPoint.id = options.mountId || "td-desc";
    mountPoint.className = "note-rich-editor-mount";
    container.appendChild(mountPoint);
    var loading = document.createElement("p");
    loading.className = "muted small";
    loading.textContent = "Загрузка редактора…";
    mountPoint.appendChild(loading);

    return loadNoteEditorScripts()
      .then(function () {
        loading.remove();
        var NoteRichEditor = getNoteRichEditorApi();
        if (!NoteRichEditor || typeof NoteRichEditor.mount !== "function") {
          return mountFallbackNoteEditor(mountPoint, body, onUpdate);
        }
        try {
          var editor = NoteRichEditor.mount(mountPoint, {
            body: body,
            placeholder: "Начните писать…",
            onUpdate: function (info) {
              if (typeof onUpdate === "function") onUpdate.apply(null, arguments);
              // Ширина / высота таблицы, ужатие фото, чужая правка — не у курсора: не прокручиваем к нему.
              if (!(info && info.noScroll)) scrollNoteCaretIntoView();
            },
            onSelection: function () {
              if (typeof options.onSelection === "function") options.onSelection.apply(null, arguments);
              if (!noteEditorHasRangeSelection()) scrollNoteCaretIntoView();
            },
            toolbarParent: formatHost || null,
            tocParent: options.tocParent || null,
            onTocNavigate: options.onTocNavigate || null,
            scrollParent: options.scrollParent || null,
            extraTocItems: options.extraTocItems || null,
            hashtags: getUserHashtagsFromCache().map(function (h) {
              return String(h.name || "");
            }),
            onTaskSlash: createTaskFromSlash,
            onOpenLink: openExternal,
            onTaskChipClick: openTaskFromChip,
            onExternalTaskClick: openExternal,
            onTaskChipRemoved: deleteTaskFromChip,
            onFocusMarkClick: onFocusMarkClick,
            onSearchNoteRefs: searchNoteRefItems,
            onNoteRefChipClick: openNoteRefFromChip,
            onEntityRefChipClick: openEntityRefFromChip,
          });
          if (editor && typeof editor.bindTapFocus === "function" && !isIOSDevice()) {
            editor.bindTapFocus(container);
          }
          return editor;
        } catch (err) {
          console.error("NoteRichEditor.mount", err);
          return mountFallbackNoteEditor(mountPoint, body, onUpdate);
        }
      })
      .catch(function (err) {
        console.error("loadNoteEditorScripts", err);
        return mountFallbackNoteEditor(mountPoint, body, onUpdate);
      });
  }

  function resolveLocalNoteFromCache(n) {
    if (!n) return n;
    var lid = localNoteIdFrom(n);
    if (!lid) return n;
    if (notesDataCache && notesDataCache.local_notes) {
      for (var i = 0; i < notesDataCache.local_notes.length; i++) {
        if (String(notesDataCache.local_notes[i].id) === String(lid)) {
          return notesDataCache.local_notes[i];
        }
      }
    }
    if (notesDataCache && notesDataCache.transcriptions) {
      for (var t = 0; t < notesDataCache.transcriptions.length; t++) {
        if (String(notesDataCache.transcriptions[t].id) === String(lid)) {
          return notesDataCache.transcriptions[t];
        }
      }
    }
    if (knowledgeDataCache && knowledgeDataCache.notes) {
      for (var k = 0; k < knowledgeDataCache.notes.length; k++) {
        if (String(knowledgeDataCache.notes[k].id) === String(lid)) {
          return knowledgeDataCache.notes[k];
        }
      }
    }
    return n;
  }

  function resolveKnowledgeNoteFromCache(n) {
    if (!n || !knowledgeDataCache || !knowledgeDataCache.notes) return n;
    var lid = localNoteIdFrom(n);
    if (!lid) return n;
    for (var i = 0; i < knowledgeDataCache.notes.length; i++) {
      if (String(knowledgeDataCache.notes[i].id) === String(lid)) {
        return knowledgeDataCache.notes[i];
      }
    }
    return n;
  }

  var NOTE_SHEET_MAIN = "main";
  var noteSheetState = {
    sheets: [],
    leftId: NOTE_SHEET_MAIN,
    rightMode: "discussion",
    rightId: "",
    rightNote: null,
    rightNotePersistTimer: null,
    focus: "left",
    contextIds: null,
    contextExplicit: false,
    rightEditor: null,
    primaryBody: "",
    sheetTimers: {},
    sheetPersists: {},
    leftScroll: {},
    skipCaretScroll: false,
    enabled: false,
    pendingOpenSheetId: "",
    leftWebCanvas: null,
    rightWebCanvas: null,
    leftBoard: null,
    rightBoard: null,
    canvasSelections: [],
  };

  function isWebSheet(sheet) {
    if (!sheet) return false;
    return String(sheet.kind || "").toLowerCase() === "web";
  }

  // Холст (kind=board): доска с блоками и стрелками — webapp/board.js, тело листа — JSON.
  function isBoardSheet(sheet) {
    if (!sheet) return false;
    return String(sheet.kind || "").toLowerCase() === "board";
  }

  function addCanvasSelection(sel) {
    if (!sel) return;
    var leoId = String(sel.leoId || "").trim();
    var sheetId = String(sel.sheetId || "").trim();
    if (!leoId && !sel.snippet) return;
    noteSheetState.canvasSelections = (noteSheetState.canvasSelections || []).filter(
      function (x) {
        return !(String(x.leoId) === leoId && String(x.sheetId) === sheetId);
      }
    );
    noteSheetState.canvasSelections.push({
      sheetId: sheetId,
      leoId: leoId,
      label: String(sel.label || leoId || "элемент").slice(0, 80),
      snippet: String(sel.snippet || "").slice(0, 4000),
    });
    if (noteSheetState.canvasSelections.length > 8) {
      noteSheetState.canvasSelections = noteSheetState.canvasSelections.slice(-8);
    }
    renderCanvasSelectionChips();
    syncNotePaieReplyForm();
  }

  function clearCanvasSelections() {
    noteSheetState.canvasSelections = [];
    renderCanvasSelectionChips();
  }

  var CANVAS_QUOTE_MARK = "◆полотно◆ ";

  function canvasSelectionLabel(sel) {
    if (!sel) return "элемент";
    return String((sel.leoId ? sel.leoId + " · " : "") + (sel.label || "элемент")).trim() || "элемент";
  }

  function formatCanvasSelectionQuote(sel) {
    return CANVAS_QUOTE_MARK + canvasSelectionLabel(sel);
  }

  function encodeCanvasSelectionsQuote(sels) {
    return (sels || [])
      .map(formatCanvasSelectionQuote)
      .filter(Boolean)
      .join("\n");
  }

  function splitDiscussQuote(quote) {
    var canvas = [];
    var textLines = [];
    String(quote || "")
      .split("\n")
      .forEach(function (line) {
        var raw = String(line || "").trim();
        if (!raw) return;
        if (raw.indexOf(CANVAS_QUOTE_MARK) === 0) {
          var label = raw.slice(CANVAS_QUOTE_MARK.length).trim();
          if (label) canvas.push({ label: label });
        } else {
          textLines.push(raw);
        }
      });
    return { canvas: canvas, text: textLines.join("\n") };
  }

  function snapshotCanvasSelections() {
    return (noteSheetState.canvasSelections || []).map(function (s) {
      return {
        sheetId: s.sheetId,
        leoId: s.leoId,
        label: s.label,
        snippet: s.snippet,
      };
    });
  }

  function activeWebCanvasSheetId() {
    var left = findNoteSheet(noteSheetState.leftId);
    if (isWebSheet(left) && left.id != null) return String(left.id);
    var right =
      noteSheetState.rightMode === "sheet" ? findNoteSheet(noteSheetState.rightId) : null;
    if (isWebSheet(right) && right.id != null) return String(right.id);
    var fromSel = (noteSheetState.canvasSelections || []).find(function (s) {
      return s && s.sheetId;
    });
    return fromSel ? String(fromSel.sheetId) : "";
  }

  function renderCanvasSelectionChips() {
    var form = document.getElementById("note-paie-reply-form");
    if (!form) return;
    var host = form.querySelector(".note-canvas-sel-chips");
    if (!host) {
      host = document.createElement("div");
      host.className = "note-canvas-sel-chips";
      var target = form.querySelector(".note-paie-reply-target");
      if (target && target.parentNode) target.parentNode.insertBefore(host, target.nextSibling);
      else form.insertBefore(host, form.firstChild);
    }
    host.innerHTML = "";
    (noteSheetState.canvasSelections || []).forEach(function (sel, idx) {
      var chip = document.createElement("div");
      chip.className = "note-canvas-sel-chip";
      var span = document.createElement("span");
      span.textContent = canvasSelectionLabel(sel);
      var btn = document.createElement("button");
      btn.type = "button";
      btn.setAttribute("aria-label", "Убрать");
      btn.textContent = "×";
      btn.addEventListener("click", function () {
        noteSheetState.canvasSelections.splice(idx, 1);
        renderCanvasSelectionChips();
        syncNotePaieReplyForm();
      });
      chip.appendChild(span);
      chip.appendChild(btn);
      host.appendChild(chip);
    });
  }

  function appendDiscussCanvasChips(host, selections) {
    var rows = Array.isArray(selections) ? selections : [];
    if (!host || !rows.length) return;
    var wrap = document.createElement("div");
    wrap.className = "note-discuss-canvas-chips";
    wrap.setAttribute("aria-label", "Выделенные блоки презентации");
    rows.forEach(function (sel) {
      var chip = document.createElement("span");
      chip.className = "note-discuss-canvas-chip";
      chip.textContent = canvasSelectionLabel(sel);
      wrap.appendChild(chip);
    });
    host.appendChild(wrap);
  }

  function ensureLeftWebCanvasHost() {
    var pad = document.querySelector("#note-editor-overlay .note-editor-pad--body");
    if (!pad) return null;
    var host = pad.querySelector(".note-web-canvas-host");
    if (!host) {
      host = document.createElement("div");
      host.className = "note-web-canvas-host";
      pad.appendChild(host);
    }
    return host;
  }

  function destroyLeftWebCanvas() {
    if (noteSheetState.leftWebCanvas && noteSheetState.leftWebCanvas.destroy) {
      noteSheetState.leftWebCanvas.destroy();
    }
    noteSheetState.leftWebCanvas = null;
    var pad = document.querySelector("#note-editor-overlay .note-editor-pad--body");
    if (pad) pad.classList.remove("is-web-canvas-mode");
    var host = pad && pad.querySelector(".note-web-canvas-host");
    if (host) host.innerHTML = "";
    var overlay = document.getElementById("note-editor-overlay");
    if (overlay) overlay.classList.remove("is-web-canvas-open");
    var toolbarWrap = document.getElementById("note-editor-toolbar-wrap");
    if (toolbarWrap) setHidden(toolbarWrap, false);
  }

  function destroyRightWebCanvas() {
    if (noteSheetState.rightWebCanvas && noteSheetState.rightWebCanvas.destroy) {
      noteSheetState.rightWebCanvas.destroy();
    }
    noteSheetState.rightWebCanvas = null;
  }

  function mountLeftWebCanvas(sheet) {
    if (canvasLayoutsCache === null) loadCanvasLayouts();
    var LeoWebCanvas = window.LeoWebCanvas;
    var host = ensureLeftWebCanvasHost();
    var pad = document.querySelector("#note-editor-overlay .note-editor-pad--body");
    if (!LeoWebCanvas || !host || !pad || !sheet) return;
    destroyLeftWebCanvas();
    pad.classList.add("is-web-canvas-mode");
    var overlay = document.getElementById("note-editor-overlay");
    if (overlay) overlay.classList.add("is-web-canvas-open");
    var toolbarWrap = document.getElementById("note-editor-toolbar-wrap");
    if (toolbarWrap) setHidden(toolbarWrap, true);
    noteSheetState.leftWebCanvas = LeoWebCanvas.create({
      host: host,
      html: sheet.body || sheet.description || "",
      sheetId: String(sheet.id),
      onSelect: addCanvasSelection,
      onRefresh: function () {
        return refreshWebCanvasSheet(String(sheet.id), "left");
      },
      onChange: function (html) {
        onWebCanvasHtmlChange(String(sheet.id), html);
      },
      onMedia: function (req) {
        handleWebCanvasMedia(String(sheet.id), req);
      },
      onIcon: openCanvasIconSheet,
      onOp: function (req) {
        return runWebCanvasOp(String(sheet.id), req);
      },
      onRestyleImages: function (req) {
        return restyleWebCanvasImages(String(sheet.id), req);
      },
      onRevise: function (req) {
        return reviseWebCanvas(String(sheet.id), req);
      },
      onTheme: rememberDeckTheme,
      getLayouts: function () {
        return canvasLayoutsCache || [];
      },
      onSaveLayout: function (req) {
        return saveCanvasLayout(String(sheet.id), req);
      },
      onDeleteLayout: deleteCanvasLayout,
      onNotify: showNoteToast,
    });
  }

  function mountRightWebCanvas(sheet) {
    if (canvasLayoutsCache === null) loadCanvasLayouts();
    var LeoWebCanvas = window.LeoWebCanvas;
    var host = document.getElementById("note-discussion-sheet-host");
    var bar = document.getElementById("note-discussion-sheet-toolbar");
    if (!LeoWebCanvas || !host || !sheet) return;
    destroyRightSheetEditor();
    destroyRightWebCanvas();
    host.innerHTML = "";
    if (bar) bar.innerHTML = "";
    noteSheetState.rightWebCanvas = LeoWebCanvas.create({
      host: host,
      html: sheet.body || sheet.description || "",
      sheetId: String(sheet.id),
      onSelect: addCanvasSelection,
      onRefresh: function () {
        return refreshWebCanvasSheet(String(sheet.id), "right");
      },
      onChange: function (html) {
        onWebCanvasHtmlChange(String(sheet.id), html);
      },
      onMedia: function (req) {
        handleWebCanvasMedia(String(sheet.id), req);
      },
      onIcon: openCanvasIconSheet,
      onOp: function (req) {
        return runWebCanvasOp(String(sheet.id), req);
      },
      onRestyleImages: function (req) {
        return restyleWebCanvasImages(String(sheet.id), req);
      },
      onRevise: function (req) {
        return reviseWebCanvas(String(sheet.id), req);
      },
      onTheme: rememberDeckTheme,
      getLayouts: function () {
        return canvasLayoutsCache || [];
      },
      onSaveLayout: function (req) {
        return saveCanvasLayout(String(sheet.id), req);
      },
      onDeleteLayout: deleteCanvasLayout,
      onNotify: showNoteToast,
    });
    noteSheetState.rightEditor = null;
  }

  function boardSheetOptions(sheet) {
    var sid = String(sheet.id);
    return {
      json: sheet.body || sheet.description || "",
      sheetId: (noteSheetsNoteId() || "") + ":" + sid,
      title: sheet.title || "Доска",
      onChange: function (json) {
        onBoardSheetChange(sid, json);
      },
      onCursor: function (x, y) {
        sendBoardCursor(sid, x, y);
      },
      onNotify: showNoteToast,
    };
  }

  function destroyLeftBoard() {
    var b = noteSheetState.leftBoard;
    if (b) stopBoardYjs(b);
    noteSheetState.leftBoard = null;
    if (!b) return;
    if (b.destroy) b.destroy();
    var pad = document.querySelector("#note-editor-overlay .note-editor-pad--body");
    if (pad) pad.classList.remove("is-board-mode", "is-web-canvas-mode");
    var overlay = document.getElementById("note-editor-overlay");
    if (overlay) overlay.classList.remove("is-web-canvas-open");
    var toolbarWrap = document.getElementById("note-editor-toolbar-wrap");
    if (toolbarWrap) setHidden(toolbarWrap, false);
  }

  function destroyRightBoard() {
    var b = noteSheetState.rightBoard;
    if (b) stopBoardYjs(b);
    noteSheetState.rightBoard = null;
    if (b && b.destroy) b.destroy();
  }

  // Холст занимает место редактора так же, как web-канвас (те же классы раскладки).
  function mountLeftBoard(sheet) {
    var LeoBoard = window.LeoBoard;
    if (!LeoBoard || !sheet) return;
    destroyLeftBoard();
    destroyLeftWebCanvas();
    var host = ensureLeftWebCanvasHost();
    var pad = document.querySelector("#note-editor-overlay .note-editor-pad--body");
    if (!host || !pad) return;
    host.innerHTML = "";
    pad.classList.add("is-web-canvas-mode", "is-board-mode");
    var overlay = document.getElementById("note-editor-overlay");
    if (overlay) overlay.classList.add("is-web-canvas-open");
    var toolbarWrap = document.getElementById("note-editor-toolbar-wrap");
    if (toolbarWrap) setHidden(toolbarWrap, true);
    noteSheetState.leftBoard = LeoBoard.create(Object.assign({ host: host }, boardSheetOptions(sheet)));
    startBoardYjs();
  }

  function mountRightBoard(sheet) {
    var LeoBoard = window.LeoBoard;
    var host = document.getElementById("note-discussion-sheet-host");
    var bar = document.getElementById("note-discussion-sheet-toolbar");
    if (!LeoBoard || !host || !sheet) return;
    destroyRightSheetEditor();
    host.innerHTML = "";
    if (bar) bar.innerHTML = "";
    noteSheetState.rightBoard = LeoBoard.create(Object.assign({ host: host }, boardSheetOptions(sheet)));
    noteSheetState.rightEditor = null;
    startBoardYjs();
  }

  function onBoardSheetChange(sheetId, json) {
    var sid = String(sheetId || "");
    var sheet = findNoteSheet(sid);
    if (!sheet || !isBoardSheet(sheet)) return;
    sheet.body = String(json || "");
    sheet.description = sheet.body;
    upsertNoteSheet(sheet);
    if (!isPrimarySheetId(sid)) scheduleExtraSheetPersist(sid);
  }

  function onWebCanvasHtmlChange(sheetId, html) {
    var sid = String(sheetId || "");
    var sheet = findNoteSheet(sid);
    if (!sheet || !isWebSheet(sheet)) return;
    sheet.body = String(html || "");
    sheet.description = sheet.body;
    upsertNoteSheet(sheet);
    if (!isPrimarySheetId(sid)) scheduleExtraSheetPersist(sid);
  }

  function fileToDataUrl(file) {
    return new Promise(function (resolve, reject) {
      var reader = new FileReader();
      reader.onload = function () {
        resolve(String(reader.result || ""));
      };
      reader.onerror = function () {
        reject(new Error("Не удалось прочитать файл"));
      };
      reader.readAsDataURL(file);
    });
  }

  function pickLocalImageFile() {
    return new Promise(function (resolve) {
      var input = document.createElement("input");
      input.type = "file";
      input.accept = "image/*";
      input.style.display = "none";
      document.body.appendChild(input);
      input.addEventListener("change", function () {
        var file = input.files && input.files[0];
        if (input.parentNode) input.parentNode.removeChild(input);
        resolve(file || null);
      });
      input.click();
    });
  }

  async function uploadCanvasImageFile(file) {
    var noteId = noteSheetsNoteId();
    if (!noteId || !file) throw new Error("Нет заметки или файла");
    var fd = new FormData();
    fd.append("file", file, file.name || "image.png");
    var res = await apiFetch(
      "/notes/local/" + encodeURIComponent(String(noteId)) + "/discuss-files",
      { method: "POST", body: fd }
    );
    var row = res && res.file;
    if (!row || !row.id) throw new Error("Не удалось загрузить изображение");
    // iframe cannot auth-fetch; embed as data URL for reliable display
    var dataUrl = await fileToDataUrl(file);
    if (dataUrl.length > 2500000) {
      throw new Error("Картинка слишком большая — сожмите файл");
    }
    return dataUrl;
  }

  async function generateCanvasImageDataUrl(prompt, sheetId) {
    var noteId = noteSheetsNoteId();
    var text = String(prompt || "").trim();
    if (!noteId) throw new Error("Нет заметки");
    if (!text) throw new Error("Введите описание картинки");
    var res = await apiFetch(
      "/notes/local/" + encodeURIComponent(String(noteId)) + "/canvas-image",
      {
        method: "POST",
        body: JSON.stringify({ prompt: text, sheet_id: sheetId ? String(sheetId) : null }),
        timeout: 240000,
      }
    );
    var dataUrl = String((res && res.data_url) || "").trim();
    if (!dataUrl) throw new Error("Модель не вернула изображение");
    return dataUrl;
  }

  // Let a pending autosave of this sheet finish before a server-side canvas edit.
  async function waitSheetPersistIdle(sheetId) {
    var id = String(sheetId || "");
    if (noteSheetState.sheetTimers[id]) {
      clearTimeout(noteSheetState.sheetTimers[id]);
      delete noteSheetState.sheetTimers[id];
    }
    var inflight = noteSheetState.sheetPersists[id];
    if (inflight) {
      try {
        await inflight;
      } catch (e) {}
    }
  }

  function webCanvasSheetPath(sheetId) {
    var noteId = noteSheetsNoteId();
    if (!noteId || String(noteId).indexOf("tmp_") === 0) {
      throw new Error("Заметка ещё не сохранена");
    }
    if (isAppOffline()) throw new Error("Нет сети — правки презентации недоступны офлайн");
    return (
      "/notes/local/" +
      encodeURIComponent(String(noteId)) +
      "/sheets/" +
      encodeURIComponent(String(sheetId))
    );
  }

  function acceptWebCanvasItem(item) {
    if (!item) return "";
    upsertNoteSheet(item);
    previewOpenNoteFromSheets();
    return String(item.body || item.description || "");
  }

  async function runWebCanvasOp(sheetId, req) {
    var path = webCanvasSheetPath(sheetId);
    await waitSheetPersistIdle(sheetId);
    var res = await apiFetch(path + "/canvas-op", {
      method: "POST",
      body: JSON.stringify({
        op: req.op,
        slide_id: req.slideId || "",
        variant: req.variant || "",
        theme: req.theme || "",
        group: req.group || "",
        index: req.index || 0,
        after: req.after == null ? null : req.after,
        delta: req.delta || 0,
        path: req.path || "",
        icon: req.icon || "",
        elements: Array.isArray(req.elements) ? req.elements : null,
        surface: req.surface || "",
        html: req.html || null,
      }),
    });
    var html = acceptWebCanvasItem(res && res.item);
    if (!html) throw new Error("Не удалось изменить слайд");
    return html;
  }

  // Перерисовать картинки презентации в её текущем стиле: сначала считаем (dry_run), спрашиваем, потом генерируем.
  async function restyleWebCanvasImages(sheetId, req) {
    var path = webCanvasSheetPath(sheetId);
    await waitSheetPersistIdle(sheetId);
    var probe = await apiFetch(path + "/canvas-restyle-images", {
      method: "POST",
      body: JSON.stringify({ html: req.html || null, dry_run: true }),
    });
    var n = Number((probe && probe.count) || 0);
    if (!n) {
      showNoteToast("В презентации нет картинок, созданных ИИ");
      return "";
    }
    var ok = await confirmDialog(
      "Перерисовать " + n + " " + pluralRu(n, "картинку", "картинки", "картинок") +
        " в текущем стиле презентации? Картинки, которые вы загрузили сами, не изменятся. Займёт до минуты."
    );
    if (!ok) return "";
    showNoteToast("Перерисовываю картинки… до минуты");
    var res = await apiFetch(path + "/canvas-restyle-images", {
      method: "POST",
      body: JSON.stringify({ html: req.html || null }),
    });
    var html = acceptWebCanvasItem(res && res.item);
    var done = Number((res && res.done) || 0);
    if (!html || !done) throw new Error("Не удалось перерисовать картинки — попробуйте ещё раз");
    showNoteToast(
      done < n
        ? "Перерисовано " + done + " из " + n + ". Остальные можно повторить"
        : "Готово: " + done + " " + pluralRu(done, "картинка", "картинки", "картинок") + " в новом стиле"
    );
    return html;
  }

  // ---- Окно ИИ «Что сделать с текстом?» (кнопка ✨ в панели и в плашке выделения) ----
  // Правки применяются как у ИИ из обсуждения (applyNoteAiEdits: подсветка + «Отменить / Ок»), в чат не пишутся.
  var noteAiSheetState = null;

  function canUseNoteAiSheet() {
    var wrap = document.getElementById("note-editor-more-wrap");
    var local = !wrap || !wrap._shareKind || wrap._shareKind === "local";
    return !!(local && noteSheetsNoteId() && buildOpenDocView());
  }

  function openNoteAiSheet(opts) {
    opts = opts || {};
    var ov = document.getElementById("note-ai-overlay");
    if (!ov) return;
    noteAiSheetState = { selection: String(opts.selection || "").trim() };
    var scope = document.getElementById("note-ai-scope");
    if (scope) scope.textContent = noteAiSheetState.selection ? "Выделенное" : "Весь лист";
    var ta = document.getElementById("note-ai-input");
    if (ta) ta.value = "";
    ov.querySelectorAll(".note-ai-chips button").forEach(function (b) {
      b.setAttribute("aria-pressed", "false");
    });
    syncNoteAiGo();
    ov.classList.remove("hidden");
    ov.setAttribute("aria-hidden", "false");
    onModalSheetOpen();
    syncAppOverlay();
    setTimeout(function () {
      if (ta) ta.focus();
    }, 60);
  }

  function closeNoteAiSheet() {
    var ov = document.getElementById("note-ai-overlay");
    if (!ov) return;
    noteAiSheetState = null;
    ov.classList.add("hidden");
    ov.setAttribute("aria-hidden", "true");
    onModalSheetClose();
    syncAppOverlay();
  }

  function syncNoteAiGo() {
    var ta = document.getElementById("note-ai-input");
    var go = document.getElementById("note-ai-go");
    if (go) go.disabled = !(ta && ta.value.trim());
  }

  async function runNoteAiSheet() {
    var ta = document.getElementById("note-ai-input");
    var go = document.getElementById("note-ai-go");
    var instruction = ta ? ta.value.trim() : "";
    var state = noteAiSheetState || {};
    var view = buildOpenDocView();
    var noteId = noteSheetsNoteId();
    if (!instruction || !view || !noteId) return;
    if (go) {
      go.classList.add("is-busy");
      go.textContent = "Думаю…";
    }
    try {
      var res = await apiFetch("/notes/local/" + encodeURIComponent(String(noteId)) + "/ai-edit", {
        method: "POST",
        timeout: 180000,
        body: JSON.stringify({
          instruction: instruction,
          doc_view: view.view,
          sheet_id: view.sheet_id,
          selection: state.selection || null,
          note_title: getNoteEditorTitle ? getNoteEditorTitle() : "",
        }),
      });
      closeNoteAiSheet();
      applyNoteAiEdits({ sheet_id: (res && res.sheet_id) || view.sheet_id, edits: (res && res.edits) || [] });
    } catch (e) {
      showNoteToast((e && e.message) || "ИИ не ответил, попробуйте ещё раз");
    } finally {
      if (go) {
        go.classList.remove("is-busy");
        go.textContent = "Сделать";
      }
    }
  }

  function bindNoteAiSheet() {
    var ov = document.getElementById("note-ai-overlay");
    if (!ov || ov._bound) return;
    ov._bound = true;
    ov.addEventListener("click", function (e) {
      if (e.target === ov) closeNoteAiSheet();
    });
    var close = document.getElementById("note-ai-close");
    if (close) close.addEventListener("click", closeNoteAiSheet);
    var ta = document.getElementById("note-ai-input");
    if (ta) {
      ta.addEventListener("input", syncNoteAiGo);
      ta.addEventListener("keydown", function (e) {
        if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
          e.preventDefault();
          runNoteAiSheet();
        }
      });
    }
    ov.querySelectorAll(".note-ai-chips button").forEach(function (b) {
      b.addEventListener("click", function () {
        if (ta) ta.value = b.getAttribute("data-p") || b.textContent;
        ov.querySelectorAll(".note-ai-chips button").forEach(function (x) {
          x.setAttribute("aria-pressed", String(x === b));
        });
        syncNoteAiGo();
        if (ta) ta.focus();
      });
    });
    var go = document.getElementById("note-ai-go");
    if (go) go.addEventListener("click", runNoteAiSheet);
  }

  // ---- Правки ИИ в открытой заметке ----
  // Модель присылает правки (assistant/lib/note_edits.py), мы применяем их в редакторе,
  // подсвечиваем изменённое (CSS Highlight API — в саму заметку ничего не пишется)
  // и показываем плашку «Отменить / Ок». Изменения сразу сохраняются; «Отменить» возвращает прежний текст.
  var noteAiReview = null;

  function openDocEditorRoot() {
    var left = findNoteSheet(noteSheetState.leftId);
    if (isWebSheet(left) || isBoardSheet(left)) return null;
    return document.querySelector("#note-editor-overlay .note-editor-pad--body .ProseMirror") ||
      document.querySelector("#note-editor-overlay .note-editor-pad--body [contenteditable='true']");
  }

  function aiDocBlocks(root) {
    return Array.prototype.filter.call(root.children, function (el) {
      return !/ProseMirror-(widget|gapcursor)|ProseMirror-trailingBreak/.test(el.className || "");
    });
  }

  function aiTables(root) {
    return Array.prototype.slice.call(root.querySelectorAll("table"));
  }

  // Вид открытого листа для модели: абзацы и таблицы с номерами строк и столбцов.
  function buildOpenDocView() {
    var root = openDocEditorRoot();
    if (!root) return null;
    var tables = aiTables(root);
    var lines = [];
    aiDocBlocks(root).forEach(function (block) {
      var t = block.tagName === "TABLE" ? block : block.querySelector("table");
      if (t) {
        var n = tables.indexOf(t) + 1;
        var rows = Array.prototype.slice.call(t.rows);
        var cols = rows.reduce(function (m, r) { return Math.max(m, r.cells.length); }, 0);
        lines.push("[Таблица " + n + ": строк " + rows.length + ", столбцов " + cols + "]");
        rows.forEach(function (r, i) {
          lines.push(i + 1 + ": " + Array.prototype.map.call(r.cells, function (c) {
            return String(c.innerText || c.textContent || "").replace(/\s+/g, " ").trim();
          }).join(" | "));
        });
        lines.push("[/Таблица " + n + "]");
        return;
      }
      var text = String(block.innerText || block.textContent || "").trim();
      if (text) lines.push(text);
    });
    var view = lines.join("\n");
    if (!view.trim()) return null;
    return { sheet_id: String(noteSheetState.leftId || NOTE_SHEET_MAIN), view: view };
  }

  function parseCellNumber(s) {
    var t = String(s || "").replace(/[\s  ]/g, "").replace(/[−–]/g, "-");
    t = t.replace(/[^0-9,.\-]/g, "");
    if (!t || !/\d/.test(t)) return null;
    if (t.indexOf(",") >= 0 && t.indexOf(".") >= 0) t = t.replace(/\./g, "").replace(",", ".");
    else t = t.replace(",", ".");
    var v = parseFloat(t);
    return isFinite(v) ? v : null;
  }

  function formatCellNumber(v, samples) {
    var dec = 0;
    var comma = true;
    samples.forEach(function (s) {
      var m = /[.,](\d+)\s*\D*$/.exec(String(s || "").trim());
      if (m) {
        dec = Math.max(dec, Math.min(2, m[1].length));
        if (String(s).indexOf(".") >= 0 && String(s).indexOf(",") < 0) comma = false;
      }
    });
    var neg = v < 0;
    var fixed = Math.abs(v).toFixed(dec);
    var parts = fixed.split(".");
    var intPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, " ");
    var out = intPart + (parts[1] ? (comma ? "," : ".") + parts[1] : "");
    return (neg ? "−" : "") + out;
  }

  function computeCells(fn, values) {
    var nums = values.filter(function (x) { return x !== null; });
    if (!nums.length) return null;
    if (fn === "avg") return nums.reduce(function (a, b) { return a + b; }, 0) / nums.length;
    if (fn === "min") return Math.min.apply(null, nums);
    if (fn === "max") return Math.max.apply(null, nums);
    if (fn === "product") return nums.reduce(function (a, b) { return a * b; }, 1);
    if (fn === "diff") return nums.slice(1).reduce(function (a, b) { return a - b; }, nums[0]);
    return nums.reduce(function (a, b) { return a + b; }, 0);
  }

  // Применение к HTML листа. Возвращает {html, marks:[{block, start, len}], applied, failed}.
  function applyAiEditsToHtml(html, edits) {
    var doc = new DOMParser().parseFromString("<div id='leo-ai-root'>" + html + "</div>", "text/html");
    var root = doc.getElementById("leo-ai-root");
    var touched = []; // {node, start, len}
    var applied = 0;
    var failed = 0;

    function textNodes(scope) {
      var out = [];
      var w = doc.createTreeWalker(scope, NodeFilter.SHOW_TEXT, null);
      var n;
      while ((n = w.nextNode())) out.push(n);
      return out;
    }

    function setCellText(cell, value) {
      var target = cell.querySelector("p") || cell;
      target.textContent = String(value);
      touched.push({ node: target.firstChild, start: 0, len: String(value).length });
    }

    function cellAt(t, r, c) {
      var row = t.rows[r - 1];
      return row ? row.cells[c - 1] || null : null;
    }

    edits.forEach(function (e) {
      if (e.op === "replace") {
        var hits = 0;
        textNodes(root).some(function (node) {
          var s = node.nodeValue;
          if (s.indexOf(e.find) < 0) return false;
          var out = "";
          var i = 0;
          var j;
          while ((j = s.indexOf(e.find, i)) >= 0) {
            out += s.slice(i, j);
            if (e.replace) touched.push({ node: node, start: out.length, len: e.replace.length, pending: true });
            out += e.replace;
            i = j + e.find.length;
            hits++;
            if (!e.all) break;
          }
          out += s.slice(i);
          node.nodeValue = out;
          return !e.all;
        });
        if (hits) applied += hits;
        else failed++;
        return;
      }
      var tables = Array.prototype.slice.call(root.querySelectorAll("table"));
      if (e.op === "set_cell") {
        var t1 = tables[e.table - 1];
        var c1 = t1 && cellAt(t1, e.row, e.col);
        if (c1) {
          setCellText(c1, e.value);
          applied++;
        } else failed++;
        return;
      }
      if (e.op === "compute") {
        var t = tables[e.table - 1];
        if (!t) { failed++; return; }
        var nRows = t.rows.length;
        var nCols = Array.prototype.reduce.call(t.rows, function (m, r) { return Math.max(m, r.cells.length); }, 0);
        function range(from, to, skip) {
          var out = [];
          for (var k = from; k <= to; k++) if (k !== skip) out.push(k);
          return out;
        }
        var byCol = !!e.target.col;
        // «all»: строки — все, кроме заголовка и итоговой; столбцы — все, кроме итогового.
        var rowsAll = range(2, nRows, e.target.row || null);
        var colsAll = range(1, nCols, e.target.col || null);
        var rowsSel = e.rows === "all" ? rowsAll : e.rows;
        var colsSel = e.cols === "all" ? colsAll : e.cols;
        var outer = byCol ? rowsSel : colsSel;
        var inner = byCol ? colsSel : rowsSel;
        outer.forEach(function (o) {
          var raw = inner.map(function (i) {
            var cell = byCol ? cellAt(t, o, i) : cellAt(t, i, o);
            return cell ? String(cell.textContent || "") : "";
          });
          var v = computeCells(e.fn, raw.map(parseCellNumber));
          var target = byCol ? cellAt(t, o, e.target.col) : cellAt(t, e.target.row, o);
          if (v === null || !target) return;
          setCellText(target, formatCellNumber(v, raw));
          applied++;
        });
        return;
      }
      if (e.op === "insert_after") {
        var blocks = Array.prototype.slice.call(root.children);
        var anchor = null;
        if (e.anchor) {
          anchor = blocks.filter(function (b) { return String(b.textContent || "").indexOf(e.anchor) >= 0; })[0] || null;
          if (!anchor) { failed++; return; }
        }
        var ref = anchor ? anchor.nextSibling : null;
        String(e.text).split(/\n+/).forEach(function (line) {
          if (!line.trim()) return;
          var p = doc.createElement("p");
          p.textContent = line;
          root.insertBefore(p, ref);
          touched.push({ node: p.firstChild, start: 0, len: line.length });
        });
        applied++;
      }
    });

    // Позиции изменений: номер блока верхнего уровня и смещение в его тексте.
    var blocks = Array.prototype.slice.call(root.children);
    var marks = [];
    touched.forEach(function (m) {
      if (!m.node || !m.len) return;
      var block = m.node.parentNode;
      while (block && block.parentNode !== root) block = block.parentNode;
      var bi = blocks.indexOf(block);
      if (bi < 0) return;
      var off = 0;
      var nodes = textNodes(block);
      for (var k = 0; k < nodes.length && nodes[k] !== m.node; k++) off += nodes[k].nodeValue.length;
      marks.push({ block: bi, start: off + m.start, len: m.len, text: m.node.nodeValue.slice(m.start, m.start + m.len) });
    });
    return { html: root.innerHTML, marks: marks, applied: applied, failed: failed };
  }

  function rangeForMark(root, mark) {
    var blocks = aiDocBlocks(root);
    var block = blocks[mark.block];
    function inBlock(b, start) {
      var w = document.createTreeWalker(b, NodeFilter.SHOW_TEXT, null);
      var n;
      var pos = 0;
      var r = document.createRange();
      var started = false;
      var end = start + mark.len;
      while ((n = w.nextNode())) {
        var len = n.nodeValue.length;
        if (!started && start <= pos + len) {
          r.setStart(n, Math.max(0, start - pos));
          started = true;
        }
        if (started && end <= pos + len) {
          r.setEnd(n, end - pos);
          return r;
        }
        pos += len;
      }
      return null;
    }
    var r = block ? inBlock(block, mark.start) : null;
    if (r && r.toString() === mark.text) return r;
    // Разметка редактора отличается — ищем текст в том же блоке.
    if (block && mark.text) {
      var idx = String(block.textContent || "").indexOf(mark.text);
      if (idx >= 0) {
        r = inBlock(block, idx);
        if (r) return r;
      }
    }
    return null;
  }

  function paintAiHighlights() {
    if (!noteAiReview || typeof CSS === "undefined" || !CSS.highlights || typeof Highlight === "undefined") return;
    var root = openDocEditorRoot();
    if (!root) return;
    var ranges = noteAiReview.marks.map(function (m) { return rangeForMark(root, m); }).filter(Boolean);
    noteAiReview.ranges = ranges;
    var hl = new Highlight();
    ranges.forEach(function (r) {
      hl.add(r);
    });
    CSS.highlights.set("leo-ai-edit", hl);
  }

  function clearAiHighlights() {
    try {
      if (typeof CSS !== "undefined" && CSS.highlights) CSS.highlights.delete("leo-ai-edit");
    } catch (_) {}
  }

  function scheduleOpenDocSave(sheetId) {
    if (isPrimarySheetId(sheetId)) {
      var body = getNoteEditorBodyEl();
      if (body && typeof body._noteEditorSchedule === "function") body._noteEditorSchedule();
    } else {
      scheduleExtraSheetPersist(sheetId);
    }
  }

  function aiEditBar() {
    var bar = document.getElementById("note-ai-edit-bar");
    if (bar) return bar;
    bar = document.createElement("div");
    bar.id = "note-ai-edit-bar";
    bar.className = "note-ai-edit-bar hidden";
    bar.setAttribute("role", "status");
    bar.innerHTML =
      '<span class="note-ai-edit-dot" aria-hidden="true"></span>' +
      '<button type="button" class="note-ai-edit-text" data-ai="next" title="Показать следующее изменение"></button>' +
      '<button type="button" class="note-ai-edit-undo" data-ai="undo">Отменить</button>' +
      '<button type="button" class="note-ai-edit-ok" data-ai="ok">Ок</button>';
    bar.addEventListener("click", function (e) {
      var b = e.target.closest("[data-ai]");
      if (!b) return;
      e.preventDefault();
      var act = b.getAttribute("data-ai");
      if (act === "ok") finishAiReview(true);
      else if (act === "undo") finishAiReview(false);
      else if (isMobileNoteLayout() && isNoteDiscussionOpen()) {
        // На телефоне обсуждение закрывает заметку — сначала показываем саму правку.
        closeNoteDiscussion();
        setTimeout(scrollToNextAiChange, 250);
      } else scrollToNextAiChange();
    });
    // На уровне страницы (а не внутри редактора): иначе панель/окно обсуждения перекрывает плашку.
    document.body.appendChild(bar);
    var pane = document.querySelector("#note-editor-overlay .note-editor-modal-body");
    if (pane && typeof ResizeObserver !== "undefined") {
      var aiBarRaf = 0;
      new ResizeObserver(function () {
        if (aiBarRaf) return;
        aiBarRaf = requestAnimationFrame(function () {
          aiBarRaf = 0;
          positionAiEditBar();
        });
      }).observe(pane);
    }
    window.addEventListener("resize", positionAiEditBar);
    return bar;
  }

  // Десктоп: обсуждение — панель рядом с заметкой (слева или справа), центруем плашку по области заметки.
  function positionAiEditBar() {
    var bar = document.getElementById("note-ai-edit-bar");
    if (!bar) return;
    var pane = document.querySelector("#note-editor-overlay .note-editor-modal-body");
    var r = pane && !isMobileNoteLayout() ? pane.getBoundingClientRect() : null;
    var left = r ? r.left : 0;
    var right = r ? r.right : 0;
    var sheet = isNoteDiscussionOpen() && document.querySelector("#note-discussion-overlay .note-discussion-sheet");
    if (r && sheet) {
      var d = sheet.getBoundingClientRect();
      if (d.width && d.left <= left + 8) left = Math.max(left, d.right);
      else if (d.width) right = Math.min(right, d.left);
    }
    if (r && right - left > 200) {
      bar.style.left = Math.round((left + right) / 2) + "px";
      bar.style.maxWidth = Math.round(right - left - 24) + "px";
    } else {
      bar.style.left = "";
      bar.style.maxWidth = "";
    }
  }

  function scrollToNextAiChange() {
    if (!noteAiReview || !noteAiReview.ranges || !noteAiReview.ranges.length) return;
    noteAiReview.cursor = ((noteAiReview.cursor || 0) + 1) % noteAiReview.ranges.length;
    var r = noteAiReview.ranges[noteAiReview.cursor];
    var el = r.startContainer.parentElement;
    if (el && el.scrollIntoView) el.scrollIntoView({ block: "center", behavior: "smooth" });
  }

  function finishAiReview(keep) {
    var review = noteAiReview;
    noteAiReview = null;
    clearAiHighlights();
    var bar = document.getElementById("note-ai-edit-bar");
    if (bar) bar.classList.add("hidden");
    if (!review || keep) return;
    var left = getLeftNoteRichEditor();
    if (left && String(noteSheetState.leftId || NOTE_SHEET_MAIN) === review.sheetId && typeof left.setHtml === "function") {
      left.setHtml(review.before);
      if (isPrimarySheetId(review.sheetId)) noteSheetState.primaryBody = review.before;
      scheduleOpenDocSave(review.sheetId);
      showNoteToast("Изменения ИИ отменены");
      if (review.rec) {
        review.rec.undone = true;
        refreshDiscussFeedNow();
      }
    }
  }

  function ruChanges(n) {
    var m10 = n % 10;
    var m100 = n % 100;
    var w = m10 === 1 && m100 !== 11 ? "изменение" : m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14) ? "изменения" : "изменений";
    return n + " " + w;
  }

  function applyNoteAiEdits(payload) {
    var edits = (payload && payload.edits) || [];
    if (!edits.length) return;
    var sheetId = String(payload.sheet_id || NOTE_SHEET_MAIN);
    var left = getLeftNoteRichEditor();
    if (!left || typeof left.getHtml !== "function" || String(noteSheetState.leftId || NOTE_SHEET_MAIN) !== sheetId || !openDocEditorRoot()) {
      showNoteToast("ИИ подготовил правки, но лист уже закрыт — откройте его и повторите запрос");
      return;
    }
    if (noteAiReview) finishAiReview(true);
    var before = left.getHtml();
    var res = applyAiEditsToHtml(before, edits);
    if (!res.applied) {
      showNoteToast("ИИ не нашёл, что поменять в заметке — уточните запрос");
      return;
    }
    left.setHtml(res.html, { preserveCursor: true });
    if (isPrimarySheetId(sheetId)) noteSheetState.primaryBody = res.html;
    markNextSaveAsAi(sheetId);
    scheduleOpenDocSave(sheetId);
    var rec = { sheetId: sheetId, before: before, after: left.getHtml(), marks: res.marks, count: res.applied, undone: false };
    noteAiReview = { sheetId: sheetId, before: before, marks: res.marks, ranges: [], cursor: -1, rec: rec };
    var bar = aiEditBar();
    bar.querySelector(".note-ai-edit-text").textContent =
      "ИИ внёс " + ruChanges(res.applied) + (res.failed ? " · не нашёл: " + res.failed : "");
    bar.classList.remove("hidden");
    positionAiEditBar();
    requestAnimationFrame(function () {
      paintAiHighlights();
      scrollToNextAiChange();
    });
    return rec;
  }

  // Правки ИИ в ответе обсуждения: «Изменено N мест · Показать в заметке · Отменить».
  // Снимки «до/после» живут в памяти сессии; после перезагрузки остаётся только строка-сводка.
  var aiEditRecords = {};
  var AI_EDITS_LS = "leo_ai_edits_v1";

  function aiEditSummaries() {
    try {
      return JSON.parse(localStorage.getItem(AI_EDITS_LS) || "{}") || {};
    } catch (_) {
      return {};
    }
  }

  function rememberAiEditRecord(commentId, rec) {
    if (!rec || !commentId) return;
    var id = String(commentId);
    var sheet = findNoteSheet(rec.sheetId);
    rec.sheetTitle = (sheet && sheet.title) || "Основная";
    aiEditRecords[id] = rec;
    var all = aiEditSummaries();
    all[id] = { n: rec.count, s: rec.sheetTitle };
    var keys = Object.keys(all);
    if (keys.length > 300) {
      keys.slice(0, keys.length - 300).forEach(function (k) {
        delete all[k];
      });
    }
    try {
      localStorage.setItem(AI_EDITS_LS, JSON.stringify(all));
    } catch (_) {}
  }

  function ruPlaces(n) {
    var m10 = n % 10;
    var m100 = n % 100;
    var w = m10 === 1 && m100 !== 11 ? "место" : m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14) ? "места" : "мест";
    return n + " " + w;
  }

  function aiHtmlKey(html) {
    return String(html || "").replace(/\s+/g, " ").trim();
  }

  function refreshDiscussFeedNow() {
    var list = document.getElementById("note-discussion-messages");
    if (list) list._renderFp = null;
    rerenderDiscussionFeed();
  }

  async function aiEditLeftEditor(rec) {
    if (String(noteSheetState.leftId || NOTE_SHEET_MAIN) !== rec.sheetId) {
      try {
        await switchLeftSheet(rec.sheetId);
      } catch (_) {}
    }
    var left = getLeftNoteRichEditor();
    if (!left || typeof left.getHtml !== "function" || String(noteSheetState.leftId || NOTE_SHEET_MAIN) !== rec.sheetId) {
      showNoteToast("Лист с правками сейчас не открыт");
      return null;
    }
    return left;
  }

  async function showAiEditRecord(rec) {
    var left = await aiEditLeftEditor(rec);
    if (!left) return;
    if (aiHtmlKey(left.getHtml()) !== aiHtmlKey(rec.after)) {
      showNoteToast("Заметку уже меняли после этой правки — подсветить не получится");
      return;
    }
    if (isMobileNoteLayout() && isNoteDiscussionOpen()) closeNoteDiscussion();
    if (noteAiReview) finishAiReview(true);
    noteAiReview = { sheetId: rec.sheetId, before: rec.before, marks: rec.marks, ranges: [], cursor: -1, rec: rec };
    var bar = aiEditBar();
    bar.querySelector(".note-ai-edit-text").textContent = "ИИ внёс " + ruChanges(rec.count);
    bar.classList.remove("hidden");
    positionAiEditBar();
    requestAnimationFrame(function () {
      paintAiHighlights();
      scrollToNextAiChange();
    });
  }

  async function setAiEditRecordUndone(rec, undone) {
    var left = await aiEditLeftEditor(rec);
    if (!left) return;
    var expect = undone ? rec.after : rec.before;
    if (aiHtmlKey(left.getHtml()) !== aiHtmlKey(expect)) {
      showNoteToast("Заметку уже меняли после этой правки — поправьте вручную");
      return;
    }
    if (noteAiReview && noteAiReview.rec === rec) {
      noteAiReview = null;
      clearAiHighlights();
      var bar = document.getElementById("note-ai-edit-bar");
      if (bar) bar.classList.add("hidden");
    }
    var html = undone ? rec.before : rec.after;
    left.setHtml(html);
    if (isPrimarySheetId(rec.sheetId)) noteSheetState.primaryBody = html;
    scheduleOpenDocSave(rec.sheetId);
    rec.undone = undone;
    showNoteToast(undone ? "Правки ИИ отменены" : "Правки ИИ возвращены");
    refreshDiscussFeedNow();
  }

  function appendAiEditsInfo(bubble, commentId) {
    var id = String(commentId);
    var rec = aiEditRecords[id];
    var sum = rec ? { n: rec.count, s: rec.sheetTitle } : aiEditSummaries()[id];
    if (!sum || !sum.n) return;
    var box = document.createElement("div");
    box.className = "note-discuss-edits" + (rec && rec.undone ? " is-undone" : "");
    var info = document.createElement("div");
    info.className = "note-discuss-edits-info";
    info.innerHTML = rec && rec.undone ? DISCUSS_ICONS.undo : DISCUSS_ICONS.pen;
    var txt = document.createElement("span");
    txt.textContent =
      rec && rec.undone
        ? "Правки отменены · " + ruPlaces(sum.n)
        : "Изменено " + ruPlaces(sum.n) + " на листе «" + (sum.s || "Основная") + "»";
    info.appendChild(txt);
    box.appendChild(info);
    if (rec) {
      var row = document.createElement("div");
      row.className = "note-discuss-edits-actions";
      function btn(label, cls, fn) {
        var b = document.createElement("button");
        b.type = "button";
        b.className = "note-discuss-edits-btn" + (cls ? " " + cls : "");
        b.textContent = label;
        b.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          fn();
        });
        row.appendChild(b);
      }
      if (rec.undone) {
        btn("Вернуть правки", "", function () {
          setAiEditRecordUndone(rec, false);
        });
      } else {
        btn("Показать в заметке", "is-primary", function () {
          showAiEditRecord(rec);
        });
        btn("Отменить", "", function () {
          setAiEditRecordUndone(rec, true);
        });
      }
      box.appendChild(row);
    }
    bubble.appendChild(box);
  }

  // Действия ИИ с календарём: карточки под ответом (создано · Отменить; удалить? · Удалить / Оставить).
  var calActionsCache = {};
  var calActionsPending = {};
  var calActionsTimer = null;

  function rememberCalendarActions(list) {
    (list || []).forEach(function (a) {
      if (a && a.id) calActionsCache[a.id] = a;
    });
  }

  function fetchCalendarActionsSoon(ids) {
    ids.forEach(function (id) {
      calActionsPending[id] = true;
    });
    clearTimeout(calActionsTimer);
    calActionsTimer = setTimeout(function () {
      var want = Object.keys(calActionsPending).filter(function (id) {
        return !calActionsCache[id];
      });
      calActionsPending = {};
      if (!want.length) return;
      apiFetch("/gpt/calendar-actions/status", { method: "POST", body: JSON.stringify({ ids: want }) })
        .then(function (res) {
          rememberCalendarActions((res && res.actions) || []);
          want.forEach(function (id) {
            if (!calActionsCache[id]) calActionsCache[id] = { id: id, missing: true };
          });
          refreshDiscussFeedNow();
        })
        .catch(function () {});
    }, 120);
  }

  var CAL_KIND_UI = {
    event_create: ["cal", "Встреча", "Создана встреча"],
    event_update: ["clock", "Встреча", "Изменена встреча"],
    task_create: ["taskBox", "Задача", "Задача"],
    reminder_create: ["bell", "Напоминание", "Напоминание"],
    event_delete: ["trash", "Встреча", "Удалить встречу"],
    task_delete: ["trash", "Задача", "Удалить задачу"],
    reminder_delete: ["trash", "Напоминание", "Удалить напоминание"],
    slot: ["cal", "Встреча", "Создана встреча"],
  };

  function matchCalendarEventInList(events, ref) {
    var want = String((ref && ref.id) || "");
    var cal = String((ref && ref.calendar_id) || "primary");
    if (!want) return null;
    var list = events || [];
    var exact = list.find(function (x) {
      return String(x.id) === want && String(x.calendar_id || "primary") === cal;
    });
    if (exact) return exact;
    // Экземпляр серии Google: id = {master}_{timestamp}, recurringEventId = master.
    return (
      list.find(function (x) {
        if (String(x.calendar_id || "primary") !== cal) return false;
        var rid = String(x.recurringEventId || (x.raw && x.raw.recurringEventId) || "");
        if (rid && rid === want) return true;
        return String(x.id || "").indexOf(want + "_") === 0;
      }) || null
    );
  }

  // Открыть встречу/задачу/напоминание из карточки в ответе ИИ.
  async function openCalendarRef(ref) {
    if (!ref || !ref.id) return;
    try {
      if (ref.type === "task") {
        openTaskFromChip(String(ref.id).replace(/^task-/, ""));
        return;
      }
      if (ref.type === "reminder") {
        var rdata = await apiFetch("/reminders", { method: "GET" });
        var rem = ((rdata && rdata.items) || []).find(function (x) {
          return String(x.id) === String(ref.id);
        });
        if (rem) openReminderModal(rem);
        else showNoteToast("Напоминание не найдено — возможно, уже удалено");
        return;
      }
      var day = await fetchCalendarDay(ref.date || "");
      var ev = matchCalendarEventInList((day && day.events) || [], ref);
      if (ev) openEventModal(ev);
      else showNoteToast("Встреча не найдена — возможно, её перенесли или удалили");
    } catch (e) {
      showNoteToast((e && e.message) || "Не удалось открыть");
    }
  }

  var calCardUiState = {};

  function calCardStateKey(type, id) {
    return String(type || "") + ":" + String(id || "").replace(/^task-/, "");
  }

  function rememberCalCardUi(type, id, patch) {
    var key = calCardStateKey(type, id);
    if (!key || key === ":") return;
    calCardUiState[key] = Object.assign({}, calCardUiState[key], patch || {});
    refreshDiscussFeedNow();
  }

  function calCardUiFor(open) {
    if (!open || open.id == null || open.id === "") return null;
    return calCardUiState[calCardStateKey(open.type, open.id)] || null;
  }

  function renderCalInfoCard(a) {
    var ui = { show_event: "cal", show_task: "taskBox", show_reminder: "bell" }[a.kind] || "cal";
    var state = calCardUiFor(a.open);
    var card = document.createElement("button");
    card.type = "button";
    card.className = "note-cal-card" + (state && state.done ? " is-done" : "");
    card.innerHTML = '<span class="note-cal-card-ico">' + DISCUSS_ICONS[ui] + "</span>";
    var copy = document.createElement("span");
    copy.className = "note-cal-card-copy";
    var t = document.createElement("b");
    t.textContent = a.title || "";
    var sub = document.createElement("small");
    var detail = a.detail || "";
    if (state && state.done && !/выполнен/i.test(detail)) detail = "Выполнена";
    sub.textContent = [a.when, detail].filter(Boolean).join(" · ");
    copy.appendChild(t);
    copy.appendChild(sub);
    card.appendChild(copy);
    var chev = document.createElement("span");
    chev.className = "note-cal-card-chev";
    chev.innerHTML = DISCUSS_ICONS.right;
    card.appendChild(chev);
    card.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      openCalendarRef(a.open);
    });
    return card;
  }

  function renderCalSlotCard(a) {
    var card = document.createElement("div");
    card.className = "note-cal-slot";
    var copy = document.createElement("div");
    copy.className = "note-cal-card-copy";
    var t = document.createElement("b");
    t.textContent = a.when || "";
    var sub = document.createElement("small");
    sub.textContent = [a.title, a.detail].filter(Boolean).join(" · ");
    copy.appendChild(t);
    copy.appendChild(sub);
    card.appendChild(copy);
    if (a.mine) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "note-discuss-edits-btn is-primary";
      b.textContent = "Поставить встречу";
      b.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        b.disabled = true;
        b.textContent = "Ставлю…";
        apiFetch("/gpt/calendar-actions/" + encodeURIComponent(a.id) + "/apply", { method: "POST" })
          .then(function (res) {
            // Остальные варианты этой подборки скрываются — перечитаем их статусы.
            Object.keys(calActionsCache).forEach(function (k) {
              if (calActionsCache[k] && calActionsCache[k].kind === "slot") delete calActionsCache[k];
            });
            if (res && res.action) calActionsCache[a.id] = res.action;
            refreshDiscussFeedNow();
            showNoteToast("Встреча создана");
            try {
              if (typeof loadActual === "function") loadActual({ silent: true });
            } catch (_) {}
          })
          .catch(function (err) {
            b.disabled = false;
            b.textContent = "Поставить встречу";
            showNoteToast((err && err.message) || "Не получилось");
          });
      });
      card.appendChild(b);
    }
    return card;
  }

  function calActionLine(a) {
    var ui = CAL_KIND_UI[a.kind] || ["cal", "", ""];
    var st = a.status;
    var head = ui[2];
    if (st === "undone") head = "Отменено";
    else if (st === "applied") head = "Удалено";
    else if (st === "dismissed") head = "Оставлено";
    var parts = [head + " «" + (a.title || ui[1]) + "»"];
    if (a.when) parts.push(a.when);
    if (a.detail && st !== "undone" && st !== "applied" && st !== "dismissed" && a.detail !== "удалить?") parts.push(a.detail);
    return { icon: st === "proposed" ? "trash" : ui[0], text: parts.join(" · ") + (st === "proposed" ? "?" : "") };
  }

  function calActionOp(a, op) {
    return apiFetch("/gpt/calendar-actions/" + encodeURIComponent(a.id) + "/" + op, { method: "POST" })
      .then(function (res) {
        if (res && res.action) calActionsCache[a.id] = res.action;
        refreshDiscussFeedNow();
        try {
          if (typeof loadActual === "function") loadActual({ silent: true });
        } catch (_) {}
        if (op === "undo") showNoteToast("Отменено");
        else if (op === "apply") showNoteToast("Удалено");
      })
      .catch(function (e) {
        showNoteToast((e && e.message) || "Не получилось");
      });
  }

  function appendCalendarActions(bubble, ids) {
    if (!ids || !ids.length) return;
    var missing = ids.filter(function (id) {
      return !calActionsCache[id];
    });
    if (missing.length) fetchCalendarActionsSoon(missing);
    var box = document.createElement("div");
    box.className = "note-discuss-cal";
    var slotHead = false;
    ids.forEach(function (id) {
      var a = calActionsCache[id];
      if (!a || a.missing) return;
      if (a.kind === "focus_item") return; // карточки разбора — под пузырём, см. appendFocusChatCards
      if (a.kind === "email_thread" || a.kind === "email_draft") {
        // письмо и черновик ответа — webapp/mail.js
        var mailCard = window.LeoMail && window.LeoMail.renderAction(a);
        if (mailCard) box.appendChild(mailCard);
        return;
      }
      if (a.kind === "show_event" || a.kind === "show_task" || a.kind === "show_reminder") {
        var cardState = calCardUiFor(a.open);
        if (cardState && cardState.deleted) return;
        box.appendChild(renderCalInfoCard(a));
        return;
      }
      if (a.kind === "slot" && a.status === "dismissed") return;
      if (a.kind === "slot" && a.status === "proposed") {
        if (!slotHead) {
          slotHead = true;
          var lbl = document.createElement("p");
          lbl.className = "note-cal-slots-label";
          lbl.textContent = "Выберите время — встреча создастся сразу";
          box.appendChild(lbl);
        }
        box.appendChild(renderCalSlotCard(a));
        return;
      }
      var line = calActionLine(a);
      var row = document.createElement("div");
      var faded = a.status === "undone" || a.status === "applied" || a.status === "dismissed";
      row.className = "note-discuss-cal-item" + (faded ? " is-faded" : "") + (a.status === "proposed" ? " is-proposed" : "");
      var info = document.createElement("div");
      info.className = "note-discuss-cal-info";
      info.innerHTML = DISCUSS_ICONS[line.icon] || DISCUSS_ICONS.cal;
      var t = document.createElement("span");
      t.textContent = line.text;
      info.appendChild(t);
      row.appendChild(info);
      if (a.mine) {
        var acts = document.createElement("div");
        acts.className = "note-discuss-edits-actions";
        function btn(label, cls, fn) {
          var b = document.createElement("button");
          b.type = "button";
          b.className = "note-discuss-edits-btn" + (cls ? " " + cls : "");
          b.textContent = label;
          b.addEventListener("click", function (e) {
            e.preventDefault();
            e.stopPropagation();
            b.disabled = true;
            fn();
          });
          acts.appendChild(b);
        }
        if (a.status === "done") {
          if (a.open) btn("Открыть", "", function () {
            openCalendarRef(a.open);
          });
          else if (a.link) btn("Открыть", "", function () {
            openExternal(a.link);
          });
          btn("Отменить", "", function () {
            calActionOp(a, "undo");
          });
        } else if (a.status === "proposed") {
          btn("Удалить", "is-danger", function () {
            calActionOp(a, "apply");
          });
          btn("Оставить", "", function () {
            calActionOp(a, "dismiss");
          });
        }
        if (acts.childNodes.length) row.appendChild(acts);
      }
      box.appendChild(row);
    });
    if (box.childNodes.length) bubble.appendChild(box);
  }

  // «Мои макеты» (свои раскладки слайдов) — общие для всех презентаций пользователя.
  var canvasLayoutsCache = null;

  function loadCanvasLayouts() {
    return apiFetch("/canvas-layouts", { method: "GET" })
      .then(function (data) {
        canvasLayoutsCache = (data && data.layouts) || [];
        return canvasLayoutsCache;
      })
      .catch(function () {
        return canvasLayoutsCache || [];
      });
  }

  async function saveCanvasLayout(sheetId, req) {
    var res = await apiFetch(webCanvasSheetPath(sheetId) + "/canvas-layouts", {
      method: "POST",
      body: JSON.stringify({ slide_id: req.slideId, html: req.html || null }),
    });
    await loadCanvasLayouts();
    return res && res.layout;
  }

  async function deleteCanvasLayout(id) {
    await apiFetch("/canvas-layouts/" + encodeURIComponent(String(id)), { method: "DELETE" });
    await loadCanvasLayouts();
  }

  // Последний выбранный стиль презентаций — новые презентации из чата строятся в нём.
  function rememberDeckTheme(theme) {
    try {
      localStorage.setItem("leo_deck_theme", String(theme || ""));
    } catch (_) {}
  }

  function preferredDeckTheme() {
    try {
      return localStorage.getItem("leo_deck_theme") || "";
    } catch (_) {
      return "";
    }
  }

  async function reviseWebCanvas(sheetId, req) {
    var path = webCanvasSheetPath(sheetId);
    await waitSheetPersistIdle(sheetId);
    var res = await apiFetch(path + "/canvas-revise", {
      method: "POST",
      body: JSON.stringify({
        comments: req.comments || {},
        html: req.html || null,
        insert_after: req.insertAfter || null,
        insert_text: req.insertText || null,
        insert_layout: req.insertLayout || null,
      }),
    });
    return {
      html: acceptWebCanvasItem(res && res.item),
      results: (res && res.results) || {},
      newIds: (res && res.new_ids) || [],
    };
  }

  // Шторка «Изображение»: крупные кнопки вместо мелкой панели внутри уменьшенного слайда
  // и своё описание для генерации (window.prompt в Telegram на телефоне часто не открывается).
  var canvasImageReq = null;

  // Библиотека абстракций: сгенерированы один раз (assistant/lib/image_style.py, Gemini 3.1 Flash),
  // лежат в webapp/canvas-kit/abstracts — выбор мгновенный и бесплатный. Только для стилей с фигурами (Аналитика).
  var CANVAS_ABSTRACTS = {
    analytic: [
      { file: "analytic-1.jpg", thumb: "analytic-1-thumb.jpg", name: "Лента из изумрудного стекла" },
      { file: "analytic-2.jpg", thumb: "analytic-2-thumb.jpg", name: "Стеклянный тор" },
      { file: "analytic-3.jpg", thumb: "analytic-3-thumb.jpg", name: "Стеклянные ступени" },
      { file: "analytic-4.jpg", thumb: "analytic-4-thumb.jpg", name: "Шар с золотой орбитой" },
      { file: "analytic-5.jpg", thumb: "analytic-5-thumb.jpg", name: "Волна светящихся линий" },
      { file: "analytic-6.jpg", thumb: "analytic-6-thumb.jpg", name: "Призма и лучи" },
      { file: "analytic-7.jpg", thumb: "analytic-7-thumb.jpg", name: "Арка-портал" },
      { file: "analytic-8.jpg", thumb: "analytic-8-thumb.jpg", name: "Парящие стеклянные кубы" },
      { file: "analytic-9.jpg", thumb: "analytic-9-thumb.jpg", name: "Капля жидкого хрома" },
      { file: "analytic-10.jpg", thumb: "analytic-10-thumb.jpg", name: "Стеклянный рельеф" }
    ],
    lime: [
      "Волна лаймового стекла", "Бархатные дюны", "Лента из стекла", "Ступени роста", "Стеклянный тор",
      "Слоистый рельеф", "Капля стекла", "Арка", "Спокойная волна", "Металлическая дуга"
    ].map(function (name, i) {
      return { file: "lime-" + (i + 1) + ".jpg", thumb: "lime-" + (i + 1) + "-thumb.jpg", name: name };
    }),
  };

  // 3D-объекты карточек «Карточки с 3D-визуалом» (scripts/gen_card_objects.py, webapp/canvas-kit/objects).
  // По умолчанию подставляет шаблон; здесь — замена на другой объект.
  var CANVAS_CARD_OBJECTS = [
    ["orb", "Шар с орбитами"], ["rings", "Стеклянные диски"], ["prism", "Призма"], ["cube", "Куб"],
    ["torus", "Тор"], ["steps", "Столбики роста"], ["shield", "Щит"], ["funnel", "Воронка"],
    ["wave", "Волна"], ["nodes", "Сеть узлов"], ["target", "Мишень"], ["cluster", "Кластер кубов"],
    ["hourglass", "Песочные часы"], ["spiral", "Спираль"], ["bubbles", "Диалог"], ["arch", "Арка"],
    ["bolt", "Молния"], ["gear", "Шестерёнки"], ["pie", "Диаграмма"], ["coins", "Монеты"],
    ["layers", "Слои"], ["puzzle", "Пазл"], ["compass", "Компас"], ["bulb", "Лампочка"]
  ];

  // Объекты в цветах стиля: «Лайм» — свой набор под белый и чёрный слайд (objects-lime/<key>-light|dark.jpg).
  function canvasCardObjects(req) {
    var lime = String((req && req.theme) || "") === "lime";
    var sfx = lime ? "-" + (String(req.surface || "") === "dark" ? "dark" : "light") : "";
    return CANVAS_CARD_OBJECTS.map(function (o) {
      return { file: o[0] + sfx + ".jpg", thumb: o[0] + sfx + "-thumb.jpg", name: o[1], dir: lime ? "objects-lime" : "objects" };
    });
  }

  function canvasAbstractUrl(file, dir) {
    if (dir) return "/webapp/canvas-kit/" + dir + "/" + file + "?v=" + encodeURIComponent(WEBAPP_BUILD);
    return "/webapp/canvas-kit/abstracts/" + file + "?v=" + encodeURIComponent(WEBAPP_BUILD);
  }

  async function urlToDataUrl(url) {
    var res = await fetch(url, { cache: "force-cache" });
    if (!res.ok) throw new Error("Не удалось загрузить картинку");
    var blob = await res.blob();
    return await new Promise(function (resolve, reject) {
      var r = new FileReader();
      r.onload = function () { resolve(String(r.result || "")); };
      r.onerror = function () { reject(new Error("Не удалось прочитать картинку")); };
      r.readAsDataURL(blob);
    });
  }

  function renderCanvasImageLibrary(req) {
    var box = document.getElementById("canvas-image-lib");
    var grid = document.getElementById("canvas-image-lib-grid");
    if (!box || !grid) return;
    var list = req.isDecor ? CANVAS_ABSTRACTS[String(req.theme || "analytic")] || [] : req.isVisual ? canvasCardObjects(req) : [];
    box.classList.toggle("hidden", !list.length);
    var label = box.querySelector(".canvas-image-label");
    if (label) label.textContent = req.isVisual ? "Готовые 3D-объекты" : "Готовые абстракции";
    grid.innerHTML = "";
    list.forEach(function (a) {
      var b = document.createElement("button");
      b.type = "button";
      b.setAttribute("role", "listitem");
      b.setAttribute("aria-label", a.name);
      b.title = a.name;
      var img = document.createElement("img");
      img.alt = "";
      img.loading = "lazy";
      img.src = canvasAbstractUrl(a.thumb || a.file, a.dir);
      b.appendChild(img);
      b.addEventListener("click", async function () {
        var cur = canvasImageReq;
        if (!cur || b.getAttribute("aria-busy") === "true") return;
        b.setAttribute("aria-busy", "true");
        try {
          // 3D-объект — путём к файлу: сервер узнаёт его и рисует как объект карточки (data URL при сохранении).
          var dataUrl = a.dir ? "/webapp/canvas-kit/" + a.dir + "/" + a.file : await urlToDataUrl(canvasAbstractUrl(a.file));
          closeCanvasImageSheet();
          // Без описания — помечается как «своя»: «Перерисовать картинки» её не трогает.
          if (cur.req.applyImg) cur.req.applyImg(dataUrl, "");
          showNoteToast(a.dir ? "Объект поставлен" : "Абстракция поставлена");
        } catch (e) {
          showNoteToast((e && e.message) || "Не удалось поставить картинку");
        } finally {
          b.removeAttribute("aria-busy");
        }
      });
      grid.appendChild(b);
    });
  }

  function openCanvasImageSheet(sheetId, req) {
    var ov = document.getElementById("canvas-image-overlay");
    if (!ov) return;
    canvasImageReq = { sheetId: String(sheetId || ""), req: req };
    var ta = document.getElementById("canvas-image-prompt");
    if (ta) ta.value = String(req.prompt || "");
    var clear = document.getElementById("canvas-image-clear");
    if (clear) {
      clear.classList.toggle("hidden", !req.hasImg);
      clear.textContent = req.isDecor ? "Вернуть фигуру" : req.isVisual ? "Вернуть 3D-визуал" : "Убрать";
    }
    renderCanvasImageLibrary(req);
    syncCanvasImageGenerateBtn();
    ov.classList.remove("hidden");
    ov.setAttribute("aria-hidden", "false");
    onModalSheetOpen();
    syncAppOverlay();
  }

  function closeCanvasImageSheet() {
    var ov = document.getElementById("canvas-image-overlay");
    if (!ov) return;
    canvasImageReq = null;
    ov.classList.add("hidden");
    ov.setAttribute("aria-hidden", "true");
    onModalSheetClose();
    syncAppOverlay();
  }

  function syncCanvasImageGenerateBtn() {
    var ta = document.getElementById("canvas-image-prompt");
    var btn = document.getElementById("canvas-image-generate");
    if (btn) btn.disabled = !(ta && ta.value.trim());
  }

  // Иконка пункта списка в презентации: каталог с описаниями (assistant/lib/canvas_icons.py), поиск, «Убрать».
  var canvasIconsCache = null;
  var canvasIconReq = null;

  function loadCanvasIcons() {
    if (canvasIconsCache) return Promise.resolve(canvasIconsCache);
    return apiFetch("/canvas-icons", { method: "GET" }).then(function (res) {
      canvasIconsCache = (res && Array.isArray(res.icons) ? res.icons : []).filter(function (x) {
        return x && x.name && x.svg;
      });
      return canvasIconsCache;
    });
  }

  function canvasIconSvg(inner) {
    return '<svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor" aria-hidden="true">' + inner + "</svg>";
  }

  function renderCanvasIconGrid() {
    var grid = document.getElementById("canvas-icon-grid");
    var q = document.getElementById("canvas-icon-search");
    var empty = document.getElementById("canvas-icon-empty");
    if (!grid || !canvasIconsCache) return;
    var words = String((q && q.value) || "").toLowerCase().trim().split(/\s+/).filter(Boolean);
    var cur = canvasIconReq ? canvasIconReq.icon : "";
    var list = canvasIconsCache.filter(function (x) {
      var hay = (x.name.replace(/_/g, " ") + " " + x.desc).toLowerCase();
      return words.every(function (w) { return hay.indexOf(w) >= 0; });
    });
    grid.innerHTML = "";
    list.forEach(function (x) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "canvas-icon-btn" + (x.name === cur ? " is-current" : "");
      b.setAttribute("role", "listitem");
      b.setAttribute("aria-label", x.desc);
      b.title = x.desc;
      b.innerHTML = canvasIconSvg(x.svg);
      b.addEventListener("click", function () { pickCanvasIcon(x.name); });
      grid.appendChild(b);
    });
    if (empty) empty.classList.toggle("hidden", list.length > 0);
  }

  function pickCanvasIcon(name) {
    var req = canvasIconReq;
    closeCanvasIconSheet();
    if (!req || typeof req.apply !== "function") return;
    if (String(name || "") === String(req.icon || "")) return;
    var found = (canvasIconsCache || []).filter(function (x) { return x.name === name; })[0];
    req.apply(name, found ? found.svg : "");
  }

  function openCanvasIconSheet(req) {
    var ov = document.getElementById("canvas-icon-overlay");
    if (!ov || !req) return;
    canvasIconReq = req;
    var q = document.getElementById("canvas-icon-search");
    if (q) q.value = "";
    var clear = document.getElementById("canvas-icon-clear");
    if (clear) clear.classList.toggle("hidden", !req.icon);
    var grid = document.getElementById("canvas-icon-grid");
    if (grid && !canvasIconsCache) grid.innerHTML = '<p class="canvas-icon-note">Загружаем иконки…</p>';
    ov.classList.remove("hidden");
    ov.setAttribute("aria-hidden", "false");
    onModalSheetOpen();
    syncAppOverlay();
    loadCanvasIcons()
      .then(function () {
        if (canvasIconReq === req) renderCanvasIconGrid();
      })
      .catch(function (e) {
        if (grid) grid.innerHTML = "";
        showNoteToast((e && e.message) || "Не удалось загрузить иконки");
      });
    if (q && isDesktopLayout()) setTimeout(function () { q.focus(); }, 30);
  }

  function closeCanvasIconSheet() {
    var ov = document.getElementById("canvas-icon-overlay");
    if (!ov || ov.classList.contains("hidden")) return;
    canvasIconReq = null;
    ov.classList.add("hidden");
    ov.setAttribute("aria-hidden", "true");
    onModalSheetClose();
    syncAppOverlay();
  }

  function bindCanvasIconSheet() {
    var ov = document.getElementById("canvas-icon-overlay");
    if (!ov) return;
    ov.addEventListener("click", function (e) {
      if (e.target === ov) closeCanvasIconSheet();
    });
    ov.addEventListener("keydown", function (e) {
      if (e.key === "Escape") closeCanvasIconSheet();
    });
    var close = document.getElementById("canvas-icon-close");
    if (close) close.addEventListener("click", closeCanvasIconSheet);
    var q = document.getElementById("canvas-icon-search");
    if (q) q.addEventListener("input", renderCanvasIconGrid);
    var clear = document.getElementById("canvas-icon-clear");
    if (clear) clear.addEventListener("click", function () { pickCanvasIcon(""); });
  }

  function bindCanvasImageSheet() {
    var ov = document.getElementById("canvas-image-overlay");
    if (!ov) return;
    ov.addEventListener("click", function (e) {
      if (e.target === ov) closeCanvasImageSheet();
    });
    var close = document.getElementById("canvas-image-close");
    if (close) close.addEventListener("click", closeCanvasImageSheet);
    var ta = document.getElementById("canvas-image-prompt");
    if (ta) ta.addEventListener("input", syncCanvasImageGenerateBtn);
    function run(action) {
      var cur = canvasImageReq;
      if (!cur) return;
      var prompt = ta ? ta.value.trim() : "";
      closeCanvasImageSheet();
      handleWebCanvasMedia(cur.sheetId, Object.assign({}, cur.req, { action: action, prompt: prompt }));
    }
    var gen = document.getElementById("canvas-image-generate");
    if (gen) gen.addEventListener("click", function () { run("generate"); });
    var up = document.getElementById("canvas-image-upload");
    if (up) up.addEventListener("click", function () { run("upload"); });
    var clear = document.getElementById("canvas-image-clear");
    if (clear) clear.addEventListener("click", function () { run("clear"); });
  }

  async function handleWebCanvasMedia(sheetId, req) {
    if (!req) return;
    var action = String(req.action || "");
    if (action === "menu") {
      openCanvasImageSheet(sheetId, req);
      return;
    }
    var setBusy = typeof req.setBusy === "function" ? req.setBusy : null;
    try {
      if (action === "clear") {
        if (req.clearMedia) req.clearMedia();
        showNoteToast("Картинка убрана");
        return;
      }
      if (action === "upload") {
        var file = await pickLocalImageFile();
        if (!file) return;
        if (setBusy) setBusy(true, "Загрузка…");
        showNoteToast("Загружаю…");
        try {
          var uploaded = await uploadCanvasImageFile(file);
          if (req.applyImg) req.applyImg(uploaded);
          showNoteToast("Картинка вставлена");
        } finally {
          if (setBusy) setBusy(false);
        }
        return;
      }
      if (action === "generate") {
        var prompt = String(req.prompt || "").trim();
        if (!prompt) {
          // Старые фреймы (без шторки) — спрашиваем описание через шторку.
          openCanvasImageSheet(sheetId, Object.assign({}, req, { action: "menu" }));
          return;
        }
        if (setBusy) setBusy(true, "Генерация…");
        showNoteToast("Генерирую… это займёт до 30 секунд");
        try {
          var generated = await generateCanvasImageDataUrl(prompt, sheetId);
          if (req.applyImg) req.applyImg(generated, prompt);
          showNoteToast("Картинка сгенерирована");
        } finally {
          if (setBusy) setBusy(false);
        }
        return;
      }
    } catch (e) {
      if (setBusy) setBusy(false);
      console.warn("handleWebCanvasMedia", e);
      showNoteToast((e && e.message) || "Не удалось обновить картинку");
    }
  }

  async function refreshWebCanvasSheet(sheetId, which) {
    var sid = String(sheetId || "");
    var noteId = noteSheetsNoteId();
    if (!sid || !noteId) return;
    try {
      var data = await apiFetch(
        "/notes/local/" + encodeURIComponent(String(noteId)) + "/sheets",
        { method: "GET" }
      );
      var sheets = (data && data.sheets) || [];
      if (sheets.length) noteSheetState.sheets = sheets;
      renderNoteSheetChips();
      var sheet = findNoteSheet(sid);
      if (!sheet || !isWebSheet(sheet)) {
        showNoteToast("Лист не найден");
        return;
      }
      var html = String(sheet.body || sheet.description || "");
      if (which === "right") {
        if (
          noteSheetState.rightWebCanvas &&
          typeof noteSheetState.rightWebCanvas.setHtml === "function" &&
          String(noteSheetState.rightId) === sid
        ) {
          noteSheetState.rightWebCanvas.setHtml(html);
        } else {
          mountRightWebCanvas(sheet);
        }
      } else {
        reloadLeftWebCanvasHtml(sheet);
      }
      showNoteToast("Презентация обновлена");
    } catch (e) {
      console.warn("refreshWebCanvasSheet", e);
      showNoteToast("Не удалось обновить презентацию");
    }
  }

  function reloadLeftWebCanvasHtml(sheet) {
    if (!sheet || !isWebSheet(sheet)) return;
    var html = String(sheet.body || sheet.description || "");
    if (
      noteSheetState.leftWebCanvas &&
      typeof noteSheetState.leftWebCanvas.setHtml === "function" &&
      String(noteSheetState.leftId) === String(sheet.id)
    ) {
      noteSheetState.leftWebCanvas.setHtml(html);
      return;
    }
    applyLeftSheetHtml(sheet);
  }

  async function applyCanvasChatResult(canvasActions) {
    var rows = Array.isArray(canvasActions) ? canvasActions : [];
    if (!rows.length) return;
    var noteId = noteSheetsNoteId();
    if (!noteId) return;
    try {
      var data = await apiFetch(
        "/notes/local/" + encodeURIComponent(String(noteId)) + "/sheets",
        { method: "GET" }
      );
      var sheets = (data && data.sheets) || [];
      if (sheets.length) noteSheetState.sheets = sheets;
      renderNoteSheetChips();
      var last = rows[rows.length - 1];
      var sid = String((last && last.sheet_id) || "");
      var sheet = sid ? findNoteSheet(sid) : null;
      if (sheet && isBoardSheet(sheet)) {
        // Доску нарисовал Лео: открыть её (или обновить открытую). В совместном режиме
        // правка уже пришла через Yjs — тело не подменяем.
        var json = String(sheet.body || sheet.description || "");
        var shown = String(noteSheetState.leftId) === sid ? noteSheetState.leftBoard
          : noteSheetState.rightMode === "sheet" && String(noteSheetState.rightId) === sid ? noteSheetState.rightBoard : null;
        if (shown) {
          if (!shown.isYjsAttached()) shown.setJson(json);
        } else {
          await switchLeftSheet(sid);
        }
        showNoteToast(last.action === "update" ? "Доска обновлена" : "Доска готова");
      } else if (sheet && isWebSheet(sheet)) {
        if (String(noteSheetState.leftId) === sid) {
          reloadLeftWebCanvasHtml(sheet);
        } else {
          await switchLeftSheet(sid);
          // switchLeftSheet no-ops when already open; force html if still needed
          if (String(noteSheetState.leftId) === sid) reloadLeftWebCanvasHtml(sheet);
        }
        showNoteToast("Презентация обновлена");
      }
      clearCanvasSelections();
    } catch (e) {
      console.warn("applyCanvasChatResult", e);
    }
  }

  function noteRefDisplayTitle(item) {
    return String((item && (item.title || item.content)) || "").trim() || "Без названия";
  }

  function buildNoteRefSuggestItems(query) {
    var q = String(query || "").trim().toLowerCase();
    var currentId = String(noteSheetsNoteId() || "");
    var items = [];
    var seen = {};

    function pushItem(item) {
      if (!item) return;
      var key = item.chatId
        ? "chat::" + String(item.chatId)
        : String(item.noteId || "") + "::" + String(item.sheetId || "");
      if (!item.chatId && !item.noteId) return;
      if (seen[key]) return;
      seen[key] = true;
      items.push(item);
    }

    (noteSheetState.sheets || []).forEach(function (s) {
      if (!s || !currentId) return;
      if (s.is_primary || isPrimarySheetId(s.id)) return;
      var title = String(s.title || "Лист").trim() || "Лист";
      if (q && title.toLowerCase().indexOf(q) < 0) return;
      pushItem({
        kind: "sheet",
        noteId: currentId,
        sheetId: String(s.id),
        label: title,
        hint: "Лист этой заметки",
      });
    });

    var notes = (notesDataCache && notesDataCache.local_notes) || [];
    notes.forEach(function (n) {
      var id = String((n && n.id) || "");
      if (!id || id === currentId) return;
      if (String(id).indexOf("tmp_") === 0) return;
      if (looksLikeTranscriptionNote(n)) return;
      var title = noteRefDisplayTitle(n);
      if (q && title.toLowerCase().indexOf(q) < 0) return;
      pushItem({
        kind: "note",
        noteId: id,
        sheetId: "",
        label: title,
        hint: "Заметка",
      });
    });

    var transcriptions = (notesDataCache && notesDataCache.transcriptions) || [];
    transcriptions.forEach(function (n) {
      var id = String((n && n.id) || "");
      if (!id || id === currentId) return;
      if (String(id).indexOf("tmp_") === 0) return;
      var title = noteRefDisplayTitle(n);
      if (q && title.toLowerCase().indexOf(q) < 0) return;
      var isSummary = transcriptionHasSummary(n);
      pushItem({
        kind: isSummary ? "summary" : "transcription",
        noteId: id,
        sheetId: "",
        label: title,
        hint: isSummary ? "Саммари" : "Транскрипция",
      });
    });

    visibleChatThreads().forEach(function (t) {
      var id = String((t && t.id) || "");
      if (!id) return;
      var title = String((t && t.title) || "").trim() || "Чат";
      if (q && title.toLowerCase().indexOf(q) < 0) return;
      pushItem({
        kind: "chat",
        refKind: "chat",
        refId: id,
        chatId: id,
        noteId: "",
        sheetId: "",
        label: title,
        hint: "Чат",
      });
    });

    return items.slice(0, 12);
  }

  function searchNoteLikeRefItems(query, done) {
    if (typeof done !== "function") return;
    var gen = (searchNoteLikeRefItems._gen = (searchNoteLikeRefItems._gen || 0) + 1);
    function finish(items) {
      if (gen !== searchNoteLikeRefItems._gen) return;
      done(items || []);
    }
    function enrichWithForeignSheets(baseItems) {
      var q = String(query || "").trim().toLowerCase();
      if (!q) {
        finish(baseItems);
        return;
      }
      var currentId = String(noteSheetsNoteId() || "");
      var notes = ((notesDataCache && notesDataCache.local_notes) || [])
        .filter(function (n) {
          var id = String((n && n.id) || "");
          if (!id || id === currentId || String(id).indexOf("tmp_") === 0) return false;
          if (looksLikeTranscriptionNote(n)) return false;
          return noteRefDisplayTitle(n).toLowerCase().indexOf(q) >= 0;
        })
        .slice(0, 3);
      if (!notes.length) {
        finish(baseItems);
        return;
      }
      Promise.all(
        notes.map(function (n) {
          return apiFetch("/notes/local/" + encodeURIComponent(String(n.id)) + "/sheets", {
            method: "GET",
          })
            .then(function (data) {
              return { note: n, sheets: (data && data.sheets) || [] };
            })
            .catch(function () {
              return { note: n, sheets: [] };
            });
        })
      ).then(function (rows) {
        if (gen !== searchNoteLikeRefItems._gen) return;
        var seen = {};
        var merged = [];
        function push(item) {
          if (!item) return;
          var key = item.chatId
            ? "chat::" + String(item.chatId)
            : String(item.noteId || "") + "::" + String(item.sheetId || "");
          if (!item.chatId && !item.noteId) return;
          if (seen[key]) return;
          seen[key] = true;
          merged.push(item);
        }
        (baseItems || []).forEach(push);
        rows.forEach(function (row) {
          var noteTitle = noteRefDisplayTitle(row.note);
          (row.sheets || []).forEach(function (s) {
            if (!s || s.is_primary || isPrimarySheetId(s.id)) return;
            var sheetTitle = String(s.title || "Лист").trim() || "Лист";
            if (
              sheetTitle.toLowerCase().indexOf(q) < 0 &&
              noteTitle.toLowerCase().indexOf(q) < 0
            ) {
              return;
            }
            push({
              kind: "sheet",
              noteId: String(row.note.id),
              sheetId: String(s.id),
              label: sheetTitle,
              hint: noteTitle,
            });
          });
        });
        finish(merged.slice(0, 12));
      });
    }
    function run() {
      if (notesDataCache) splitTranscriptionsOutOfLocalNotes(notesDataCache);
      var base = buildNoteRefSuggestItems(query);
      finish(base);
      enrichWithForeignSheets(base);
    }
    var tasks = [];
    if (!notesDataCache || !notesDataCache.local_notes) {
      tasks.push(
        apiFetch("/notes?limit=120", { method: "GET" })
          .then(function (data) {
            if (gen !== searchNoteLikeRefItems._gen) return;
            notesDataCache = data || notesDataCache;
            if (data) {
              splitTranscriptionsOutOfLocalNotes(notesDataCache);
              writeMiniappCache("notes", data);
            }
          })
          .catch(function () {})
      );
    }
    if (!(chatThreadsCache || []).length) {
      tasks.push(loadChatThreads().catch(function () {}));
    }
    if (!tasks.length) {
      run();
      return;
    }
    Promise.all(tasks).then(function () {
      if (gen !== searchNoteLikeRefItems._gen) return;
      run();
    });
  }

  // «+» в заметке: задачи, напоминания и люди (заметки/листы — searchNoteLikeRefItems).
  var noteRefDataCache = {};

  function cachedRefList(key, path, pick) {
    var hit = noteRefDataCache[key];
    if (hit && Date.now() - hit.at < 60000) return Promise.resolve(hit.items);
    return apiFetch(path, { method: "GET" })
      .then(function (data) {
        var items = pick(data) || [];
        noteRefDataCache[key] = { at: Date.now(), items: items };
        return items;
      })
      .catch(function () {
        return (hit && hit.items) || [];
      });
  }

  function noteRefShortDate(iso) {
    var d = iso ? new Date(iso) : null;
    if (!d || isNaN(d.getTime())) return "";
    return d.getDate() + " " + RU_MON[d.getMonth()];
  }

  function searchTaskRefItems(query) {
    return apiFetch("/calendar/tasks?q=" + encodeURIComponent(String(query || "").trim()), { method: "GET" })
      .then(function (r) {
        return ((r && r.tasks) || []).map(function (t) {
          var when = noteRefShortDate(t.start_at || (t.event && t.event.start && t.event.start.dateTime));
          return {
            refKind: "task",
            refId: String(t.id),
            label: String(t.title || "").trim() || "Задача",
            hint: ["Задача", t.done ? "выполнена" : when].filter(Boolean).join(" · "),
          };
        });
      })
      .catch(function () {
        return [];
      });
  }

  function searchReminderRefItems(query) {
    var q = String(query || "").trim().toLowerCase();
    return cachedRefList("reminders", "/reminders", function (d) {
      return d && d.items;
    }).then(function (items) {
      var now = Date.now();
      return items
        .filter(function (r) {
          if (!r || !r.id || String(r.id).indexOf("tmp_") === 0) return false;
          return !q || String(r.task || "").toLowerCase().indexOf(q) >= 0;
        })
        .sort(function (a, b) {
          // Предстоящие — первыми, ближайшие сверху; прошедшие — в конце, свежие сверху.
          var ta = new Date(a.when_iso).getTime() || 0;
          var tb = new Date(b.when_iso).getTime() || 0;
          var pa = a.done || ta < now;
          var pb = b.done || tb < now;
          if (pa !== pb) return pa ? 1 : -1;
          return pa ? tb - ta : ta - tb;
        })
        .slice(0, 15)
        .map(function (r) {
          return {
            refKind: "reminder",
            refId: String(r.id),
            label: String(r.task || "").trim() || "Напоминание",
            hint: ["Напоминание", noteRefShortDate(r.when_iso)].filter(Boolean).join(" · "),
          };
        });
    });
  }

  function searchPersonRefItems(query) {
    var q = String(query || "").trim().toLowerCase().replace(/^@/, "");
    return cachedRefList("contacts", "/contacts", function (d) {
      return d && d.items;
    }).then(function (items) {
      return items
        .filter(function (c) {
          if (!c || !c.key) return false;
          if (!q) return true;
          var hay = [c.name, c.email, c.telegram_username, (c.aliases || []).join(" ")].join(" ").toLowerCase();
          return hay.indexOf(q) >= 0;
        })
        .slice(0, 15)
        .map(function (c) {
          var sub = c.email || (c.telegram_username ? "@" + c.telegram_username : "");
          return {
            refKind: "person",
            refId: String(c.key),
            label: String(c.name || "").trim() || sub || "Человек",
            hint: ["Человек", c.name ? sub : ""].filter(Boolean).join(" · "),
          };
        });
    });
  }

  function searchNoteRefItems(query, done, kind) {
    if (typeof done !== "function") return;
    var gen = (searchNoteRefItems._gen = (searchNoteRefItems._gen || 0) + 1);
    function finish(items) {
      if (gen !== searchNoteRefItems._gen) return;
      done(items || []);
    }
    if (kind === "note") {
      searchNoteLikeRefItems(query, finish);
      return;
    }
    if (kind === "task") {
      searchTaskRefItems(query).then(finish);
      return;
    }
    if (kind === "reminder") {
      searchReminderRefItems(query).then(finish);
      return;
    }
    if (kind === "person") {
      searchPersonRefItems(query).then(finish);
      return;
    }
    // Без фильтра — понемногу из каждого типа, заметки отдаём сразу, остальное догружаем.
    var parts = { note: [], task: [], person: [], reminder: [] };
    function emit() {
      finish(
        [].concat(
          parts.task.slice(0, 4),
          parts.note.slice(0, 5),
          parts.person.slice(0, 4),
          parts.reminder.slice(0, 3)
        )
      );
    }
    searchNoteLikeRefItems(query, function (items) {
      parts.note = items || [];
      emit();
    });
    Promise.all([
      searchTaskRefItems(query).then(function (x) {
        parts.task = x;
      }),
      searchPersonRefItems(query).then(function (x) {
        parts.person = x;
      }),
      searchReminderRefItems(query).then(function (x) {
        parts.reminder = x;
      }),
    ]).then(emit);
  }

  function openEntityRefFromChip(kind, id, label) {
    var rid = String(id || "").trim();
    if (!rid) return;
    if (kind === "task") {
      apiFetch("/calendar/tasks/" + encodeURIComponent(rid), { method: "GET" })
        .then(function (r) {
          var task = r && r.task;
          if (!task) throw { status: 404 };
          openTaskModal(
            Object.assign({}, task.event || {}, task, { id: "task-" + task.id, task_id: task.id })
          );
        })
        .catch(function (e) {
          alert(e && e.status === 404 ? "Задача «" + (label || "") + "» удалена или недоступна" : (e && e.message) || "Не удалось открыть задачу");
        });
      return;
    }
    if (kind === "reminder") {
      delete noteRefDataCache.reminders;
      cachedRefList("reminders", "/reminders", function (d) {
        return d && d.items;
      }).then(function (items) {
        var r = items.filter(function (x) {
          return x && String(x.id) === rid;
        })[0];
        if (r) openReminderModal(r);
        else alert("Напоминание «" + (label || "") + "» удалено");
      });
      return;
    }
    if (kind === "person") {
      cachedRefList("contacts", "/contacts", function (d) {
        return d && d.items;
      }).then(function (items) {
        var c = items.filter(function (x) {
          return x && String(x.key || "").toLowerCase() === rid.toLowerCase();
        })[0];
        if (c) openContactDetail(c);
        else alert("Контакт «" + (label || "") + "» не найден");
      });
    }
  }

  // Строка «Заметки» в карточке задачи/напоминания/контакта: где сущность упомянута через «+».
  function mountNoteBacklinks(host, kind, id, closeCard) {
    if (!host || !id) return;
    var token = (host._backlinksToken = {});
    flushOpenNoteForShare()
      .catch(function () {})
      .then(function () {
        return apiFetch(
          "/notes/backlinks?kind=" + encodeURIComponent(kind) + "&id=" + encodeURIComponent(String(id)),
          { method: "GET" }
        );
      })
      .then(function (r) {
        if (host._backlinksToken !== token || !host.isConnected) return;
        var items = (r && r.items) || [];
        host.innerHTML = "";
        host.classList.toggle("hidden", !items.length);
        if (!items.length) return;
        var label = document.createElement("span");
        label.className = "event-sheet-row-label";
        label.textContent = items.length > 1 ? "Заметки" : "Заметка";
        host.appendChild(label);
        var chips = document.createElement("span");
        chips.className = "note-backlinks";
        items.forEach(function (it) {
          var b = document.createElement("button");
          b.type = "button";
          b.className = "note-backlink-chip";
          b.innerHTML = it.is_transcription ? WAVE_ICON : NOTE_ICON;
          var t = document.createElement("span");
          t.textContent = it.sheet_id ? it.title + " · " + it.sheet_title : it.title;
          b.appendChild(t);
          b.title = t.textContent;
          b.addEventListener("click", function (e) {
            e.preventDefault();
            e.stopPropagation();
            if (typeof closeCard === "function") closeCard();
            openNoteRefFromChip(String(it.note_id), it.sheet_id || "");
          });
          chips.appendChild(b);
        });
        host.appendChild(chips);
      })
      .catch(function () {
        if (host._backlinksToken === token) host.classList.add("hidden");
      });
  }

  function openNoteRefFromChip(noteId, sheetId, chatId) {
    var cid = String(chatId || "").trim();
    if (cid) {
      setTab("notes", { noAnim: true });
      setNotesSubTab("chats");
      var thread = null;
      for (var i = 0; i < (chatThreadsCache || []).length; i++) {
        if (String(chatThreadsCache[i].id) === cid) {
          thread = chatThreadsCache[i];
          break;
        }
      }
      openChatThread(thread || { id: cid });
      return;
    }
    var nid = String(noteId || "").trim();
    var sid = String(sheetId || "").trim();
    if (!nid) return;
    var current = String(noteSheetsNoteId() || "");
    if (current && current === nid) {
      if (sid && !isPrimarySheetId(sid)) switchLeftSheet(sid);
      return;
    }
    noteSheetState.pendingOpenSheetId =
      sid && !isPrimarySheetId(sid) ? sid : "";
    var note = resolveLocalNoteFromCache({ id: nid });
    if (note && looksLikeTranscriptionNote(note)) {
      setNotesSubTab("transcriptions");
    }
    openNoteDetail(note && note.id ? note : { id: nid }, { isLocal: true });
  }

  function getLeftNoteRichEditor() {
    var body = getNoteEditorBodyEl();
    return body && body._noteRichEditor ? body._noteRichEditor : null;
  }

  function getActiveNoteRichEditor() {
    // Чужая заметка в правом слое не должна подменять dirty/save основной.
    if (
      noteSheetState.focus === "right" &&
      noteSheetState.rightEditor &&
      noteSheetState.rightMode === "sheet"
    ) {
      return noteSheetState.rightEditor;
    }
    if (
      noteSheetState.focus === "right" &&
      noteSheetState.rightEditor &&
      noteSheetState.rightMode === "note" &&
      isNoteDiscussionOpen()
    ) {
      return noteSheetState.rightEditor;
    }
    return getLeftNoteRichEditor();
  }

  function readActiveNoteEditorHtml(editorInst) {
    var inst = editorInst || getActiveNoteRichEditor();
    if (!inst || typeof inst.getHtml !== "function") return "";
    return inst.getHtml();
  }

  function bindNoteTaskHandlers(root, noteId, getBody, onSaved) {
    if (!root || !noteId) return;
    root.querySelectorAll(".note-task input[type=checkbox]").forEach(function (cb) {
      cb.addEventListener("change", async function () {
        var taskIndex = parseInt(cb.getAttribute("data-task-index") || "-1", 10);
        var lineIndex = parseInt(cb.getAttribute("data-line") || "-1", 10);
        var body = typeof getBody === "function" ? getBody() : "";
        var next = body;
        if (taskIndex >= 0 && window.NoteHtml && window.NoteHtml.toggleTaskInStorageHtml) {
          next = window.NoteHtml.toggleTaskInStorageHtml(body, taskIndex);
        } else if (lineIndex >= 0) {
          next = toggleNoteTaskAtLine(body, lineIndex);
        }
        if (next === body) return;
        try {
          await apiFetch("/notes/local/" + encodeURIComponent(String(noteId)), {
            method: "PATCH",
            body: JSON.stringify({ description: next }),
          });
          if (typeof onSaved === "function") onSaved(next);
          var contentRoot = root.querySelector(".note-body-html, .note-body-plain") || root;
          contentRoot.innerHTML = wrapTablesForScroll(
            renderRichTextInner(next, { interactive: true })
          );
          bindNoteTaskHandlers(root, noteId, function () {
            return next;
          }, onSaved);
        } catch (e) {
          alert(e.message || String(e));
          cb.checked = !cb.checked;
          var li = cb.closest(".note-task");
          if (li) li.classList.toggle("note-task--checked", cb.checked);
        }
      });
    });
  }

  function toggleNoteTaskAtLine(body, lineIndex) {
    var lines = String(body || "").split("\n");
    if (lineIndex < 0 || lineIndex >= lines.length) return body;
    var line = lines[lineIndex];
    var m = line.match(/^(\s*-\s+)\[([ xX])\]\s+(.*)$/);
    if (!m) return body;
    var checked = String(m[2]).toLowerCase() === "x";
    lines[lineIndex] = m[1] + "[" + (checked ? " " : "x") + "] " + m[3];
    return lines.join("\n");
  }

  function bindChatsNewBtnOnce() {
    var b = document.getElementById("chats-new-btn");
    if (!b || b._bound) return;
    b._bound = true;
    b.addEventListener("click", function (e) {
      e.preventDefault();
      createAndOpenChatThread();
    });
    window.addEventListener("resize", syncNotesCreateFab);
  }

  // ---- Кнопка «вниз» в ленте обсуждения/чата: появляется, когда ушли вверх от последних сообщений ----
  function ensureDiscussScrollDownBtn() {
    var sheet = document.querySelector("#note-discussion-overlay .note-discussion-sheet");
    var scroll = sheet && sheet.querySelector(".note-discussion-scroll");
    if (!sheet || !scroll) return;
    var btn = sheet.querySelector(".discuss-scroll-down");
    if (!btn) {
      btn = document.createElement("button");
      btn.type = "button";
      btn.className = "discuss-scroll-down hidden";
      btn.setAttribute("aria-label", "К последним сообщениям");
      btn.title = "К последним сообщениям";
      btn.innerHTML =
        '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 5v14M6 13l6 6 6-6"/></svg>';
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        scrollDiscussionToEnd();
        btn.classList.add("hidden");
      });
      if (getComputedStyle(sheet).position === "static") sheet.style.position = "relative";
      sheet.appendChild(btn);
    }
    if (!scroll._downBtnBound) {
      scroll._downBtnBound = true;
      var tick = 0;
      scroll.addEventListener(
        "scroll",
        function () {
          if (tick) return;
          tick = setTimeout(function () {
            tick = 0;
            syncDiscussScrollDownBtn();
          }, 80);
        },
        { passive: true }
      );
    }
    syncDiscussScrollDownBtn();
  }

  function syncDiscussScrollDownBtn() {
    var sheet = document.querySelector("#note-discussion-overlay .note-discussion-sheet");
    var btn = sheet && sheet.querySelector(".discuss-scroll-down");
    var scroll = sheet && sheet.querySelector(".note-discussion-scroll");
    if (!btn || !scroll) return;
    var far = scroll.scrollHeight - scroll.scrollTop - scroll.clientHeight > 320;
    if (far) {
      // Над полем ввода: его высота меняется (вложения, многострочный текст).
      var compose = sheet.querySelector(".note-discussion-compose");
      var sr = sheet.getBoundingClientRect();
      var bottom = compose && !compose.classList.contains("hidden") ? sr.bottom - compose.getBoundingClientRect().top : 0;
      btn.style.bottom = Math.max(12, Math.round(bottom) + 12) + "px";
    }
    btn.classList.toggle("hidden", !far);
  }

  function syncNotesCreateFab() {
    bindChatsNewBtnOnce();
    var createBtn = document.getElementById("notes-create-btn");
    if (!createBtn) return;
    var notesPanel = document.getElementById("panel-notes");
    var notesDetail = document.getElementById("notes-detail");
    var notesRoot = document.getElementById("notes-root");
    var show =
      currentTab === "notes" &&
      (notesSubTab === "notes" ||
        notesSubTab === "chats" ||
        notesSubTab === "transcriptions") &&
      notesPanel &&
      !notesPanel.classList.contains("hidden") &&
      (!notesDetail || notesDetail.classList.contains("hidden")) &&
      (!notesRoot || !notesRoot.classList.contains("hidden")) &&
      (!isNoteEditorModalOpen() || document.documentElement.classList.contains("notes-split"));
    // Чаты на десктопе: «Новый чат» — в шапке списка, плавающий «+» перекрывал отправку сообщения.
    var chatsHeaderNew = show && notesSubTab === "chats" && isDesktopLayout();
    var chatsNewBtn = document.getElementById("chats-new-btn");
    if (chatsNewBtn) setHidden(chatsNewBtn, !chatsHeaderNew);
    setHidden(createBtn, !show || chatsHeaderNew);
    if (notesSubTab === "chats") {
      createBtn.setAttribute("aria-label", "Создать чат");
      createBtn.setAttribute("title", "Новый чат");
    } else if (notesSubTab === "transcriptions") {
      createBtn.setAttribute("aria-label", "Загрузить транскрипцию");
      createBtn.setAttribute("title", "Новая транскрипция");
    } else {
      createBtn.setAttribute("aria-label", "Создать заметку");
      createBtn.setAttribute("title", "Новая заметка");
    }
    syncKnowledgeCreateFab();
  }

  function syncKnowledgeCreateFab() {
    var createBtn = document.getElementById("knowledge-create-btn");
    if (!createBtn) return;
    var knowledgePanel = document.getElementById("panel-knowledge");
    var show =
      currentTab === "knowledge" &&
      knowledgePanel &&
      !knowledgePanel.classList.contains("hidden") &&
      !isNoteEditorModalOpen();
    setHidden(createBtn, !show);
  }

  function syncActualCreateFab() {
    var createBtn = document.getElementById("actual-create-btn");
    if (!createBtn) return;
    var actualPanel = document.getElementById("panel-actual");
    var show =
      currentTab === "actual" &&
      actualPanel &&
      !actualPanel.classList.contains("hidden") &&
      !isNoteEditorModalOpen();
    setHidden(createBtn, !show);
    setHidden(document.getElementById("actual-voice-btn"), !show);
    if (!show) closeActualCreateMenu();
  }

  function leaveChatThreadsMode() {
    activeChatThreadId = "";
    leavingChatsTab = true;
    try {
      if (isNoteDiscussionOpen()) closeNoteDiscussion(true);
      restoreDiscussionOverlayHost();
      clearChatShareWrap();
      document.documentElement.classList.remove("chats-split-open");
      var empty = document.getElementById("chat-thread-empty");
      if (empty) setHidden(empty, false);
      pruneEmptyChatDrafts("");
    } finally {
      leavingChatsTab = false;
      syncChatDiscussionChrome();
      renderNoteAskModes();
    }
  }

  function ensureChatShareHost() {
    var host = document.getElementById("chat-share-host");
    if (!host) {
      host = document.createElement("div");
      host.id = "chat-share-host";
      host.className = "hidden";
      host.setAttribute("aria-hidden", "true");
      document.body.appendChild(host);
    }
    return host;
  }

  function clearChatShareWrap() {
    var host = document.getElementById("chat-share-host");
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap && host && wrap.parentNode === host) {
      wrap._shareKind = "";
      wrap._shareId = "";
      if (wrap.parentNode) wrap.parentNode.removeChild(wrap);
    }
    var panel = document.getElementById("note-editor-comments");
    if (panel && host && panel.parentNode === host) {
      panel._allComments = [];
      panel._commentsCache = [];
      if (panel.parentNode) panel.parentNode.removeChild(panel);
    }
  }

  function clearDiscussionMessagesUi() {
    var list = document.getElementById("note-discussion-messages");
    if (!list) return;
    list.innerHTML = "";
    list._renderFp = "";
    var pending = document.getElementById("note-discuss-pending");
    if (pending && pending.parentNode) pending.parentNode.removeChild(pending);
    var optimistic = document.getElementById("note-discuss-optimistic-user");
    if (optimistic && optimistic.parentNode) optimistic.parentNode.removeChild(optimistic);
  }

  function isDiscussionTargetActive(kind, itemId) {
    var wrap = document.getElementById("note-editor-more-wrap");
    return !!(
      wrap &&
      String(wrap._shareKind || "") === String(kind || "") &&
      String(wrap._shareId || "") === String(itemId || "")
    );
  }

  function ensureChatShareWrap(threadId) {
    var host = ensureChatShareHost();
    if (isNoteEditorModalOpen()) {
      try {
        handleNoteEditorModalClose();
      } catch (_) {}
    }
    var existing = document.getElementById("note-editor-more-wrap");
    while (existing) {
      if (existing.parentNode) existing.parentNode.removeChild(existing);
      existing = document.getElementById("note-editor-more-wrap");
    }
    var stalePanel = document.getElementById("note-editor-comments");
    if (stalePanel && stalePanel.parentNode && stalePanel.parentNode !== host) {
      stalePanel.parentNode.removeChild(stalePanel);
      stalePanel = null;
    } else if (stalePanel && host && stalePanel.parentNode === host) {
      stalePanel._allComments = [];
      stalePanel._commentsCache = [];
      stalePanel._paieComments = [];
      stalePanel._commentsKind = "chat";
      stalePanel._commentsItemId = String(threadId);
    }
    // Сразу убираем ленту прошлого чата — иначе гонка loadNoteComments вернёт старые сообщения.
    clearDiscussionMessagesUi();
    var wrap = document.createElement("div");
    wrap.id = "note-editor-more-wrap";
    wrap.className = "note-more-wrap hidden";
    wrap._shareKind = "chat";
    wrap._shareId = String(threadId);
    wrap._gptBusy = false;
    wrap._gptPhase = "";
    wrap._shareShared = false;
    wrap._shareUrl = "";
    wrap._shareAccess = "view";
    wrap._shareSheetIds = [];
    wrap._paeiRunning = false;
    wrap._askMode = "gpt";
    wrap._noteMembers = [];
    wrap._noteRevision = 1;
    wrap._noteUpdatedAt = "";
    wrap._isNoteOwner = true;
    wrap._discussionDismissed = false;
    host.appendChild(wrap);
    var panel = document.getElementById("note-editor-comments");
    if (!panel || panel.parentNode !== host) {
      if (panel && panel.parentNode) panel.parentNode.removeChild(panel);
      panel = document.createElement("aside");
      panel.id = "note-editor-comments";
      panel.className = "note-comments hidden";
      panel.innerHTML = '<div class="note-comments-list"></div>';
      host.appendChild(panel);
    }
    panel._allComments = [];
    panel._commentsCache = [];
    panel._paieComments = [];
    panel._commentsKind = "chat";
    panel._commentsItemId = String(threadId);
    return wrap;
  }

  function restoreDiscussionOverlayHost() {
    var ov = document.getElementById("note-discussion-overlay");
    if (!ov) return;
    ov.classList.remove("chat-hosted-discussion");
    if (ov._chatHostStyles) {
      ov.style.cssText = ov._chatHostStylesPrev || "";
      ov._chatHostStyles = false;
      ov._chatHostStylesPrev = "";
    }
    if (!ov._chatHomeParent) return;
    if (ov.parentNode !== ov._chatHomeParent) {
      ov._chatHomeParent.appendChild(ov);
    }
  }

  function chatSplitPaneReady() {
    if (notesSubTab !== "chats") return false;
    var pane = document.getElementById("chat-thread-pane");
    var root = document.getElementById("notes-pane-chats");
    if (!pane || !root || root.classList.contains("hidden")) return false;
    if (currentTab !== "notes") return false;
    document.documentElement.classList.add("notes-chats-tab");
    var cs = window.getComputedStyle(pane);
    if (cs.display === "none") {
      // принудительно включаем split, если CSS ещё не применился
      pane.style.display = "flex";
    }
    var rect = pane.getBoundingClientRect();
    return rect.width >= 80 && rect.height >= 80;
  }

  function applyChatHostedOverlayStyles(ov) {
    if (!ov) return;
    if (!ov._chatHostStyles) {
      ov._chatHostStylesPrev = ov.getAttribute("style") || "";
      ov._chatHostStyles = true;
    }
    ov.classList.add("chat-hosted-discussion");
    ov.style.setProperty("position", "absolute", "important");
    ov.style.setProperty("inset", "0px", "important");
    ov.style.setProperty("top", "0px", "important");
    ov.style.setProperty("right", "0px", "important");
    ov.style.setProperty("bottom", "0px", "important");
    ov.style.setProperty("left", "0px", "important");
    ov.style.setProperty("width", "100%", "important");
    ov.style.setProperty("height", "100%", "important");
    ov.style.setProperty("max-width", "none", "important");
    ov.style.setProperty("display", "flex", "important");
    ov.style.setProperty("visibility", "visible", "important");
    ov.style.setProperty("opacity", "1", "important");
    ov.style.setProperty("z-index", "5", "important");
    ov.style.setProperty("border", "none", "important");
    ov.style.setProperty("box-shadow", "none", "important");
    ov.style.setProperty("background", "var(--bg, #0a0a0a)", "important");
    ov.style.setProperty("pointer-events", "auto", "important");
  }

  function hostDiscussionInChatPane() {
    var ov = document.getElementById("note-discussion-overlay");
    var pane = document.getElementById("chat-thread-pane");
    if (!ov) return;
    if (!ov._chatHomeParent) ov._chatHomeParent = ov.parentNode;
    if (chatSplitPaneReady() && pane) {
      if (ov.parentNode !== pane) pane.appendChild(ov);
      document.documentElement.classList.add("notes-chats-tab");
      document.documentElement.classList.add("chats-split-open");
      document.documentElement.classList.add("note-discussion-open");
      var empty = document.getElementById("chat-thread-empty");
      if (empty) setHidden(empty, true);
      ov.classList.remove("hidden");
      ov.setAttribute("aria-hidden", "false");
      applyChatHostedOverlayStyles(ov);
      var sheet = ov.querySelector(".note-discussion-sheet");
      if (sheet) {
        sheet.style.maxWidth = "none";
        sheet.style.height = "100%";
        sheet.style.maxHeight = "100%";
        sheet.style.width = "100%";
      }
    } else {
      restoreDiscussionOverlayHost();
      document.documentElement.classList.remove("chats-split-open");
    }
  }

  function syncChatDiscussionTitle(title) {
    var label = document.getElementById("note-discussion-title-label");
    var t = String(title || "Чат").trim() || "Чат";
    if (label) label.textContent = t;
    var btn = document.getElementById("note-discussion-title");
    if (btn) {
      // На «Актуальном» название — кнопка со списком прошлых чатов с Ассистентом.
      var actual = document.documentElement.classList.contains("actual-assistant-open");
      btn.disabled = !actual;
      btn.classList.toggle("note-pane-switch--plain", !actual);
      btn.title = actual ? "Чаты с Ассистентом" : t;
      btn.setAttribute("aria-expanded", "false");
    }
  }

  function sortChatThreadsCache() {
    chatThreadsCache.sort(function (a, b) {
      var pin = (b.pinned ? 1 : 0) - (a.pinned ? 1 : 0);
      if (pin) return pin;
      return String(b.updated_at || "").localeCompare(String(a.updated_at || ""));
    });
  }

  function chatThreadHasMessages(thread) {
    if (!thread) return false;
    if (thread.has_messages === true) return true;
    if (Number(thread.message_count) > 0) return true;
    if (String(thread.last_preview || "").trim()) return true;
    return false;
  }

  function isEmptyChatDraft(thread) {
    if (!thread || chatThreadHasMessages(thread)) return false;
    if (thread.pinned || thread.title_locked) return false;
    var title = String(thread.title || "").trim() || "Новый чат";
    return title === "Новый чат";
  }

  // Чаты с Ассистентом с «Актуального» живут только там (как чаты заметки — в заметке).
  function chatThreadOrigin(t) {
    return String((t && t.origin) || "");
  }

  function visibleChatThreads() {
    return (chatThreadsCache || []).filter(function (t) {
      if (chatThreadOrigin(t) === "actual") return false;
      return chatThreadHasMessages(t) || !isEmptyChatDraft(t);
    });
  }

  function actualChatThreads() {
    return (chatThreadsCache || []).filter(function (t) {
      return chatThreadOrigin(t) === "actual" && chatThreadHasMessages(t);
    });
  }

  function findEmptyChatDraft(exceptId, origin) {
    for (var i = 0; i < (chatThreadsCache || []).length; i++) {
      var t = chatThreadsCache[i];
      if (chatThreadOrigin(t) !== String(origin || "")) continue;
      if (isEmptyChatDraft(t) && String(t.id) !== String(exceptId || "")) {
        return t;
      }
    }
    return null;
  }

  async function pruneEmptyChatDrafts(keepId) {
    var empties = (chatThreadsCache || []).filter(function (t) {
      var id = String(t.id);
      if (String(id) === String(keepId || "")) return false;
      if (!isEmptyChatDraft(t)) return false;
      return !!sessionChatDraftIds[id];
    });
    if (!empties.length) return;
    for (var i = 0; i < empties.length; i++) {
      var id = String(empties[i].id);
      try {
        await apiFetch("/chats/" + encodeURIComponent(id), { method: "DELETE" });
        delete sessionChatDraftIds[id];
      } catch (_) {}
    }
    chatThreadsCache = (chatThreadsCache || []).filter(function (t) {
      return !empties.some(function (e) {
        return String(e.id) === String(t.id);
      });
    });
    renderChatThreadsList();
    renderSidebarTrees();
  }

  function closeChatThreadMenus() {
    document.querySelectorAll(".chat-thread-menu:not(.hidden)").forEach(function (el) {
      el.classList.add("hidden");
      el.style.position = "";
      el.style.top = "";
      el.style.left = "";
      el.style.right = "";
      el.style.zIndex = "";
      if (el._homeParent && el.parentNode !== el._homeParent) {
        el._homeParent.appendChild(el);
      }
    });
    document.querySelectorAll(".chat-thread-more-btn[aria-expanded='true']").forEach(function (btn) {
      btn.setAttribute("aria-expanded", "false");
    });
  }

  var chatThreadMenuDocClickBound = false;
  function bindChatThreadMenuDocClickOnce() {
    if (chatThreadMenuDocClickBound) return;
    chatThreadMenuDocClickBound = true;
    document.addEventListener("click", function (e) {
      if (
        e.target &&
        e.target.closest &&
        (e.target.closest(".chat-thread-more-wrap") || e.target.closest(".chat-thread-menu"))
      ) {
        return;
      }
      closeChatThreadMenus();
    });
  }

  function syncChatDiscussionChrome() {
    var closeBtn = document.getElementById("note-discussion-close");
    if (closeBtn) {
      // Прячем только в «Заметки → Чаты» на десктопе (там чат встроен в экран). notesSubTab помнит последнюю
      // подвкладку и вне «Заметок» — без проверки вкладки «×» пропадал у ассистента на «Актуальном».
      setHidden(closeBtn, currentTab === "notes" && notesSubTab === "chats" && isDesktopLayout());
    }
    document.documentElement.classList.toggle(
      "notes-chats-tab",
      currentTab === "notes" && notesSubTab === "chats"
    );
  }

  function upsertChatThreadCache(thread) {
    if (!thread || thread.id == null) return;
    var id = String(thread.id);
    var found = false;
    chatThreadsCache = (chatThreadsCache || []).map(function (t) {
      if (String(t.id) === id) {
        found = true;
        return Object.assign({}, t, thread);
      }
      return t;
    });
    if (!found) chatThreadsCache.unshift(thread);
    if (chatThreadHasMessages(thread)) delete sessionChatDraftIds[id];
    sortChatThreadsCache();
    renderChatThreadsList();
    if (String(activeChatThreadId) === id) {
      syncChatDiscussionTitle(thread.title);
    }
  }

  function renderChatThreadsList() {
    var list = document.getElementById("chat-threads-list");
    if (!list) return;
    bindChatThreadMenuDocClickOnce();
    closeChatThreadMenus();
    list.innerHTML = "";
    var all = visibleChatThreads();
    var q = notesSubTab === "chats" ? notesSearchText() : "";
    var rows = q
      ? all.filter(function (t) {
          return (String(t.title || "") + " " + String(t.last_preview || "")).toLowerCase().indexOf(q) >= 0;
        })
      : all;
    if (!rows.length) {
      list.innerHTML = all.length
        ? '<p class="muted empty-hint">Ничего не найдено. Измените поиск.</p>'
        : '<p class="muted empty-hint">Чатов пока нет. Нажмите «+», чтобы начать диалог с ИИ.</p>';
      return;
    }
    // Обычный список чатов (строки), в стиле нового дизайна.
    rows.forEach(function (thread) {
      var id = String(thread.id);
      var row = document.createElement("div");
      row.className = "chat-thread-row cl-row";
      row.setAttribute("role", "listitem");
      row.setAttribute("data-chat-id", id);
      if (String(activeChatThreadId) === id) row.classList.add("is-active", "is-current");
      var main = document.createElement("div");
      main.className = "chat-thread-row-main";
      var head = document.createElement("div");
      head.className = "cl-head";
      var title = document.createElement("span");
      title.className = "cl-title";
      title.textContent = String(thread.title || "Новый чат");
      if (q) title.innerHTML = notesHighlightHtml(String(thread.title || "Новый чат"), q);
      var date = document.createElement("span");
      date.className = "cl-date";
      date.textContent = formatNotesCardDate(thread.updated_at || thread.created_at);
      head.appendChild(title);
      head.appendChild(date);
      if (thread.pinned) {
        var pin = document.createElement("span");
        pin.className = "note-card-pin";
        pin.setAttribute("aria-label", "Закреплён");
        pin.innerHTML =
          '<svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M16 9V4h1c.55 0 1-.45 1-1s-.45-1-1-1H7c-.55 0-1 .45-1 1s.45 1 1 1h1v5c0 1.66-1.34 3-3 3v2h5.2v6h1.6v-6H18v-2c-1.66 0-3-1.34-3-3z"/></svg>';
        head.appendChild(pin);
      }
      main.appendChild(head);
      var prevText = String(thread.last_preview || "").replace(/\b(?:SPEAKER|Speaker|speaker)[_ ]?\d+\s*:\s*/g, "");
      if (prevText) {
        var preview = document.createElement("p");
        preview.className = "chat-thread-row-preview";
        preview.innerHTML = q ? notesHighlightHtml(prevText, q) : escapeHtml(prevText);
        main.appendChild(preview);
      }
      row.appendChild(main);

      var moreWrap = document.createElement("div");
      moreWrap.className = "chat-thread-more-wrap";
      var moreBtn = document.createElement("button");
      moreBtn.type = "button";
      moreBtn.className = "chat-thread-more-btn";
      moreBtn.setAttribute("aria-label", "Действия");
      moreBtn.setAttribute("aria-haspopup", "menu");
      moreBtn.setAttribute("aria-expanded", "false");
      moreBtn.innerHTML =
        '<svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">' +
        '<circle cx="12" cy="5" r="1.7"/><circle cx="12" cy="12" r="1.7"/><circle cx="12" cy="19" r="1.7"/>' +
        "</svg>";
      var menu = document.createElement("div");
      menu.className = "chat-thread-menu note-card-menu hidden";
      menu.setAttribute("role", "menu");
      function addMenuItem(label, fn, danger) {
        var item = document.createElement("button");
        item.type = "button";
        item.className =
          "chat-thread-menu-item" + (danger ? " chat-thread-menu-item--danger" : "");
        item.setAttribute("role", "menuitem");
        item.textContent = label;
        item.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          closeChatThreadMenus();
          fn();
        });
        menu.appendChild(item);
      }
      addMenuItem("Переименовать", function () {
        renameChatThread(thread);
      });
      addMenuItem(thread.pinned ? "Открепить" : "Закрепить чат", function () {
        toggleChatThreadPin(thread, !thread.pinned);
      });
      addMenuItem("Поделиться", function () {
        shareChatThread(thread);
      });
      addMenuItem("Добавить к заметке", function () {
        addChatThreadToNote(thread);
      });
      addMenuItem(
        "Удалить",
        function () {
          deleteChatThread(id);
        },
        true
      );
      moreBtn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var wasOpen = !menu.classList.contains("hidden");
        closeChatThreadMenus();
        closeNoteCardMenus();
        if (wasOpen) return;
        if (!menu._homeParent) menu._homeParent = menu.parentNode;
        document.body.appendChild(menu);
        menu.classList.remove("hidden");
        moreBtn.setAttribute("aria-expanded", "true");
        positionNoteCardMenu(moreBtn, menu);
      });
      moreWrap.appendChild(moreBtn);
      moreWrap.appendChild(menu);
      row.appendChild(moreWrap);

      row.addEventListener("click", function () {
        openChatThread(thread);
      });
      list.appendChild(row);
    });
    syncChatsSplitLeft();
  }

  function syncChatsSplitLeft() {
    if (notesSubTab !== "chats") return;
    var notesRoot = document.getElementById("notes-root");
    if (!notesRoot) return;
    var rect = notesRoot.getBoundingClientRect();
    if (rect.width) document.documentElement.style.setProperty("--notes-split-left", Math.round(rect.right + notesColGap(rect)) + "px");
  }

  // Отступ справа от колонки = отступу слева (от бокового меню) — колонка по центру своего места.
  function notesColGap(rootRect) {
    var side = document.getElementById("app-sidebar") || document.querySelector(".tabbar");
    var sr = side && side.getBoundingClientRect();
    if (!sr || !sr.width || sr.right > rootRect.left) return 16;
    return Math.max(8, Math.round(rootRect.left - sr.right));
  }

  async function renameChatThread(thread) {
    if (!thread || thread.id == null) return;
    var next = await promptDialog("Название чата", String(thread.title || "Новый чат"));
    if (next == null) return;
    next = String(next).trim();
    if (!next) {
      alert("Введите название");
      return;
    }
    try {
      var data = await apiFetch("/chats/" + encodeURIComponent(String(thread.id)), {
        method: "PATCH",
        body: JSON.stringify({ title: next }),
      });
      if (data && data.chat) upsertChatThreadCache(data.chat);
      else {
        upsertChatThreadCache(Object.assign({}, thread, { title: next }));
      }
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  async function toggleChatThreadPin(thread, pinned) {
    if (!thread || thread.id == null) return;
    try {
      var data = await apiFetch("/chats/" + encodeURIComponent(String(thread.id)), {
        method: "PATCH",
        body: JSON.stringify({ pinned: !!pinned }),
      });
      if (data && data.chat) upsertChatThreadCache(data.chat);
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  async function formatChatThreadTranscript(thread) {
    var id = String((thread && thread.id) || "");
    if (!id) return "";
    var data = await apiFetch(
      "/notes/chat/" + encodeURIComponent(id) + "/comments",
      { method: "GET" }
    );
    var rows = (data && data.comments) || [];
    var lines = ["# " + String((thread && thread.title) || "Чат"), ""];
    rows.forEach(function (c) {
      if (!c) return;
      var who = discussionAuthorLabel(c);
      var body = String(c.body || "").trim();
      if (!body) return;
      lines.push("**" + who + ":** " + body);
      lines.push("");
    });
    return lines.join("\n").trim();
  }

  async function shareChatThread(thread) {
    if (!thread || thread.id == null) return;
    try {
      var id = String(thread.id);
      ensureChatShareWrap(id);
      var wrap = document.getElementById("note-editor-more-wrap");
      if (!wrap) return;
      try {
        var data = await apiFetch(
          "/notes/chat/" + encodeURIComponent(id) + "/share",
          { method: "GET" }
        );
        applyShareState(wrap, data);
      } catch (_) {}
      openShareAccessSheet();
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  async function addChatThreadToNote(thread) {
    try {
      var text = await formatChatThreadTranscript(thread);
      if (!text) {
        showNoteToast("В чате пока нет сообщений");
        return;
      }
      openNoteLinkPicker(text);
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  async function loadChatThreads() {
    if (chatThreadsLoading) return;
    chatThreadsLoading = true;
    try {
      var data = await apiFetch("/chats?limit=100", { method: "GET" });
      chatThreadsCache = (data && data.chats) || [];
      sortChatThreadsCache();
      renderChatThreadsList();
      renderSidebarTrees();
    } catch (e) {
      var list = document.getElementById("chat-threads-list");
      if (list && !visibleChatThreads().length) {
        list.innerHTML = '<p class="error"></p>';
        list.querySelector(".error").textContent = e.message || String(e);
      }
    } finally {
      chatThreadsLoading = false;
    }
  }

  async function deleteChatThread(id) {
    await apiFetch("/chats/" + encodeURIComponent(String(id)), { method: "DELETE" });
    chatThreadsCache = (chatThreadsCache || []).filter(function (t) {
      return String(t.id) !== String(id);
    });
    if (String(activeChatThreadId) === String(id)) {
      activeChatThreadId = "";
      if (isNoteDiscussionOpen()) closeNoteDiscussion(true);
      else if (isDesktopLayout() && notesSubTab === "chats") {
        restoreDiscussionOverlayHost();
        document.documentElement.classList.remove("chats-split-open");
        clearChatShareWrap();
        ensureDesktopChatComposer();
      } else {
        restoreDiscussionOverlayHost();
        document.documentElement.classList.remove("chats-split-open");
        var empty = document.getElementById("chat-thread-empty");
        if (empty) setHidden(empty, false);
        clearChatShareWrap();
      }
    }
    renderChatThreadsList();
  }

  // Строка «🧠 Память Лео: N из M материалов», пока семантическая память догоняет новые
  // заметки и встречи (иначе кажется, что Лео их не знает). Скрыта, когда всё проиндексировано.
  var leoMemoryTimer = null;

  function isLeoChatOpen() {
    var wrap = document.getElementById("note-editor-more-wrap");
    return isNoteDiscussionOpen() && !!(wrap && wrap._shareKind === "chat");
  }

  async function refreshLeoMemoryStatus() {
    var el = document.getElementById("leo-memory-status");
    if (!el) return;
    if (leoMemoryTimer) {
      clearTimeout(leoMemoryTimer);
      leoMemoryTimer = null;
    }
    if (!isLeoChatOpen()) {
      el.classList.add("hidden");
      return;
    }
    var st = null;
    try {
      st = await apiFetch("/memory/status", { method: "GET" });
    } catch (_) {
      st = null;
    }
    var total = st && st.enabled ? Number(st.total || 0) : 0;
    var done = st && st.enabled ? Number(st.indexed || 0) : 0;
    if (!total || done >= total || !isLeoChatOpen()) {
      el.classList.add("hidden");
      return;
    }
    var pending = (st.pending || []).filter(Boolean);
    el.textContent =
      "🧠 Память Лео: " + done + " из " + total + " материалов" +
      (pending.length ? " · догружаю «" + pending[0] + "»" + (total - done > 1 ? " и ещё " + (total - done - 1) : "") : "");
    el.title = "Новые заметки и встречи попадают в память Лео примерно через минуту. Пока материал не загружен, Лео может его не знать.";
    el.classList.remove("hidden");
    leoMemoryTimer = setTimeout(refreshLeoMemoryStatus, 30000);
  }

  async function openChatThread(thread) {
    if (!thread || thread.id == null) return;
    var id = String(thread.id);
    var prevId = activeChatThreadId;
    activeChatThreadId = id;
    ensureChatShareWrap(id);
    var wrapEarly = document.getElementById("note-editor-more-wrap");
    if (wrapEarly && Array.isArray(thread.members)) {
      wrapEarly._noteMembers = thread.members;
    }
    renderChatThreadsList();
    await pruneEmptyChatDrafts(id);
    if (prevId && String(prevId) !== id) {
      /* previous empty draft pruned above */
    }
    if (!document.getElementById("note-editor-more-wrap")) {
      ensureChatShareWrap(id);
    }
    hostDiscussionInChatPane();
    var panel = document.getElementById("note-editor-comments");
    var listEl = panel && panel.querySelector(".note-comments-list");
    try {
      await loadNoteComments("chat", id, listEl);
    } catch (e) {
      alert(e.message || String(e));
      return;
    }
    refreshLeoMemoryStatus();
    try {
      var mem = await apiFetch("/chats/" + encodeURIComponent(id) + "/members", {
        method: "GET",
      });
      var wrapMem = document.getElementById("note-editor-more-wrap");
      if (wrapMem && mem) {
        wrapMem._noteMembers = (mem.chat && mem.chat.members) || mem.members || [];
        if (mem.chat) upsertChatThreadCache(mem.chat);
      }
    } catch (_) {}
    if (!document.getElementById("note-editor-more-wrap")) {
      ensureChatShareWrap(id);
    }
    hostDiscussionInChatPane();
    openNoteDiscussion({
      mode: "gpt",
      focus: !chatSplitPaneReady(),
      keepSheet: true,
    });
    hostDiscussionInChatPane();
    syncChatDiscussionTitle(thread.title);
    renderNoteAskModes();
    syncChatDiscussionChrome();
    syncNoteDiscussionOpenClass();
    syncAppOverlay();
    window.requestAnimationFrame(function () {
      hostDiscussionInChatPane();
    });
  }

  async function createAndOpenChatThread(opts) {
    var origin = String((opts && opts.origin) || "");
    try {
      var blank = findEmptyChatDraft(activeChatThreadId, origin);
      if (blank) {
        await openChatThread(blank);
        return;
      }
      if (activeChatThreadId) {
        var current = null;
        for (var i = 0; i < (chatThreadsCache || []).length; i++) {
          if (String(chatThreadsCache[i].id) === String(activeChatThreadId)) {
            current = chatThreadsCache[i];
            break;
          }
        }
        if (current && !chatThreadHasMessages(current) && chatThreadOrigin(current) === origin) {
          await openChatThread(current);
          return;
        }
      }
      await pruneEmptyChatDrafts("");
      var data = await apiFetch("/chats", {
        method: "POST",
        body: JSON.stringify(origin ? { origin: origin } : {}),
      });
      var thread = data && data.chat;
      if (!thread) throw new Error("Не удалось создать чат");
      upsertChatThreadCache(thread);
      sessionChatDraftIds[String(thread.id)] = 1;
      await openChatThread(thread);
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  async function ensureDesktopChatComposer() {
    if (leavingChatsTab || notesSubTab !== "chats" || currentTab !== "notes") return;
    document.documentElement.classList.add("notes-chats-tab");
    if (!chatSplitPaneReady() && !isDesktopLayout()) return;
    if (activeChatThreadId && isNoteDiscussionOpen()) {
      hostDiscussionInChatPane();
      return;
    }
    var blank = findEmptyChatDraft("");
    if (blank) await openChatThread(blank);
    else await createAndOpenChatThread();
  }

  // Вкладки «Заметки / Чаты / Транскрипции»: при прокрутке вверх всплывают сверху,
  // при прокрутке вниз прячутся — не нужно листать до самого верха.
  function bindNotesSubtabsReveal() {
    var row = document.querySelector("#panel-notes .notes-subtabs-row");
    var scroller = row && row.closest(".main-scroll");
    if (!row || row._revealBound) return;
    row._revealBound = true;
    var spacer = null;
    var lastY = 0;
    var travel = 0;
    var ticking = false;
    function scrollY() {
      if (scroller && scroller.scrollHeight > scroller.clientHeight + 2) return scroller.scrollTop;
      return window.scrollY || document.documentElement.scrollTop || 0;
    }
    function place() {
      if (!spacer) return;
      var r = spacer.getBoundingClientRect();
      row.style.left = Math.round(r.left) + "px";
      row.style.width = Math.round(r.width) + "px";
    }
    function setFloating(on) {
      if (on && !spacer) {
        spacer = document.createElement("div");
        spacer.className = "notes-subtabs-spacer";
        spacer.style.height = row.offsetHeight + "px";
        spacer.style.marginBottom = getComputedStyle(row).marginBottom;
        row.parentNode.insertBefore(spacer, row);
        row.classList.add("is-floating");
        place();
      } else if (!on && spacer) {
        row.classList.remove("is-floating", "is-shown");
        row.style.left = "";
        row.style.width = "";
        if (spacer.parentNode) spacer.parentNode.removeChild(spacer);
        spacer = null;
      }
    }
    // Смена вкладки: список другой высоты — начинаем с верха, вкладки на своём месте.
    row._resetReveal = function () {
      setFloating(false);
      row._suppressUntil = Date.now() + 450;
      try {
        window.scrollTo(0, 0);
      } catch (_) {}
      if (scroller) scroller.scrollTop = 0;
      lastY = 0;
    };
    function onScroll() {
      void ticking;
      if (row._suppressUntil && Date.now() < row._suppressUntil) {
        lastY = scrollY();
        return;
      }
      (function () {
        var panel = document.getElementById("panel-notes");
        if (!panel || panel.classList.contains("hidden")) {
          setFloating(false);
          return;
        }
        var y = scrollY();
        // Отскок у краёв (iOS) — не реагируем: иначе панель «мигает» туда-сюда.
        var maxY = scroller && scroller.scrollHeight > scroller.clientHeight + 2
          ? scroller.scrollHeight - scroller.clientHeight
          : (document.documentElement.scrollHeight || 0) - window.innerHeight;
        if (y < 0 || y > maxY + 1) return;
        if (y < 140) {
          setFloating(false);
          lastY = y;
          travel = 0;
          return;
        }
        var dy = y - lastY;
        lastY = y;
        if (!dy) return;
        // Копим путь в одну сторону: показываем после 24px вверх, прячем после 24px вниз.
        if ((dy < 0) !== (travel < 0)) travel = 0;
        travel += dy;
        if (Math.abs(travel) < 24) return;
        setFloating(true);
        var show = travel < 0;
        if (row.classList.contains("is-shown") !== show) row.classList.toggle("is-shown", show);
      })();
    }
    if (scroller) scroller.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", place);
  }

  function setNotesSubTab(name) {
    var next = name || "notes";
    if (next === "summaries") next = "transcriptions";
    if (next !== notesSubTab && notesSelect.on) exitNotesSelectMode();
    if (next !== notesSubTab) window.setTimeout(scheduleNotesServerSearch, 0);
    if (next === "chats" && next !== notesSubTab && notesSplitCurrentId && isNoteEditorModalOpen()) {
      closeNoteEditorModal();
    }
    if (notesSubTab === "chats" && next !== "chats") notesSplitAutoOpened = false;
    syncNotesColLayout();
    if (next !== notesSubTab) window.setTimeout(syncNotesSplitLayout, 0);
    var subRow = document.querySelector("#panel-notes .notes-subtabs-row");
    if (subRow && typeof subRow._resetReveal === "function" && next !== notesSubTab) subRow._resetReveal();
    if (notesSubTab === "chats" && next !== "chats") {
      leaveChatThreadsMode();
    }
    notesSubTab = next;
    document.querySelectorAll("#panel-notes .subtab-btn").forEach(function (b) {
      b.classList.toggle("active", b.getAttribute("data-subtab") === next);
    });
    setHidden(document.getElementById("notes-pane-notes"), next !== "notes");
    setHidden(document.getElementById("notes-pane-chats"), next !== "chats");
    setHidden(document.getElementById("notes-pane-transcriptions"), next !== "transcriptions");
    var filterBar = document.querySelector("#panel-notes .notes-filter-bar");
    setHidden(filterBar, false);
    syncChatDiscussionChrome();
    if (next === "chats") {
      var openWrap = document.getElementById("note-editor-more-wrap");
      if (isNoteDiscussionOpen() && (!openWrap || openWrap._shareKind !== "chat")) {
        closeNoteDiscussion(true);
      }
      document.documentElement.classList.add("notes-chats-tab");
      loadChatThreads().then(function () {
        window.requestAnimationFrame(function () {
          ensureDesktopChatComposer();
        });
      });
    }
    syncNotesCreateFab();
    renderSidebarTrees();
  }
  function clearNoteEditorToolbarWrap() {
    var toolbarWrap = document.getElementById("note-editor-toolbar-wrap");
    var formatHost = document.getElementById("note-editor-format-toolbar-host");
    if (formatHost) formatHost.innerHTML = "";
    if (toolbarWrap) setHidden(toolbarWrap, true);
    syncNoteGptToolbarButton(false);
  }

  function clearNoteEditorTagsWrap() {
    var tagsWrap = document.getElementById("note-editor-tags-wrap");
    if (!tagsWrap) return;
    if (typeof tagsWrap._tagPickerUnmount === "function") {
      try {
        tagsWrap._tagPickerUnmount();
      } catch (_) {}
      tagsWrap._tagPickerUnmount = null;
    }
    tagsWrap.innerHTML = "";
    setHidden(tagsWrap, true);
    hideShareControls();
  }

  function closeNoteMoreMenu() {
    var menu = document.getElementById("note-editor-more-menu");
    var btn = document.getElementById("note-editor-more-btn");
    if (menu) {
      menu.classList.add("hidden");
      menu.style.position = "";
      menu.style.top = "";
      menu.style.right = "";
      menu.style.left = "";
      menu.style.zIndex = "";
    }
    if (btn) btn.setAttribute("aria-expanded", "false");
  }

  function hideShareControls() {
    closeNoteMoreMenu();
    closeShareAccessSheet();
    hideNoteCommentsPanel();
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap) {
      wrap._shareKind = "";
      wrap._shareId = "";
      wrap._shareShared = false;
      wrap._shareUrl = "";
      wrap._shareAccess = "view";
      wrap._shareSheetIds = [];
      wrap._paeiRunning = false;
      wrap._commentChairId = null;
      wrap._commentDraft = null;
      wrap._noteMembers = [];
      wrap._noteRevision = 1;
      wrap._noteUpdatedAt = "";
      wrap._isNoteOwner = true;
      wrap._isKnowledge = false;
      if (wrap.parentNode) wrap.parentNode.removeChild(wrap);
    }
  }

  var noteCollabState = {
    timer: null,
    noteId: "",
    applying: false,
    lastTypedAt: 0,
    lastPollAt: 0,
    peerCount: 0,
    sentCursor: undefined,
    sentCursorAt: 0,
    photoBlobs: {},
    photoMiss: {},
    photoInflight: {},
  };

  function noteMemberInitials(member) {
    var name = String((member && (member.name || member.username)) || "").trim();
    if (!name) return "?";
    var parts = name.replace(/^@/, "").split(/\s+/).filter(Boolean);
    if (parts.length >= 2) return (parts[0].charAt(0) + parts[1].charAt(0)).toUpperCase();
    return name.replace(/^@/, "").slice(0, 2).toUpperCase();
  }

  function applyTelegramAvatar(img, opts) {
    opts = opts || {};
    var uid = String(opts.userId || "");
    var uname = String(opts.username || "")
      .replace(/^@/, "")
      .trim()
      .toLowerCase();
    if (!img || (!uid && !uname)) return;
    if (uid && noteCollabState.photoBlobs[uid]) {
      img.src = noteCollabState.photoBlobs[uid];
      img.classList.add("has-photo");
      return;
    }
    var unameKey = uname ? "u:" + uname : "";
    if (unameKey && noteCollabState.photoBlobs[unameKey]) {
      img.src = noteCollabState.photoBlobs[unameKey];
      img.classList.add("has-photo");
      return;
    }
    function setBlob(key, blob) {
      if (!key || !blob || !blob.size) return false;
      var url = URL.createObjectURL(blob);
      noteCollabState.photoBlobs[key] = url;
      delete noteCollabState.photoMiss[key];
      img.src = url;
      img.classList.add("has-photo");
      return true;
    }
    function fetchPhoto(path, key) {
      if (!key || noteCollabState.photoMiss[key]) return Promise.resolve(false);
      if (noteCollabState.photoBlobs[key]) {
        img.src = noteCollabState.photoBlobs[key];
        img.classList.add("has-photo");
        return Promise.resolve(true);
      }
      if (noteCollabState.photoInflight[key]) {
        return noteCollabState.photoInflight[key].then(function (ok) {
          if (ok && noteCollabState.photoBlobs[key]) {
            img.src = noteCollabState.photoBlobs[key];
            img.classList.add("has-photo");
          }
          return ok;
        });
      }
      var req = fetch(API + path, {
        credentials: "same-origin",
        headers: authHeaders(),
      })
        .then(function (res) {
          return res.ok ? res.blob() : null;
        })
        .then(function (blob) {
          var ok = setBlob(key, blob);
          if (!ok) noteCollabState.photoMiss[key] = 1;
          return ok;
        })
        .catch(function () {
          noteCollabState.photoMiss[key] = 1;
          return false;
        })
        .then(function (ok) {
          delete noteCollabState.photoInflight[key];
          return ok;
        });
      noteCollabState.photoInflight[key] = req;
      return req;
    }
    if (uid) {
      if (noteCollabState.photoMiss[uid] && !(uname && unameKey && !noteCollabState.photoMiss[unameKey])) {
        return;
      }
      fetchPhoto("/users/" + encodeURIComponent(uid) + "/photo", uid).then(function (ok) {
        if (!ok && uname && unameKey) {
          fetchPhoto("/contacts/telegram-photo/" + encodeURIComponent(uname), unameKey);
        }
      });
      return;
    }
    fetchPhoto("/contacts/telegram-photo/" + encodeURIComponent(uname), unameKey);
  }

  function applyNoteMemberPhoto(img, userId) {
    applyTelegramAvatar(img, { userId: userId });
  }

  function noteMemberAvatarNode(member, opts) {
    opts = opts || {};
    var el = document.createElement("span");
    el.className = "note-member-avatar" + (opts.online ? " is-online" : "");
    if (member && member.color) el.style.setProperty("--note-member-color", member.color);
    el.title = String((member && (member.name || member.username)) || "Участник");
    var img = document.createElement("img");
    img.alt = "";
    el.appendChild(img);
    var fallback = document.createElement("span");
    fallback.className = "note-member-avatar-fallback";
    fallback.textContent = noteMemberInitials(member);
    el.appendChild(fallback);
    applyTelegramAvatar(img, {
      userId: member && (member.user_id || member.telegram_user_id),
      username: member && member.username,
    });
    return el;
  }

  function buildNoteCardAvatars(members) {
    var list = (members || []).filter(function (m) {
      return m && m.user_id;
    });
    if (list.length < 2) return null;
    var wrap = document.createElement("div");
    wrap.className = "note-card-avatars";
    list.slice(0, 4).forEach(function (m) {
      wrap.appendChild(noteMemberAvatarNode(m));
    });
    if (list.length > 4) {
      var more = document.createElement("span");
      more.className = "note-member-avatar note-member-avatar-more";
      more.textContent = "+" + (list.length - 4);
      wrap.appendChild(more);
    }
    return wrap;
  }

  function syncNoteCardActionsPad(inner, actions) {
    if (!inner || !actions) return;
    var w = Math.ceil(actions.getBoundingClientRect().width || 0);
    inner.style.paddingRight = Math.max(44, w + 10) + "px";
  }

  function appendNoteCardAvatars(inner, members) {
    var wrap = buildNoteCardAvatars(members);
    if (!wrap || !inner) return;
    var actions = inner.querySelector(".note-card-actions");
    if (actions) {
      var menuWraps = actions.querySelectorAll(".note-card-menu-wrap");
      var moreWrap = menuWraps.length ? menuWraps[menuWraps.length - 1] : null;
      if (moreWrap) actions.insertBefore(wrap, moreWrap);
      else actions.appendChild(wrap);
      syncNoteCardActionsPad(inner, actions);
      return;
    }
    var title = inner.querySelector(".note-card-excerpt");
    if (title) {
      var row = document.createElement("div");
      row.className = "note-card-title-row";
      title.parentNode.insertBefore(row, title);
      row.appendChild(title);
      row.appendChild(wrap);
    } else {
      inner.appendChild(wrap);
    }
  }

  var noteMembersSeenAt = {};
  function renderOpenNoteMembers(members, peers) {
    var row = document.getElementById("note-editor-members");
    if (!row) return;
    var list = members || [];
    // Присутствие «мигает» между опросами — считаем участника в сети ещё 12 с после последнего сигнала,
    // и не пересобираем строку, если ничего не поменялось (иначе шапка заметки дёргается).
    var now = Date.now();
    var openWrap = document.getElementById("note-editor-more-wrap");
    var openId = openWrap ? String(openWrap._shareKind || "") + ":" + String(openWrap._shareId || "") : "";
    if (row._noteKey !== openId) {
      noteMembersSeenAt = {};
      row._noteKey = openId;
      row._sig = null;
    }
    (peers || []).forEach(function (p) {
      if (p && p.user_id != null) noteMembersSeenAt[String(p.user_id)] = { at: now, peer: p };
    });
    var online = [];
    Object.keys(noteMembersSeenAt).forEach(function (k) {
      var rec = noteMembersSeenAt[k];
      if (now - rec.at <= 12000) online.push(rec.peer);
      else delete noteMembersSeenAt[k];
    });
    var onlineIds = {};
    online.forEach(function (p) {
      onlineIds[String(p.user_id)] = p;
    });
    var sig = JSON.stringify([
      list.map(function (m) {
        return [m.user_id, m.name || m.username || "", !!m.is_owner, m.color || ""];
      }),
      Object.keys(onlineIds).sort(),
    ]);
    if (row._sig === sig && row.childNodes.length + (row.classList.contains("hidden") ? 1 : 0) > 0) return;
    row._sig = sig;
    row.innerHTML = "";
    if (list.length <= 1 && !online.length) {
      row.classList.add("hidden");
      return;
    }
    row.classList.remove("hidden");
    var people = document.createElement("div");
    people.className = "note-editor-members-people";
    list.forEach(function (m) {
      var chip = document.createElement("span");
      chip.className = "note-editor-member-chip";
      var live = onlineIds[String(m.user_id)];
      chip.appendChild(noteMemberAvatarNode(m, { online: !!live }));
      var label = document.createElement("span");
      label.textContent = m.is_owner
        ? (m.name || "Автор") + " · автор"
        : m.name || m.username || "Участник";
      chip.appendChild(label);
      people.appendChild(chip);
    });
    row.appendChild(people);
    if (online.length) {
      var live = document.createElement("p");
      live.className = "note-editor-members-live";
      live.textContent =
        online.length === 1
          ? online[0].name + " сейчас в заметке"
          : online
              .map(function (p) {
                return p.name;
              })
              .join(", ") + " сейчас в заметке";
      row.appendChild(live);
    }
  }

  function ensureNoteCollabOverlay() {
    var pad = document.querySelector("#note-editor-overlay .note-editor-pad--body");
    if (!pad) return null;
    var overlay = document.getElementById("note-collab-cursors");
    if (!overlay) {
      overlay = document.createElement("div");
      overlay.id = "note-collab-cursors";
      overlay.className = "note-collab-cursors";
      pad.style.position = "relative";
      pad.appendChild(overlay);
    }
    return overlay;
  }

  function paintRemoteCursors(peers) {
    var overlay = ensureNoteCollabOverlay();
    var editor = getActiveNoteRichEditor();
    if (!overlay) return;
    overlay.innerHTML = "";
    if (!editor || typeof editor.coordsAtPos !== "function") return;
    var pad = overlay.parentNode;
    if (!pad || !pad.getBoundingClientRect) return;
    var padRect = pad.getBoundingClientRect();
    (peers || []).forEach(function (p) {
      if (p.cursor == null) return;
      var coords = null;
      try {
        coords = editor.coordsAtPos(p.cursor);
      } catch (_) {
        return;
      }
      if (!coords) return;
      var caret = document.createElement("div");
      caret.className = "note-collab-caret";
      caret.style.left = coords.left - padRect.left + pad.scrollLeft + "px";
      caret.style.top = coords.top - padRect.top + pad.scrollTop + "px";
      caret.style.height = Math.max(16, coords.bottom - coords.top) + "px";
      caret.style.background = p.color || "#529ef4";
      var flag = document.createElement("span");
      flag.className = "note-collab-caret-label";
      flag.style.background = p.color || "#529ef4";
      flag.textContent = String(p.name || "Участник").split(" ")[0];
      caret.appendChild(flag);
      overlay.appendChild(caret);
    });
  }

  function stopNoteCollab() {
    if (noteCollabState.timer) {
      clearInterval(noteCollabState.timer);
      noteCollabState.timer = null;
    }
    var id = noteCollabState.noteId;
    noteCollabState.noteId = "";
    noteCollabState.peerCount = 0;
    noteCollabState.sentCursor = undefined;
    noteCollabState.requestSave = null;
    stopNoteYjs();
    var rt = realtimeApi();
    if (rt && id) rt.unsub(id);
    if (id) {
      apiFetch("/notes/local/" + encodeURIComponent(id) + "/collab", {
        method: "DELETE",
      }).catch(function () {});
    }
    var overlay = document.getElementById("note-collab-cursors");
    if (overlay) overlay.innerHTML = "";
  }

  function applyRemoteSharedNote(item, force) {
    if (!item) return;
    if (!force) {
      var draftId = currentOpenNoteId() || (item && item.id);
      var draft = readLocalNoteDraft(draftId);
      var api = noteDraftsApi();
      var remoteBody = item.body || item.description;
      if (
        draft &&
        api &&
        !(api.bodiesEqual(draft.title, item.title) && api.bodiesEqual(draft.body, remoteBody)) &&
        !noteDraftHasLocalEdits(draft)
      ) {
        // Черновик без правок (например, сохранён при сворачивании приложения) — устарел.
        clearLocalNoteDraft(draftId);
        draft = null;
      }
      if (
        draft &&
        api &&
        !(api.bodiesEqual(draft.title, item.title) && api.bodiesEqual(draft.body, remoteBody))
      ) {
        var base = noteEditorBaseline();
        if (base && notePayloadEquals(base.title, base.description, item.title, remoteBody)) {
          adoptNoteRevision(item, draftId);
        }
        return;
      }
    }
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap) {
      var apiRev = noteDraftsApi();
      var nextRev = apiRev ? apiRev.revNum(item.revision) : Number(item.revision || 0);
      var curRev = apiRev ? apiRev.revNum(wrap._noteRevision) : Number(wrap._noteRevision || 0);
      if (nextRev >= curRev) {
        wrap._noteRevision = item.revision || wrap._noteRevision;
        wrap._noteUpdatedAt = item.updated_at || wrap._noteUpdatedAt;
      }
      wrap._noteMembers = item.members || wrap._noteMembers || [];
      wrap._isNoteOwner = item.is_owner !== false;
    }
    prependLocalInCache(item);
    var typing = Date.now() - noteCollabState.lastTypedAt < 1600;
    if (typing && !force) return;
    var titleInput = document.getElementById("note-editor-title-input");
    noteCollabState.applying = true;
    try {
      if (titleInput && item.title != null && titleInput.value !== String(item.title || "")) {
        titleInput.value = String(item.title || "");
        titleInput.dispatchEvent(new Event("input"));
      }
      var nextBody = String(item.body || item.description || "");
      noteSheetState.primaryBody = nextBody;
      var main = findNoteSheet(NOTE_SHEET_MAIN);
      if (main) {
        main.body = nextBody;
        main.description = nextBody;
        main.revision = item.revision || main.revision;
      }
      var left = getLeftNoteRichEditor();
      if (
        isPrimarySheetId(noteSheetState.leftId) &&
        left &&
        typeof left.getHtml === "function" &&
        typeof left.setHtml === "function"
      ) {
        if (left.getHtml() !== nextBody) left.setHtml(nextBody, { preserveCursor: true });
      }
      // Чужая версия — новая точка отсчёта: иначе автосохранение примет её за наши правки.
      var bodyEl = getNoteEditorBodyEl();
      if (bodyEl && bodyEl._noteEditor) {
        bodyEl._noteEditor.baseline = noteEditorSnapshot(item.title, nextBody);
      }
    } finally {
      noteCollabState.applying = false;
    }
  }

  // ---- Листы, изменённые другими участниками ----
  // Опрос collab приносит версии листов (без содержимого). Изменённые листы подтягиваем
  // и показываем на месте, если у нас в этом листе нет несохранённых правок.
  function sheetHasLocalWork(id) {
    return !!(noteSheetState.sheetTimers[id] || noteSheetState.sheetPersists[id]);
  }

  function syncRemoteSheets(noteId, remote, remoteOrder) {
    if (!Array.isArray(remote) || !noteSheetsEnabled()) return;
    if (String(noteSheetsNoteId()) !== String(noteId) || noteSheetState.remoteSheetsLoading) return;
    // Другой участник переставил вкладки — просто переупорядочиваем у себя.
    if (Array.isArray(remoteOrder) && remoteOrder.length === noteSheetState.sheets.length && !document.querySelector(".note-editor-sheets.is-reordering")) {
      var localOrder = noteSheetState.sheets.map(function (x) { return String(x.id); });
      if (remoteOrder.join("|") !== localOrder.join("|") && remoteOrder.slice().sort().join("|") === localOrder.slice().sort().join("|")) {
        var byId = {};
        noteSheetState.sheets.forEach(function (x) { byId[String(x.id)] = x; });
        noteSheetState.sheets = remoteOrder.map(function (rid) { return byId[String(rid)]; });
        if (!document.querySelector(".note-sheet-chip-input")) renderNoteSheetChips();
      }
    }
    var local = extraNoteSheets();
    var byId = {};
    local.forEach(function (l) {
      byId[String(l.id)] = l;
    });
    var structural =
      remote.length !== local.length ||
      remote.some(function (r) {
        return !byId[String(r.id)];
      });
    var changed = remote.some(function (r) {
      var l = byId[String(r.id)];
      if (!l || sheetHasLocalWork(String(r.id))) return false;
      return Number(r.revision || 0) > Number(l.revision || 0) || String(r.title || "") !== String(l.title || "");
    });
    if (!structural && !changed) return;
    noteSheetState.remoteSheetsLoading = true;
    apiFetch("/notes/local/" + encodeURIComponent(noteId) + "/sheets", { method: "GET" })
      .then(function (data) {
        if (String(noteSheetsNoteId()) !== String(noteId)) return;
        applyRemoteSheets(((data && data.sheets) || []).filter(Boolean));
      })
      .catch(function () {})
      .then(function () {
        noteSheetState.remoteSheetsLoading = false;
      });
  }

  function applyRemoteSheets(fresh) {
    var primary = findNoteSheet(NOTE_SHEET_MAIN);
    var updated = [];
    // fresh — все листы в порядке вкладок; «Основную» берём свою (её текст синхронизирует collab).
    var next = fresh.map(function (r) {
      var id = String(r.id);
      if (r.is_primary || isPrimarySheetId(id)) return primary || r;
      var l = findNoteSheet(id);
      if (l && sheetHasLocalWork(id)) return l; // свои правки ещё сохраняются
      if (l && Number(r.revision || 0) > Number(l.revision || 0)) updated.push(r);
      return r;
    });
    noteSheetState.sheets = next;
    updated.forEach(showRemoteSheetBody);
    var leftGone = !isPrimarySheetId(noteSheetState.leftId) && !findNoteSheet(noteSheetState.leftId);
    if (leftGone) {
      switchLeftSheet(NOTE_SHEET_MAIN);
      showNoteToast("Лист удалён другим участником");
    }
    // Не перерисовываем вкладки, пока пользователь переименовывает лист.
    if (!document.querySelector(".note-sheet-chip-input")) renderNoteSheetChips();
  }

  function showRemoteSheetBody(sheet) {
    var id = String(sheet.id);
    var html = String(sheet.body || sheet.description || "");
    noteSheetState.applyingRemoteSheet = id;
    try {
      if (String(noteSheetState.leftId) === id) {
        if (isBoardSheet(sheet) !== !!noteSheetState.leftBoard) applyLeftSheetHtml(sheet);
        else if (noteSheetState.leftBoard) {
          if (noteSheetState.leftBoard.getJson() !== html) noteSheetState.leftBoard.setJsonKeepView(html);
        } else if (isWebSheet(sheet) !== !!noteSheetState.leftWebCanvas) applyLeftSheetHtml(sheet);
        else if (noteSheetState.leftWebCanvas) {
          if (noteSheetState.leftWebCanvas.getHtml() !== html) noteSheetState.leftWebCanvas.setHtmlKeepScroll(html);
        } else {
          var left = getLeftNoteRichEditor();
          if (left && typeof left.getHtml === "function" && left.getHtml() !== html) {
            left.setHtml(html, { preserveCursor: true });
          }
        }
      }
      if (noteSheetState.rightMode === "sheet" && String(noteSheetState.rightId) === id) {
        if (noteSheetState.rightBoard) {
          if (noteSheetState.rightBoard.getJson() !== html) noteSheetState.rightBoard.setJsonKeepView(html);
        } else if (noteSheetState.rightWebCanvas) {
          if (noteSheetState.rightWebCanvas.getHtml() !== html) noteSheetState.rightWebCanvas.setHtmlKeepScroll(html);
        } else if (noteSheetState.rightEditor && typeof noteSheetState.rightEditor.getHtml === "function") {
          if (noteSheetState.rightEditor.getHtml() !== html) {
            noteSheetState.rightEditor.setHtml(html, { preserveCursor: true });
          }
        }
      }
    } finally {
      // Изменение от setHtml — не наша правка: не сохраняем его обратно.
      if (noteSheetState.sheetTimers[id]) {
        clearTimeout(noteSheetState.sheetTimers[id]);
        delete noteSheetState.sheetTimers[id];
      }
      setTimeout(function () {
        if (noteSheetState.applyingRemoteSheet === id) noteSheetState.applyingRemoteSheet = "";
      }, 0);
    }
  }

  function noteCollabTick() {
    var wrap = document.getElementById("note-editor-more-wrap");
    var id = noteCollabState.noteId;
    if (!wrap || !id || String(wrap._shareId) !== String(id)) {
      stopNoteCollab();
      return;
    }
    noteCollabState.lastPollAt = Date.now();
    var cursor = currentNoteCursor();
    apiFetch("/notes/local/" + encodeURIComponent(id) + "/collab", {
      method: "POST",
      body: JSON.stringify({ cursor: cursor }),
    })
      .then(function (data) {
        if (noteCollabState.noteId !== String(id)) return;
        var item = data && data.item;
        var peers = (data && data.peers) || [];
        var members = (data && data.members) || (wrap._noteMembers || []);
        wrap._noteMembers = members;
        noteCollabState.peerCount = peers.length;
        renderOpenNoteMembers(members, peers);
        paintRemoteCursors(peers);
        if (data && data.sheets) syncRemoteSheets(String(id), data.sheets, data.sheet_order);
        if (!item) return;
        var remoteRev = Number(item.revision || 0);
        var localRev = Number(wrap._noteRevision || 0);
        if (remoteRev > localRev) {
          if (noteYjsActive(id)) applyRemoteNoteTitle(item);
          else applyRemoteSharedNote(item, false);
        }
        else if (remoteRev === localRev && item.updated_at) {
          wrap._noteUpdatedAt = item.updated_at;
        }
      })
      .catch(function () {});
  }

  function startNoteCollab(noteId, note) {
    stopNoteCollab();
    if (!noteId) return;
    noteCollabState.noteId = String(noteId);
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap && note) {
      wrap._noteMembers = note.members || [];
      wrap._noteRevision = note.revision || 1;
      wrap._noteUpdatedAt = note.updated_at || "";
      wrap._isNoteOwner = note.is_owner !== false;
      renderOpenNoteMembers(wrap._noteMembers, []);
    }
    var rt = realtimeApi();
    if (rt) rt.sub(noteId);
    noteCollabTick();
    noteCollabState.timer = setInterval(noteCollabLoop, NOTE_COLLAB_SAMPLE_MS);
  }

  // ---- Живые обновления (webapp/realtime.js) ----
  // Сокет приносит «заметка / листы / обсуждение изменились» и курсоры участников;
  // данные берём тем же запросом collab. Без сокета — прежний опрос раз в 1,4 с.
  var NOTE_COLLAB_SAMPLE_MS = 400; // курсор читаем часто, по сети уходит только изменение
  var NOTE_COLLAB_POLL_MS = 1400;
  var NOTE_COLLAB_LIVE_POLL_MS = 15000; // страховочный опрос при живом сокете
  var NOTE_PRESENCE_KEEPALIVE_MS = 4000; // присутствие на сервере живёт 12 с
  var NOTE_SAVE_DELAY_MS = 1500;
  var NOTE_SAVE_DELAY_LIVE_MS = 500; // в заметке есть другие люди — сохраняем чаще
  var realtimeStarted = false;
  var realtimeCollabKick = null;
  var realtimeNotesTimer = null;

  function realtimeApi() {
    return window.LeoRealtime || null;
  }

  function realtimeLive(noteId) {
    var rt = realtimeApi();
    return !!(rt && noteId && rt.isLive(noteId));
  }

  function startRealtime() {
    var rt = realtimeApi();
    if (!rt) return;
    if (realtimeStarted) {
      rt.restart();
      return;
    }
    realtimeStarted = true;
    rt.start({ getHeaders: authHeaders, onEvent: handleRealtimeEvent });
  }

  function currentNoteCursor() {
    var editor = isPrimarySheetId(noteSheetState.leftId) ? getLeftNoteRichEditor() : null;
    return editor && typeof editor.getCursor === "function" ? editor.getCursor() : null;
  }

  function noteSaveDelayMs() {
    return noteCollabState.peerCount > 0 && realtimeLive(noteCollabState.noteId)
      ? NOTE_SAVE_DELAY_LIVE_MS
      : NOTE_SAVE_DELAY_MS;
  }

  function noteCollabLoop() {
    var id = noteCollabState.noteId;
    if (!id || document.hidden) return;
    var now = Date.now();
    if (realtimeLive(id)) {
      var cursor = currentNoteCursor();
      if (
        cursor !== noteCollabState.sentCursor ||
        now - noteCollabState.sentCursorAt >= NOTE_PRESENCE_KEEPALIVE_MS
      ) {
        if (realtimeApi().cursor(id, cursor)) {
          noteCollabState.sentCursor = cursor;
          noteCollabState.sentCursorAt = now;
        }
      }
      if (now - noteCollabState.lastPollAt >= NOTE_COLLAB_LIVE_POLL_MS) noteCollabTick();
      return;
    }
    if (now - noteCollabState.lastPollAt >= NOTE_COLLAB_POLL_MS - 50) noteCollabTick();
  }

  // ---- Совместная правка текста (webapp/note-yjs.js) ----
  var noteYjsSession = null;
  var noteYjsDisabled = {}; // note_id → причина: здесь совместная правка не удалась, работаем как раньше

  function noteYjsActive(noteId) {
    return !!(noteYjsSession && noteYjsSession.isReady() && String(noteYjsSession.noteId) === String(noteId));
  }

  function startNoteYjs(noteId) {
    var id = String(noteId || "");
    if (!id || noteYjsDisabled[id] || !window.LeoNoteYjs) return;
    if (noteYjsSession && String(noteYjsSession.noteId) === id) {
      noteYjsSession.join(); // переподключение: догнать журнал и отдать свои правки
      return;
    }
    stopNoteYjs();
    var api = getNoteRichEditorApi();
    var left = getLeftNoteRichEditor();
    if (!api || !api.Y || !left || typeof left.attachYjs !== "function") return; // старый бандл редактора
    var rt = realtimeApi();
    noteYjsSession = window.LeoNoteYjs.createSession({
      noteId: id,
      Y: api.Y,
      send: function (obj) {
        return !!(rt && rt.send(obj));
      },
      getEditor: function () {
        return isPrimarySheetId(noteSheetState.leftId) ? getLeftNoteRichEditor() : null;
      },
      getAnyEditor: getLeftNoteRichEditor,
      onReady: function () {
        // Черновик и «выберите версию» в совместном режиме не нужны: правки сливает Yjs.
        clearLocalNoteDraft(id);
      },
      onReseeded: function () {
        if (typeof noteCollabState.requestSave === "function") noteCollabState.requestSave();
      },
      onRemoteChange: function () {
        if (typeof noteCollabState.requestSave === "function") noteCollabState.requestSave();
      },
      onFallback: function (reason) {
        console.warn("[yjs] fallback", id, reason);
        noteYjsDisabled[id] = reason || "error";
        noteYjsSession = null;
        kickNoteCollab();
      },
    });
    noteYjsSession.join();
  }

  function stopNoteYjs() {
    if (!noteYjsSession) return;
    var s = noteYjsSession;
    noteYjsSession = null;
    s.stop();
  }

  // ---- Холст в совместной заметке: свой документ Yjs на лист (комната note_id + sheet_id) ----
  var noteYjsAllowed = {}; // note_id → сервер разрешил Yjs (общая заметка)
  var boardYjs = null; // {noteId, sheetId, board, session}
  var boardCursors = {}; // user_id → {x, y, name, color, sheetId, t}
  var boardCursorTimer = null;
  var boardCursorSentAt = 0;

  function openBoardForYjs() {
    var left = findNoteSheet(noteSheetState.leftId);
    if (noteSheetState.leftBoard && isBoardSheet(left) && !isTempSheetId(left.id)) {
      return { board: noteSheetState.leftBoard, sheetId: String(left.id) };
    }
    var right = noteSheetState.rightMode === "sheet" ? findNoteSheet(noteSheetState.rightId) : null;
    if (noteSheetState.rightBoard && isBoardSheet(right) && !isTempSheetId(right.id)) {
      return { board: noteSheetState.rightBoard, sheetId: String(right.id) };
    }
    return null;
  }

  function isTempSheetId(id) {
    return String(id || "").indexOf("tmp_") === 0;
  }

  function startBoardYjs() {
    var noteId = String(noteSheetsNoteId() || "");
    var open = openBoardForYjs();
    if (!open || !noteId || !noteYjsAllowed[noteId] || !window.LeoNoteYjs || !window.LeoBoard) {
      if (boardYjs && (!open || boardYjs.board !== open.board)) stopBoardYjs();
      return;
    }
    var key = noteId + ":" + open.sheetId;
    if (noteYjsDisabled[key]) return;
    if (boardYjs && boardYjs.board === open.board && boardYjs.sheetId === open.sheetId) {
      boardYjs.session.join(); // переподключение
      return;
    }
    stopBoardYjs();
    var api = getNoteRichEditorApi();
    if (!api || !api.Y) return;
    var Y = api.Y;
    var board = open.board;
    var sid = open.sheetId;
    var rt = realtimeApi();
    var session = window.LeoNoteYjs.createSession({
      noteId: noteId,
      sheetId: sid,
      Y: Y,
      send: function (obj) {
        return !!(rt && rt.send(obj));
      },
      adapter: {
        hasContent: function (doc) {
          return doc.getMap("elements").size > 0;
        },
        canSave: function () {
          return board.isYjsAttached();
        },
        attach: function (doc, ready) {
          if (ready && !board.isYjsAttached()) board.attachYjs(doc, Y);
        },
        detach: function () {
          board.detachYjs();
        },
        seed: function (doc, json, origin) {
          window.LeoBoard.seedDoc(Y, doc, json, origin);
          return true;
        },
        reseed: function (doc, oldJson, json, origin) {
          window.LeoBoard.applyDelta(Y, doc, oldJson, json, origin);
          return true;
        },
      },
      onReseeded: function () {
        scheduleExtraSheetPersist(sid);
      },
      onRemoteChange: function () {
        // Ведущий сохраняет тело листа и после чужих правок — JSON на сервере не отстаёт.
        scheduleExtraSheetPersist(sid);
      },
      onFallback: function (reason) {
        console.warn("[yjs] board fallback", key, reason);
        noteYjsDisabled[key] = reason || "error";
        if (boardYjs && boardYjs.session === session) boardYjs = null;
      },
    });
    boardYjs = { noteId: noteId, sheetId: sid, board: board, session: session };
    session.join();
  }

  function stopBoardYjs(board) {
    if (!boardYjs || (board && boardYjs.board !== board)) return;
    var b = boardYjs;
    boardYjs = null;
    b.session.stop();
  }

  function boardYjsReady(sheetId) {
    return !!(boardYjs && boardYjs.sheetId === String(sheetId) && boardYjs.session.isReady() && boardYjs.board.isYjsAttached());
  }

  function sendBoardCursor(sheetId, x, y) {
    var noteId = String(noteSheetsNoteId() || "");
    if (!noteYjsAllowed[noteId] || !realtimeLive(noteId)) return;
    var now = Date.now();
    if (now - boardCursorSentAt < 80) return;
    boardCursorSentAt = now;
    var rt = realtimeApi();
    if (rt) rt.send({ type: "board.cursor", note_id: Number(noteId), sheet_id: String(sheetId), x: x, y: y });
  }

  var BOARD_CURSOR_COLORS = ["#e8590c", "#2f9e44", "#7048e8", "#d6336c", "#1c7ed6", "#f08c00", "#0c8599"];

  function boardCursorColor(userId) {
    var h = 0;
    String(userId || "").split("").forEach(function (c) {
      h = (h * 31 + c.charCodeAt(0)) >>> 0;
    });
    return BOARD_CURSOR_COLORS[h % BOARD_CURSOR_COLORS.length];
  }

  function paintBoardCursors() {
    var now = Date.now();
    var bySheet = {};
    Object.keys(boardCursors).forEach(function (uid) {
      var c = boardCursors[uid];
      if (now - c.t > 6000) {
        delete boardCursors[uid];
        return;
      }
      (bySheet[c.sheetId] = bySheet[c.sheetId] || []).push(c);
    });
    [["left", noteSheetState.leftBoard, noteSheetState.leftId], ["right", noteSheetState.rightBoard, noteSheetState.rightId]].forEach(function (row) {
      if (row[1]) row[1].setRemoteCursors(bySheet[String(row[2])] || []);
    });
    if (boardCursorTimer) clearTimeout(boardCursorTimer);
    boardCursorTimer = Object.keys(boardCursors).length ? setTimeout(paintBoardCursors, 2000) : null;
  }

  function onBoardCursorEvent(ev) {
    var rt = realtimeApi();
    if (!ev || (rt && String(ev.user_id) === rt.userId())) return;
    boardCursors[String(ev.user_id)] = {
      x: Number(ev.x), y: Number(ev.y), name: String(ev.name || "").split(" ")[0],
      color: boardCursorColor(ev.user_id), sheetId: String(ev.sheet_id || ""), t: Date.now(),
    };
    paintBoardCursors();
  }

  /** Заголовок — вне совместного документа: берём чужой, если сами его сейчас не правим. */
  function applyRemoteNoteTitle(item) {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap) {
      wrap._noteRevision = item.revision || wrap._noteRevision;
      wrap._noteUpdatedAt = item.updated_at || wrap._noteUpdatedAt;
      wrap._noteMembers = item.members || wrap._noteMembers || [];
    }
    var titleInput = document.getElementById("note-editor-title-input");
    if (!titleInput || item.title == null || document.activeElement === titleInput) return;
    if (titleInput.value === String(item.title || "")) return;
    noteCollabState.applying = true;
    try {
      titleInput.value = String(item.title || "");
      titleInput.dispatchEvent(new Event("input"));
    } finally {
      noteCollabState.applying = false;
    }
  }

  function kickNoteCollab(delayMs) {
    if (realtimeCollabKick) return;
    realtimeCollabKick = setTimeout(function () {
      realtimeCollabKick = null;
      if (noteCollabState.noteId) noteCollabTick();
    }, delayMs || 60);
  }

  function applyLivePresence(peers) {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap) return;
    var rt = realtimeApi();
    var me = rt ? rt.userId() : "";
    var others = (peers || []).filter(function (p) {
      return String(p.user_id) !== me;
    });
    noteCollabState.peerCount = others.length;
    renderOpenNoteMembers(wrap._noteMembers || [], others);
    paintRemoteCursors(others);
  }

  function handleRealtimeEvent(ev) {
    var type = ev && ev.type;
    var openId = noteCollabState.noteId;
    var evNote = ev && ev.note_id != null ? String(ev.note_id) : "";
    if (type === "subscribed") {
      if (evNote) noteYjsAllowed[evNote] = !!ev.yjs;
      if (evNote && evNote === openId) {
        kickNoteCollab(); // догнать пропущенное, пока сокета не было
        if (ev.yjs) startNoteYjs(openId);
        else stopNoteYjs();
        startBoardYjs();
      }
      return;
    }
    if (type && type.indexOf("y.") === 0) {
      if (ev.sheet_id != null && String(ev.sheet_id) !== "main") {
        if (boardYjs && evNote === boardYjs.noteId) boardYjs.session.handle(ev);
        return;
      }
      if (noteYjsSession && evNote === String(noteYjsSession.noteId)) noteYjsSession.handle(ev);
      return;
    }
    if (type === "board.cursor") {
      if (evNote && evNote === openId) onBoardCursorEvent(ev);
      return;
    }
    if (type === "note.changed" || type === "sheets.changed" || type === "note.deleted") {
      if (!evNote || evNote !== openId) return;
      var rt = realtimeApi();
      // Своё сохранение: ответ PATCH обычно приходит следом — проверим чуть позже.
      var own = type === "note.changed" && rt && ev.actor && String(ev.actor) === rt.userId();
      kickNoteCollab(own ? 800 : 60);
      return;
    }
    if (type === "presence") {
      if (evNote && evNote === openId) applyLivePresence(ev.peers);
      return;
    }
    if (type === "comments.changed") {
      kickDiscussionLiveUpdates(evNote);
      return;
    }
    if (type === "task.changed") {
      // Сообщение / статус в задаче (в т.ч. ответ из Telegram) — открытой карточке и списку «Поручено другим».
      kickPostedLiveUpdate(ev.task_id != null ? String(ev.task_id) : "");
      return;
    }
    if (type === "notes.changed") {
      // Новая заметка из бота (транскрибация и т.п.) — обновить открытый список.
      if (realtimeNotesTimer) clearTimeout(realtimeNotesTimer);
      realtimeNotesTimer = setTimeout(function () {
        realtimeNotesTimer = null;
        if (currentTab === "notes" && !document.hidden) loadNotes().catch(function () {});
      }, 1500);
    }
  }

  function pendingNoteIdFromLocation() {
    try {
      var q = new URLSearchParams(location.search || "");
      var n = q.get("note") || q.get("n");
      if (n && /^\d+$/.test(n)) return n;
    } catch (_) {}
    var hash = String(location.hash || "").replace(/^#/, "");
    var hm = hash.match(/(?:^|&)note=(\d+)/) || hash.match(/^note=(\d+)/);
    if (hm) return hm[1];
    var tg = window.Telegram && window.Telegram.WebApp;
    var start = tg && tg.initDataUnsafe && tg.initDataUnsafe.start_param;
    if (start) {
      var sm = String(start).match(/^note[_-]?(\d+)$/i);
      if (sm) return sm[1];
    }
    return "";
  }

  function pendingTaskIdFromLocation() {
    try {
      var q = new URLSearchParams(location.search || "");
      var t = q.get("task") || q.get("t");
      if (t && /^\d+$/.test(t)) return t;
    } catch (_) {}
    var hash = String(location.hash || "").replace(/^#/, "");
    var hm = hash.match(/(?:^|&)task=(\d+)/) || hash.match(/^task=(\d+)/);
    if (hm) return hm[1];
    var tg = window.Telegram && window.Telegram.WebApp;
    var start = tg && tg.initDataUnsafe && tg.initDataUnsafe.start_param;
    if (start) {
      var sm = String(start).match(/^task[_-]?(\d+)$/i);
      if (sm) return sm[1];
    }
    return "";
  }

  function applyLeoProtocolSearchParam() {
    // protocol_handlers: web+leo://… → /webapp/?leo=web%2Bleo%3A%2F%2F…
    try {
      var q = new URLSearchParams(location.search || "");
      var raw = (q.get("leo") || "").trim();
      if (!raw) return false;
      var rest = raw.replace(/^web\+leo:\/\//i, "");
      var path = rest;
      var protoQuery = "";
      var qi = rest.indexOf("?");
      if (qi >= 0) {
        path = rest.slice(0, qi);
        protoQuery = rest.slice(qi + 1);
      }
      var next = new URL(location.href);
      next.searchParams.delete("leo");
      if (path.indexOf("event/") === 0) {
        var eid = decodeURIComponent(path.slice("event/".length).split("/")[0] || "");
        if (eid) next.searchParams.set("event", eid);
        var pq = new URLSearchParams(protoQuery);
        if (pq.get("cal")) next.searchParams.set("cal", pq.get("cal"));
        if (pq.get("day")) next.searchParams.set("day", pq.get("day"));
      } else if (path.indexOf("open") === 0) {
        var pq2 = new URLSearchParams(protoQuery);
        var p = (pq2.get("p") || "/").trim() || "/";
        try {
          var mapped = new URL(p, location.origin + "/webapp/");
          if (mapped.origin === location.origin) {
            mapped.searchParams.forEach(function (v, k) {
              next.searchParams.set(k, v);
            });
          }
        } catch (_) {}
      }
      history.replaceState(null, "", next.pathname + next.search + next.hash);
      return true;
    } catch (_) {
      return false;
    }
  }

  function pendingEventFromLocation() {
    applyLeoProtocolSearchParam();
    try {
      var q = new URLSearchParams(location.search || "");
      var eid = (q.get("event") || q.get("e") || "").trim();
      if (eid) {
        return {
          id: eid,
          calendar_id: (q.get("cal") || q.get("calendar") || "primary").trim() || "primary",
          date: (q.get("day") || q.get("date") || "").trim().slice(0, 10),
        };
      }
    } catch (_) {}
    var hash = String(location.hash || "").replace(/^#/, "");
    var hm = hash.match(/(?:^|&)event=([^&]+)/) || hash.match(/^event=([^&]+)/);
    if (hm) {
      var hp = {};
      try {
        hp = Object.fromEntries(new URLSearchParams(hash));
      } catch (_) {}
      return {
        id: decodeURIComponent(hm[1]),
        calendar_id: String(hp.cal || hp.calendar || "primary"),
        date: String(hp.day || hp.date || "").slice(0, 10),
      };
    }
    var tg = window.Telegram && window.Telegram.WebApp;
    var start = tg && tg.initDataUnsafe && tg.initDataUnsafe.start_param;
    if (start) {
      var sm = String(start).match(/^event[_-](.+)$/i);
      if (sm) return { id: sm[1], calendar_id: "primary", date: "" };
    }
    return null;
  }

  function pendingChatIdFromLocation() {
    try {
      var q = new URLSearchParams(location.search || "");
      var c = q.get("chat") || q.get("c");
      if (c && String(c).trim()) return String(c).trim();
    } catch (_) {}
    var hash = String(location.hash || "").replace(/^#/, "");
    var hm = hash.match(/(?:^|&)chat=([^&]+)/) || hash.match(/^chat=([^&]+)/);
    if (hm) return decodeURIComponent(hm[1]);
    var tg = window.Telegram && window.Telegram.WebApp;
    var start = tg && tg.initDataUnsafe && tg.initDataUnsafe.start_param;
    if (start) {
      var sm = String(start).match(/^chat[_-](.+)$/i);
      if (sm) return sm[1];
    }
    return "";
  }

  function copyShareUrl(url) {
    if (!url) return Promise.resolve();
    if (navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(url);
    }
    return new Promise(function (resolve, reject) {
      var ta = document.createElement("textarea");
      ta.value = url;
      ta.setAttribute("readonly", "");
      ta.style.position = "fixed";
      ta.style.left = "-9999px";
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand("copy");
        resolve();
      } catch (e) {
        reject(e);
      }
      document.body.removeChild(ta);
    });
  }

  function copyTextWithOptionalHtml(plain, html) {
    var text = String(plain || "");
    var rich = String(html || "").trim();
    if (!text && rich) text = htmlToPlainText(rich);
    if (!text) return Promise.reject(new Error("empty"));
    if (
      rich &&
      navigator.clipboard &&
      typeof navigator.clipboard.write === "function" &&
      typeof window.ClipboardItem === "function"
    ) {
      try {
        var item = new ClipboardItem({
          "text/plain": Promise.resolve(new Blob([text], { type: "text/plain" })),
          "text/html": Promise.resolve(new Blob([rich], { type: "text/html" })),
        });
        return navigator.clipboard.write([item]).catch(function () {
          return copyShareUrl(text);
        });
      } catch (_) {
        /* fall through to plain */
      }
    }
    return copyShareUrl(text);
  }

  function shareHaptic() {
    var tg = window.Telegram && window.Telegram.WebApp;
    if (tg && tg.HapticFeedback) tg.HapticFeedback.notificationOccurred("success");
  }

  // ---- История версий заметки ----
  // Десктоп: список версий справа (на месте обсуждения), выбранная версия — слева вместо текста,
  // только для чтения. Телефон: список — отдельный экран, версия — следующий экран.
  var noteHistory = null;
  // Правка ИИ: следующее сохранение этого листа уходит с пометкой (для «правка ИИ» в истории).
  var noteAiSaveMarks = {};

  function markNextSaveAsAi(sheetId) {
    noteAiSaveMarks[String(sheetId || NOTE_SHEET_MAIN)] = Date.now();
  }

  function aiEditSourceHeader(path, method) {
    if (String(method || "").toUpperCase() !== "PATCH") return "";
    var m = /^\/notes\/local\/[^/?]+(?:\/sheets\/([^/?]+))?(?:\?|$)/.exec(String(path || ""));
    if (!m) return "";
    var key = m[1] ? decodeURIComponent(m[1]) : NOTE_SHEET_MAIN;
    var at = noteAiSaveMarks[key];
    if (!at) return "";
    delete noteAiSaveMarks[key];
    return Date.now() - at < 120000 ? "ai" : "";
  }

  function isNoteHistoryOpen() {
    return !!noteHistory;
  }

  var RU_MONTHS_GEN = ["января", "февраля", "марта", "апреля", "мая", "июня", "июля", "августа", "сентября", "октября", "ноября", "декабря"];
  var RU_MONTHS_SHORT = ["янв", "фев", "мар", "апр", "мая", "июн", "июл", "авг", "сен", "окт", "ноя", "дек"];

  function nhDate(v) {
    var d = new Date(String((v && (v.state_at || v.saved_at)) || ""));
    return isNaN(d.getTime()) ? new Date() : d;
  }

  function nhTime(d) {
    return String(d.getHours()).padStart(2, "0") + ":" + String(d.getMinutes()).padStart(2, "0");
  }

  function nhDayLabel(d) {
    var today = new Date();
    var y = new Date(today.getFullYear(), today.getMonth(), today.getDate() - 1);
    if (d.toDateString() === today.toDateString()) return "Сегодня";
    if (d.toDateString() === y.toDateString()) return "Вчера";
    return d.getDate() + " " + RU_MONTHS_GEN[d.getMonth()] + (d.getFullYear() !== today.getFullYear() ? " " + d.getFullYear() : "");
  }

  function nhStamp(d) {
    return d.getDate() + " " + RU_MONTHS_SHORT[d.getMonth()] + ", " + nhTime(d);
  }

  function nhSheetKey(v) {
    var sid = Number((v && v.sheet_id) || 0);
    return sid ? String(sid) : NOTE_SHEET_MAIN;
  }

  function nhSheetLabel(v) {
    if (nhSheetKey(v) === NOTE_SHEET_MAIN) return "Основная";
    var live = findNoteSheet(nhSheetKey(v));
    return "лист «" + String((live && live.title) || v.sheet_title || "Лист") + "»";
  }

  function nhAuthor(v) {
    if (String(v.source || "") === "ai") return { name: "Ассистент", ai: true };
    var a = (noteHistory && noteHistory.authors && noteHistory.authors[String(v.author_user_id || "")]) || null;
    return { name: a ? a.name : "", photo: a ? a.photo_url : null };
  }

  function nhNum(n) {
    return String(Math.abs(n)).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
  }

  // Чистим сохранённый HTML для показа «только чтение»: без скриптов, iframe и обработчиков.
  function nhSafeFragment(html) {
    var doc = new DOMParser().parseFromString("<body>" + String(html || "") + "</body>", "text/html");
    doc.body.querySelectorAll("script,style,iframe,object,embed,link,meta,form,base").forEach(function (el) {
      el.remove();
    });
    doc.body.querySelectorAll("*").forEach(function (el) {
      Array.prototype.slice.call(el.attributes).forEach(function (a) {
        var n = a.name.toLowerCase();
        var val = String(a.value || "").trim().toLowerCase();
        if (n.indexOf("on") === 0 || n === "contenteditable" || ((n === "href" || n === "src" || n === "xlink:href") && val.indexOf("javascript:") === 0)) {
          el.removeAttribute(a.name);
        }
      });
      if (el.tagName === "INPUT") el.setAttribute("disabled", "");
    });
    var frag = document.createDocumentFragment();
    while (doc.body.firstChild) frag.appendChild(document.adoptNode(doc.body.firstChild));
    return frag;
  }

  // Текст по абзацам: строки для сравнения версий.
  function nhBlocks(html) {
    var doc = new DOMParser().parseFromString("<body>" + String(html || "") + "</body>", "text/html");
    doc.body.querySelectorAll("script,style").forEach(function (el) {
      el.remove();
    });
    var out = [];
    var BLOCK = /^(P|LI|H[1-6]|PRE|BLOCKQUOTE|TR|DIV|SECTION|ARTICLE|FIGURE|DT|DD)$/;
    function walk(node) {
      for (var c = node.firstChild; c; c = c.nextSibling) {
        if (c.nodeType !== 1) continue;
        var hasBlockChild = Array.prototype.some.call(c.children, function (k) {
          return BLOCK.test(k.tagName) || k.tagName === "UL" || k.tagName === "OL" || k.tagName === "TABLE" || k.tagName === "TBODY";
        });
        if (c.tagName === "IMG") out.push("[картинка]");
        else if (BLOCK.test(c.tagName) && !hasBlockChild) {
          var t = c.tagName === "TR"
            ? Array.prototype.map.call(c.children, function (td) { return td.textContent.trim(); }).join(" | ")
            : c.textContent.replace(/\s+/g, " ").trim();
          if (!t && c.querySelector("img")) t = "[картинка]";
          if (t) out.push(t);
        } else walk(c);
      }
    }
    walk(doc.body);
    if (!out.length) {
      var all = doc.body.textContent.replace(/\s+/g, " ").trim();
      if (all) out.push(all);
    }
    return out;
  }

  // Наибольшая общая подпоследовательность: пары [тип, a, b] (= / - / +).
  function nhDiffSeq(a, b, eq) {
    eq = eq || function (x, y) { return x === y; };
    var pre = 0;
    while (pre < a.length && pre < b.length && eq(a[pre], b[pre])) pre++;
    var suf = 0;
    while (suf < a.length - pre && suf < b.length - pre && eq(a[a.length - 1 - suf], b[b.length - 1 - suf])) suf++;
    var A = a.slice(pre, a.length - suf);
    var B = b.slice(pre, b.length - suf);
    var mid = [];
    var n = A.length;
    var m = B.length;
    if (n * m > 4000000) {
      A.forEach(function (x) { mid.push(["-", x]); });
      B.forEach(function (y) { mid.push(["+", y]); });
    } else {
      var w = m + 1;
      var L = new Uint32Array((n + 1) * w);
      for (var i = n - 1; i >= 0; i--) {
        for (var j = m - 1; j >= 0; j--) {
          L[i * w + j] = eq(A[i], B[j]) ? L[(i + 1) * w + j + 1] + 1 : Math.max(L[(i + 1) * w + j], L[i * w + j + 1]);
        }
      }
      var x = 0;
      var y = 0;
      while (x < n && y < m) {
        if (eq(A[x], B[y])) {
          mid.push(["=", A[x]]);
          x++;
          y++;
        } else if (L[(x + 1) * w + y] >= L[x * w + y + 1]) mid.push(["-", A[x++]]);
        else mid.push(["+", B[y++]]);
      }
      while (x < n) mid.push(["-", A[x++]]);
      while (y < m) mid.push(["+", B[y++]]);
    }
    var out = [];
    a.slice(0, pre).forEach(function (t) { out.push(["=", t]); });
    out = out.concat(mid);
    a.slice(a.length - suf).forEach(function (t) { out.push(["=", t]); });
    return out;
  }

  // Пробел между двумя удалёнными (или добавленными) словами — часть одного фрагмента.
  function nhMergeWordOps(ops) {
    var out = [];
    for (var i = 0; i < ops.length; i++) {
      var op = ops[i];
      var prev = out[out.length - 1];
      var nxt = ops[i + 1];
      if (op[0] === "=" && !op[1].trim() && prev && nxt && prev[0] !== "=" && prev[0] === nxt[0]) op = [prev[0], op[1]];
      if (prev && prev[0] === op[0]) prev[1] += op[1];
      else out.push([op[0], op[1]]);
    }
    return out;
  }

  // Сравнение версии (old) с текущим текстом (cur): добавленное — зелёным, удалённое — красным.
  function nhRenderDiff(host, oldHtml, curHtml) {
    var lines = nhDiffSeq(nhBlocks(oldHtml), nhBlocks(curHtml));
    var changed = 0;
    for (var i = 0; i < lines.length; i++) {
      var op = lines[i];
      var p = document.createElement("p");
      if (op[0] === "=") {
        p.textContent = op[1];
        host.appendChild(p);
        continue;
      }
      changed++;
      // Пара «удалено + добавлено» подряд — правка абзаца: сравниваем по словам.
      var next = lines[i + 1];
      if (op[0] === "-" && next && next[0] === "+" && op[1].length < 6000 && next[1].length < 6000) {
        var words = nhMergeWordOps(nhDiffSeq(op[1].split(/(\s+)/), next[1].split(/(\s+)/)));
        var same = 0;
        words.forEach(function (wd) {
          if (wd[0] === "=") same += wd[1].split(/\s+/).filter(Boolean).length;
        });
        if (same >= 2) {
          words.forEach(function (wd) {
            if (wd[0] === "=") p.appendChild(document.createTextNode(wd[1]));
            else {
              var el = document.createElement(wd[0] === "+" ? "ins" : "del");
              el.textContent = wd[1];
              p.appendChild(el);
            }
          });
          p.className = "nh-diff-mod";
          host.appendChild(p);
          i++;
          continue;
        }
      }
      var mark = document.createElement(op[0] === "+" ? "ins" : "del");
      mark.textContent = op[1];
      p.appendChild(mark);
      p.className = op[0] === "+" ? "nh-diff-add" : "nh-diff-del";
      host.appendChild(p);
    }
    if (!changed) {
      var none = document.createElement("p");
      none.className = "nh-diff-none";
      none.textContent = "Текст не отличается от текущего (могло измениться только оформление).";
      host.insertBefore(none, host.firstChild);
    }
  }

  function nhCurrentHtml(key) {
    if (key === NOTE_SHEET_MAIN) {
      var left = getLeftNoteRichEditor();
      if (isPrimarySheetId(noteSheetState.leftId) && left && typeof left.getHtml === "function") return left.getHtml();
      return String(noteSheetState.primaryBody || "");
    }
    if (String(noteSheetState.leftId) === key) {
      try {
        return readSheetEditorHtml("left");
      } catch (_) {}
    }
    var sh = findNoteSheet(key);
    return sh ? String(sh.body || sh.description || "") : "";
  }

  function nhEnsureOverlay() {
    var ov = document.getElementById("note-history-overlay");
    if (ov) return ov;
    ov = document.createElement("div");
    ov.id = "note-history-overlay";
    ov.className = "note-history-overlay hidden";
    ov.setAttribute("aria-hidden", "true");
    ov.innerHTML =
      '<div class="nh-sheet" role="dialog" aria-label="История версий">' +
      '<div class="nh-screen nh-screen--list">' +
      '<div class="nh-head">' +
      '<button type="button" class="nh-back" data-nh="close-m">‹ Назад</button>' +
      '<div class="nh-title">История версий</div>' +
      '<button type="button" class="nh-close" data-nh="close" aria-label="Закрыть" title="Закрыть">' +
      '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>' +
      "</button></div>" +
      '<div class="nh-filter" role="tablist"></div>' +
      '<div class="nh-list"></div>' +
      "</div>" +
      '<div class="nh-screen nh-screen--view hidden">' +
      '<div class="nh-head">' +
      '<button type="button" class="nh-back" data-nh="list">‹ История</button>' +
      '<div class="nh-title nh-view-title"></div><span></span></div>' +
      '<div class="nh-seg" role="tablist">' +
      '<button type="button" data-nh="mode-version" class="is-on">Версия</button>' +
      '<button type="button" data-nh="mode-diff">Изменения</button></div>' +
      '<div class="note-rich-editor-body nh-view-body nh-doc"></div>' +
      '<div class="nh-view-foot"><button type="button" class="btn primary nh-restore-big" data-nh="restore">Восстановить эту версию</button></div>' +
      "</div></div>";
    ov.addEventListener("click", onNoteHistoryClick);
    document.body.appendChild(ov);
    return ov;
  }

  function nhEnsurePreview() {
    // Под названием и вкладками листов — на месте текста заметки.
    var col = document.querySelector("#note-editor-modal-body .note-editor-main-column");
    var bodyPad = col && col.querySelector(".note-editor-pad--body");
    if (!col || !bodyPad) return null;
    var pv = document.getElementById("note-history-preview");
    if (pv && pv.parentNode === col) return pv;
    if (pv && pv.parentNode) pv.parentNode.removeChild(pv);
    pv = document.createElement("div");
    pv.id = "note-history-preview";
    pv.className = "note-editor-pad nh-preview hidden";
    pv.innerHTML =
      '<div class="nh-banner">' +
      '<div class="nh-banner-text"><b class="nh-banner-title"></b> <span class="nh-banner-sub"></span></div>' +
      '<button type="button" class="btn-text nh-banner-diff" data-nh="toggle-diff">Показать изменения</button>' +
      '<button type="button" class="btn primary nh-banner-restore" data-nh="restore">Восстановить</button>' +
      "</div>" +
      '<div class="nh-preview-scroll"><div class="note-rich-editor-body nh-doc nh-preview-body"></div></div>';
    pv.addEventListener("click", onNoteHistoryClick);
    col.insertBefore(pv, bodyPad);
    return pv;
  }

  async function openNoteHistory() {
    var wrap = document.getElementById("note-editor-more-wrap");
    var noteId = currentOpenNoteId();
    if (!wrap || wrap._shareKind !== "local" || !noteId) return;
    if (String(noteId).indexOf("tmp_") === 0) {
      showNoteToast("Заметка ещё сохраняется — попробуйте через пару секунд");
      return;
    }
    if (noteHistory) closeNoteHistory();
    var root = document.documentElement;
    var hadDiscussion = isNoteDiscussionOpen();
    var wasSplit = root.classList.contains("notes-split");
    noteHistory = {
      noteId: String(noteId),
      versions: [],
      current: {},
      authors: {},
      filter: "all",
      selId: "",
      mode: "version",
      bodies: {},
      hadDiscussion: hadDiscussion && isDesktopLayout(),
      wasSplit: wasSplit,
      loading: true,
    };
    if (hadDiscussion) closeNoteDiscussion(true);
    if (wasSplit) {
      setNotesSplitMode("full");
      syncNotesSplitLayout();
    }
    var ov = nhEnsureOverlay();
    ov.classList.remove("hidden");
    ov.setAttribute("aria-hidden", "false");
    nhShowScreen("list");
    root.classList.add("note-history-open");
    applyNotePaneWidths();
    renderNoteHistory();
    syncTelegramNativeBack();
    try {
      await flushOpenNoteForShare();
    } catch (_) {}
    await loadNoteHistory();
  }

  async function loadNoteHistory() {
    var h = noteHistory;
    if (!h) return;
    try {
      var data = await apiFetch("/notes/local/" + encodeURIComponent(h.noteId) + "/versions", { method: "GET" });
      if (noteHistory !== h) return;
      h.versions = (data && data.versions) || [];
      h.current = (data && data.current) || {};
      h.authors = (data && data.authors) || {};
      h.error = "";
    } catch (e) {
      if (noteHistory !== h) return;
      h.error = (e && e.message) || "Не удалось загрузить историю";
    }
    h.loading = false;
    renderNoteHistory();
  }

  function closeNoteHistory() {
    var h = noteHistory;
    if (!h) return;
    noteHistory = null;
    nhHidePreview();
    var ov = document.getElementById("note-history-overlay");
    if (ov) {
      ov.classList.add("hidden");
      ov.setAttribute("aria-hidden", "true");
    }
    document.documentElement.classList.remove("note-history-open");
    applyNotePaneWidths();
    if (h.wasSplit && isNoteEditorModalOpen()) {
      setNotesSplitMode("split");
      syncNotesSplitLayout();
    }
    if (h.hadDiscussion && isNoteEditorModalOpen()) {
      var wrap = document.getElementById("note-editor-more-wrap");
      if (wrap) wrap._discussionDismissed = false;
      syncDesktopNoteDiscussion();
    }
    syncTelegramNativeBack();
  }

  // «Назад» телефона / Telegram: из версии — к списку, из списка — в заметку.
  function noteHistoryBack() {
    if (!noteHistory) return false;
    if (noteHistory.selId && !isDesktopLayout()) {
      noteHistory.selId = "";
      nhShowScreen("list");
      renderNoteHistory();
      return true;
    }
    closeNoteHistory();
    return true;
  }

  function nhShowScreen(name) {
    var ov = document.getElementById("note-history-overlay");
    if (!ov) return;
    ov.querySelector(".nh-screen--list").classList.toggle("hidden", name !== "list");
    ov.querySelector(".nh-screen--view").classList.toggle("hidden", name !== "view");
  }

  function nhSheetsForFilter() {
    var h = noteHistory;
    var seen = {};
    var out = [{ key: NOTE_SHEET_MAIN, title: "Основная" }];
    seen[NOTE_SHEET_MAIN] = true;
    noteSheetState.sheets.forEach(function (s) {
      var k = isPrimarySheetId(s.id) || s.is_primary ? NOTE_SHEET_MAIN : String(s.id);
      if (seen[k]) return;
      seen[k] = true;
      out.push({ key: k, title: String(s.title || "Лист") });
    });
    (h ? h.versions : []).forEach(function (v) {
      var k = nhSheetKey(v);
      if (seen[k]) return;
      seen[k] = true;
      out.push({ key: k, title: String(v.sheet_title || "Лист") + " (удалён)" });
    });
    return out;
  }

  function nhVersionRows() {
    var h = noteHistory;
    var rows = h.versions.filter(function (v) {
      return h.filter === "all" || nhSheetKey(v) === h.filter;
    });
    // Изменение размера — относительно предыдущей (более старой) версии того же листа.
    var bySheet = {};
    h.versions
      .slice()
      .sort(function (a, b) { return Number(a.id) - Number(b.id); })
      .forEach(function (v) {
        var k = nhSheetKey(v);
        v._delta = bySheet[k] == null ? null : Number(v.size || 0) - bySheet[k];
        bySheet[k] = Number(v.size || 0);
      });
    return rows;
  }

  function renderNoteHistory() {
    var h = noteHistory;
    var ov = document.getElementById("note-history-overlay");
    if (!h || !ov) return;
    var filterEl = ov.querySelector(".nh-filter");
    var sheets = nhSheetsForFilter();
    filterEl.innerHTML = "";
    var opts = [{ key: "all", title: "Вся заметка" }].concat(sheets);
    if (opts.length <= 2) opts = [{ key: "all", title: "Вся заметка" }];
    opts.forEach(function (o) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "nh-chip" + (h.filter === o.key ? " is-on" : "");
      b.setAttribute("data-nh", "filter");
      b.setAttribute("data-key", o.key);
      b.textContent = o.title;
      filterEl.appendChild(b);
    });
    filterEl.classList.toggle("hidden", opts.length < 2);
    var list = ov.querySelector(".nh-list");
    list.innerHTML = "";
    if (h.loading) {
      list.innerHTML = '<div class="nh-empty">Загружаю историю…</div>';
      return;
    }
    if (h.error) {
      var err = document.createElement("div");
      err.className = "nh-empty";
      err.textContent = h.error;
      list.appendChild(err);
      return;
    }
    list.appendChild(nhNowRow());
    var rows = nhVersionRows();
    if (!rows.length) {
      var empty = document.createElement("div");
      empty.className = "nh-empty";
      empty.textContent = "Прошлых версий пока нет. Они появятся после правок — не чаще раза в 10 минут, и всегда при крупном изменении или удалении листа.";
      list.appendChild(empty);
      return;
    }
    var lastDay = nhDayLabel(new Date());
    rows.forEach(function (v) {
      var d = nhDate(v);
      var day = nhDayLabel(d);
      if (day !== lastDay) {
        var hd = document.createElement("div");
        hd.className = "nh-day";
        hd.textContent = day;
        list.appendChild(hd);
        lastDay = day;
      }
      list.appendChild(nhRow(v, d));
    });
  }

  function nhAvatar(author) {
    var av = document.createElement("span");
    av.className = "nh-av" + (author.ai ? " nh-av--ai" : "");
    if (author.ai) av.textContent = "✦";
    else if (author.photo) {
      var img = document.createElement("img");
      img.src = author.photo;
      img.alt = "";
      img.referrerPolicy = "no-referrer";
      av.appendChild(img);
    } else av.textContent = (author.name || "·").replace(/^@/, "").charAt(0).toUpperCase() || "·";
    return av;
  }

  function nhNowRow() {
    var h = noteHistory;
    var cur = h.filter === "all" ? null : h.current[h.filter === NOTE_SHEET_MAIN ? "0" : h.filter];
    if (!cur && h.filter === "all") {
      Object.keys(h.current).forEach(function (k) {
        var c = h.current[k];
        if (!cur || String(c.at || "") > String(cur.at || "")) cur = Object.assign({ sheet_id: Number(k) }, c);
      });
    }
    var row = document.createElement("button");
    row.type = "button";
    row.className = "nh-row nh-row--now" + (!h.selId ? " is-sel" : "");
    row.setAttribute("data-nh", "now");
    var author = cur ? nhAuthor(cur) : { name: "" };
    row.appendChild(nhAvatar(author));
    var mid = document.createElement("span");
    mid.className = "nh-row-mid";
    var top = document.createElement("span");
    top.className = "nh-row-top";
    top.innerHTML = "<b>Сейчас</b>";
    var sub = document.createElement("span");
    sub.className = "nh-row-sub";
    sub.textContent = "текущий текст" + (author.name ? " · " + author.name : "");
    mid.appendChild(top);
    mid.appendChild(sub);
    row.appendChild(mid);
    return row;
  }

  function nhRow(v, d) {
    var h = noteHistory;
    var row = document.createElement("button");
    row.type = "button";
    row.className = "nh-row" + (String(h.selId) === String(v.id) ? " is-sel" : "");
    row.setAttribute("data-nh", "pick");
    row.setAttribute("data-id", String(v.id));
    var author = nhAuthor(v);
    row.appendChild(nhAvatar(author));
    var mid = document.createElement("span");
    mid.className = "nh-row-mid";
    var top = document.createElement("span");
    top.className = "nh-row-top";
    var t = document.createElement("b");
    t.textContent = nhTime(d);
    top.appendChild(t);
    if (v._delta != null && v._delta !== 0) {
      var dl = document.createElement("span");
      dl.className = "nh-delta " + (v._delta > 0 ? "is-plus" : "is-minus");
      dl.textContent = (v._delta > 0 ? "+" : "−") + nhNum(v._delta);
      top.appendChild(dl);
    }
    var sub = document.createElement("span");
    sub.className = "nh-row-sub";
    sub.textContent = [author.name, nhSheetLabel(v)].filter(Boolean).join(" · ");
    mid.appendChild(top);
    mid.appendChild(sub);
    var tags = [];
    if (author.ai) tags.push(["правка ИИ", "ai"]);
    if (v.reason === "sheet_deleted") tags.push(["лист удалён", "del"]);
    if (v.reason === "note_deleted") tags.push(["перед удалением", "del"]);
    if (v.reason === "before_restore") tags.push(["до восстановления", ""]);
    if (tags.length) {
      var tg = document.createElement("span");
      tg.className = "nh-tags";
      tags.forEach(function (x) {
        var s = document.createElement("span");
        s.className = "nh-tag" + (x[1] ? " nh-tag--" + x[1] : "");
        s.textContent = x[0];
        tg.appendChild(s);
      });
      mid.appendChild(tg);
    }
    row.appendChild(mid);
    return row;
  }

  function nhFindVersion(id) {
    var h = noteHistory;
    if (!h) return null;
    for (var i = 0; i < h.versions.length; i++) if (String(h.versions[i].id) === String(id)) return h.versions[i];
    return null;
  }

  async function nhLoadBody(v) {
    var h = noteHistory;
    if (h.bodies[v.id] != null) return h.bodies[v.id];
    var data = await apiFetch(
      "/notes/local/" + encodeURIComponent(h.noteId) + "/versions/" + encodeURIComponent(String(v.id)),
      { method: "GET" }
    );
    var body = String((data && data.version && data.version.body) || "");
    if (noteHistory === h) h.bodies[v.id] = body;
    return body;
  }

  async function nhPick(id) {
    var h = noteHistory;
    var v = nhFindVersion(id);
    if (!h || !v) return;
    h.selId = String(v.id);
    renderNoteHistory();
    var desktop = isDesktopLayout();
    if (!desktop) {
      nhShowScreen("view");
      var ov = document.getElementById("note-history-overlay");
      ov.querySelector(".nh-view-title").textContent = nhStamp(nhDate(v));
      ov.querySelector(".nh-view-body").innerHTML = '<p class="nh-empty">Загружаю…</p>';
    } else {
      var pv = nhEnsurePreview();
      if (pv) {
        pv.querySelector(".nh-preview-body").innerHTML = '<p class="nh-empty">Загружаю…</p>';
        pv.classList.remove("hidden");
        document.getElementById("note-editor-overlay").classList.add("nh-previewing");
      }
    }
    try {
      await nhLoadBody(v);
    } catch (e) {
      showNoteToast((e && e.message) || "Не удалось открыть версию");
      return;
    }
    if (noteHistory !== h || h.selId !== String(v.id)) return;
    nhPaintSelected();
  }

  var nhBoardPreview = null;

  function nhPaintSelected() {
    var h = noteHistory;
    var v = h && nhFindVersion(h.selId);
    if (!v) return;
    var body = h.bodies[v.id];
    if (body == null) return;
    var key = nhSheetKey(v);
    var isBoard = String(v.sheet_kind || "").toLowerCase() === "board";
    // Холст — JSON: построчного сравнения нет, показываем версию картинкой.
    var isWeb = String(v.sheet_kind || "").toLowerCase() === "web" || isBoard;
    var host;
    if (isDesktopLayout()) {
      var pv = nhEnsurePreview();
      if (!pv) return;
      var author = nhAuthor(v);
      pv.querySelector(".nh-banner-title").textContent =
        h.mode === "diff" ? "Изменения" : "Версия от " + nhStamp(nhDate(v));
      pv.querySelector(".nh-banner-sub").textContent =
        h.mode === "diff"
          ? "с версии " + nhTime(nhDate(v)) + " до текущей · зелёным — добавлено, красным — удалено"
          : [author.name, nhSheetLabel(v), "только просмотр"].filter(Boolean).join(" · ");
      var diffBtn = pv.querySelector(".nh-banner-diff");
      diffBtn.textContent = h.mode === "diff" ? "Скрыть изменения" : "Показать изменения";
      diffBtn.classList.toggle("hidden", isWeb);
      host = pv.querySelector(".nh-preview-body");
    } else {
      var ov = document.getElementById("note-history-overlay");
      ov.querySelectorAll(".nh-seg button").forEach(function (b) {
        b.classList.toggle("is-on", b.getAttribute("data-nh") === "mode-" + h.mode);
      });
      ov.querySelector(".nh-seg").classList.toggle("hidden", isWeb);
      host = ov.querySelector(".nh-view-body");
    }
    if (nhBoardPreview) {
      nhBoardPreview.destroy();
      nhBoardPreview = null;
    }
    host.innerHTML = "";
    host.classList.toggle("nh-doc--diff", h.mode === "diff");
    if (isBoard && window.LeoBoard) {
      var bh = document.createElement("div");
      bh.className = "nh-board-frame";
      host.appendChild(bh);
      nhBoardPreview = window.LeoBoard.create({ host: bh, json: body, readOnly: true });
    } else if (h.mode === "diff" && !isWeb) {
      var gone = v.reason === "sheet_deleted" && !findNoteSheet(key);
      nhRenderDiff(host, body, gone ? "" : nhCurrentHtml(key));
    } else if (isWeb) {
      var fr = document.createElement("iframe");
      fr.className = "nh-web-frame";
      fr.setAttribute("sandbox", "");
      fr.srcdoc = body;
      host.appendChild(fr);
    } else {
      if (!body.trim()) host.innerHTML = '<p class="nh-empty">Пустой текст</p>';
      else host.appendChild(nhSafeFragment(body));
    }
    var scroller = isDesktopLayout() ? document.querySelector("#note-editor-overlay .note-editor-modal-body") : host;
    if (scroller) scroller.scrollTop = 0;
  }

  function nhHidePreview() {
    if (nhBoardPreview) {
      nhBoardPreview.destroy();
      nhBoardPreview = null;
    }
    var pv = document.getElementById("note-history-preview");
    if (pv) {
      pv.classList.add("hidden");
      var b = pv.querySelector(".nh-preview-body");
      if (b) b.innerHTML = "";
    }
    var ov = document.getElementById("note-editor-overlay");
    if (ov) ov.classList.remove("nh-previewing");
  }

  function nhBackToNow() {
    var h = noteHistory;
    if (!h) return;
    h.selId = "";
    h.mode = "version";
    nhHidePreview();
    renderNoteHistory();
  }

  async function nhRestoreSelected() {
    var h = noteHistory;
    var v = h && nhFindVersion(h.selId);
    if (!v || h.restoring) return;
    var key = nhSheetKey(v);
    var live = key === NOTE_SHEET_MAIN ? true : !!findNoteSheet(key);
    var what = key === NOTE_SHEET_MAIN ? "«Основной»" : "листа «" + String(v.sheet_title || "Лист") + "»";
    var msg = live
      ? "Восстановить версию от " + nhStamp(nhDate(v)) + "?\n\nТекст " + what + " станет как в этой версии. Текущий текст не пропадёт — он сохранится в истории, и восстановление можно отменить."
      : "Вернуть удалённый лист «" + String(v.sheet_title || "Лист") + "»?\n\nОн появится в заметке новым листом.";
    if (!(await confirmDialog(msg))) return;
    if (noteHistory !== h) return;
    h.restoring = true;
    try {
      await flushOpenNoteForShare();
      var res = await apiFetch(
        "/notes/local/" + encodeURIComponent(h.noteId) + "/versions/" + encodeURIComponent(String(v.id)) + "/restore",
        { method: "POST", body: "{}" }
      );
      nhApplyRestore(res);
      closeNoteHistory();
      nhRestoredToast(v, res, h.noteId);
    } catch (e) {
      showNoteToast((e && e.message) || "Не удалось восстановить версию");
    } finally {
      h.restoring = false;
    }
  }

  function nhApplyRestore(res) {
    if (!res) return;
    if (res.kind === "note" && res.item) {
      clearLocalNoteDraft(res.item.id);
      applyRemoteSharedNote(res.item, true);
      return;
    }
    if (res.kind === "sheet" && res.sheet) {
      upsertNoteSheet(res.sheet);
      if (!res.recreated) showRemoteSheetBody(res.sheet);
      renderNoteSheetChips();
    }
  }

  function nhRestoredToast(v, res, noteId) {
    var node = document.createElement("span");
    node.className = "note-toast-copy";
    var t = document.createElement("span");
    t.textContent = res && res.recreated ? "Лист возвращён" : "Версия от " + nhTime(nhDate(v)) + " восстановлена";
    node.appendChild(t);
    var canUndo = res && (res.recreated ? res.sheet : res.undo_version_id);
    if (canUndo) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "note-toast-link";
      b.textContent = "Отменить";
      b.addEventListener("click", function () {
        var el = document.getElementById("note-toast");
        if (el) el.classList.add("hidden");
        nhUndoRestore(res, noteId);
      });
      node.appendChild(b);
    }
    showNoteToast("", { node: node, actionable: true, duration: 5600 });
  }

  async function nhUndoRestore(res, noteId) {
    if (String(currentOpenNoteId()) !== String(noteId)) return;
    try {
      if (res.recreated && res.sheet) {
        await apiFetch(
          "/notes/local/" + encodeURIComponent(noteId) + "/sheets/" + encodeURIComponent(String(res.sheet.id)),
          { method: "DELETE" }
        );
        noteSheetState.sheets = noteSheetState.sheets.filter(function (s) {
          return String(s.id) !== String(res.sheet.id);
        });
        if (String(noteSheetState.leftId) === String(res.sheet.id)) switchLeftSheet(NOTE_SHEET_MAIN);
        renderNoteSheetChips();
      } else {
        await flushOpenNoteForShare();
        var back = await apiFetch(
          "/notes/local/" + encodeURIComponent(noteId) + "/versions/" + encodeURIComponent(String(res.undo_version_id)) + "/restore",
          { method: "POST", body: "{}" }
        );
        nhApplyRestore(back);
      }
      showNoteToast("Восстановление отменено");
    } catch (e) {
      showNoteToast((e && e.message) || "Не удалось отменить");
    }
  }

  function onNoteHistoryClick(e) {
    var b = e.target.closest("[data-nh]");
    if (!b || !noteHistory) return;
    e.preventDefault();
    var act = b.getAttribute("data-nh");
    if (act === "close" || act === "close-m") closeNoteHistory();
    else if (act === "list") noteHistoryBack();
    else if (act === "filter") {
      noteHistory.filter = b.getAttribute("data-key") || "all";
      renderNoteHistory();
    } else if (act === "now") nhBackToNow();
    else if (act === "pick") nhPick(b.getAttribute("data-id"));
    else if (act === "toggle-diff") {
      noteHistory.mode = noteHistory.mode === "diff" ? "version" : "diff";
      nhPaintSelected();
    } else if (act === "mode-version" || act === "mode-diff") {
      noteHistory.mode = act === "mode-diff" ? "diff" : "version";
      nhPaintSelected();
    } else if (act === "restore") nhRestoreSelected();
  }

  window.addEventListener("resize", function () {
    if (!noteHistory) return;
    // Перешли между телефоном и десктопом — показываем выбранную версию в нужном месте.
    var desktop = isDesktopLayout();
    if (desktop) nhShowScreen("list");
    else nhHidePreview();
    if (noteHistory.selId) {
      if (!desktop) nhShowScreen("view");
      else {
        var pv = nhEnsurePreview();
        if (pv) {
          pv.classList.remove("hidden");
          document.getElementById("note-editor-overlay").classList.add("nh-previewing");
        }
      }
      nhPaintSelected();
    }
  });

  function fillNoteMoreMenu() {
    var menu = document.getElementById("note-editor-more-menu");
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!menu || !wrap) return;
    menu.innerHTML = "";
    var shared = !!wrap._shareShared;

    function addItem(label, onClick, disabled, opts) {
      opts = opts || {};
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className =
        "note-more-menu-item" + (opts.danger ? " note-more-menu-item--danger" : "");
      btn.textContent = label;
      if (disabled) {
        btn.disabled = true;
        btn.classList.add("is-busy");
      } else {
        btn.addEventListener("click", function (e) {
          e.stopPropagation();
          onClick();
        });
      }
      menu.appendChild(btn);
    }

    var mobileTocMenu =
      !window.matchMedia || window.matchMedia("(max-width: 959px)").matches;
    if (false && mobileTocMenu && getActiveNoteEditorPage()) {
      addItem("Оглавление", function () {
        closeNoteMoreMenu();
        openActiveNoteEditorToc();
      });
    }

    if (noteSheetsEnabled()) {
      addItem("Новый лист", function () {
        closeNoteMoreMenu();
        createNoteSheet({ openOn: "left", kind: "doc" });
      });
      addItem("Новая доска", function () {
        closeNoteMoreMenu();
        createNoteSheet({ openOn: "left", kind: "board" });
      });
      addItem("Новая презентация", function () {
        closeNoteMoreMenu();
        createNoteSheet({ openOn: "left", kind: "web" });
      });
    }

    var shareKind = String(wrap._shareKind || "");
    var shareId = wrap._shareId ? String(wrap._shareId) : "";
    if (shareId && (shareKind === "local" || shareKind === "journal")) {
      addItem("Выгрузить…", function () {
        closeNoteMoreMenu();
        openNoteExportSheet([{ kind: shareKind, id: shareId }]);
      });
    }

    if (shareId && shareKind === "local" && !wrap._isKnowledge) {
      addItem("Копировать в Базу знаний", function () {
        closeNoteMoreMenu();
        copyLocalNoteToKnowledge(shareId);
      });
    }

    if (wrap._isKnowledge && wrap._isNoteOwner !== false) {
      addItem("Поделиться с командой", function () {
        closeNoteMoreMenu();
        openNoteTeamShareSheet();
      });
    }

    if (shareKind === "local" || shareKind === "journal") {
      // «Поделиться» — иконкой в шапке; там же «Отключить все ссылки».
    } else if (!shared) {
      addItem("Поделиться", function () {
        closeNoteMoreMenu();
        openShareAccessSheet();
      });
    } else {
      addItem(
        wrap._shareAccess === "comment"
          ? "Сменить доступ · комментарии"
          : "Сменить доступ · просмотр",
        function () {
          closeNoteMoreMenu();
          openShareAccessSheet();
        }
      );
      addItem("Скопировать ссылку", function () {
        copyExistingShareLink();
      });
      addItem("Закрыть доступ", function () {
        revokeShareLink();
      });
    }

    if (shareId && shareKind === "local" && String(shareId).indexOf("tmp_") !== 0 && !wrap._isKnowledge) {
      var hasMeeting = noteMeetingState.noteId === String(shareId) && !!noteMeetingState.meeting;
      addItem(hasMeeting ? "Другая встреча" : "Добавить ко встрече", function () {
        closeNoteMoreMenu();
        openNoteMeetingPicker(shareId);
      });
    }

    if (shareId && shareKind === "local" && String(shareId).indexOf("tmp_") !== 0) {
      addItem("История версий", function () {
        closeNoteMoreMenu();
        openNoteHistory();
      });
    }

    if (shareId && (shareKind === "local" || shareKind === "journal")) {
      var isKb = !!wrap._isKnowledge;
      var deleteLabel =
        wrap._isNoteOwner === false
          ? isKb
            ? "Убрать из списка"
            : "Убрать из списка"
          : isKb
            ? "Удалить документ"
            : "Удалить заметку";
      addItem(
        deleteLabel,
        async function () {
          closeNoteMoreMenu();
          var msg =
            wrap._isNoteOwner === false
              ? isKb
                ? "Убрать документ из списка?"
                : "Убрать заметку из списка?"
              : isKb
                ? "Удалить документ?"
                : "Удалить заметку?";
          if (!(await confirmDialog(msg))) return;
          try {
            await deleteLocalNoteById(shareId);
            closeNoteEditorModal();
            if (notesDataCache) renderNotesPanesFromData(notesDataCache);
            if (knowledgeDataCache) renderKnowledgePaneFromData(knowledgeDataCache);
          } catch (err) {
            alert(err.message || String(err));
          }
        },
        false,
        { danger: true }
      );
    }
  }

  var GPT_MODEL_LS = "leo_gpt_model";
  var GPT_MODEL_DEFAULT = "openai/gpt-4.1";
  var RESEARCH_MODEL_LS = "leo_research_model";
  var PAIE_MODEL_LS = "leo_paie_model";
  var PAIE_MODEL_DEFAULT = "google/gemini-2.5-flash";
  var gptModelsState = { loaded: false, loading: false, models: [], defaultId: GPT_MODEL_DEFAULT };
  var paieModelsState = { loaded: false, loading: false, models: [], defaultId: PAIE_MODEL_DEFAULT };
  var userAgentsState = { loaded: false, loading: false, agents: [] };
  var composerAgentModel = "";

  function noteComposerAsset(name) {
    return "/webapp/icons/" + name + ".svg?v=" + WEBAPP_BUILD;
  }

  function noteAskModeLabel(mode) {
    if (mode === "gpt") return "Ассистент";
    if (mode === "research") return "Исследование";
    if (mode === "comment") return "Комментарий";
    if (mode === "paie") return "Совет PAIE";
    var agent = findUserAgent(mode);
    return (agent && agent.title) || "Агент";
  }

  function noteAskUsesChips(mode) {
    return mode === "gpt" || mode === "research" || isCustomAskMode(mode);
  }

  function noteAskUsesComposerEditor(mode) {
    return noteAskUsesChips(mode) || mode === "comment";
  }

  function noteAskAllowsMentions(mode) {
    return isChatAskMode(mode) || mode === "comment";
  }

  function noteAskPlaceholder(mode) {
    var wrap = document.getElementById("note-editor-more-wrap");
    var quoted = !!(wrap && wrap._commentDraft && String(wrap._commentDraft.quote || "").trim());
    var isChatThread = !!(wrap && wrap._shareKind === "chat");
    if (isChatAskMode(mode)) {
      if (gptComposerChipCount(noteGptEditor())) {
        return "Спросите про выделенный текст…";
      }
      return isChatThread ? "Задайте вопрос…" : "Спросите или попросите изменить заметку…";
    }
    if (mode === "research") {
      return gptComposerChipCount(noteGptEditor())
        ? "Что исследовать по выделенному?"
        : "Что исследовать? Например: цены конкурентов";
    }
    if (mode === "comment") {
      var chatNow = currentDiscussChatId();
      if (chatNow !== null && chatNow !== COMMENTS_CHAT_ID) return "Сообщение в чат без ответа ИИ";
      return quoted ? "Комментарий к выделенному тексту" : "Комментарий для участников…";
    }
    return quoted
      ? "Уточнение по выделенному тексту"
      : "Уточнение или новая информация — CHAIR ответит";
  }

  var GPT_CHIP_MAX = 5;
  var GPT_CHIP_PREVIEW = 36;
  var GPT_QUOTE_MAX = 2000;

  function noteGptEditor() {
    return document.getElementById("note-paie-reply-editor");
  }

  function clipChipPreview(text) {
    var raw = String(text || "").replace(/\s+/g, " ").trim();
    if (raw.length <= GPT_CHIP_PREVIEW) return raw;
    return raw.slice(0, GPT_CHIP_PREVIEW - 1) + "…";
  }

  function clipGptQuote(text) {
    var raw = String(text || "").replace(/\s+/g, " ").trim();
    if (raw.length > GPT_QUOTE_MAX) return raw.slice(0, GPT_QUOTE_MAX - 1) + "…";
    return raw;
  }

  function gptComposerChipCount(ed) {
    return ed ? ed.querySelectorAll(".note-gpt-quote-chip").length : 0;
  }

  function gptComposerIsEmpty(ed) {
    if (!ed) return true;
    if (ed.querySelector(".note-gpt-quote-chip")) return false;
    if (ed.querySelector(".note-discuss-mention")) return false;
    if (ed.querySelector("ul, ol, h1, h2, h3")) return false;
    return !String(ed.innerText || "").replace(/\u00a0/g, " ").trim();
  }

  function normalizeEmptyGptComposer(ed) {
    if (!ed || !gptComposerIsEmpty(ed)) return false;
    var html = String(ed.innerHTML || "")
      .replace(/<br\s*\/?>/gi, "")
      .replace(/&nbsp;/gi, "")
      .replace(/\u00a0/g, "")
      .replace(/<div><\/div>/gi, "")
      .replace(/<p><\/p>/gi, "")
      .trim();
    if (!html) {
      if (ed.innerHTML !== "") {
        ed.innerHTML = "";
        return true;
      }
      return false;
    }
    return false;
  }

  function placeComposerCaretAtStart(ed) {
    if (!ed || document.activeElement !== ed) return;
    try {
      var sel = window.getSelection();
      if (!sel) return;
      var range = document.createRange();
      range.selectNodeContents(ed);
      range.collapse(true);
      sel.removeAllRanges();
      sel.addRange(range);
    } catch (_) {}
  }

  function syncGptEditorEmpty(ed) {
    ed = ed || noteGptEditor();
    if (!ed) return;
    var cleared = normalizeEmptyGptComposer(ed);
    var empty = gptComposerIsEmpty(ed);
    ed.classList.toggle("is-empty", empty);
    if (cleared && empty) placeComposerCaretAtStart(ed);
  }

  function clearGptComposer() {
    var ed = noteGptEditor();
    if (!ed) return;
    ed.innerHTML = "";
    ed._savedRange = null;
    syncGptEditorEmpty(ed);
    autosizeNoteComposer(ed);
  }

  function composerEditorValue(el) {
    if (!el) return "";
    if (typeof el.value === "string" && !el.isContentEditable) return el.value || "";
    return String(el.innerText || "").replace(/\u00a0/g, " ");
  }

  // ——— Вёрстка в поле ввода обсуждения / чатов, как в заметках ———
  // «# », «## », «### » — заголовок; «- », «* » — список; «1. » — нумерованный.
  // Enter в пункте — новый пункт, на пустом — выход из списка; Backspace в начале — обычная строка.
  var COMPOSER_MD_BLOCK = /^(H[1-3]|LI)$/;

  function composerCaret(ed) {
    var sel = window.getSelection();
    if (!sel || !sel.rangeCount || !sel.isCollapsed) return null;
    var r = sel.getRangeAt(0);
    return ed.contains(r.startContainer) ? r : null;
  }

  function composerBlockOf(ed, node) {
    for (var n = node; n && n !== ed; n = n.parentNode) {
      if (n.nodeType === 1 && COMPOSER_MD_BLOCK.test(n.nodeName)) return n;
    }
    return null;
  }

  function composerPlaceCaret(el, atEnd) {
    var r = document.createRange();
    r.selectNodeContents(el);
    r.collapse(!atEnd);
    var sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(r);
  }

  function composerFill(el) {
    if (!String(el.textContent || "").length && !el.querySelector("br, .note-discuss-mention")) el.appendChild(document.createElement("br"));
    return el;
  }

  // Строка ввода: узлы от начала строки (после <br> или начала обёртки) до следующего <br>.
  function composerLineNodes(node) {
    var nodes = [node];
    for (var n = node.nextSibling; n; n = n.nextSibling) {
      nodes.push(n);
      if (n.nodeName === "BR") break;
    }
    return nodes;
  }

  function composerMdInputRule(ed, e) {
    if (!e || e.inputType !== "insertText" || e.data !== " ") return;
    var r = composerCaret(ed);
    if (!r || r.startContainer.nodeType !== 3) return;
    var tn = r.startContainer;
    if (composerBlockOf(ed, tn)) return;
    var par = tn.parentNode;
    if (par !== ed && !((par.nodeName === "DIV" || par.nodeName === "P") && par.parentNode === ed)) return;
    var prev = tn.previousSibling;
    // Пустые текстовые узлы (остаются после переноса строки) — не текст перед маркером.
    while (prev && prev.nodeType === 3 && !prev.nodeValue) {
      var gone = prev;
      prev = prev.previousSibling;
      gone.remove();
    }
    if (prev && prev.nodeName !== "BR") return;
    var before = tn.nodeValue.slice(0, r.startOffset).replace(/\u00a0/g, " ");
    var m = /^(#{1,3}) $/.exec(before) || /^([-*•]) $/.exec(before) || /^(\d{1,3})[.)] $/.exec(before);
    if (!m) return;
    var block;
    var wrap;
    if (m[1].charAt(0) === "#") {
      block = wrap = document.createElement("h" + m[1].length);
    } else {
      var ordered = /^\d/.test(m[1]);
      wrap = document.createElement(ordered ? "ol" : "ul");
      if (ordered && m[1] !== "1") wrap.setAttribute("start", m[1]);
      block = document.createElement("li");
      wrap.appendChild(block);
    }
    tn.nodeValue = tn.nodeValue.slice(r.startOffset);
    var line = composerLineNodes(tn);
    var whole = par !== ed && !prev && line[line.length - 1] === par.lastChild;
    var anchor = whole ? par : line[0];
    anchor.parentNode.insertBefore(wrap, anchor);
    line.forEach(function (n) {
      if (n.nodeName === "BR" && n === line[line.length - 1] && line.length > 1) n.remove();
      else block.appendChild(n);
    });
    if (whole) par.remove();
    if (prev && prev.nodeName === "BR") prev.remove();
    composerFill(block);
    // Подряд идущие списки одного вида — один список.
    var before2 = wrap.previousSibling;
    if (block !== wrap && before2 && before2.nodeName === wrap.nodeName) {
      before2.appendChild(block);
      wrap.remove();
    }
    composerPlaceCaret(block, false);
  }

  function composerMdKeydown(ed, e) {
    if (e.key !== "Enter" && e.key !== "Backspace") return false;
    if (e.metaKey || e.ctrlKey || e.altKey) return false;
    var r = composerCaret(ed);
    if (!r) return false;
    var block = composerBlockOf(ed, r.startContainer);
    if (!block) return false;
    var atStart = (function () {
      var t = document.createRange();
      t.selectNodeContents(block);
      t.setEnd(r.startContainer, r.startOffset);
      return !t.toString().length;
    })();
    var empty = !String(block.textContent || "").replace(/\u00a0/g, " ").trim() && !block.querySelector(".note-discuss-mention");
    if (e.key === "Backspace") {
      if (!atStart) return false;
      e.preventDefault();
      composerUnwrapBlock(ed, block);
      return true;
    }
    if (e.shiftKey && block.nodeName !== "LI") return false;
    e.preventDefault();
    if (block.nodeName === "LI" && empty) {
      composerUnwrapBlock(ed, block);
      return true;
    }
    // Остаток строки после каретки — в новый пункт (или в обычную строку после заголовка).
    var tail = document.createRange();
    tail.setStart(r.startContainer, r.startOffset);
    tail.setEnd(block, block.childNodes.length);
    var frag = tail.extractContents();
    var next = document.createElement(block.nodeName === "LI" ? "li" : "div");
    next.appendChild(frag);
    [block, next].forEach(function (el) {
      Array.prototype.slice.call(el.childNodes).forEach(function (n) {
        if (n.nodeType === 3 && !n.nodeValue) n.remove();
      });
    });
    composerFill(block);
    composerFill(next);
    block.parentNode.insertBefore(next, block.nextSibling);
    composerPlaceCaret(next, false);
    return true;
  }

  // Пункт / заголовок → обычная строка на том же месте (список при этом делится надвое).
  function composerUnwrapBlock(ed, block) {
    var line = document.createElement("div");
    while (block.firstChild) line.appendChild(block.firstChild);
    composerFill(line);
    if (block.nodeName !== "LI") {
      block.parentNode.replaceChild(line, block);
    } else {
      var list = block.parentNode;
      var idx = Array.prototype.indexOf.call(list.children, block);
      var rest = [];
      for (var n = block.nextSibling; n; n = n.nextSibling) rest.push(n);
      block.remove();
      list.parentNode.insertBefore(line, list.nextSibling);
      if (rest.length) {
        var tailList = document.createElement(list.nodeName.toLowerCase());
        if (list.nodeName === "OL") {
          // Номера после выделенной строки не сдвигаются: «3. c» остаётся третьим.
          tailList.setAttribute("start", String(Number(list.getAttribute("start") || 1) + idx + 1));
        }
        rest.forEach(function (x) {
          tailList.appendChild(x);
        });
        line.parentNode.insertBefore(tailList, line.nextSibling);
      }
      if (!list.children.length) list.remove();
    }
    composerPlaceCaret(line, false);
  }

  function serializeGptComposer(ed) {
    ed = ed || noteGptEditor();
    if (!ed) return { text: "", quotes: [] };
    var quotes = [];
    var parts = [];
    // То же по порядку: цитата — строками «> …», за ней свой текст (для нескольких реплаев).
    var threaded = [];
    function push(t) {
      parts.push(t);
      threaded.push(t);
    }
    function walk(node) {
      if (node.nodeType === 3) {
        push(node.nodeValue);
        return;
      }
      if (node.nodeType !== 1) return;
      if (node.classList && node.classList.contains("note-gpt-quote-chip")) {
        var q = String(node.getAttribute("data-quote") || "").trim();
        // Цитата уходит в поле quote / reply UI, не в тело бабла.
        if (q) {
          quotes.push(q);
          threaded.push("\n\n" + q.split("\n").map(function (l) { return "> " + l; }).join("\n") + "\n");
        }
        return;
      }
      if (node.classList && node.classList.contains("note-discuss-mention")) {
        var mention = String(node.getAttribute("data-mention") || node.textContent || "").trim();
        if (mention) push(mention.indexOf("@") === 0 ? mention : "@" + mention);
        return;
      }
      if (node.nodeName === "BR") {
        // Пустая строка пункта списка / заголовка — не перенос.
        if (!(node.parentNode && /^(LI|H[1-6])$/.test(node.parentNode.nodeName) && node.parentNode.childNodes.length === 1)) push("\n");
        return;
      }
      // Вёрстка из поля ввода → Markdown: «# заголовок», «- пункт», «1. пункт».
      var md = /^H([1-6])$/.exec(node.nodeName);
      if (md || node.nodeName === "LI") {
        if (parts.length && parts[parts.length - 1] !== "\n") push("\n");
        var p0 = parts.length;
        var t0 = threaded.length;
        var prefix = md ? "#".repeat(Number(md[1])) + " " : "- ";
        if (!md && node.parentNode && node.parentNode.nodeName === "OL") {
          var n = Number(node.parentNode.getAttribute("start") || 1);
          for (var sib = node.previousElementSibling; sib; sib = sib.previousElementSibling) n++;
          prefix = n + ". ";
        }
        push(prefix);
        var kidsMd = node.childNodes;
        for (var k = 0; k < kidsMd.length; k++) walk(kidsMd[k]);
        if (!parts.slice(p0 + 1).join("").replace(/\u00a0/g, " ").trim()) {
          parts.length = p0;
          threaded.length = t0;
          return;
        }
        push("\n");
        return;
      }
      if (node.nodeName === "UL" || node.nodeName === "OL") {
        var lk = node.childNodes;
        for (var li = 0; li < lk.length; li++) walk(lk[li]);
        return;
      }
      var block = node.nodeName === "DIV" || node.nodeName === "P";
      if (block && parts.length && parts[parts.length - 1] !== "\n") push("\n");
      var kids = node.childNodes;
      for (var i = 0; i < kids.length; i++) walk(kids[i]);
    }
    var rootKids = ed.childNodes;
    for (var r = 0; r < rootKids.length; r++) walk(rootKids[r]);
    function tidy(arr) {
      return arr
        .join("")
        .replace(/\u00a0/g, " ")
        .replace(/[ \t]+\n/g, "\n")
        .replace(/\n{3,}/g, "\n\n")
        .trim();
    }
    // Несколько цитат с комментариями между ними — отправляем по порядку («> цитата», под ней комментарий),
    // и в сообщении, и для модели; раньше все цитаты слипались в начале, а комментарии — после.
    if (quotes.length > 1) return { text: tidy(threaded), quotes: [], threaded: true };
    return { text: tidy(parts), quotes: quotes };
  }

  // Тело с реплаями по порядку: строки «> …» — блок цитаты, за ним свой текст.
  function isThreadedDiscussBody(text) {
    return /(^|\n)> /.test(String(text || ""));
  }

  // comment — сохранённое сообщение: цитата ведёт к сообщению, откуда взята (или к фрагменту заметки).
  function appendDiscussThreadedBody(bubble, text, withMentions, comment) {
    var quoteBuf = [];
    var textBuf = [];
    function flushQuote() {
      if (!quoteBuf.length) return;
      var q = quoteBuf.join("\n");
      quoteBuf = [];
      var targetId = comment ? findDiscussMessageByQuote(q, comment.id) : 0;
      var who = targetId ? discussReplyWhoLabel({ parent_id: targetId }) || "Цитата" : "Фрагмент";
      appendDiscussReplyQuote(bubble, q, who, targetId);
      if (targetId || !comment) return;
      // Не из ленты — значит из заметки: нажатие показывает фрагмент в заметке.
      var noteReply = bubble.lastElementChild;
      if (!noteReply || !noteReply.classList.contains("note-discuss-reply")) return;
      noteReply.classList.add("is-nav");
      noteReply.setAttribute("role", "button");
      noteReply.setAttribute("tabindex", "0");
      noteReply.title = "Показать в заметке";
      noteReply.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        jumpToNoteQuote(comment, q);
      });
    }
    function flushText() {
      var t = textBuf.join("\n").trim();
      textBuf = [];
      if (!t) return;
      var el = document.createElement("div");
      el.className = "note-discuss-bubble-body note-discuss-thread-text";
      if (withMentions) fillDiscussBodyWithMentions(el, t);
      else el.textContent = t;
      bubble.appendChild(el);
    }
    String(text || "").split("\n").forEach(function (line) {
      if (/^> ?/.test(line)) {
        flushText();
        quoteBuf.push(line.replace(/^> ?/, ""));
      } else {
        flushQuote();
        textBuf.push(line);
      }
    });
    flushQuote();
    flushText();
  }

  function cloneGptEditorRange(range, ed) {
    if (!range || !ed) return null;
    try {
      var root = range.commonAncestorContainer;
      if (root !== ed && !ed.contains(root)) return null;
      return range.cloneRange();
    } catch (_) {
      return null;
    }
  }

  function rememberGptEditorRange() {
    var ed = noteGptEditor();
    if (!ed || ed._ignoreRange) return;
    if (document.activeElement !== ed) return;
    var sel = window.getSelection && window.getSelection();
    if (!sel || !sel.rangeCount) return;
    var saved = cloneGptEditorRange(sel.getRangeAt(0), ed);
    if (saved) ed._savedRange = saved;
  }

  function restoreGptEditorRange(ed, preferred) {
    var sel = window.getSelection && window.getSelection();
    if (!ed || !sel) return;
    sel.removeAllRanges();
    var range = cloneGptEditorRange(preferred || ed._savedRange, ed);
    if (range) {
      try {
        sel.addRange(range);
        return;
      } catch (_) {}
    }
    range = document.createRange();
    range.selectNodeContents(ed);
    range.collapse(false);
    sel.addRange(range);
  }

  function insertGptQuoteChip(quote) {
    var ed = noteGptEditor();
    var q = clipGptQuote(quote);
    if (!ed || !q) return false;
    if (gptComposerChipCount(ed) >= GPT_CHIP_MAX) {
      showNoteToast("Можно добавить не больше 5 отрывков");
      return false;
    }
    var saved = cloneGptEditorRange(ed._savedRange, ed);
    var chip = document.createElement("span");
    chip.className = "note-gpt-quote-chip";
    chip.setAttribute("data-quote", q);
    chip.setAttribute("contenteditable", "false");
    chip.textContent = clipChipPreview(q);
    ed._ignoreRange = true;
    try {
      try {
        ed.focus();
      } catch (_) {}
      if (saved) ed._savedRange = saved;
      restoreGptEditorRange(ed, saved);
      var sel = window.getSelection();
      var range = sel && sel.rangeCount ? cloneGptEditorRange(sel.getRangeAt(0), ed) : null;
      if (!range) {
        range = document.createRange();
        range.selectNodeContents(ed);
        range.collapse(false);
      }
      range.deleteContents();
      var spaceAfter = document.createTextNode("\u00a0");
      range.insertNode(spaceAfter);
      range.insertNode(chip);
      var caret = document.createRange();
      caret.setStartAfter(spaceAfter);
      caret.collapse(true);
      if (sel) {
        sel.removeAllRanges();
        sel.addRange(caret);
      }
      ed._savedRange = caret.cloneRange();
    } finally {
      ed._ignoreRange = false;
    }
    syncGptEditorEmpty(ed);
    autosizeNoteComposer(ed);
    ed.setAttribute("data-placeholder", noteAskPlaceholder(noteAskMode()));
    syncNotePaieReplyForm();
    return true;
  }

  function adjacentGptChip(ed, dir) {
    var sel = window.getSelection();
    if (!ed || !sel || !sel.isCollapsed || !sel.rangeCount) return null;
    var range = sel.getRangeAt(0);
    var node = range.startContainer;
    var offset = range.startOffset;
    function isChip(n) {
      return !!(
        n &&
        n.nodeType === 1 &&
        n.classList &&
        (n.classList.contains("note-gpt-quote-chip") || n.classList.contains("note-discuss-mention"))
      );
    }
    function isBlankText(n) {
      return !!(n && n.nodeType === 3 && !String(n.nodeValue || "").replace(/[\s\u00a0]/g, ""));
    }
    function walk(start) {
      var n = start;
      while (n) {
        if (isChip(n)) return n;
        if (n.nodeType === 3 && !isBlankText(n)) return null;
        n = dir < 0 ? n.previousSibling : n.nextSibling;
      }
      return null;
    }
    if (node === ed) {
      return dir < 0 ? walk(ed.childNodes[offset - 1]) : walk(ed.childNodes[offset]);
    }
    if (node.nodeType === 3) {
      var raw = node.nodeValue || "";
      if (
        dir < 0 &&
        (offset === 0 || !String(raw.slice(0, offset) || "").replace(/[\s\u00a0]/g, ""))
      ) {
        return walk(node.previousSibling);
      }
      if (
        dir > 0 &&
        (offset === raw.length || !String(raw.slice(offset) || "").replace(/[\s\u00a0]/g, ""))
      ) {
        return walk(node.nextSibling);
      }
      return null;
    }
    if (isChip(node)) return node;
    if (node.nodeType === 1 && node !== ed && offset === 0 && dir < 0) {
      return walk(node.previousSibling);
    }
    return null;
  }

  function selectedGptChip(ed) {
    var sel = window.getSelection();
    if (!ed || !sel || !sel.rangeCount) return null;
    var node = sel.anchorNode;
    var el = node && (node.nodeType === 1 ? node : node.parentElement);
    var chip =
      el && el.closest
        ? el.closest(".note-gpt-quote-chip, .note-discuss-mention")
        : null;
    return chip && ed.contains(chip) ? chip : null;
  }

  function removeGptChip(ed, chip) {
    if (!ed || !chip || !chip.parentNode) return;
    var next = document.createRange();
    next.setStartBefore(chip);
    next.collapse(true);
    chip.parentNode.removeChild(chip);
    var sel = window.getSelection();
    if (sel) {
      sel.removeAllRanges();
      sel.addRange(next);
    }
    ed._savedRange = next.cloneRange();
    syncGptEditorEmpty(ed);
    autosizeNoteComposer(ed);
    if (ed) ed.setAttribute("data-placeholder", noteAskPlaceholder("gpt"));
    syncNotePaieReplyForm();
  }

  function discussionParticipants() {
    var wrap = document.getElementById("note-editor-more-wrap");
    var rows = (wrap && wrap._noteMembers) || [];
    return rows
      .map(function (m) {
        if (!m) return null;
        var uname = String(m.username || "").trim().replace(/^@/, "");
        var name = String(m.name || "").trim();
        if (!name) {
          name = uname
            ? "@" + uname
            : [m.first_name, m.last_name].filter(Boolean).join(" ").trim();
        }
        if (!name && !uname) name = "Участник";
        return {
          user_id: String(m.user_id || ""),
          username: uname,
          name: name,
          mention: uname
            ? "@" + uname
            : "@" + String(name || "user").replace(/\s+/g, ""),
        };
      })
      .filter(function (m) {
        return m && m.user_id;
      });
  }

  function closeDiscussMentionMenu() {
    var menu = document.getElementById("note-discuss-mention-menu");
    if (menu) menu.classList.add("hidden");
  }

  function ensureDiscussMentionMenu() {
    var form = document.getElementById("note-paie-reply-form");
    if (!form) return null;
    var menu = document.getElementById("note-discuss-mention-menu");
    if (menu) return menu;
    menu = document.createElement("div");
    menu.id = "note-discuss-mention-menu";
    menu.className = "note-discuss-mention-menu hidden";
    menu.setAttribute("role", "listbox");
    form.appendChild(menu);
    return menu;
  }

  function getMentionQueryAtCaret(ed) {
    var sel = window.getSelection && window.getSelection();
    if (!ed || !sel || !sel.rangeCount || !sel.isCollapsed) return null;
    var range = sel.getRangeAt(0);
    var node = range.startContainer;
    if (!node || node.nodeType !== 3 || !ed.contains(node)) return null;
    var before = String(node.nodeValue || "").slice(0, range.startOffset);
    var m = before.match(/(^|[\s\u00a0([{\"'«])@([a-zA-Z0-9_]{0,32})$/);
    if (!m) return null;
    return {
      query: String(m[2] || ""),
      node: node,
      start: range.startOffset - (String(m[2] || "").length + 1),
      end: range.startOffset,
    };
  }

  function renderDiscussMentionMenu(query) {
    var menu = ensureDiscussMentionMenu();
    if (!menu) return;
    var q = String(query || "").toLowerCase();
    var rows = discussionParticipants().filter(function (m) {
      if (!q) return true;
      return (
        String(m.username || "").toLowerCase().indexOf(q) >= 0 ||
        String(m.name || "").toLowerCase().indexOf(q) >= 0
      );
    });
    menu.innerHTML = "";
    if (!rows.length) {
      menu.classList.add("hidden");
      return;
    }
    rows.slice(0, 8).forEach(function (m) {
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "note-discuss-mention-item";
      btn.setAttribute("role", "option");
      var title = document.createElement("span");
      title.className = "note-discuss-mention-item-name";
      title.textContent = m.name;
      btn.appendChild(title);
      if (m.username) {
        var handle = document.createElement("span");
        handle.className = "note-discuss-mention-item-handle";
        handle.textContent = "@" + m.username;
        btn.appendChild(handle);
      }
      btn.addEventListener("mousedown", function (e) {
        e.preventDefault();
        e.stopPropagation();
        insertDiscussMention(m);
      });
      menu.appendChild(btn);
    });
    menu.classList.remove("hidden");
  }

  function syncDiscussMentionMenu() {
    var ed = noteGptEditor();
    if (!ed || !noteAskAllowsMentions(noteAskMode())) {
      closeDiscussMentionMenu();
      return;
    }
    if (!discussionParticipants().length) {
      closeDiscussMentionMenu();
      return;
    }
    var at = getMentionQueryAtCaret(ed);
    if (!at) {
      closeDiscussMentionMenu();
      return;
    }
    renderDiscussMentionMenu(at.query);
  }

  function insertDiscussMention(member) {
    var ed = noteGptEditor();
    if (!ed || !member) return;
    var at = getMentionQueryAtCaret(ed);
    var chip = document.createElement("span");
    chip.className = "note-discuss-mention";
    chip.setAttribute("contenteditable", "false");
    chip.setAttribute("data-user-id", String(member.user_id || ""));
    chip.setAttribute("data-mention", member.mention || ("@" + (member.username || member.name)));
    if (member.username) chip.setAttribute("data-username", member.username);
    chip.textContent = member.mention || ("@" + (member.username || member.name));
    ed._ignoreRange = true;
    try {
      try {
        ed.focus();
      } catch (_) {}
      var sel = window.getSelection();
      if (at && at.node && sel) {
        var del = document.createRange();
        del.setStart(at.node, at.start);
        del.setEnd(at.node, at.end);
        del.deleteContents();
        del.insertNode(chip);
        var after = document.createTextNode("\u00a0");
        if (chip.parentNode) chip.parentNode.insertBefore(after, chip.nextSibling);
        var caret = document.createRange();
        caret.setStart(after, after.nodeValue.length);
        caret.collapse(true);
        sel.removeAllRanges();
        sel.addRange(caret);
        ed._savedRange = caret.cloneRange();
      } else {
        restoreGptEditorRange(ed);
        sel = window.getSelection();
        if (sel && sel.rangeCount) {
          var r = sel.getRangeAt(0);
          r.deleteContents();
          r.insertNode(chip);
          r.setStartAfter(chip);
          r.collapse(true);
          sel.removeAllRanges();
          sel.addRange(r);
          ed._savedRange = r.cloneRange();
        } else {
          ed.appendChild(chip);
        }
      }
    } finally {
      ed._ignoreRange = false;
    }
    closeDiscussMentionMenu();
    syncGptEditorEmpty(ed);
    autosizeNoteComposer(ed);
    syncNotePaieReplyForm();
  }

  // Текст сообщения: ссылки кликабельны, @упоминания подсвечены.
  function appendDiscussTextWithLinks(el, text) {
    var re = /(https?:\/\/[^\s<>"]+|www\.[^\s<>"]+)/gi;
    var last = 0;
    var m;
    while ((m = re.exec(text))) {
      var href = safeHttpUrl(m[0]);
      if (!href) continue;
      var tail = (m[0].match(/[),.;:!?'"»]+$/) || [""])[0];
      var shown = tail ? m[0].slice(0, -tail.length) : m[0];
      if (m.index > last) el.appendChild(document.createTextNode(text.slice(last, m.index)));
      var a = document.createElement("a");
      a.className = "note-discuss-link";
      a.href = href;
      a.target = "_blank";
      a.rel = "noopener noreferrer";
      a.textContent = shown;
      a.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        openExternal(this.href);
      });
      el.appendChild(a);
      last = m.index + shown.length;
    }
    if (last < text.length) el.appendChild(document.createTextNode(text.slice(last)));
  }

  function fillDiscussBodyWithMentions(el, text) {
    if (!el) return;
    var raw = String(text || "");
    el.textContent = "";
    if (!raw) return;
    var re = /(^|[\s([{«"'])(@[a-zA-Z0-9_]{2,32})/g;
    var last = 0;
    var m;
    while ((m = re.exec(raw))) {
      var start = m.index + m[1].length;
      if (start > last) appendDiscussTextWithLinks(el, raw.slice(last, start));
      var span = document.createElement("span");
      span.className = "note-discuss-mention-text";
      span.textContent = m[2];
      el.appendChild(span);
      last = start + m[2].length;
    }
    if (last < raw.length) appendDiscussTextWithLinks(el, raw.slice(last));
  }

  // Сообщение участника: «# », «- », «1. » из поля ввода — заголовки и списки; упоминания и ссылки как раньше.
  var DISCUSS_MD_LINE = /^(?:(#{1,3}) |[-*•] |(\d{1,3})[.)] )(.*)$/;

  function fillDiscussBodyBlocks(el, text) {
    var lines = String(text || "").split("\n");
    if (!lines.some(function (l) { return DISCUSS_MD_LINE.test(l); })) {
      fillDiscussBodyWithMentions(el, text);
      return;
    }
    el.textContent = "";
    el.classList.add("has-md");
    var list = null;
    var plain = [];
    function flushPlain() {
      if (!plain.length) return;
      var p = document.createElement("div");
      p.className = "note-discuss-md-p";
      fillDiscussBodyWithMentions(p, plain.join("\n"));
      el.appendChild(p);
      plain = [];
    }
    lines.forEach(function (line) {
      var m = DISCUSS_MD_LINE.exec(line);
      if (!m) {
        list = null;
        if (line.trim() || plain.length) plain.push(line);
        return;
      }
      flushPlain();
      if (m[1]) {
        list = null;
        var h = document.createElement("p");
        h.className = "note-discuss-md-h note-discuss-md-h" + m[1].length;
        fillDiscussBodyWithMentions(h, m[3]);
        el.appendChild(h);
        return;
      }
      var tag = m[2] ? "OL" : "UL";
      if (!list || list.nodeName !== tag) {
        list = document.createElement(tag.toLowerCase());
        list.className = "note-discuss-md-list";
        if (m[2] && m[2] !== "1") list.setAttribute("start", m[2]);
        el.appendChild(list);
      }
      var li = document.createElement("li");
      fillDiscussBodyWithMentions(li, m[3]);
      list.appendChild(li);
    });
    flushPlain();
  }

  function discussionHistoryAuthorLabel(c) {
    if (isAssistantComment(c)) return "";
    var uname = String((c && c.author_username) || "").trim().replace(/^@/, "");
    var name = String((c && c.author_name) || "").trim();
    if (uname && name) return "@" + uname + " (" + name + ")";
    if (uname) return "@" + uname;
    if (name) return name;
    return "Участник";
  }

