  // Метки говорящего от транскрайбера («SPEAKER_1:», «Speaker_0», «Спикер 2:») в диктовке не нужны.
  function stripSpeakerLabels(text) {
    return String(text || "")
      .replace(/(^|\s)[[(]?(?:speaker|спикер)[ _-]?\d+[\])]?\s*[:：.\-—]?\s*/gi, "$1")
      .replace(/[ \t]+\n/g, "\n")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
  }

