  function selectedGptModelId() {
    // Тред «Лео · Telegram» отвечает моделью из Профиля → «Лео в Telegram».
    if (isTgLeoThread(activeChatThreadId) && tgLeoState.model) return tgLeoState.model;
    if (composerAgentModel) return composerAgentModel;
    try {
      var stored = String(localStorage.getItem(GPT_MODEL_LS) || "").trim();
      if (stored) return stored;
    } catch (_) {}
    return gptModelsState.defaultId || GPT_MODEL_DEFAULT;
  }

  function setSelectedGptModelId(id) {
    var next = String(id || "").trim();
    if (!next) return;
    if (isTgLeoThread(activeChatThreadId)) {
      tgLeoState.model = next;
      syncGptModelButton();
      saveTgLeoModel(next);
      return;
    }
    composerAgentModel = next;
    syncGptModelButton();
    if (isCustomAskMode(noteAskMode())) {
      var agentId = noteAskMode();
      var agent = findUserAgent(agentId);
      if (agent) agent.model = next;
      apiFetch("/agents/" + encodeURIComponent(agentId), {
        method: "PATCH",
        body: JSON.stringify({ model: next }),
      })
        .then(function () {
          return loadUserAgents();
        })
        .catch(function () {});
      return;
    }
    try {
      localStorage.setItem(GPT_MODEL_LS, next);
    } catch (_) {}
  }

  function gptModelShortName(id) {
    var found = gptModelsState.models.find(function (m) {
      return m.id === id;
    });
    if (found && found.name) return found.name;
    var raw = String(id || "");
    if (!raw) return "GPT";
    var short = raw.split("/").pop() || raw;
    if (/^gpt-/i.test(short)) return "GPT-" + short.slice(4);
    if (/^gpt/i.test(short)) return "GPT-" + short.slice(3).replace(/^[-_\s]+/, "");
    return short;
  }

  function closeNoteComposerMenus(except) {
    var form = document.getElementById("note-paie-reply-form");
    if (!form) return;
    form.querySelectorAll(".note-paie-menu").forEach(function (menu) {
      if (except && menu === except) return;
      menu.classList.add("hidden");
    });
    var plusMenu = document.getElementById("note-paie-plus-menu");
    if (plusMenu && plusMenu !== except) {
      plusMenu.classList.add("hidden");
      showPlusMenuPage("root");
    }
    form.querySelectorAll(".note-paie-mode-compact, .note-paie-model-btn, .note-paie-kb-toggle, .note-paie-attach").forEach(function (btn) {
      btn.classList.remove("is-open");
      btn.setAttribute("aria-expanded", "false");
    });
    syncNoteFormatToolbarForComposer();
  }

  function renderGptModelMenu(query) {
    var form = document.getElementById("note-paie-reply-form");
    var list = form && form.querySelector(".note-paie-menu--models .note-paie-menu-list");
    if (!list) return;
    var mode = noteAskMode();
    var paie = mode === "paie";
    var research = mode === "research";
    var state = paie ? paieModelsState : gptModelsState;
    var q = String(query || "").trim().toLowerCase();
    var selected = paie
      ? selectedPaieModelId()
      : research
        ? selectedResearchModelId()
        : selectedGptModelId();
    var rows = state.models.filter(function (m) {
      if (!q) return true;
      return (
        String(m.name || "").toLowerCase().indexOf(q) >= 0 ||
        String(m.id || "").toLowerCase().indexOf(q) >= 0
      );
    });
    list.innerHTML = "";
    if (!rows.length) {
      var empty = document.createElement("p");
      empty.className = "note-paie-menu-empty";
      empty.textContent = state.loading ? "Загрузка…" : "Нет моделей";
      list.appendChild(empty);
      return;
    }
    rows.forEach(function (m) {
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "note-paie-menu-item" + (m.id === selected ? " is-active" : "");
      btn.setAttribute("data-model-id", m.id);
      btn.textContent = (m.name || m.id) + (m.reasoning ? " · рассуждение" : "");
      btn.title = m.id;
      btn.addEventListener("click", function () {
        if (paie) applyPaieModel(m.id, true);
        else if (research) applyResearchModel(m.id, true);
        else setSelectedGptModelId(m.id);
        closeNoteComposerMenus();
      });
      list.appendChild(btn);
    });
  }

  function selectedPaieModelId() {
    if (noteAskMode() === "paie" && composerAgentModel) return composerAgentModel;
    try {
      var stored = String(localStorage.getItem(PAIE_MODEL_LS) || "").trim();
      if (stored) return stored;
    } catch (_) {}
    var agent = findUserAgent("paie");
    if (agent && agent.model) return agent.model;
    return paieModelsState.defaultId || PAIE_MODEL_DEFAULT;
  }

  function paieModelShortName(id) {
    var found = paieModelsState.models.find(function (m) {
      return m.id === id;
    });
    if (found && found.name) return found.name;
    var raw = String(id || "");
    return raw.split("/").pop() || "PAIE";
  }

  function selectedResearchModelId() {
    if (noteAskMode() === "research" && composerAgentModel) return composerAgentModel;
    try {
      var stored = String(localStorage.getItem(RESEARCH_MODEL_LS) || "").trim();
      if (stored) return stored;
    } catch (_) {}
    var agent = findUserAgent("research");
    if (agent && agent.model) return agent.model;
    return gptModelsState.defaultId || GPT_MODEL_DEFAULT;
  }

  function applyResearchModel(id, persist) {
    var next = String(id || "").trim();
    if (!next) return;
    composerAgentModel = next;
    var agent = findUserAgent("research");
    if (agent) agent.model = next;
    try {
      localStorage.setItem(RESEARCH_MODEL_LS, next);
    } catch (_) {}
    syncGptModelButton();
    if (!persist) return;
    apiFetch("/agents/research", {
      method: "PATCH",
      body: JSON.stringify({ model: next }),
    })
      .then(function () {
        return loadUserAgents();
      })
      .catch(function () {});
  }

  function applyPaieModel(id, persist) {
    var next = String(id || "").trim();
    if (!next) return;
    composerAgentModel = next;
    var agent = findUserAgent("paie");
    if (agent) agent.model = next;
    try {
      localStorage.setItem(PAIE_MODEL_LS, next);
    } catch (_) {}
    syncGptModelButton();
    if (!persist) return;
    apiFetch("/agents/paie", {
      method: "PATCH",
      body: JSON.stringify({ model: next }),
    })
      .then(function () {
        return loadUserAgents();
      })
      .catch(function () {});
  }

  function syncGptModelButton() {
    var form = document.getElementById("note-paie-reply-form");
    var label = form && form.querySelector(".note-paie-model-label");
    if (label) {
      label.textContent =
        noteAskMode() === "paie"
          ? paieModelShortName(selectedPaieModelId())
          : gptModelShortName(selectedGptModelId());
    }
    syncComposerModeChip();
  }

  async function loadGptModels() {
    if (gptModelsState.loaded || gptModelsState.loading) {
      syncGptModelButton();
      renderGptModelMenu();
      return;
    }
    gptModelsState.loading = true;
    renderGptModelMenu();
    try {
      var res = await apiFetch("/gpt/models");
      gptModelsState.models = Array.isArray(res && res.models) ? res.models : [];
      gptModelsState.defaultId = String((res && res.default) || "").trim() || GPT_MODEL_DEFAULT;
      gptModelsState.loaded = true;
      var allowed = {};
      gptModelsState.models.forEach(function (m) {
        if (m && m.id) allowed[m.id] = true;
      });
      var pickingGpt = noteAskMode() !== "research" && noteAskMode() !== "paie";
      var current = pickingGpt ? selectedGptModelId() : "";
      if (pickingGpt && (!current || !allowed[current])) {
        setSelectedGptModelId(
          (allowed[GPT_MODEL_DEFAULT] && GPT_MODEL_DEFAULT) ||
            gptModelsState.defaultId ||
            (gptModelsState.models[0] && gptModelsState.models[0].id) ||
            GPT_MODEL_DEFAULT
        );
      }
    } catch (_) {
      gptModelsState.models = [
        { id: "openai/gpt-5.6-sol", name: "GPT-5.6 Sol" },
        { id: "openai/gpt-5.5", name: "GPT-5.5" },
        { id: "openai/gpt-5.4", name: "GPT-5.4" },
        { id: "openai/gpt-5", name: "GPT-5" },
        { id: "openai/gpt-4.1", name: "GPT-4.1" },
        { id: "openai/gpt-4o", name: "GPT-4o" },
        { id: "openai/gpt-4o-mini", name: "GPT-4o mini" },
        { id: "openai/o3", name: "o3", reasoning: true },
        { id: "openai/o4-mini", name: "o4-mini", reasoning: true },
        { id: "google/gemini-2.5-pro", name: "Gemini 2.5 Pro", reasoning: true },
        { id: "deepseek/deepseek-r1", name: "DeepSeek R1", reasoning: true },
        { id: "anthropic/claude-opus-5.5", name: "Claude Opus 5.5", reasoning: true },
        { id: "anthropic/claude-fable-5.1", name: "Claude Fable 5.1", reasoning: true },
      ];
      gptModelsState.defaultId = GPT_MODEL_DEFAULT;
      gptModelsState.loaded = true;
      if (!selectedGptModelId()) setSelectedGptModelId(GPT_MODEL_DEFAULT);
    } finally {
      gptModelsState.loading = false;
      syncGptModelButton();
      renderGptModelMenu();
    }
  }

  async function loadPaieModels() {
    if (paieModelsState.loaded || paieModelsState.loading) {
      syncGptModelButton();
      renderGptModelMenu();
      return;
    }
    paieModelsState.loading = true;
    renderGptModelMenu();
    try {
      var res = await apiFetch("/paie/models");
      paieModelsState.models = Array.isArray(res && res.models) ? res.models : [];
      paieModelsState.defaultId = String((res && res.default) || "").trim() || PAIE_MODEL_DEFAULT;
      paieModelsState.loaded = true;
      var allowed = {};
      paieModelsState.models.forEach(function (m) {
        if (m && m.id) allowed[m.id] = true;
      });
      var current = selectedPaieModelId();
      if (current && !allowed[current]) {
        paieModelsState.models.unshift({
          id: current,
          name: current.split("/").pop(),
          reasoning: false,
        });
      }
    } catch (_) {
      paieModelsState.models = [
        { id: "google/gemini-2.5-flash", name: "Gemini 2.5 Flash" },
        { id: "openai/gpt-5.4", name: "GPT-5.4" },
        { id: "openai/gpt-4.1", name: "GPT-4.1" },
        { id: "openai/o3", name: "o3", reasoning: true },
        { id: "openai/o4-mini", name: "o4-mini", reasoning: true },
        { id: "google/gemini-2.5-pro", name: "Gemini 2.5 Pro", reasoning: true },
        { id: "deepseek/deepseek-r1", name: "DeepSeek R1", reasoning: true },
        { id: "anthropic/claude-opus-5.5", name: "Claude Opus 5.5", reasoning: true },
        { id: "anthropic/claude-fable-5.1", name: "Claude Fable 5.1", reasoning: true },
      ];
      paieModelsState.defaultId = PAIE_MODEL_DEFAULT;
      paieModelsState.loaded = true;
    } finally {
      paieModelsState.loading = false;
      syncGptModelButton();
      renderGptModelMenu();
    }
  }

  function findUserAgent(id) {
    var want = String(id || "");
    var rows = userAgentsState.agents || [];
    for (var i = 0; i < rows.length; i++) {
      if (String(rows[i].id) === want) return rows[i];
    }
    return null;
  }

  function isCustomAskMode(mode) {
    var agent = findUserAgent(mode);
    return !!(agent && agent.kind === "custom");
  }

  function isChatAskMode(mode) {
    return mode === "gpt" || isCustomAskMode(mode);
  }

  async function loadUserAgents() {
    if (userAgentsState.loading) return userAgentsState.agents;
    userAgentsState.loading = true;
    try {
      var res = await apiFetch("/agents");
      userAgentsState.agents = (res && res.agents) || [];
      userAgentsState.loaded = true;
    } catch (_) {
      if (!userAgentsState.loaded) {
        userAgentsState.agents = [
          { id: "paie", kind: "paie", title: "PAIE", builtin: true },
          { id: "research", kind: "research", title: "Research", builtin: true },
          { id: "gpt", kind: "gpt", title: "GPT", builtin: true },
        ];
      }
    } finally {
      userAgentsState.loading = false;
    }
    renderNoteAskModes();
    return userAgentsState.agents;
  }

  function renderNoteAskModes() {
    var form = document.getElementById("note-paie-reply-form");
    if (!form) return;
    var switchEl = form.querySelector(".note-paie-mode-switch");
    var menu = form.querySelector(".note-paie-mode-menu");
    if (!switchEl || !menu) return;
    var wrap = document.getElementById("note-editor-more-wrap");
    var isChatThread =
      !!(wrap && wrap._shareKind === "chat") &&
      (notesSubTab === "chats" || !!activeChatThreadId);
    var current = noteAskMode();
    if (isChatThread && current === "comment") {
      if (wrap) wrap._askMode = "gpt";
      current = "gpt";
    }
    // «Текст» (без ИИ) убран там, где есть чаты: людям пишут в чате «Комментарии».
    var items = (userAgentsState.agents || []).slice();
    if (!isChatThread && !noteChatsEnabled()) {
      items.push({ id: "comment", title: "Комментарий без ИИ", kind: "comment" });
    }
    items.sort(function (a, b) {
      var order = { gpt: 0, research: 1, paie: 2 };
      var ao = order[a.id] != null ? order[a.id] : 3;
      var bo = order[b.id] != null ? order[b.id] : 3;
      return ao - bo;
    });
    var MODE_META = {
      gpt: ["spark", "Отвечает и правит заметку"],
      research: ["globe", "Ищет в интернете, отчёт с источниками"],
      paie: ["people", "Четыре роли обсуждают и дают решение"],
      comment: ["people", "Сообщение участникам, ИИ не отвечает"],
    };
    function makeBtn(agent, cls) {
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = cls + (String(agent.id) === current ? " is-active" : "");
      btn.setAttribute("data-mode", agent.id);
      btn.setAttribute("role", cls.indexOf("menu-item") >= 0 ? "option" : "tab");
      var builtinTitle = MODE_META[agent.id] && agent.id !== "comment" ? noteAskModeLabel(agent.id) : "";
      if (cls.indexOf("menu-item") >= 0) {
        var meta = MODE_META[agent.id] || ["bot", "Ваш агент"];
        btn.classList.add("note-ask-item");
        btn.innerHTML =
          '<span class="note-ask-ico is-' + meta[0] + '">' + DISCUSS_ICONS[meta[0]] + "</span>" +
          '<span class="note-ask-copy"><b></b><small></small></span>' +
          '<span class="note-ask-check">' + DISCUSS_ICONS.check + "</span>";
        btn.querySelector("b").textContent = builtinTitle || agent.title || agent.id;
        btn.querySelector("small").textContent = meta[1];
      } else {
        btn.textContent = builtinTitle || agent.title || agent.id;
      }
      btn.addEventListener("click", function () {
        setNoteAskMode(agent.id);
        closeNoteComposerMenus();
      });
      return btn;
    }
    switchEl.innerHTML = "";
    menu.innerHTML = "";
    var label = document.createElement("p");
    label.className = "note-menu-label";
    label.textContent = "Кто отвечает";
    menu.appendChild(label);
    items.forEach(function (agent) {
      switchEl.appendChild(makeBtn(agent, "note-paie-mode"));
      menu.appendChild(makeBtn(agent, "note-paie-menu-item"));
    });
    var hr = document.createElement("div");
    hr.className = "note-menu-hr note-ask-model-hr";
    menu.appendChild(hr);
    var modelItem = document.createElement("button");
    modelItem.type = "button";
    modelItem.className = "note-paie-menu-item note-ask-model";
    modelItem.innerHTML =
      '<span>Модель</span><span class="note-ask-model-val"></span><span class="note-ask-model-chev">' +
      DISCUSS_ICONS.right + "</span>";
    modelItem.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      var mb = form.querySelector(".note-paie-model-btn");
      if (mb) mb.click();
    });
    menu.appendChild(modelItem);
    syncComposerModeChip();
  }

  // Чип «✨ Ассистент · GPT-4.1»: режим и модель одной кнопкой.
  function syncComposerModeChip() {
    var form = document.getElementById("note-paie-reply-form");
    if (!form) return;
    var mode = noteAskMode();
    var paie = mode === "paie";
    var research = mode === "research";
    var lbl = form.querySelector(".note-paie-mode-compact-label");
    var model = paie
      ? paieModelShortName(selectedPaieModelId())
      : gptModelShortName(research ? selectedResearchModelId() : selectedGptModelId());
    if (lbl) {
      lbl.textContent =
        noteAskModeLabel(mode) + (isChatAskMode(mode) || paie || research ? " · " + model : "");
    }
    var ico = form.querySelector(".note-paie-mode-compact-ico");
    if (ico) {
      var key = mode === "research" ? "globe" : mode === "paie" ? "people" : isCustomAskMode(mode) ? "bot" : "spark";
      if (ico._key !== key) {
        ico._key = key;
        ico.innerHTML = DISCUSS_ICONS[key];
      }
    }
    var mv = form.querySelector(".note-ask-model-val");
    if (mv) mv.textContent = model;
  }

  function profileAgentsMsg(ok, err) {
    var msg = document.getElementById("agents-form-msg");
    var error = document.getElementById("agents-form-err");
    if (msg) msg.classList.add("hidden");
    // Успех — тостом: форма к этому моменту обычно уже закрыта.
    if (ok) showNoteToast(ok);
    if (error) {
      error.textContent = err || "";
      error.classList.toggle("hidden", !err);
    }
  }

  function fillAgentModelSelect(selected, models) {
    var sel = document.getElementById("agents-f-model");
    if (!sel) return;
    models = (models || gptModelsState.models || []).slice();
    if (!models.length) {
      models = [
        { id: "openai/gpt-4.1", name: "GPT-4.1" },
        { id: "openai/gpt-4o", name: "GPT-4o" },
        { id: "openai/gpt-4o-mini", name: "GPT-4o mini" },
      ];
    }
    if (selected && !models.some(function (m) { return m.id === selected; })) {
      models.unshift({ id: selected, name: selected.split("/").pop() });
    }
    sel.innerHTML = "";
    models.forEach(function (m) {
      var opt = document.createElement("option");
      opt.value = m.id;
      opt.textContent = (m.name || m.id) + (m.reasoning ? " · рассуждение" : "");
      if (m.id === selected) opt.selected = true;
      sel.appendChild(opt);
    });
  }

  var AGENT_KIND_HINT = {
    paie: "Отвечает по базе знаний",
    research: "Ищет в интернете",
    gpt: "Общий помощник",
  };

  function agentModelLabel(id) {
    if (!id) return "";
    var all = (gptModelsState.models || []).concat((typeof paieModelsState !== "undefined" && paieModelsState.models) || []);
    var m = all.filter(function (x) {
      return x && x.id === id;
    })[0];
    return (m && (m.name || m.label)) || String(id).split("/").pop();
  }

  function renderProfileAgentsList() {
    var builtinEl = document.getElementById("agents-builtin-list");
    var customEl = document.getElementById("agents-custom-list");
    if (!builtinEl || !customEl) return;
    builtinEl.classList.remove("pf-skel-list");
    builtinEl.innerHTML = "";
    customEl.innerHTML = "";
    (userAgentsState.agents || []).forEach(function (agent) {
      var row = document.createElement("button");
      row.type = "button";
      row.className = "pf-row";
      row.innerHTML =
        '<span class="pf-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 8V4H8" /><rect width="16" height="12" x="4" y="8" rx="2" /><path d="M2 14h2M20 14h2M15 13v2M9 13v2" /></svg></span>' +
        '<span class="pf-row-body"><span class="pf-row-text"><span class="pf-row-title"></span><span class="pf-row-sub"></span></span>' +
        '<span class="pf-row-val"></span><span class="pf-chev" aria-hidden="true">›</span></span>';
      row.querySelector(".pf-row-title").textContent = agent.title || agent.id;
      var sub = row.querySelector(".pf-row-sub");
      var hint = agent.builtin ? AGENT_KIND_HINT[agent.kind] || "" : "";
      if (hint) sub.textContent = hint;
      else sub.remove();
      row.querySelector(".pf-row-val").textContent = agentModelLabel(agent.model) || "по умолчанию";
      row.addEventListener("click", function () {
        openAgentForm(agent);
      });
      (agent.builtin ? builtinEl : customEl).appendChild(row);
    });
  }

  function syncAgentFormFields(kind) {
    var titleField = document.getElementById("agents-title-field");
    var webField = document.getElementById("agents-web-field");
    var tempField = document.getElementById("agents-temp-field");
    var roundsField = document.getElementById("agents-rounds-field");
    if (titleField) titleField.classList.toggle("hidden", kind !== "custom" && kind !== "new");
    if (webField) webField.classList.toggle("hidden", kind !== "gpt" && kind !== "custom" && kind !== "new");
    if (tempField) tempField.classList.toggle("hidden", kind === "paie");
    if (roundsField) roundsField.classList.toggle("hidden", kind !== "paie");
  }

  function openAgentForm(agent) {
    var fields = document.getElementById("modal-fields");
    var overlay = document.getElementById("modal-overlay");
    if (!fields || !overlay) return;
    var isNew = !agent;
    var kind = isNew ? "new" : agent.kind;
    document.getElementById("modal-title").textContent = isNew
      ? "Новый агент"
      : agent.title || "Агент";
    document.getElementById("modal-kind").value = "agent";
    document.getElementById("modal-reminder-id").value = "";
    document.getElementById("modal-event-id").value = "";
    document.getElementById("modal-calendar-id").value = "";
    fields.innerHTML =
      '<div class="event-sheet pf-screen-body pf-agent-form">' +
      '<input type="hidden" id="agents-edit-id" value="" />' +
      '<div class="pf-list" id="agents-title-field">' +
      '<label class="pf-field"><span class="pf-field-label">Название</span>' +
      '<input id="agents-f-title" type="text" class="pf-input" maxlength="60" placeholder="Например, «Редактор постов»" autocomplete="off" /></label>' +
      "</div>" +
      '<div class="pf-group"><p class="pf-group-title">Промпт</p><div class="pf-list">' +
      '<label class="pf-field"><textarea id="agents-f-prompt" class="pf-input agents-textarea" rows="8" maxlength="12000" placeholder="Кто этот агент и как он работает"></textarea></label>' +
      '<label class="pf-field"><span class="pf-field-label">Правила</span>' +
      '<textarea id="agents-f-rules" class="pf-input agents-textarea agents-textarea--rules" rows="3" maxlength="4000" placeholder="Ограничения и тон"></textarea></label>' +
      "</div></div>" +
      '<div class="pf-group"><p class="pf-group-title">Модель</p><div class="pf-list">' +
      '<label class="pf-row pf-row--static pf-row--select-inline"><span class="pf-row-body"><span class="pf-row-text"><span class="pf-row-title">Модель</span></span>' +
      '<select id="agents-f-model" class="pf-select"></select></span></label>' +
      '<div class="pf-field" id="agents-temp-field">' +
      '<span class="pf-range-head"><span class="pf-row-title">Креативность</span><output id="agents-f-temp-out" class="pf-row-val"></output></span>' +
      '<input type="range" id="agents-f-temp" class="pf-range" min="0" max="2" step="0.1" aria-label="Креативность" />' +
      '<span class="pf-range-scale"><span>точнее</span><span>свободнее</span></span>' +
      "</div>" +
      '<label class="pf-row pf-row--static hidden" id="agents-web-field"><span class="pf-row-body"><span class="pf-row-text"><span class="pf-row-title">Поиск в интернете</span></span>' +
      '<input type="checkbox" id="agents-f-web" class="pf-switch" /></span></label>' +
      '<label class="pf-row pf-row--static hidden" id="agents-rounds-field"><span class="pf-row-body"><span class="pf-row-text"><span class="pf-row-title">Шагов поиска</span><span class="pf-row-sub">Сколько раз агент уточняет запрос к базе</span></span>' +
      '<input type="number" id="agents-f-rounds" class="pf-num-input" min="1" max="8" step="1" /></span></label>' +
      "</div></div>" +
      '<button type="button" class="pf-btn pf-btn--ghost hidden" id="agents-reset">Вернуть настройки по умолчанию</button>' +
      '<p id="agents-form-msg" class="pf-hint billing-msg hidden"></p>' +
      '<p id="agents-form-err" class="pf-field-error hidden"></p>' +
      "</div>";
    var idEl = document.getElementById("agents-edit-id");
    var titleEl = document.getElementById("agents-f-title");
    var promptEl = document.getElementById("agents-f-prompt");
    var rulesEl = document.getElementById("agents-f-rules");
    var tempEl = document.getElementById("agents-f-temp");
    var webEl = document.getElementById("agents-f-web");
    var roundsEl = document.getElementById("agents-f-rounds");
    var resetBtn = document.getElementById("agents-reset");
    if (idEl) idEl.value = isNew ? "" : String(agent.id);
    if (titleEl) {
      titleEl.value = isNew ? "" : agent.title || "";
      titleEl.disabled = !isNew && !agent.can_rename;
    }
    if (promptEl) promptEl.value = isNew ? "" : agent.prompt || "";
    if (rulesEl) rulesEl.value = isNew ? "" : agent.rules || "";
    if (tempEl) {
      tempEl.value =
        agent && agent.temperature != null
          ? String(agent.temperature)
          : kind === "research"
            ? "0.2"
            : "0.1";
    }
    var tempOut = document.getElementById("agents-f-temp-out");
    function syncTempOut() {
      if (tempOut && tempEl) tempOut.textContent = Number(tempEl.value || 0).toLocaleString("ru-RU", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
    }
    if (tempEl) tempEl.addEventListener("input", syncTempOut);
    syncTempOut();
    if (webEl) webEl.checked = !!(agent && agent.web_search);
    if (roundsEl) {
      roundsEl.value = agent && agent.max_rounds != null ? String(agent.max_rounds) : "4";
    }
    var modelForForm =
      kind === "paie"
        ? (agent && agent.model) || PAIE_MODEL_DEFAULT
        : (agent && agent.model) || GPT_MODEL_DEFAULT;
    fillAgentModelSelect(
      modelForForm,
      kind === "paie" ? paieModelsState.models : gptModelsState.models
    );
    var reloadModels = kind === "paie" ? loadPaieModels() : loadGptModels();
    Promise.resolve(reloadModels).then(function () {
      if (!document.getElementById("agents-f-model")) return;
      fillAgentModelSelect(
        modelForForm,
        kind === "paie" ? paieModelsState.models : gptModelsState.models
      );
    });
    if (resetBtn) {
      resetBtn.classList.toggle("hidden", isNew || !agent.builtin);
      resetBtn.addEventListener("click", function () {
        resetAgentForm();
      });
    }
    setModalSheetActions({
      showDelete: !isNew && !!agent.can_delete,
      showDone: false,
    });
    syncAgentFormFields(kind);
    profileAgentsMsg("", "");
    overlay.classList.remove("hidden");
    overlay.setAttribute("aria-hidden", "false");
    onModalSheetOpen();
    syncAppOverlay();
  }

  function closeAgentForm() {
    var kindEl = document.getElementById("modal-kind");
    if (kindEl && kindEl.value === "agent") closeModal();
    profileAgentsMsg("", "");
  }

  async function saveAgentForm() {
    var idEl = document.getElementById("agents-edit-id");
    var titleEl = document.getElementById("agents-f-title");
    var promptEl = document.getElementById("agents-f-prompt");
    var rulesEl = document.getElementById("agents-f-rules");
    var modelEl = document.getElementById("agents-f-model");
    var tempEl = document.getElementById("agents-f-temp");
    var webEl = document.getElementById("agents-f-web");
    var roundsEl = document.getElementById("agents-f-rounds");
    var id = idEl && idEl.value;
    var body = {
      prompt: promptEl ? promptEl.value : "",
      rules: rulesEl ? rulesEl.value : "",
      model: modelEl ? modelEl.value : "",
      temperature: tempEl && tempEl.value !== "" ? Number(tempEl.value) : null,
      web_search: !!(webEl && webEl.checked),
    };
    if (roundsEl && !roundsEl.closest(".hidden")) {
      body.max_rounds = Number(roundsEl.value || 4);
    }
    try {
      profileAgentsMsg("", "");
      if (!id) {
        body.title = titleEl ? titleEl.value : "";
        await apiFetch("/agents", { method: "POST", body: JSON.stringify(body) });
      } else {
        var current = findUserAgent(id);
        if (current && current.can_rename) body.title = titleEl ? titleEl.value : current.title;
        await apiFetch("/agents/" + encodeURIComponent(id), {
          method: "PATCH",
          body: JSON.stringify(body),
        });
      }
      await loadUserAgents();
      renderProfileAgentsList();
      closeAgentForm();
      profileAgentsMsg("Сохранено", "");
    } catch (e) {
      profileAgentsMsg("", (e && e.message) || String(e));
    }
  }

  async function resetAgentForm() {
    var idEl = document.getElementById("agents-edit-id");
    var id = idEl && idEl.value;
    if (!id) return;
    try {
      await apiFetch("/agents/" + encodeURIComponent(id) + "/reset", { method: "POST" });
      await loadUserAgents();
      renderProfileAgentsList();
      var next = findUserAgent(id);
      if (next) openAgentForm(next);
      else closeAgentForm();
      profileAgentsMsg("Сброшено к заводским", "");
    } catch (e) {
      profileAgentsMsg("", (e && e.message) || String(e));
    }
  }

  async function deleteAgentForm() {
    var idEl = document.getElementById("agents-edit-id");
    var id = idEl && idEl.value;
    if (!id) return;
    var ok = await confirmDialog("Удалить этого агента?");
    if (!ok) return;
    try {
      await apiFetch("/agents/" + encodeURIComponent(id), { method: "DELETE" });
      await loadUserAgents();
      renderProfileAgentsList();
      closeAgentForm();
    } catch (e) {
      profileAgentsMsg("", (e && e.message) || String(e));
    }
  }

  async function openProfileAgents() {
    profileScreen("agents");
    closeAgentForm();
    await loadGptModels();
    await loadUserAgents();
    renderProfileAgentsList();
  }

  function composerLineHeight(el) {
    var lh = parseFloat(window.getComputedStyle(el).lineHeight);
    if (isFinite(lh) && lh > 8) return lh;
    var fs = parseFloat(window.getComputedStyle(el).fontSize) || 16;
    return fs * 1.35;
  }

  function composerPlaceholderWraps(el) {
    var value = composerEditorValue(el);
    if (!el || String(value || "").replace(/\s+/g, " ").trim()) return false;
    if (el.querySelector && el.querySelector(".note-gpt-quote-chip")) return false;
    var ph = el.getAttribute("placeholder") || el.getAttribute("data-placeholder") || "";
    if (!ph || el.clientWidth < 8) return false;
    var cs = window.getComputedStyle(el);
    var probe = document.createElement("div");
    var padX = (parseFloat(cs.paddingLeft) || 0) + (parseFloat(cs.paddingRight) || 0);
    probe.style.cssText =
      "position:absolute;left:-9999px;top:0;visibility:hidden;pointer-events:none;" +
      "white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;padding:0;border:0;" +
      "box-sizing:border-box;font:" +
      cs.font +
      ";font-size:" +
      cs.fontSize +
      ";font-weight:" +
      cs.fontWeight +
      ";letter-spacing:" +
      cs.letterSpacing +
      ";line-height:" +
      cs.lineHeight +
      ";width:" +
      Math.max(8, el.clientWidth - padX) +
      "px;";
    probe.textContent = ph;
    document.body.appendChild(probe);
    var wraps = probe.offsetHeight > composerLineHeight(el) * 1.35;
    document.body.removeChild(probe);
    return wraps;
  }

  function scrollTextareaCaretIntoView(el) {
    if (!el || el.tagName !== "TEXTAREA") return;
    var value = String(el.value || "");
    var pos = el.selectionEnd != null ? el.selectionEnd : value.length;
    if (pos >= value.length) {
      el.scrollTop = el.scrollHeight;
      return;
    }
    var cs = window.getComputedStyle(el);
    var mirror = document.createElement("div");
    var props = [
      "boxSizing",
      "width",
      "paddingTop",
      "paddingRight",
      "paddingBottom",
      "paddingLeft",
      "borderTopWidth",
      "borderRightWidth",
      "borderBottomWidth",
      "borderLeftWidth",
      "fontFamily",
      "fontSize",
      "fontWeight",
      "fontStyle",
      "letterSpacing",
      "textTransform",
      "wordSpacing",
      "textIndent",
      "lineHeight",
      "whiteSpace",
      "wordWrap",
      "overflowWrap",
    ];
    mirror.style.position = "absolute";
    mirror.style.visibility = "hidden";
    mirror.style.left = "-9999px";
    mirror.style.top = "0";
    mirror.style.whiteSpace = "pre-wrap";
    mirror.style.wordWrap = "break-word";
    mirror.style.overflowWrap = "break-word";
    mirror.style.width = el.clientWidth + "px";
    props.forEach(function (p) {
      try {
        mirror.style[p] = cs[p];
      } catch (_) {}
    });
    mirror.textContent = value.slice(0, pos);
    var marker = document.createElement("span");
    marker.textContent = "|";
    mirror.appendChild(marker);
    document.body.appendChild(mirror);
    var top = marker.offsetTop;
    var bottom = top + Math.max(marker.offsetHeight, composerLineHeight(el));
    document.body.removeChild(mirror);
    var pad = 6;
    if (bottom > el.scrollTop + el.clientHeight - pad) {
      el.scrollTop = bottom - el.clientHeight + pad;
    } else if (top < el.scrollTop + pad) {
      el.scrollTop = Math.max(0, top - pad);
    }
  }

  function scrollComposerCaretIntoView(el) {
    if (!el) return;
    if (el.scrollHeight <= el.clientHeight + 2) return;
    var run = function () {
      if (!el.isConnected) return;
      if (el.scrollHeight <= el.clientHeight + 2) return;
      if (el.tagName === "TEXTAREA") {
        scrollTextareaCaretIntoView(el);
        return;
      }
      if (!el.isContentEditable) {
        el.scrollTop = el.scrollHeight;
        return;
      }
      var sel = window.getSelection && window.getSelection();
      if (!sel || !sel.rangeCount) {
        el.scrollTop = el.scrollHeight;
        return;
      }
      var range = sel.getRangeAt(0);
      var root = range.commonAncestorContainer;
      var rootEl = root && (root.nodeType === 1 ? root : root.parentNode);
      if (!rootEl || (rootEl !== el && !el.contains(rootEl))) {
        el.scrollTop = el.scrollHeight;
        return;
      }
      var caretRect = null;
      var rects = range.getClientRects();
      if (rects && rects.length) caretRect = rects[rects.length - 1];
      if (!caretRect || (!(caretRect.width || caretRect.height) && !caretRect.top)) {
        caretRect = range.getBoundingClientRect();
      }
      if (!caretRect || (!(caretRect.width || caretRect.height) && !caretRect.top)) {
        // Пустой rect у caret в конце строки — временный маркер.
        try {
          var marker = document.createElement("span");
          marker.textContent = "\u200b";
          var probe = range.cloneRange();
          probe.collapse(false);
          probe.insertNode(marker);
          caretRect = marker.getBoundingClientRect();
          var parent = marker.parentNode;
          if (parent) {
            parent.removeChild(marker);
            if (parent.normalize) parent.normalize();
          }
          sel.removeAllRanges();
          sel.addRange(range);
        } catch (_) {
          caretRect = null;
        }
      }
      if (!caretRect || (!(caretRect.width || caretRect.height) && !caretRect.top)) {
        el.scrollTop = el.scrollHeight;
        return;
      }
      var box = el.getBoundingClientRect();
      var margin = 6;
      if (caretRect.bottom > box.bottom - margin) {
        el.scrollTop += caretRect.bottom - (box.bottom - margin);
      } else if (caretRect.top < box.top + margin) {
        el.scrollTop -= box.top + margin - caretRect.top;
      }
    };
    window.requestAnimationFrame(run);
  }

  function autosizeNoteComposer(el) {
    if (!el) return;
    var line = composerLineHeight(el);
    var cs = window.getComputedStyle(el);
    var padY = (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0);
    var minSingle = Math.round(line + Math.max(padY, 8));
    var minMulti = Math.round(line * 2 + padY);
    var maxH = 136;
    var focused = document.activeElement === el;
    el.classList.remove("is-multiline");
    el.classList.remove("is-overflowing");
    // height:auto сбрасывает scrollTop — после ресайза вернём курсор в зону видимости.
    el.style.height = "auto";
    var value = composerEditorValue(el);
    if (el.querySelector && el.querySelector(".note-gpt-quote-chip")) {
      value = value || " ";
    }
    var valueHasBreak = value.indexOf("\n") >= 0;
    // Перенос — это вторая строка, а не лишние пиксели: чип цитаты чуть выше строки текста,
    // и с порогом «+1px» поле прыгало между одной и двумя строками.
    var measuredWraps = valueHasBreak || (!!value && el.scrollHeight > minSingle + line * 0.5);
    // Гистерезис: в две строки поле раскладывается иначе, и текст у края «качался».
    // Возвращаемся к одной строке, только когда текст стал короче, чем в момент переноса.
    var len = value.length;
    var valueWraps = measuredWraps;
    if (measuredWraps) {
      if (!el._multiAtLen) el._multiAtLen = len;
    } else if (el._multiAtLen && len >= el._multiAtLen) {
      valueWraps = true;
    } else {
      el._multiAtLen = 0;
    }
    var placeholderWraps = composerPlaceholderWraps(el);
    if (!valueWraps) {
      var singleH = Math.max(el.scrollHeight, minSingle);
      if (!value && placeholderWraps) {
        el.classList.add("is-multiline");
        singleH = Math.max(singleH, minMulti);
      }
      el.style.height = Math.min(singleH, maxH) + "px";
      return;
    }
    el.classList.add("is-multiline");
    el.style.height = "auto";
    var h = Math.max(el.scrollHeight, minMulti);
    if (h > maxH) {
      h = maxH;
      el.classList.add("is-overflowing");
    }
    el.style.height = h + "px";
    if (focused && el.classList.contains("is-overflowing")) {
      scrollComposerCaretIntoView(el);
    }
  }

  var DISCUSS_ATTACH_MAX = 8;
  var DISCUSS_ATTACH_MAX_BYTES = 12 * 1024 * 1024;
  var DISCUSS_CONTEXT_NOTES_MAX = 5;
  var discussFileBlobUrls = {};

  function discussPendingFiles() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap) return [];
    if (!wrap._discussPending) wrap._discussPending = [];
    return wrap._discussPending;
  }

  function discussPendingContextNotes() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap) return [];
    if (!wrap._discussContextNotes) wrap._discussContextNotes = [];
    return wrap._discussContextNotes;
  }

  function discussContextNoteIds() {
    return discussPendingContextNotes()
      .map(function (n) {
        if (!n || n.id == null) return "";
        var id = String(n.id);
        if (!id) return "";
        if (n.kind === "journal") return "journal:" + id;
        if (n.kind === "chat") return "chat:" + id;
        return id;
      })
      .filter(Boolean);
  }

  function clearDiscussPendingContextNotes() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap) wrap._discussContextNotes = [];
    renderDiscussAttachPreview();
    syncNotePaieReplyForm();
  }

  function addDiscussContextNote(note, kind) {
    var id = note && note.id != null ? String(note.id) : "";
    if (!id) return;
    var itemKind = kind === "journal" || kind === "chat" ? kind : "local";
    var list = discussPendingContextNotes();
    if (
      list.some(function (n) {
        return String(n.id) === id && (n.kind || "local") === itemKind;
      })
    ) {
      return;
    }
    if (list.length >= DISCUSS_CONTEXT_NOTES_MAX) {
      alert("Можно прикрепить не больше " + DISCUSS_CONTEXT_NOTES_MAX + " материалов");
      return;
    }
    var title = "";
    if (itemKind === "journal") {
      title = journalCardTitle(note) || "Запись";
    } else if (itemKind === "chat") {
      title = String((note && note.title) || "Чат");
    } else {
      title =
        sanitizeNoteTitle((note && (note.title || note.content)) || "") ||
        String((note && (note.title || note.content)) || "Заметка");
    }
    list.push({
      id: id,
      kind: itemKind,
      title: title,
    });
    renderDiscussAttachPreview();
    syncNotePaieReplyForm();
  }

  function removeDiscussContextNote(idx) {
    discussPendingContextNotes().splice(idx, 1);
    renderDiscussAttachPreview();
    syncNotePaieReplyForm();
  }

  function clearDiscussPendingFiles() {
    var list = discussPendingFiles();
    list.forEach(function (item) {
      if (item && item.previewUrl) {
        try {
          URL.revokeObjectURL(item.previewUrl);
        } catch (_) {}
      }
    });
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap) wrap._discussPending = [];
    renderDiscussAttachPreview();
  }

  function discussFileKind(file) {
    var type = String((file && file.type) || "").toLowerCase();
    if (type.indexOf("image/") === 0) return "image";
    var name = String((file && file.name) || "").toLowerCase();
    if (/\.(png|jpe?g|gif|webp|heic|heif)$/.test(name)) return "image";
    return "file";
  }

  function addDiscussPendingFiles(fileList) {
    var pending = discussPendingFiles();
    var files = Array.prototype.slice.call(fileList || []);
    files.forEach(function (file) {
      if (!file || pending.length >= DISCUSS_ATTACH_MAX) return;
      if (file.size > DISCUSS_ATTACH_MAX_BYTES) {
        alert("Файл «" + (file.name || "файл") + "» слишком большой (максимум 12 МБ)");
        return;
      }
      pending.push({
        file: file,
        name: file.name || "file",
        mime: file.type || "",
        size: file.size || 0,
        kind: discussFileKind(file),
        previewUrl: file.type && file.type.indexOf("image/") === 0 ? URL.createObjectURL(file) : "",
      });
    });
    renderDiscussAttachPreview();
    syncNotePaieReplyForm();
  }

  function removeDiscussPendingFile(idx) {
    var pending = discussPendingFiles();
    var item = pending[idx];
    if (item && item.previewUrl) {
      try {
        URL.revokeObjectURL(item.previewUrl);
      } catch (_) {}
    }
    pending.splice(idx, 1);
    renderDiscussAttachPreview();
    syncNotePaieReplyForm();
  }

  function renderDiscussAttachPreview() {
    var host = document.getElementById("note-paie-attach-preview");
    if (!host) return;
    var pending = discussPendingFiles();
    var notes = discussPendingContextNotes();
    host.innerHTML = "";
    if (!pending.length && !notes.length) {
      host.classList.add("hidden");
      return;
    }
    host.classList.remove("hidden");
    notes.forEach(function (item, idx) {
      var chip = document.createElement("div");
      chip.className = "note-paie-attach-chip is-note";
      var name = document.createElement("span");
      name.className = "note-paie-attach-chip-name";
      name.textContent = item.title || "Материал";
      chip.appendChild(name);
      var rm = document.createElement("button");
      rm.type = "button";
      rm.className = "note-paie-attach-chip-remove";
      rm.setAttribute("aria-label", "Убрать вложение");
      rm.textContent = "×";
      rm.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        removeDiscussContextNote(idx);
      });
      chip.appendChild(rm);
      host.appendChild(chip);
    });
    pending.forEach(function (item, idx) {
      var chip = document.createElement("div");
      chip.className = "note-paie-attach-chip" + (item.kind === "image" ? " is-image" : "");
      if (item.kind === "image" && item.previewUrl) {
        var img = document.createElement("img");
        img.src = item.previewUrl;
        img.alt = item.name || "Фото";
        chip.appendChild(img);
      }
      var name = document.createElement("span");
      name.className = "note-paie-attach-chip-name";
      name.textContent = item.name || "Файл";
      chip.appendChild(name);
      var rm = document.createElement("button");
      rm.type = "button";
      rm.className = "note-paie-attach-chip-remove";
      rm.setAttribute("aria-label", "Убрать файл");
      rm.textContent = "×";
      rm.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        removeDiscussPendingFile(idx);
      });
      chip.appendChild(rm);
      host.appendChild(chip);
    });
  }

  function showPlusMenuPage(page) {
    var menu = document.getElementById("note-paie-plus-menu");
    if (!menu) return;
    menu.querySelectorAll(".note-paie-plus-page").forEach(function (el) {
      el.classList.toggle("hidden", el.getAttribute("data-plus-page") !== page);
    });
    if (page === "notes") {
      plusPickerActiveProjectId = 0;
      var search = document.getElementById("note-paie-plus-search");
      if (search) {
        search.value = "";
        search.placeholder =
          plusPickerKind === "transcription"
            ? "Поиск транскрипций"
            : plusPickerKind === "summary"
              ? "Поиск саммари"
              : "Поиск заметок";
      }
      var chips = document.getElementById("note-paie-plus-project-chips");
      if (chips) setHidden(chips, false);
      ensureUserTagsLoaded().finally(function () {
        renderPlusNotePicker("");
      });
      window.setTimeout(function () {
        if (search) {
          try {
            search.focus();
          } catch (_) {}
        }
      }, 20);
    }
  }

  function plusPickerItems(query) {
    var wrap = document.getElementById("note-editor-more-wrap");
    var currentKind = wrap ? String(wrap._shareKind || "") : "";
    var currentId = wrap && wrap._shareId ? String(wrap._shareId) : "";
    var selected = {};
    discussPendingContextNotes().forEach(function (n) {
      if (!n || n.id == null) return;
      var key = (n.kind || "local") + ":" + String(n.id);
      selected[key] = true;
    });
    var q = String(query || "").trim().toLowerCase();
    var kind = plusPickerKind || "note";
    var source = [];
    if (kind === "transcription") {
      source = (notesDataCache && notesDataCache.transcriptions) || [];
    } else if (kind === "summary") {
      source = ((notesDataCache && notesDataCache.transcriptions) || []).filter(
        function (n) {
          return transcriptionHasSummary(n);
        }
      );
    } else {
      source = (notesDataCache && notesDataCache.local_notes) || [];
    }
    return source.filter(function (n) {
      var id = String((n && n.id) || "");
      if (!id) return false;
      var itemKind = "local";
      if (selected[itemKind + ":" + id]) return false;
      if (currentKind === "local" && id === currentId) return false;
      if (n.is_knowledge || n.role === "knowledge") return false;
      if (!noteMatchesPickerProjectFilter(n, plusPickerActiveProjectId)) return false;
      if (!q) return true;
      if (itemKind === "journal") {
        var jTitle = String(journalCardTitle(n) || "").toLowerCase();
        var jPrev = String(n.preview || "").toLowerCase();
        return jTitle.indexOf(q) >= 0 || jPrev.indexOf(q) >= 0;
      }
      var title = String(n.title || n.content || "").toLowerCase();
      var preview = notePlainExcerpt(n.description || n.body || "", 80).toLowerCase();
      return title.indexOf(q) >= 0 || preview.indexOf(q) >= 0;
    });
  }

  function renderPlusNotePicker(query) {
    var list = document.getElementById("note-paie-plus-notes");
    if (!list) return;
    var chipsHost = document.getElementById("note-paie-plus-project-chips");
    renderNotePickerProjectChips(
      chipsHost,
      function () {
        return plusPickerActiveProjectId;
      },
      function (v) {
        plusPickerActiveProjectId = v;
      },
      function () {
        var search = document.getElementById("note-paie-plus-search");
        renderPlusNotePicker(search ? search.value : "");
      }
    );
    var notes = plusPickerItems(query);
    list.innerHTML = "";
    if (!notes.length) {
      var empty = document.createElement("p");
      empty.className = "note-paie-menu-empty";
      var emptyDefault =
        plusPickerKind === "transcription"
          ? "Транскрипций нет"
          : plusPickerKind === "summary"
            ? "Саммари нет"
            : "Других заметок нет";
      empty.textContent = !notesDataCache
        ? "Загрузка…"
        : String(query || "").trim() || plusPickerActiveProjectId
          ? "Ничего не найдено"
          : emptyDefault;
      list.appendChild(empty);
      return;
    }
    notes.forEach(function (n) {
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "note-paie-menu-item note-paie-plus-note";
      var title = document.createElement("span");
      title.className = "note-paie-kb-item-title";
      var titleText =
        sanitizeNoteTitle(n.title || n.content || n.main_topic || "") ||
        String(n.title || n.content || n.main_topic || "Без названия");
      title.textContent = titleText;
      btn.appendChild(title);
      var project = noteProjectOf(n);
      var projectName = (project && (project.name || project.title)) || "";
      if (projectName) {
        var meta = document.createElement("span");
        meta.className = "note-paie-plus-note-project";
        meta.textContent = String(projectName);
        btn.appendChild(meta);
      }
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        addDiscussContextNote(n, "local");
        closeNoteComposerMenus();
      });
      list.appendChild(btn);
    });
  }

  function ensurePlusPickerNotes() {
    if (notesDataCache) {
      if (plusPickerKind === "transcription") {
        return Promise.resolve(notesDataCache.transcriptions || []);
      }
      if (plusPickerKind === "summary") {
        return Promise.resolve(
          ((notesDataCache && notesDataCache.transcriptions) || []).filter(transcriptionHasSummary)
        );
      }
      if (Array.isArray(notesDataCache.local_notes) && notesDataCache.local_notes.length) {
        return Promise.resolve(notesDataCache.local_notes);
      }
    }
    return Promise.resolve(loadNotes())
      .then(function () {
        if (plusPickerKind === "transcription") {
          return (notesDataCache && notesDataCache.transcriptions) || [];
        }
        if (plusPickerKind === "summary") {
          return ((notesDataCache && notesDataCache.transcriptions) || []).filter(
            transcriptionHasSummary
          );
        }
        return (notesDataCache && notesDataCache.local_notes) || [];
      })
      .catch(function () {
        return [];
      });
  }

  // «Добавить чат заметки»: переписка другого чата этой заметки уходит ИИ как контекст.
  function renderPlusChatPicker() {
    var list = document.getElementById("note-paie-plus-chats");
    var wrap = discussWrap();
    if (!list || !wrap) return;
    list.innerHTML = "";
    var cur = currentDiscussChatId();
    var chats = (wrap._noteChats || []).filter(function (c) {
      return Number(c.id) !== cur && Number(c.message_count) > 0;
    });
    if (!chats.length) {
      var empty = document.createElement("p");
      empty.className = "note-paie-plus-empty";
      empty.textContent = "В этой заметке пока нет других чатов с сообщениями";
      list.appendChild(empty);
      return;
    }
    chats.forEach(function (c) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "note-paie-menu-item note-paie-plus-chat";
      b.setAttribute("role", "option");
      var t = document.createElement("span");
      t.className = "note-paie-plus-chat-title";
      t.textContent = noteChatTitle(c);
      var m = document.createElement("span");
      m.className = "note-paie-plus-chat-meta";
      m.textContent =
        (Number(c.id) === COMMENTS_CHAT_ID ? "Общие · " : c.visibility === "private" ? "Личный · " : "Общий · ") +
        noteChatMeta(c);
      b.appendChild(t);
      b.appendChild(m);
      b.addEventListener("click", function (e) {
        e.preventDefault();
        addDiscussContextNote(
          { id: String(wrap._shareId) + ":" + String(c.id), title: "Чат: " + noteChatTitle(c) },
          "chat"
        );
        closeNoteComposerMenus();
      });
      list.appendChild(b);
    });
  }

  function openPlusPicker(kind) {
    plusPickerKind = kind || "note";
    showPlusMenuPage("notes");
    ensurePlusPickerNotes().then(function () {
      var search = document.getElementById("note-paie-plus-search");
      renderPlusNotePicker(search ? search.value : "");
    });
  }
  function bindDiscussAttachOnce(form) {
    var btn = document.getElementById("note-paie-attach");
    var input = document.getElementById("note-paie-attach-input");
    var menu = document.getElementById("note-paie-plus-menu");
    if (!btn || !input || !menu || btn._bound) return;
    btn._bound = true;
    btn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      if (btn.disabled) return;
      var open = menu && menu.classList.contains("hidden");
      closeNoteComposerMenus(open ? menu : null);
      if (menu && open) {
        var chatItem = menu.querySelector('[data-plus-action="chat"]');
        if (chatItem) chatItem.classList.toggle("hidden", !noteChatsEnabled());
        showPlusMenuPage("root");
        menu.classList.remove("hidden");
        btn.classList.add("is-open");
        btn.setAttribute("aria-expanded", "true");
      }
      syncNoteFormatToolbarForComposer();
    });
    if (menu && !menu._bound) {
      menu._bound = true;
      menu.addEventListener("click", function (e) {
        e.stopPropagation();
      });
      var fileBtn = menu.querySelector('[data-plus-action="file"]');
      if (fileBtn) {
        fileBtn.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          // iOS: click() должен быть в том же gesture, до закрытия меню.
          try {
            input.click();
          } catch (_) {}
          window.setTimeout(function () {
            closeNoteComposerMenus();
          }, 0);
        });
      }
      var noteBtn = menu.querySelector('[data-plus-action="note"]');
      if (noteBtn) {
        noteBtn.addEventListener("click", function (e) {
          e.preventDefault();
          openPlusPicker("note");
        });
      }
      var chatPlusBtn = menu.querySelector('[data-plus-action="chat"]');
      if (chatPlusBtn) {
        chatPlusBtn.addEventListener("click", function (e) {
          e.preventDefault();
          renderPlusChatPicker();
          showPlusMenuPage("chats");
          var w = discussWrap();
          if (w && w._shareKind && w._shareId) {
            loadNoteChats(w._shareKind, w._shareId).then(renderPlusChatPicker).catch(function () {});
          }
        });
      }
      var chatsBack = menu.querySelector('[data-plus-back="chats"]');
      if (chatsBack) {
        chatsBack.addEventListener("click", function (e) {
          e.preventDefault();
          showPlusMenuPage("root");
        });
      }
      var transcriptionBtn = menu.querySelector('[data-plus-action="transcription"]');
      if (transcriptionBtn) {
        transcriptionBtn.addEventListener("click", function (e) {
          e.preventDefault();
          openPlusPicker("transcription");
        });
      }
      var summaryBtn = menu.querySelector('[data-plus-action="summary"]');
      if (summaryBtn) {
        summaryBtn.addEventListener("click", function (e) {
          e.preventDefault();
          openPlusPicker("summary");
        });
      }
      var notesList = document.getElementById("note-paie-plus-notes");
      if (notesList && !notesList._scrollBound) {
        notesList._scrollBound = true;
        notesList.addEventListener(
          "touchstart",
          function (e) {
            e.stopPropagation();
          },
          { passive: true }
        );
        notesList.addEventListener(
          "touchmove",
          function (e) {
            e.stopPropagation();
          },
          { passive: true }
        );
        notesList.addEventListener(
          "wheel",
          function (e) {
            e.stopPropagation();
          },
          { passive: true }
        );
      }
      var back = document.getElementById("note-paie-plus-back");
      if (back) {
        back.addEventListener("click", function (e) {
          e.preventDefault();
          showPlusMenuPage("root");
        });
      }
      var search = document.getElementById("note-paie-plus-search");
      if (search) {
        search.addEventListener("input", function () {
          renderPlusNotePicker(search.value);
        });
        search.addEventListener("click", function (e) {
          e.stopPropagation();
        });
      }
    }
    input.addEventListener("change", function () {
      if (input.files && input.files.length) addDiscussPendingFiles(input.files);
      input.value = "";
    });
    if (form && !form._attachDropBound) {
      form._attachDropBound = true;
      form.addEventListener("dragover", function (e) {
        if (!e.dataTransfer) return;
        e.preventDefault();
        form.classList.add("is-drop-attach");
      });
      form.addEventListener("dragleave", function () {
        form.classList.remove("is-drop-attach");
      });
      form.addEventListener("drop", function (e) {
        form.classList.remove("is-drop-attach");
        if (!e.dataTransfer || !e.dataTransfer.files || !e.dataTransfer.files.length) return;
        e.preventDefault();
        addDiscussPendingFiles(e.dataTransfer.files);
      });
    }
  }

  async function uploadDiscussPendingFiles(kind, itemId) {
    var pending = discussPendingFiles().slice();
    var ids = [];
    var i;
    for (i = 0; i < pending.length; i++) {
      var item = pending[i];
      var fd = new FormData();
      fd.append("file", item.file, item.name || "file");
      var res = await apiFetch(
        "/notes/" + encodeURIComponent(kind) + "/" + encodeURIComponent(itemId) + "/discuss-files",
        { method: "POST", body: fd }
      );
      var row = res && res.file;
      if (!row || !row.id) throw new Error("Не удалось загрузить файл");
      ids.push(row.id);
    }
    return ids;
  }

  function discussAuthFileUrl(att) {
    return API + String((att && att.url) || "");
  }

  async function discussFileObjectUrl(att) {
    var key = String((att && att.id) || "");
    if (!key) return "";
    if (discussFileBlobUrls[key]) return discussFileBlobUrls[key];
    var res = await fetch(discussAuthFileUrl(att), {
      credentials: "same-origin",
      headers: authHeaders(),
    });
    if (!res.ok) throw new Error("Не удалось открыть файл");
    var blob = await res.blob();
    var url = URL.createObjectURL(blob);
    discussFileBlobUrls[key] = url;
    return url;
  }

  function closeDiscussMediaViewer() {
    var ov = document.getElementById("discuss-media-viewer");
    if (!ov) return;
    if (ov._onKey) {
      document.removeEventListener("keydown", ov._onKey, true);
      ov._onKey = null;
    }
    if (ov.parentNode) ov.parentNode.removeChild(ov);
  }

  function downloadDiscussBlobUrl(src, filename) {
    var a = document.createElement("a");
    a.href = src;
    a.download = filename || "file";
    document.body.appendChild(a);
    a.click();
    a.remove();
  }

  function openDiscussMediaViewer(att, src) {
    closeDiscussMediaViewer();
    var name = (att && att.name) || "Файл";
    var mime = String((att && att.mime) || "").toLowerCase();
    var isImage = String((att && att.kind) || "") === "image" || mime.indexOf("image/") === 0;
    var isPdf = mime.indexOf("pdf") >= 0 || /\.pdf$/i.test(name);
    var ov = document.createElement("div");
    ov.id = "discuss-media-viewer";
    ov.className = "discuss-media-viewer";
    ov.setAttribute("role", "dialog");
    ov.setAttribute("aria-modal", "true");
    ov.setAttribute("aria-label", name);
    ov.innerHTML =
      '<div class="discuss-media-viewer-backdrop" data-close="1"></div>' +
      '<div class="discuss-media-viewer-sheet">' +
      '<div class="discuss-media-viewer-bar">' +
      '<p class="discuss-media-viewer-title"></p>' +
      '<div class="discuss-media-viewer-actions">' +
      '<button type="button" class="discuss-media-viewer-btn" data-download="1" aria-label="Скачать" title="Скачать">' +
      '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v12"/><path d="m7 10 5 5 5-5"/><path d="M5 21h14"/></svg>' +
      "</button>" +
      '<button type="button" class="discuss-media-viewer-btn" data-close="1" aria-label="Закрыть" title="Закрыть">' +
      '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>' +
      "</button>" +
      "</div></div>" +
      '<div class="discuss-media-viewer-body"></div>' +
      "</div>";
    var title = ov.querySelector(".discuss-media-viewer-title");
    if (title) title.textContent = name;
    var body = ov.querySelector(".discuss-media-viewer-body");
    if (isImage) {
      var img = document.createElement("img");
      img.className = "discuss-media-viewer-img";
      img.src = src;
      img.alt = name;
      body.appendChild(img);
    } else if (isPdf) {
      var frame = document.createElement("iframe");
      frame.className = "discuss-media-viewer-frame";
      frame.src = src;
      frame.title = name;
      body.appendChild(frame);
    } else {
      var hint = document.createElement("p");
      hint.className = "discuss-media-viewer-hint";
      hint.textContent = "Нажмите «Скачать», чтобы сохранить файл.";
      body.appendChild(hint);
    }
    ov.addEventListener("click", function (e) {
      var t = e.target;
      if (!t) return;
      if (t.closest && t.closest("[data-download]")) {
        e.preventDefault();
        e.stopPropagation();
        downloadDiscussBlobUrl(src, name);
        return;
      }
      if (t.closest && t.closest("[data-close]")) {
        e.preventDefault();
        e.stopPropagation();
        closeDiscussMediaViewer();
      }
    });
    ov._onKey = function (e) {
      if (e.key === "Escape") {
        e.preventDefault();
        closeDiscussMediaViewer();
      }
    };
    document.addEventListener("keydown", ov._onKey, true);
    document.body.appendChild(ov);
  }

  async function openDiscussAttachment(att) {
    var src = await discussFileObjectUrl(att);
    openDiscussMediaViewer(att, src);
  }

  function renderDiscussAttachments(host, attachments) {
    var list = (attachments || []).filter(Boolean);
    if (!host || !list.length) return;
    var wrap = document.createElement("div");
    wrap.className = "note-discuss-attach-list";
    list.forEach(function (att) {
      if (String(att.kind || "") === "image") {
        var btn = document.createElement("button");
        btn.type = "button";
        btn.className = "note-discuss-attach-img-btn";
        btn.setAttribute("aria-label", "Открыть " + (att.name || "фото"));
        var img = document.createElement("img");
        img.className = "note-discuss-attach-img";
        img.alt = att.name || "Фото";
        btn.appendChild(img);
        btn.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          openDiscussAttachment(att).catch(function (err) {
            alert(err.message || String(err));
          });
        });
        wrap.appendChild(btn);
        discussFileObjectUrl(att)
          .then(function (src) {
            img.src = src;
          })
          .catch(function () {
            btn.replaceWith(renderDiscussFileChip(att));
          });
        return;
      }
      wrap.appendChild(renderDiscussFileChip(att));
    });
    host.appendChild(wrap);
  }

  function renderDiscussFileChip(att) {
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "note-discuss-attach-file";
    btn.textContent = att.name || "Файл";
    btn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      openDiscussAttachment(att).catch(function (err) {
        alert(err.message || String(err));
      });
    });
    return btn;
  }

  function renderPendingAttachThumbs(host) {
    var pending = discussPendingFiles();
    if (!host || !pending.length) return;
    var wrap = document.createElement("div");
    wrap.className = "note-discuss-attach-list";
    pending.forEach(function (item) {
      if (item.kind === "image" && item.previewUrl) {
        var img = document.createElement("img");
        img.className = "note-discuss-attach-img";
        img.src = item.previewUrl;
        img.alt = item.name || "Фото";
        wrap.appendChild(img);
      } else {
        var chip = document.createElement("span");
        chip.className = "note-discuss-attach-file";
        chip.textContent = item.name || "Файл";
        wrap.appendChild(chip);
      }
    });
    host.appendChild(wrap);
  }

  function ensureAttachPreviewAboveComposer(form) {
    if (!form) return;
    var preview = form.querySelector("#note-paie-attach-preview");
    var row = form.querySelector(".note-paie-toprow") || form.querySelector(".note-paie-composer-row");
    if (!preview || !row || !row.parentNode) return;
    if (preview.nextElementSibling === row) return;
    row.parentNode.insertBefore(preview, row);
  }

  function bindNotePaieReplyForm(threadEl) {
    var form = document.getElementById("note-paie-reply-form");
    if (
      !form ||
      !form.querySelector("#note-paie-attach") ||
      !form.querySelector("#note-paie-plus-menu") ||
      !form.querySelector('[data-plus-action="transcription"]') ||
      !form.querySelector('[data-plus-action="summary"]') ||
      !form.querySelector('[data-plus-action="chat"]') ||
      !form.querySelector(".note-paie-kb-wrap") ||
      !form.querySelector("#note-paie-reply-editor") ||
      !form.querySelector('[data-mode="research"]') ||
      !form.querySelector(".note-paie-toprow")
    ) {
      var html = notePaieReplyFormHtml();
      if (form) form.outerHTML = html;
      else if (threadEl) threadEl.insertAdjacentHTML("beforeend", html);
      form = document.getElementById("note-paie-reply-form");
    }
    if (!form) return;
    ensureAttachPreviewAboveComposer(form);
    bindComposerDictation(form);
    bindNoteKnowledgeToggle(form);
    bindDiscussAttachOnce(form);
    if (form._bound) return;
    form._bound = true;
    var input = document.getElementById("note-paie-reply-input");
    var editor = noteGptEditor();
    var compact = form.querySelector(".note-paie-mode-compact");
    var modeMenu = form.querySelector(".note-paie-mode-menu");
    var modelBtn = form.querySelector(".note-paie-model-btn");
    var modelMenu = form.querySelector(".note-paie-menu--models");
    var modelSearch = form.querySelector(".note-paie-model-search");
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      closeNoteComposerMenus();
      var busyWrap = document.getElementById("note-editor-more-wrap");
      if (busyWrap && busyWrap._gptBusy) {
        stopNoteGptAnswer();
        return;
      }
      if (isChatAskMode(noteAskMode())) {
        var packed = serializeGptComposer(editor);
        submitNoteGptQuestion(packed.text);
      } else if (noteAskMode() === "research") {
        var researchPacked = serializeGptComposer(editor);
        submitNoteResearch(researchPacked.text);
      } else if (noteAskMode() === "comment") {
        var commentPacked = serializeGptComposer(editor);
        submitNoteFooterComment(commentPacked.text);
      } else submitNotePaieReply(input && input.value);
    });
    var replyClear = form.querySelector(".note-paie-reply-target-clear");
    if (replyClear && !replyClear._bound) {
      replyClear._bound = true;
      replyClear.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        clearNoteComposerCommentTarget();
        var focusEl = noteAskUsesComposerEditor(noteAskMode())
          ? noteGptEditor()
          : document.getElementById("note-paie-reply-input");
        if (focusEl) {
          if (focusEl.id === "note-paie-reply-input") {
            focusEl.placeholder = noteAskPlaceholder(noteAskMode());
          } else {
            focusEl.setAttribute("data-placeholder", noteAskPlaceholder(noteAskMode()));
          }
          try {
            focusEl.focus();
          } catch (_) {}
        }
      });
    }
    form.querySelectorAll(".note-paie-mode, .note-paie-mode-menu [data-mode]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        setNoteAskMode(btn.getAttribute("data-mode"));
        closeNoteComposerMenus();
      });
    });
    loadUserAgents();
    if (compact) {
      compact.addEventListener("click", function (e) {
        e.stopPropagation();
        var open = modeMenu && modeMenu.classList.contains("hidden");
        closeNoteComposerMenus(open ? modeMenu : null);
        if (modeMenu && open) {
          modeMenu.classList.remove("hidden");
          compact.classList.add("is-open");
          compact.setAttribute("aria-expanded", "true");
        }
        syncNoteFormatToolbarForComposer();
      });
    }
    if (modelBtn) {
      modelBtn.addEventListener("click", function (e) {
        e.stopPropagation();
        var open = modelMenu && modelMenu.classList.contains("hidden");
        closeNoteComposerMenus(open ? modelMenu : null);
        if (modelMenu && open) {
          if (noteAskMode() === "paie") loadPaieModels();
          else loadGptModels();
          modelMenu.classList.remove("hidden");
          modelBtn.classList.add("is-open");
          modelBtn.setAttribute("aria-expanded", "true");
          if (modelSearch && !isMobileNoteLayout()) {
            try {
              modelSearch.focus();
            } catch (_) {}
          }
        }
        syncNoteFormatToolbarForComposer();
      });
    }
    var modelBack = form.querySelector(".note-model-back");
    if (modelBack && compact) {
      modelBack.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        compact.click();
      });
    }
    if (modelSearch) {
      modelSearch.addEventListener("input", function () {
        renderGptModelMenu(modelSearch.value);
      });
      modelSearch.addEventListener("click", function (e) {
        e.stopPropagation();
      });
    }
    if (modeMenu) {
      modeMenu.addEventListener("click", function (e) {
        e.stopPropagation();
      });
    }
    if (modelMenu) {
      modelMenu.addEventListener("click", function (e) {
        e.stopPropagation();
      });
    }
    var kbMenu = form.querySelector(".note-paie-menu--kb");
    if (kbMenu) {
      kbMenu.addEventListener("click", function (e) {
        e.stopPropagation();
      });
    }
    form.addEventListener("focusin", function () {
      syncNoteFormatToolbarForComposer();
    });
    form.addEventListener("focusout", function () {
      window.setTimeout(syncNoteFormatToolbarForComposer, 80);
    });
    if (input) {
      function sizeComposer() {
        autosizeNoteComposer(input);
      }
      sizeComposer();
      window.requestAnimationFrame(sizeComposer);
      input.addEventListener("input", function () {
        autosizeNoteComposer(input);
        syncNotePaieReplyForm();
      });
      if (!input._composerRo && typeof ResizeObserver === "function") {
        // Высоту меняет сам autosize — реагируем только на смену ширины и раз за кадр,
        // иначе наблюдатель зацикливается и поле ввода дёргается.
        input._composerRo = new ResizeObserver(function (entries) {
          var w = entries && entries[0] && entries[0].contentRect ? Math.round(entries[0].contentRect.width) : 0;
          if (w && w === input._composerRoW) return;
          input._composerRoW = w;
          if (input._composerRoRaf) return;
          input._composerRoRaf = requestAnimationFrame(function () {
            input._composerRoRaf = 0;
            autosizeNoteComposer(input);
          });
        });
        input._composerRo.observe(input);
      }
      input.addEventListener("keydown", function (e) {
        if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
          e.preventDefault();
          if (typeof form.requestSubmit === "function") form.requestSubmit();
          else form.dispatchEvent(new Event("submit", { cancelable: true, bubbles: true }));
        }
      });
      input.addEventListener("keyup", function (e) {
        if (!input.classList.contains("is-overflowing")) return;
        var key = e && e.key;
        if (
          key === "ArrowUp" ||
          key === "ArrowDown" ||
          key === "ArrowLeft" ||
          key === "ArrowRight" ||
          key === "Home" ||
          key === "End" ||
          key === "PageUp" ||
          key === "PageDown"
        ) {
          scrollComposerCaretIntoView(input);
        }
      });
      input.addEventListener("click", function () {
        if (input.classList.contains("is-overflowing")) scrollComposerCaretIntoView(input);
      });
    }
    if (editor) {
      function sizeGptEditor() {
        autosizeNoteComposer(editor);
      }
      syncGptEditorEmpty(editor);
      sizeGptEditor();
      window.requestAnimationFrame(sizeGptEditor);
      editor.addEventListener("input", function (e) {
        composerMdInputRule(editor, e);
        syncGptEditorEmpty(editor);
        editor.setAttribute("data-placeholder", noteAskPlaceholder("gpt"));
        autosizeNoteComposer(editor);
        rememberGptEditorRange();
        syncNotePaieReplyForm();
        syncDiscussMentionMenu();
      });
      editor.addEventListener("keyup", function (e) {
        rememberGptEditorRange();
        syncDiscussMentionMenu();
        if (!editor.classList.contains("is-overflowing")) return;
        var key = e && e.key;
        if (
          key === "ArrowUp" ||
          key === "ArrowDown" ||
          key === "ArrowLeft" ||
          key === "ArrowRight" ||
          key === "Home" ||
          key === "End" ||
          key === "PageUp" ||
          key === "PageDown" ||
          key === "Enter" ||
          key === "Backspace" ||
          key === "Delete"
        ) {
          scrollComposerCaretIntoView(editor);
        }
      });
      editor.addEventListener("click", function () {
        if (editor.classList.contains("is-overflowing")) scrollComposerCaretIntoView(editor);
      });
      editor.addEventListener("pointerup", function () {
        window.setTimeout(function () {
          rememberGptEditorRange();
          syncDiscussMentionMenu();
        }, 0);
      });
      editor.addEventListener("paste", function (e) {
        e.preventDefault();
        closeDiscussMentionMenu();
        var clip = e.clipboardData || window.clipboardData;
        var text = clip ? clip.getData("text/plain") : "";
        if (document.queryCommandSupported && document.queryCommandSupported("insertText")) {
          document.execCommand("insertText", false, text);
        } else if (text) {
          var sel = window.getSelection();
          if (sel && sel.rangeCount) {
            var r = sel.getRangeAt(0);
            r.deleteContents();
            r.insertNode(document.createTextNode(text));
            r.collapse(false);
          }
        }
        syncGptEditorEmpty(editor);
        autosizeNoteComposer(editor);
        rememberGptEditorRange();
        syncNotePaieReplyForm();
        syncDiscussMentionMenu();
        if (editor.classList.contains("is-overflowing")) scrollComposerCaretIntoView(editor);
      });
      editor.addEventListener("keydown", function (e) {
        if (e.key === "Escape") {
          closeDiscussMentionMenu();
        }
        if (e.key === "Backspace" || e.key === "Delete") {
          var chip = selectedGptChip(editor) || adjacentGptChip(editor, e.key === "Backspace" ? -1 : 1);
          if (chip) {
            e.preventDefault();
            removeGptChip(editor, chip);
            closeDiscussMentionMenu();
            return;
          }
        }
        if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
          e.preventDefault();
          closeDiscussMentionMenu();
          if (typeof form.requestSubmit === "function") form.requestSubmit();
          else form.dispatchEvent(new Event("submit", { cancelable: true, bubbles: true }));
          return;
        }
        if (!e.isComposing && composerMdKeydown(editor, e)) {
          syncGptEditorEmpty(editor);
          autosizeNoteComposer(editor);
          rememberGptEditorRange();
          syncNotePaieReplyForm();
        }
      });
      if (!editor._composerRo && typeof ResizeObserver === "function") {
        // Высоту меняет сам autosize — реагируем только на смену ширины и раз за кадр,
        // иначе наблюдатель зацикливается и поле ввода дёргается.
        editor._composerRo = new ResizeObserver(function (entries) {
          var w = entries && entries[0] && entries[0].contentRect ? Math.round(entries[0].contentRect.width) : 0;
          if (w && w === editor._composerRoW) return;
          editor._composerRoW = w;
          if (editor._composerRoRaf) return;
          editor._composerRoRaf = requestAnimationFrame(function () {
            editor._composerRoRaf = 0;
            autosizeNoteComposer(editor);
          });
        });
        editor._composerRo.observe(editor);
      }
    }
    if (!document._noteComposerMenuBound) {
      document._noteComposerMenuBound = true;
      document.addEventListener("click", function (e) {
        var t = e && e.target;
        if (t && t.closest && t.closest(".note-discuss-actions")) return;
        if (t && t.closest && t.closest("#note-discuss-mention-menu")) return;
        closeNoteComposerMenus();
        closeNoteAnswerMenu();
        closeDiscussMentionMenu();
      });
    }
    syncGptModelButton();
  }

  function isNoteDiscussionOpen() {
    var ov = document.getElementById("note-discussion-overlay");
    return !!(ov && !ov.classList.contains("hidden"));
  }

  function freezeNoteEditorUnderDiscussion() {
    resetNoteEditorOverlayPin();
    var sheet = document.querySelector("#note-editor-overlay .modal--sheet");
    var body = sheet && sheet.querySelector(".modal-body");
    if (sheet) {
      sheet.style.transform = "";
      sheet.style.height = "";
      sheet.style.maxHeight = "";
    }
    if (body) body.style.paddingBottom = "";
    document.documentElement.classList.remove("note-editor-kb-open");
    document.documentElement.style.removeProperty("--note-editor-kb-inset");
  }

  function resetDiscussionOverlayViewport() {
    document.documentElement.classList.remove("note-discussion-kb-open");
    var ov = document.getElementById("note-discussion-overlay");
    var sheet = ov && ov.querySelector(".note-discussion-sheet");
    if (ov) {
      ov.style.top = "";
      ov.style.left = "";
      ov.style.right = "";
      ov.style.bottom = "";
      ov.style.width = "";
      ov.style.height = "";
      ov.style.maxHeight = "";
      ov.style.transform = "";
    }
    if (sheet) {
      sheet.style.height = "";
      sheet.style.maxHeight = "";
      sheet.style.transform = "";
    }
  }

  function updateDiscussionOverlayForKeyboard() {
    var ov = document.getElementById("note-discussion-overlay");
    var sheet = ov && ov.querySelector(".note-discussion-sheet");
    if (!ov || !sheet || ov.classList.contains("hidden")) return;
    if (isDesktopLayout()) {
      resetDiscussionOverlayViewport();
      return;
    }
    freezeNoteEditorUnderDiscussion();
    var vv = window.visualViewport;
    var visH = noteEditorVisibleHeightPx();
    var layoutH = Math.max(
      window.innerHeight || 0,
      document.documentElement.clientHeight || 0,
      visH
    );
    var offsetTop = vv && typeof vv.offsetTop === "number" ? Math.round(vv.offsetTop) : 0;
    var offsetLeft = vv && typeof vv.offsetLeft === "number" ? Math.round(vv.offsetLeft) : 0;
    var visW =
      vv && typeof vv.width === "number" && vv.width > 0
        ? Math.round(vv.width)
        : window.innerWidth;
    ov.style.top = "0px";
    ov.style.left = "0px";
    ov.style.right = "auto";
    ov.style.bottom = "auto";
    ov.style.width = Math.max(window.innerWidth || 0, visW + offsetLeft) + "px";
    ov.style.height = Math.max(layoutH, visH + offsetTop) + "px";
    ov.style.maxHeight = "";
    ov.style.transform = "";
    var ovTop = Math.round(ov.getBoundingClientRect().top);
    var sheetShift = ovTop < -8 ? -ovTop : 0;
    var sheetH = visH > 0 ? visH : layoutH;
    sheet.style.height = sheetH + "px";
    sheet.style.maxHeight = sheetH + "px";
    sheet.style.transform = sheetShift ? "translateY(" + sheetShift + "px)" : "";
    // Клавиатура открыта — нижний отступ под home indicator не нужен (была пустая полоса над клавиатурой).
    var kbGuess = Math.max(0, Math.round(layoutH - sheetH - offsetTop));
    document.documentElement.classList.toggle("note-discussion-kb-open", kbGuess > 40);
    if (window.scrollY || window.scrollX) {
      try {
        window.scrollTo(0, 0);
      } catch (_) {}
    }
  }

  function resetNoteSheetState(primaryBody) {
    destroyLeftBoard();
    destroyRightSheetEditor();
    if (noteSheetState.rightNotePersistTimer) {
      clearTimeout(noteSheetState.rightNotePersistTimer);
      noteSheetState.rightNotePersistTimer = null;
    }
    Object.keys(noteSheetState.sheetTimers || {}).forEach(function (id) {
      clearTimeout(noteSheetState.sheetTimers[id]);
    });
    noteSheetState.sheets = [];
    noteSheetState.leftId = NOTE_SHEET_MAIN;
    noteSheetState.rightMode = "discussion";
    noteSheetState.rightId = "";
    noteSheetState.rightNote = null;
    noteSheetState.focus = "left";
    noteSheetState.contextIds = null;
    noteSheetState.contextExplicit = false;
    noteSheetState.rightEditor = null;
    noteSheetState.primaryBody = primaryBody || "";
    noteSheetState.sheetTimers = {};
    noteSheetState.sheetPersists = {};
    noteSheetState.leftScroll = {};
    noteSheetState.skipCaretScroll = false;
    noteSheetState.enabled = false;
    syncNotePaneModeClass();
    renderNoteSheetChips();
    syncNotePaneHeader();
  }

  function noteSheetsShareWrap() {
    return document.getElementById("note-editor-more-wrap");
  }

  function noteSheetsNoteId() {
    var wrap = noteSheetsShareWrap();
    if (!wrap || wrap._shareKind !== "local") return "";
    return String(wrap._shareId || "");
  }

  function noteSheetsEnabled() {
    var wrap = noteSheetsShareWrap();
    return !!(noteSheetState.enabled && wrap && wrap._shareKind === "local" && wrap._shareId);
  }

  function notePaneSwitchEnabled() {
    var wrap = noteSheetsShareWrap();
    return !!(wrap && wrap._shareKind && wrap._shareId);
  }

  function currentDiscussSourceKey() {
    var wrap = noteSheetsShareWrap();
    if (!wrap || !wrap._shareKind || !wrap._shareId) return "";
    return String(wrap._shareKind) + ":" + String(wrap._shareId);
  }

  function findNoteSheet(id) {
    var want = String(id || NOTE_SHEET_MAIN);
    for (var i = 0; i < noteSheetState.sheets.length; i++) {
      if (String(noteSheetState.sheets[i].id) === want) return noteSheetState.sheets[i];
    }
    return null;
  }

  function upsertNoteSheet(item) {
    if (!item) return;
    var id = String(item.id);
    for (var i = 0; i < noteSheetState.sheets.length; i++) {
      if (String(noteSheetState.sheets[i].id) === id) {
        noteSheetState.sheets[i] = item;
        return;
      }
    }
    noteSheetState.sheets.push(item);
  }

  function extraNoteSheets() {
    return noteSheetState.sheets.filter(function (s) {
      return s && !s.is_primary && String(s.id) !== NOTE_SHEET_MAIN;
    });
  }

  function isPrimarySheetId(id) {
    return String(id || NOTE_SHEET_MAIN) === NOTE_SHEET_MAIN;
  }

  function focusedNoteSheetId() {
    if (
      noteSheetState.focus === "right" &&
      noteSheetState.rightMode === "sheet" &&
      noteSheetState.rightId
    ) {
      return String(noteSheetState.rightId);
    }
    return String(noteSheetState.leftId || NOTE_SHEET_MAIN);
  }

  function defaultContextSheetIds() {
    var ids = [NOTE_SHEET_MAIN];
    var focus = focusedNoteSheetId();
    if (focus && ids.indexOf(focus) < 0) ids.push(focus);
    return ids;
  }

  function selectedContextSheetIds() {
    if (noteSheetState.contextExplicit && Array.isArray(noteSheetState.contextIds)) {
      return noteSheetState.contextIds.slice();
    }
    return defaultContextSheetIds();
  }

  function setNoteSheetFocus(pane) {
    noteSheetState.focus = pane === "right" ? "right" : "left";
    if (!noteSheetState.contextExplicit) {
      noteSheetState.contextIds = defaultContextSheetIds();
      renderNoteKnowledgeMenu();
      syncNoteKnowledgeToggle();
    }
  }

  function syncNotePaneModeClass() {
    var sheetOpen =
      (noteSheetState.rightMode === "sheet" || noteSheetState.rightMode === "note") &&
      isNoteDiscussionOpen();
    document.documentElement.classList.toggle("note-discussion-sheet-open", sheetOpen);
    var pane = document.getElementById("note-discussion-sheet-pane");
    var msgs = document.getElementById("note-discussion-messages");
    if (pane) pane.classList.toggle("hidden", !sheetOpen);
    if (msgs) msgs.classList.toggle("hidden", !!sheetOpen);
  }

  function closeNotePaneSwitchMenu() {
    var menu = document.getElementById("note-pane-switch-menu");
    var btn = document.getElementById("note-discussion-title");
    if (menu) {
      menu.classList.add("hidden");
      menu.classList.remove("note-pane-switch-menu--picker");
      menu.classList.remove("is-from-right");
    }
    if (btn) {
      btn.classList.remove("is-open");
      btn.setAttribute("aria-expanded", "false");
    }
    var rightBtn = document.getElementById("note-discussion-new-ctx");
    if (rightBtn) rightBtn.classList.remove("is-open");
  }

  function syncNotePaneHeader() {
    var label = document.getElementById("note-discussion-title-label");
    var btn = document.getElementById("note-discussion-title");
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap && wrap._shareKind === "chat") {
      var chatTitle = "Чат";
      for (var i = 0; i < (chatThreadsCache || []).length; i++) {
        if (String(chatThreadsCache[i].id) === String(wrap._shareId)) {
          chatTitle = String(chatThreadsCache[i].title || "Чат");
          break;
        }
      }
      syncChatDiscussionTitle(chatTitle);
      return;
    }
    var title = (noteSheetState.rightMode === "discussion" && currentDiscussChatTitle()) || "Обсуждение";
    if (noteSheetState.rightMode === "sheet") {
      var sheet = findNoteSheet(noteSheetState.rightId);
      title = (sheet && sheet.title) || "Лист";
    } else if (noteSheetState.rightMode === "note" && noteSheetState.rightNote) {
      title =
        sanitizeNoteTitle(noteSheetState.rightNote.title || "") ||
        String(noteSheetState.rightNote.title || "Заметка");
    }
    if (label) label.textContent = title;
    if (btn) btn.title = title;
    if (btn) {
      var curChat = noteSheetState.rightMode === "discussion" ? currentDiscussChatId() : null;
      var priv = !!(curChat && curChat > 0 && (noteChatById(curChat) || {}).visibility === "private");
      btn.classList.toggle("is-private-chat", priv);
      if (priv) btn.title = title + " — личный чат";
    }
    var canSwitch = notePaneSwitchEnabled() || (noteSheetState.rightMode === "discussion" && noteChatsEnabled());
    // С чатами переключение листов — кнопкой справа; на листе название без меню.
    if (noteChatsEnabled() && noteSheetState.rightMode !== "discussion") canSwitch = false;
    if (btn) {
      btn.disabled = !canSwitch;
      btn.classList.toggle("note-pane-switch--plain", !canSwitch);
    }
    var sub = document.getElementById("note-discussion-subtitle");
    if (sub) {
      var subText = "";
      if (noteSheetState.rightMode === "discussion" && noteChatsEnabled()) {
        var cur = currentDiscussChatId();
        var chatObj = cur && cur > 0 ? noteChatById(cur) || {} : {};
        var members = ((wrap && wrap._noteMembers) || []).length;
        if (cur === COMMENTS_CHAT_ID) subText = "Участники заметки · без ИИ";
        else if (chatObj.visibility === "private" || (cur === 0 && wrap && wrap._newChatVisibility === "private")) {
          subText = "Личный · видите только вы";
        } else {
          subText = "Общий чат" + (members > 1 ? " · " + members + " " + (members % 10 >= 2 && members % 10 <= 4 && (members % 100 < 12 || members % 100 > 14) ? "участника" : members % 10 === 1 && members % 100 !== 11 ? "участник" : "участников") : "");
        }
      }
      sub.textContent = subText;
      sub.classList.toggle("hidden", !subText);
    }
    syncNotePaneModeClass();
  }

  function paneOpenNoteCandidates(query) {
    var wrap = noteSheetsShareWrap();
    var currentId = wrap && wrap._shareId ? String(wrap._shareId) : "";
    var currentKind = wrap && wrap._shareKind ? String(wrap._shareKind) : "";
    var rightId =
      noteSheetState.rightMode === "note" && noteSheetState.rightNote
        ? String(noteSheetState.rightNote.id || "")
        : "";
    var q = String(query || "").trim().toLowerCase();
    var out = [];
    var seen = {};
    function pushItem(n, kind) {
      if (!n) return;
      var id = String(n.id || "");
      if (!id) return;
      if (seen[id]) return;
      if (rightId && id === rightId) return;
      if (currentId && id === currentId) {
        if (currentKind === "journal") {
          if (kind === "journal") return;
        } else if (kind === "local" || kind === "knowledge") {
          return;
        }
      }
      var title =
        sanitizeNoteTitle(n.title || n.content || n.main_topic || "") ||
        String(n.title || n.content || n.main_topic || "Без названия");
      if (q) {
        var hay =
          (title + " " + notePlainExcerpt(n.description || n.body || n.preview || "", 80)).toLowerCase();
        if (hay.indexOf(q) < 0) return;
      }
      if (!noteMatchesPickerProjectFilter(n, panePickerActiveProjectId)) return;
      seen[id] = true;
      out.push({
        kind: kind,
        id: id,
        title: title,
        project: noteProjectOf(n),
        is_knowledge: !!(n.is_knowledge || n.role === "knowledge" || kind === "knowledge"),
        raw: n,
      });
    }
    ((notesDataCache && notesDataCache.local_notes) || []).forEach(function (n) {
      pushItem(n, "local");
    });
    ((knowledgeDataCache && knowledgeDataCache.notes) || []).forEach(function (n) {
      pushItem(n, "knowledge");
    });
    return out;
  }

  function ensurePaneOpenNoteCandidates() {
    var tasks = [];
    if (!notesDataCache || !Array.isArray(notesDataCache.local_notes)) {
      tasks.push(Promise.resolve(loadNotes()).catch(function () {}));
    }
    if (!knowledgeDataCache || !Array.isArray(knowledgeDataCache.notes)) {
      tasks.push(Promise.resolve(loadKnowledgeNotes()).catch(function () {}));
    }
    return Promise.all(tasks).then(function () {
      return paneOpenNoteCandidates("");
    });
  }

  function renderNotePaneOpenNotePicker(query, opts) {
    opts = opts || {};
    var menu = document.getElementById("note-pane-switch-menu");
    if (!menu) return;
    if (opts.resetProjectFilter) panePickerActiveProjectId = 0;
    menu.classList.add("note-pane-switch-menu--picker");
    menu.innerHTML = "";
    var back = document.createElement("button");
    back.type = "button";
    back.className = "note-pane-switch-item note-pane-switch-back";
    back.textContent = "← Назад";
    back.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      renderNotePaneSwitchMenu();
    });
    menu.appendChild(back);
    var searchRow = document.createElement("div");
    searchRow.className = "note-pane-switch-search-row";
    var search = document.createElement("input");
    search.type = "search";
    search.className = "note-pane-switch-search";
    search.placeholder = "Поиск заметок";
    search.autocomplete = "off";
    search.value = String(query || "");
    var createBtn = document.createElement("button");
    createBtn.type = "button";
    createBtn.className = "note-pane-switch-create";
    createBtn.setAttribute("aria-label", "Новая заметка");
    createBtn.title = "Новая заметка";
    createBtn.innerHTML =
      '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>';
    createBtn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      createAndOpenNoteInRightPane();
    });
    searchRow.appendChild(search);
    searchRow.appendChild(createBtn);
    menu.appendChild(searchRow);
    var chips = document.createElement("div");
    chips.className = "note-pane-switch-project-chips notes-project-chips hidden";
    chips.setAttribute("role", "listbox");
    chips.setAttribute("aria-label", "Проекты");
    menu.appendChild(chips);
    var list = document.createElement("div");
    list.className = "note-pane-switch-note-list";
    menu.appendChild(list);
    function fill() {
      renderNotePickerProjectChips(
        chips,
        function () {
          return panePickerActiveProjectId;
        },
        function (v) {
          panePickerActiveProjectId = v;
        },
        fill
      );
      var q = search.value || "";
      var notes = paneOpenNoteCandidates(q);
      list.innerHTML = "";
      if (!notes.length) {
        var empty = document.createElement("p");
        empty.className = "note-pane-switch-empty";
        empty.textContent =
          notesDataCache || knowledgeDataCache
            ? String(q).trim() || panePickerActiveProjectId
              ? "Ничего не найдено"
              : "Других заметок нет"
            : "Загрузка…";
        list.appendChild(empty);
        return;
      }
      notes.forEach(function (n) {
        var btn = document.createElement("button");
        btn.type = "button";
        btn.className = "note-pane-switch-item note-pane-switch-note";
        var title = document.createElement("span");
        title.className = "note-pane-switch-note-title";
        title.textContent = n.title;
        btn.appendChild(title);
        var projectName = (n.project && (n.project.name || n.project.title)) || "";
        if (projectName) {
          var meta = document.createElement("span");
          meta.className = "note-pane-switch-note-project";
          meta.textContent = String(projectName);
          btn.appendChild(meta);
        }
        btn.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          openNoteInRightPane(n);
        });
        list.appendChild(btn);
      });
    }
    search.addEventListener("input", fill);
    search.addEventListener("click", function (e) {
      e.stopPropagation();
    });
    fill();
    window.setTimeout(function () {
      try {
        search.focus();
      } catch (_) {}
    }, 20);
  }

  function renderNotePaneSwitchMenu() {
    var menu = document.getElementById("note-pane-switch-menu");
    if (!menu) return;
    menu.classList.remove("note-pane-switch-menu--picker");
    menu.innerHTML = "";
    function addItem(label, active, onClick, icon) {
      var row = document.createElement("button");
      row.type = "button";
      row.className = "note-pane-switch-item" + (active ? " is-active" : "") + (icon ? " has-ico" : "");
      row.setAttribute("role", "menuitem");
      if (icon) {
        row.innerHTML = '<span class="note-pane-ico">' + DISCUSS_ICONS[icon] + "</span><span></span>";
        row.lastChild.textContent = label;
      } else {
        row.textContent = label;
      }
      row.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        onClick();
      });
      menu.appendChild(row);
    }
    addItem("Обсуждение", noteSheetState.rightMode === "discussion", function () {
      closeNotePaneSwitchMenu();
      setRightPaneMode("discussion");
    }, "chat");
    var discussSep = document.createElement("div");
    discussSep.className = "note-pane-switch-sep";
    menu.appendChild(discussSep);
    var leftOpenId = String(noteSheetState.leftId || NOTE_SHEET_MAIN);
    var otherSheets = (noteSheetState.sheets || []).filter(function (s) {
      return String(s.id) !== leftOpenId;
    });
    if (noteSheetsEnabled() || otherSheets.length) {
      var sheetsLabel = document.createElement("div");
      sheetsLabel.className = "note-pane-switch-label";
      sheetsLabel.textContent = "Листы заметки";
      menu.appendChild(sheetsLabel);
    }
    otherSheets.forEach(function (s) {
      addItem(
        s.title || "Лист",
        noteSheetState.rightMode === "sheet" && String(s.id) === String(noteSheetState.rightId),
        function () {
          closeNotePaneSwitchMenu();
          setRightPaneMode("sheet", s.id);
        },
        isWebSheet(s) ? "grid" : isBoardSheet(s) ? "board" : "note"
      );
    });
    if (noteSheetsEnabled()) {
      if (otherSheets.length) {
        var newSep = document.createElement("div");
        newSep.className = "note-pane-switch-sep";
        menu.appendChild(newSep);
      }
      addItem("Новый лист", false, function () {
        closeNotePaneSwitchMenu();
        createNoteSheet({ openOn: "right", kind: "doc" });
      }, "notePlus");
      addItem("Новая доска", false, function () {
        closeNotePaneSwitchMenu();
        createNoteSheet({ openOn: "right", kind: "board" });
      }, "board");
      addItem("Новая презентация", false, function () {
        closeNotePaneSwitchMenu();
        createNoteSheet({ openOn: "right", kind: "web" });
      }, "grid");
    }
    if (noteSheetState.rightMode === "note" && noteSheetState.rightNote) {
      var openTitle =
        sanitizeNoteTitle(noteSheetState.rightNote.title || "") ||
        String(noteSheetState.rightNote.title || "Заметка");
      addItem(openTitle, true, function () {
        closeNotePaneSwitchMenu();
      }, "note");
    }
    var sep = document.createElement("div");
    sep.className = "note-pane-switch-sep";
    menu.appendChild(sep);
    addItem("Открыть другую заметку", false, function () {
      renderNotePaneOpenNotePicker("", { resetProjectFilter: true });
      ensurePaneOpenNoteCandidates().then(function () {
        ensureUserTagsLoaded().finally(function () {
          var menuEl = document.getElementById("note-pane-switch-menu");
          if (menuEl && menuEl.classList.contains("note-pane-switch-menu--picker")) {
            renderNotePaneOpenNotePicker(
              (menuEl.querySelector(".note-pane-switch-search") || {}).value || ""
            );
          }
        });
      });
    }, "search");
  }

  function toggleNotePaneSwitchMenu(opts) {
    if (!notePaneSwitchEnabled()) return;
    var menu = document.getElementById("note-pane-switch-menu");
    var btn = document.getElementById("note-discussion-title");
    if (!menu || !btn) return;
    var open = menu.classList.contains("hidden");
    if (open) {
      closeNoteChatsMenu();
      renderNotePaneSwitchMenu();
      var fromRight = !!(opts && opts.fromRight);
      menu.classList.toggle("is-from-right", fromRight);
      menu.classList.remove("hidden");
      var opener = fromRight ? document.getElementById("note-discussion-new-ctx") : btn;
      if (opener) {
        opener.classList.add("is-open");
        opener.setAttribute("aria-expanded", "true");
      }
    } else {
      closeNotePaneSwitchMenu();
    }
  }

  function destroyRightSheetEditor() {
    if (noteSheetState.rightNotePersistTimer) {
      clearTimeout(noteSheetState.rightNotePersistTimer);
      noteSheetState.rightNotePersistTimer = null;
    }
    destroyRightWebCanvas();
    destroyRightBoard();
    var inst = noteSheetState.rightEditor;
    if (inst && typeof inst.destroy === "function") {
      try {
        inst.destroy();
      } catch (_) {}
    }
    noteSheetState.rightEditor = null;
    var host = document.getElementById("note-discussion-sheet-host");
    var bar = document.getElementById("note-discussion-sheet-toolbar");
    if (host) host.innerHTML = "";
    if (bar) bar.innerHTML = "";
    if (noteSheetState.focus === "right") noteSheetState.focus = "left";
  }

  function scheduleRightForeignNotePersist() {
    if (!noteSheetState.rightNote || noteSheetState.rightMode !== "note") return;
    var rightNote = noteSheetState.rightNote;
    if (rightNote && rightNote.id && (rightNote.kind || "local") !== "journal") {
      writeLocalNoteDraft(rightNote.id, {
        title: String(rightNote.title || "").trim(),
        body: readSheetEditorHtml("right") || rightNote.body || rightNote.description || "",
        baseRevision: rightNote.revision,
        baseUpdatedAt: rightNote.updated_at,
      });
    }
    if (noteSheetState.rightNotePersistTimer) clearTimeout(noteSheetState.rightNotePersistTimer);
    noteSheetState.rightNotePersistTimer = setTimeout(function () {
      persistRightForeignNote().catch(function (e) {
        setNoteEditorSaveHint(e.message || "Не удалось сохранить заметку");
      });
    }, 1500);
  }

  async function persistRightForeignNote(snap) {
    var note = snap || noteSheetState.rightNote;
    if (!note || !note.id) return;
    var html =
      snap && snap.body != null
        ? snap.body
        : readSheetEditorHtml("right") || note.body || note.description || "";
    note.body = html;
    note.description = html;
    var title = String(note.title || "").trim() || "Без названия";
    var kind = note.kind === "knowledge" ? "local" : note.kind || "local";
    if (kind === "journal") {
      await apiFetch("/notes/journal/" + encodeURIComponent(String(note.id)), {
        method: "PATCH",
        body: JSON.stringify({ title: title, description: html }),
      });
      updateJournalInCache(note.id, note.operation, {
        id: note.id,
        main_topic: title,
        preview: notePlainExcerpt(html, 400),
      });
      if (notesDataCache) renderNotesPanesFromData(notesDataCache);
      return;
    }
    writeLocalNoteDraft(note.id, {
      title: title,
      body: html,
      baseRevision: note.revision,
      baseUpdatedAt: note.updated_at,
    });
    var patchBody = { title: title, description: html };
    if (note.revision) patchBody.expected_revision = note.revision;
    var patchRes;
    try {
      patchRes = await apiFetch("/notes/local/" + encodeURIComponent(String(note.id)), {
        method: "PATCH",
        body: JSON.stringify(patchBody),
      });
    } catch (e) {
      if (e && e.status === 409 && e.conflictItem) {
        var remoteRight = e.conflictItem;
        if (notePayloadEquals(title, html, remoteRight.title, remoteRight.body || remoteRight.description)) {
          adoptNoteRevision(remoteRight, note.id);
          note.revision = remoteRight.revision || note.revision;
          note.updated_at = remoteRight.updated_at || note.updated_at;
          clearLocalNoteDraftIfUnchanged(note.id, title, html);
          return;
        }
        handleNotePatchConflict(note.id, remoteRight, title, html);
        return;
      }
      throw e;
    }
    clearLocalNoteDraftIfUnchanged(note.id, title, html);
    var item = (patchRes && patchRes.item) || {
      id: note.id,
      title: title,
      description: html,
      body: html,
      role: note.kind === "knowledge" ? "knowledge" : note.role || "",
      is_knowledge: note.kind === "knowledge",
      is_transcription: !!note.is_transcription,
      primary_sheet_title: note.primary_sheet_title || "",
    };
    stampTranscriptionFields(item, note);
    if (patchRes && patchRes.item) {
      note.revision = patchRes.item.revision || note.revision;
      note.updated_at = patchRes.item.updated_at || note.updated_at;
    }
    if (note.kind === "knowledge" || isKnowledgeNoteItem(item)) {
      item.role = "knowledge";
      item.is_knowledge = true;
      prependKnowledgeInCache(Object.assign({}, item, { tags: note.tags, project: note.project }));
    } else {
      syncLocalNoteInList(Object.assign({}, item, { tags: note.tags, project: note.project }));
    }
    if (noteSheetState.rightNote && String(noteSheetState.rightNote.id) === String(note.id)) {
      noteSheetState.rightNote.title = item.title || title;
      syncNotePaneHeader();
    }
  }

  function flushRightForeignNoteBeforeLeave() {
    if (noteSheetState.rightMode !== "note" || !noteSheetState.rightNote) return;
    if (noteSheetState.rightNotePersistTimer) {
      clearTimeout(noteSheetState.rightNotePersistTimer);
      noteSheetState.rightNotePersistTimer = null;
    }
    var note = noteSheetState.rightNote;
    var html = readSheetEditorHtml("right") || note.body || note.description || "";
    var snap = Object.assign({}, note, {
      body: html,
      description: html,
      title: String(note.title || "").trim() || "Без названия",
    });
    persistRightForeignNote(snap).catch(function () {});
  }

  async function openNoteInRightPane(item) {
    closeNotePaneSwitchMenu();
    try {
      flushRightForeignNoteBeforeLeave();
      var loaded = await fetchNoteForRightPane(item);
      if (!isNoteDiscussionOpen()) {
        openNoteDiscussion({ fromDesktopSync: true, focus: false });
      }
      await flushSheetEditor("right").catch(function () {});
      noteSheetState.rightMode = "note";
      noteSheetState.rightId = "";
      noteSheetState.rightNote = loaded;
      setNoteSheetFocus("right");
      syncNotePaneHeader();
      mountRightForeignNote(loaded);
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  function mountRightForeignNote(note) {
    var host = document.getElementById("note-discussion-sheet-host");
    var bar = document.getElementById("note-discussion-sheet-toolbar");
    if (!host || !note) return;
    destroyRightSheetEditor();
    host.innerHTML = "";
    if (bar) bar.innerHTML = "";
    var titleWrap = document.createElement("div");
    titleWrap.className = "note-discussion-right-note-title-wrap";
    var titleInput = document.createElement("textarea");
    titleInput.className = "note-discussion-right-note-title";
    titleInput.rows = 1;
    titleInput.spellcheck = true;
    titleInput.placeholder = "Заголовок";
    titleInput.value = String(note.title || "");
    titleInput.addEventListener("input", function () {
      note.title = titleInput.value;
      syncNotePaneHeader();
      scheduleRightForeignNotePersist();
      bindNoteTitleAutoresize(titleInput);
    });
    titleWrap.appendChild(titleInput);
    host.appendChild(titleWrap);
    var bodyHost = document.createElement("div");
    bodyHost.className = "note-discussion-right-note-body";
    host.appendChild(bodyHost);
    bindNoteTitleAutoresize(titleInput);
    mountNoteRichEditor(bodyHost, note.body || note.description || "", function () {
      scheduleRightForeignNotePersist();
    }, {
      toolbarParent: bar,
      showSharedToolbar: false,
      mountId: "td-desc-right-note",
      scrollParent: host,
    }).then(function (editor) {
      noteSheetState.rightEditor = editor;
      host.addEventListener(
        "focusin",
        function () {
          setNoteSheetFocus("right");
        },
        true
      );
    });
  }

  async function fetchNoteForRightPane(item) {
    var kind = item.kind === "knowledge" ? "local" : item.kind || "local";
    var id = String(item.id || "");
    if (!id) throw new Error("Нет id заметки");
    if (kind === "journal") {
      var jres = await apiFetch("/notes/journal/" + encodeURIComponent(id), { method: "GET" });
      var jit = (jres && jres.item) || item.raw || {};
      return {
        kind: "journal",
        id: id,
        title: journalTitleForEditor(jit, item.raw || jit),
        body: prepareJournalBodyForEditor(jit),
        description: prepareJournalBodyForEditor(jit),
        operation: jit.operation || (item.raw && item.raw.operation) || "",
        tags: noteTagsOf(jit),
        project: noteProjectOf(jit),
      };
    }
    var res = await apiFetch("/notes/local/" + encodeURIComponent(id), { method: "GET" });
    var it = (res && res.item) || item.raw || {};
    var isKb = item.kind === "knowledge" || isKnowledgeNoteItem(it) || item.is_knowledge;
    var loaded = {
      kind: isKb ? "knowledge" : "local",
      id: String(it.id || id),
      title: sanitizeNoteTitle(it.title || it.content || "") || String(it.title || "Без названия"),
      body: it.body || it.description || "",
      description: it.body || it.description || "",
      tags: noteTagsOf(it),
      project: noteProjectOf(it),
      revision: it.revision,
      updated_at: it.updated_at,
    };
    var hydrated = hydrateLocalNoteWithDraft(loaded);
    if (hydrated.use === "draft") {
      loaded.title = hydrated.title;
      loaded.body = hydrated.body;
      loaded.description = hydrated.body;
    }
    return loaded;
  }

  async function createAndOpenNoteInRightPane() {
    closeNotePaneSwitchMenu();
    try {
      var res = await apiFetch("/notes/local", {
        method: "POST",
        body: JSON.stringify({ title: "Новая заметка", description: "" }),
      });
      var item = (res && res.item) || null;
      if (!item || item.id == null) throw new Error("Не удалось создать заметку");
      prependLocalInCache(item);
      if (notesDataCache) renderNotesPanesFromData(notesDataCache);
      await openNoteInRightPane({
        kind: "local",
        id: item.id,
        title: item.title || "Новая заметка",
        raw: item,
      });
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  function previewOpenNoteFromSheets() {
    var body = getNoteEditorBodyEl();
    if (body && typeof body._notePreviewList === "function") body._notePreviewList();
  }

  function scheduleExtraSheetPersist(sheetId) {
    var id = String(sheetId || "");
    if (!id || isPrimarySheetId(id)) return;
    if (noteSheetState.applyingRemoteSheet === id) return; // чужая версия, только что показанная
    previewOpenNoteFromSheets();
    if (noteSheetState.sheetTimers[id]) clearTimeout(noteSheetState.sheetTimers[id]);
    noteSheetState.sheetTimers[id] = setTimeout(function () {
      persistExtraSheet(id).catch(function (e) {
        setNoteEditorSaveHint(e.message || "Не удалось сохранить лист");
      });
    }, 1500);
  }

  function readSheetEditorHtml(which) {
    if (which === "right") {
      if (noteSheetState.rightBoard) return noteSheetState.rightBoard.getJson();
      if (noteSheetState.rightWebCanvas && typeof noteSheetState.rightWebCanvas.getHtml === "function") {
        return noteSheetState.rightWebCanvas.getHtml();
      }
      var instR = noteSheetState.rightEditor;
      if (instR && typeof instR.getHtml === "function") return instR.getHtml();
      return "";
    }
    if (noteSheetState.leftBoard) return noteSheetState.leftBoard.getJson();
    if (noteSheetState.leftWebCanvas && typeof noteSheetState.leftWebCanvas.getHtml === "function") {
      return noteSheetState.leftWebCanvas.getHtml();
    }
    var inst = getLeftNoteRichEditor();
    if (inst && typeof inst.getHtml === "function") return inst.getHtml();
    return "";
  }

  function flushSheetEditor(which) {
    var id = which === "right" ? noteSheetState.rightId : noteSheetState.leftId;
    if (!id) return Promise.resolve();
    if (noteSheetState.sheetTimers[id]) {
      clearTimeout(noteSheetState.sheetTimers[id]);
      delete noteSheetState.sheetTimers[id];
    }
    if (isPrimarySheetId(id)) {
      var html = readSheetEditorHtml(which);
      if (html) noteSheetState.primaryBody = html;
      return Promise.resolve();
    }
    return persistExtraSheet(id);
  }

  async function persistExtraSheet(sheetId) {
    var id = String(sheetId || "");
    if (!id || isPrimarySheetId(id)) return;
    var prev = noteSheetState.sheetPersists[id];
    var run = function () {
      return persistExtraSheetNow(id);
    };
    var next = prev ? prev.then(run, run) : run();
    noteSheetState.sheetPersists[id] = next;
    try {
      return await next;
    } finally {
      if (noteSheetState.sheetPersists[id] === next) delete noteSheetState.sheetPersists[id];
    }
  }

  async function persistExtraSheetNow(sheetId, retried) {
    var id = String(sheetId || "");
    var noteId = noteSheetsNoteId();
    var sheet = findNoteSheet(id);
    if (!id || !noteId || !sheet || isPrimarySheetId(id)) return;
    var html = "";
    if (String(noteSheetState.leftId) === id) html = readSheetEditorHtml("left");
    else if (String(noteSheetState.rightId) === id) html = readSheetEditorHtml("right");
    else html = sheet.body || sheet.description || "";
    var titleAtStart = String(sheet.title || "");
    var body = {
      title: titleAtStart,
      description: html,
      expected_revision: sheet.revision,
    };
    if (isBoardSheet(sheet) && boardYjsReady(id)) {
      // Тело холста из совместного документа: правки других уже слиты Yjs, ревизию не сверяем.
      body.yjs = true;
      delete body.expected_revision;
    }
    if (isAppOffline() || String(noteId).indexOf("tmp_") === 0) {
      sheet.body = html;
      sheet.description = html;
      enqueueOfflineOp({
        type: "sheet_patch",
        clientId: id,
        noteId: String(noteId),
        path:
          "/notes/local/" +
          encodeURIComponent(String(noteId)) +
          "/sheets/" +
          encodeURIComponent(id),
        method: "PATCH",
        body: { title: titleAtStart, description: html },
      });
      showOfflineSavedToast();
      return;
    }
    try {
      var res = await apiFetch(
        "/notes/local/" +
          encodeURIComponent(String(noteId)) +
          "/sheets/" +
          encodeURIComponent(id),
        { method: "PATCH", body: JSON.stringify(body) }
      );
      if (res && res.note_updated_at) bumpNoteUpdatedInList(noteId, res.note_updated_at);
      if (res && res.item) {
        var saved = res.item;
        saved.body = html;
        saved.description = html;
        var live = findNoteSheet(id);
        var liveTitle = live ? String(live.title || "") : "";
        // Пока шёл PATCH, могли переименовать чип — не откатываем более новое имя.
        if (liveTitle && liveTitle !== titleAtStart) {
          saved.title = liveTitle;
          upsertNoteSheet(saved);
          previewOpenNoteFromSheets();
          persistExtraSheet(id).catch(function (e) {
            setNoteEditorSaveHint(e.message || "Не удалось сохранить название листа");
          });
        } else {
          saved.title = String(saved.title || titleAtStart);
          upsertNoteSheet(saved);
          previewOpenNoteFromSheets();
        }
      }
    } catch (e) {
      var remote = e && e.conflictItem;
      if (e && e.status === 409 && remote) {
        if (sheet) sheet.revision = remote.revision || sheet.revision;
        if (!retried) return persistExtraSheetNow(id, true);
        var err = new Error("Лист изменён в другой вкладке. Сохраните ещё раз.");
        err.status = 409;
        throw err;
      }
      throw e;
    }
  }

  function mountRightSheetEditor(sheet) {
    var host = document.getElementById("note-discussion-sheet-host");
    var bar = document.getElementById("note-discussion-sheet-toolbar");
    if (!host || !sheet) return;
    destroyRightSheetEditor();
    destroyRightWebCanvas();
    host.innerHTML = "";
    if (bar) bar.innerHTML = "";
    if (isBoardSheet(sheet)) {
      mountRightBoard(sheet);
      host.addEventListener(
        "focusin",
        function () {
          setNoteSheetFocus("right");
        },
        true
      );
      return;
    }
    if (isWebSheet(sheet)) {
      mountRightWebCanvas(sheet);
      host.addEventListener(
        "focusin",
        function () {
          setNoteSheetFocus("right");
        },
        true
      );
      return;
    }
    mountNoteRichEditor(host, sheet.body || sheet.description || "", function () {
      if (String(noteSheetState.rightId) === String(sheet.id) && !isPrimarySheetId(sheet.id)) {
        scheduleExtraSheetPersist(sheet.id);
      } else if (isPrimarySheetId(sheet.id)) {
        noteSheetState.primaryBody = readSheetEditorHtml("right");
        var leftFlush = getNoteEditorBodyEl();
        if (leftFlush && typeof leftFlush._noteEditorSchedule === "function") {
          leftFlush._noteEditorSchedule();
        }
      }
    }, {
      toolbarParent: bar,
      showSharedToolbar: false,
      mountId: "td-desc-right",
      scrollParent: host,
    }).then(function (editor) {
      noteSheetState.rightEditor = editor;
      host.addEventListener(
        "focusin",
        function () {
          setNoteSheetFocus("right");
        },
        true
      );
    });
  }

  function setRightPaneMode(mode, sheetId) {
    if (mode === "sheet") {
      var sheet = findNoteSheet(sheetId || noteSheetState.rightId || NOTE_SHEET_MAIN);
      if (!sheet) sheet = findNoteSheet(NOTE_SHEET_MAIN);
      if (!sheet) return;
      if (!isNoteDiscussionOpen()) openNoteDiscussion({ fromDesktopSync: true, focus: false });
      flushRightForeignNoteBeforeLeave();
      noteSheetState.rightMode = "sheet";
      noteSheetState.rightId = String(sheet.id);
      noteSheetState.rightNote = null;
      setNoteSheetFocus("right");
      syncNotePaneHeader();
      mountRightSheetEditor(sheet);
      return;
    }
    if (mode === "note") {
      return;
    }
    flushRightForeignNoteBeforeLeave();
    flushSheetEditor("right").catch(function () {});
    noteSheetState.rightMode = "discussion";
    noteSheetState.rightId = "";
    noteSheetState.rightNote = null;
    destroyRightSheetEditor();
    setNoteSheetFocus("left");
    syncNotePaneHeader();
  }

  function applyLeftSheetHtml(sheet) {
    var toPrimary = !!(sheet && isPrimarySheetId(sheet.id));
    // Совместный документ привязан к основному листу: другой лист его не трогает.
    if (noteYjsSession && !toPrimary) noteYjsSession.detach();
    if (isBoardSheet(sheet)) {
      mountLeftBoard(sheet);
      return;
    }
    destroyLeftBoard();
    if (isWebSheet(sheet)) {
      mountLeftWebCanvas(sheet);
      return;
    }
    destroyLeftWebCanvas();
    var editor = getLeftNoteRichEditor();
    var html = (sheet && (sheet.body || sheet.description)) || "";
    if (editor && typeof editor.setHtml === "function") editor.setHtml(html);
    if (noteYjsSession && toPrimary) noteYjsSession.attach();
  }

  function saveLeftSheetScroll() {
    var el = getNoteEditorScrollEl();
    if (!el) return;
    if (!noteSheetState.leftScroll) noteSheetState.leftScroll = {};
    noteSheetState.leftScroll[String(noteSheetState.leftId || NOTE_SHEET_MAIN)] = el.scrollTop;
  }

  function restoreLeftSheetScroll(sheetId) {
    var el = getNoteEditorScrollEl();
    if (!el) return;
    var saved = noteSheetState.leftScroll && noteSheetState.leftScroll[String(sheetId || NOTE_SHEET_MAIN)];
    el.scrollTop = typeof saved === "number" ? saved : 0;
  }

  async function switchLeftSheet(sheetId) {
    var next = findNoteSheet(sheetId);
    if (!next) return;
    if (noteAiReview && String(next.id) !== noteAiReview.sheetId) finishAiReview(true);
    var prevId = String(noteSheetState.leftId || NOTE_SHEET_MAIN);
    if (String(next.id) === prevId) {
      setNoteSheetFocus("left");
      renderNoteSheetChips();
      return;
    }
    saveLeftSheetScroll();
    noteSheetState.skipCaretScroll = true;
    await flushSheetEditor("left");
    if (isPrimarySheetId(prevId)) {
      noteSheetState.primaryBody = readSheetEditorHtml("left") || noteSheetState.primaryBody;
      var main = findNoteSheet(NOTE_SHEET_MAIN);
      if (main) {
        main.body = noteSheetState.primaryBody;
        main.description = noteSheetState.primaryBody;
      }
    }
    noteSheetState.leftId = String(next.id);
    var transNote = resolveLocalNoteFromCache({ id: noteSheetsNoteId() });
    var pad = document.querySelector("#note-editor-overlay .note-editor-pad--body");
    if (
      isTranscriptionNoteItem(transNote) &&
      transcriptionIsGenerating(transNote) &&
      isPrimarySheetId(next.id) &&
      pad
    ) {
      pad.innerHTML = noteSheetSkeletonHtml();
    } else {
      applyLeftSheetHtml(next);
    }
    setNoteSheetFocus("left");
    renderNoteSheetChips();
    var restore = function () {
      restoreLeftSheetScroll(next.id);
    };
    restore();
    requestAnimationFrame(function () {
      restore();
      requestAnimationFrame(function () {
        restore();
        window.setTimeout(function () {
          restore();
          noteSheetState.skipCaretScroll = false;
        }, 80);
      });
    });
  }

  // ---- Вкладки листов: перетаскивание и иконка шеринга ----
  var SHARE_TAB_ICON =
    '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
    '<path d="M10 14a5 5 0 0 0 7.07 0l3-3a5 5 0 0 0-7.07-7.07l-1 1"/><path d="M14 10a5 5 0 0 0-7.07 0l-3 3a5 5 0 0 0 7.07 7.07l1-1"/></svg>';

  // Ссылка, открывающая лист: сначала ссылка только на него, иначе последняя, где он есть.
  function shareLinkForSheet(sheetId) {
    var wrap = discussWrap();
    var links = (wrap && Array.isArray(wrap._shareLinks) && wrap._shareLinksFor === String(wrap._shareId)) ? wrap._shareLinks : [];
    var id = String(sheetId);
    var has = links.filter(function (l) {
      var ids = (l.sheet_ids || []).map(String);
      return ids.length ? ids.indexOf(id) >= 0 : isPrimarySheetId(id);
    });
    var exact = has.filter(function (l) { return (l.sheet_ids || []).length === 1; })[0];
    return exact || has[0] || null;
  }

  function loadNoteShareLinks() {
    var wrap = discussWrap();
    if (!wrap || wrap._shareKind !== "local" || !wrap._shareId || String(wrap._shareId).indexOf("tmp_") === 0) return;
    var id = String(wrap._shareId);
    apiFetch("/notes/local/" + encodeURIComponent(id) + "/share", { method: "GET" })
      .then(function (data) {
        var live = discussWrap();
        if (!live || String(live._shareId) !== id) return;
        applyShareState(live, data);
        renderNoteSheetChips();
      })
      .catch(function () {});
  }

  function closeSheetShareMenu() {
    var m = document.getElementById("note-sheet-share-menu");
    if (m && m.parentNode) m.parentNode.removeChild(m);
  }

  function openSheetShareMenu(anchor, sheet) {
    closeSheetShareMenu();
    var link = shareLinkForSheet(sheet.id);
    if (!link) return;
    var menu = document.createElement("div");
    menu.id = "note-sheet-share-menu";
    menu.className = "note-sheet-kind-menu note-sheet-share-menu";
    menu.setAttribute("role", "menu");
    function item(label, fn, danger) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "note-sheet-kind-menu-item" + (danger ? " is-danger" : "");
      b.setAttribute("role", "menuitem");
      var t = document.createElement("span");
      t.className = "note-sheet-kind-menu-title";
      t.textContent = label;
      b.appendChild(t);
      b.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        closeSheetShareMenu();
        fn();
      });
      menu.appendChild(b);
    }
    item("Скопировать ссылку", function () {
      copyShareUrl(link.url).then(function () {
        shareHaptic();
        showNoteToast("Ссылка скопирована");
      }).catch(function (e) {
        alert(e.message || String(e));
      });
    });
    var toComment = link.access !== "comment";
    item(toComment ? "Изменить права: разрешить комментарии" : "Изменить права: только просмотр", function () {
      setShareLinkAccess(link, toComment ? "comment" : "view");
    });
    item("Закрыть доступ", function () {
      revokeOneShareLink(link);
    }, true);
    var foot = document.createElement("p");
    foot.className = "note-sheet-share-foot";
    var shared = (link.sheet_ids || []).length > 1 ? " · ссылка на " + (link.sheet_ids || []).length + " листа" : "";
    foot.textContent = (link.access === "comment" ? "Комментарии" : "Просмотр") + " · " + ruViews(link.views || 0) + shared;
    menu.appendChild(foot);
    document.body.appendChild(menu);
    var r = anchor.getBoundingClientRect();
    var left = Math.min(Math.max(8, r.left - 8), window.innerWidth - menu.offsetWidth - 8);
    menu.style.left = left + "px";
    menu.style.top = r.bottom + 6 + "px";
    setTimeout(function () {
      document.addEventListener("click", closeSheetShareMenu, { once: true });
    }, 0);
  }

  function ruViews(n) {
    var m10 = n % 10;
    var m100 = n % 100;
    var w = m10 === 1 && m100 !== 11 ? "просмотр" : m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14) ? "просмотра" : "просмотров";
    return n + " " + w;
  }

  async function setShareLinkAccess(link, access) {
    var wrap = getShareCtx() || discussWrap();
    if (!wrap || !wrap._shareId) return;
    try {
      var data = await apiFetch(
        "/notes/" + encodeURIComponent(wrap._shareKind) + "/" + encodeURIComponent(wrap._shareId) + "/share",
        { method: "POST", body: JSON.stringify({ access: access, sheet_ids: link.sheet_ids || [] }) }
      );
      applyShareState(wrap, Object.assign({}, data, { views: link.views }));
      renderNoteSheetChips();
      if (typeof syncShareSelectionState === "function") syncShareSelectionState();
      showNoteToast(access === "comment" ? "По ссылке можно комментировать" : "Ссылка только для просмотра");
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  // Перетаскивание вкладок: мышью — сразу при сдвиге, пальцем — после удержания.
  function attachSheetTabsDrag(host) {
    if (host._dragBound) return;
    host._dragBound = true;
    var drag = null;
    function chips() {
      return Array.prototype.slice.call(host.querySelectorAll(".note-sheet-chip[data-sheet-id]"));
    }
    function begin() {
      drag.on = true;
      drag.chip.classList.add("is-dragging");
      host.classList.add("is-reordering");
      try {
        var tg = window.Telegram && window.Telegram.WebApp;
        if (tg && tg.HapticFeedback) tg.HapticFeedback.impactOccurred("light");
      } catch (_) {}
    }
    host.addEventListener("pointerdown", function (e) {
      var chip = e.target.closest && e.target.closest(".note-sheet-chip[data-sheet-id]");
      if (!chip || chip.querySelector(".note-sheet-chip-input") || e.target.closest(".note-sheet-chip-share")) return;
      if (e.button !== undefined && e.button !== 0) return;
      drag = { chip: chip, x: e.clientX, y: e.clientY, id: e.pointerId, touch: e.pointerType !== "mouse", on: false, before: chips().map(function (c) { return c.getAttribute("data-sheet-id"); }) };
      if (drag.touch) {
        drag.timer = setTimeout(function () {
          if (drag && !drag.on) begin();
        }, 380);
      }
    });
    host.addEventListener("pointermove", function (e) {
      if (!drag || e.pointerId !== drag.id) return;
      var dx = e.clientX - drag.x;
      var dy = e.clientY - drag.y;
      if (!drag.on) {
        if (drag.touch) {
          if (Math.abs(dx) > 8 || Math.abs(dy) > 8) {
            clearTimeout(drag.timer);
            drag = null; // это прокрутка вкладок
          }
          return;
        }
        if (Math.abs(dx) < 6) return;
        begin();
      }
      e.preventDefault();
      // Меняем местами с соседом, когда палец/курсор прошёл его середину.
      chips().forEach(function (other) {
        if (other === drag.chip) return;
        var r = other.getBoundingClientRect();
        var mid = r.left + r.width / 2;
        var me = drag.chip.getBoundingClientRect();
        if (me.left < r.left && e.clientX > mid) host.insertBefore(drag.chip, other.nextSibling);
        else if (me.left > r.left && e.clientX < mid) host.insertBefore(drag.chip, other);
      });
    });
    host.addEventListener("touchmove", function (e) {
      if (drag && drag.on) e.preventDefault(); // во время перетаскивания не прокручиваем
    }, { passive: false });
    function end() {
      if (!drag) return;
      clearTimeout(drag.timer);
      var was = drag;
      drag = null;
      if (!was.on) return;
      was.chip.classList.remove("is-dragging");
      host.classList.remove("is-reordering");
      host._suppressClickUntil = Date.now() + 400;
      var order = chips().map(function (c) { return c.getAttribute("data-sheet-id"); });
      if (order.join("|") !== was.before.join("|")) saveSheetOrder(order);
    }
    host.addEventListener("pointerup", end);
    host.addEventListener("pointercancel", end);
    host.addEventListener("click", function (e) {
      if (host._suppressClickUntil && Date.now() < host._suppressClickUntil) {
        e.preventDefault();
        e.stopPropagation();
      }
    }, true);
  }

  function saveSheetOrder(order) {
    var noteId = noteSheetsNoteId();
    if (!noteId) return;
    var byId = {};
    noteSheetState.sheets.forEach(function (s) { byId[String(s.id)] = s; });
    var prev = noteSheetState.sheets.slice();
    noteSheetState.sheets = order.map(function (id) { return byId[id]; }).filter(Boolean);
    renderNoteSheetChips();
    apiFetch("/notes/local/" + encodeURIComponent(String(noteId)) + "/sheets/order", {
      method: "PUT",
      body: JSON.stringify({ order: order }),
    }).catch(function (e) {
      noteSheetState.sheets = prev;
      renderNoteSheetChips();
      showNoteToast((e && e.message) || "Не удалось изменить порядок листов");
    });
  }

  function scheduleTranscriptSheetSync() {
    // лист переключается асинхронно: сверяемся сразу и после монтирования редактора
    [0, 120, 600].forEach(function (ms) {
      setTimeout(syncTranscriptSheetView, ms);
    });
  }

  function renderNoteSheetChips() {
    var host = document.getElementById("note-editor-sheets");
    if (!host) return;
    scheduleTranscriptSheetSync();
    host.innerHTML = "";
    if (!noteSheetsEnabled()) {
      host.classList.add("hidden");
      return;
    }
    var transNote = resolveLocalNoteFromCache({ id: noteSheetsNoteId() });
    var isTrans = isTranscriptionNoteItem(transNote);
    if (isTrans) {
      host.classList.remove("hidden");
      noteSheetState.sheets.forEach(function (s) {
        var chip = document.createElement("button");
        chip.type = "button";
        chip.className =
          "note-sheet-chip" +
          (isWebSheet(s) ? " is-web" : "") +
          (isBoardSheet(s) ? " is-board" : "") +
          (String(s.id) === String(noteSheetState.leftId) ? " is-active" : "");
        var label = document.createElement("span");
        label.className = "note-sheet-chip-label";
        label.textContent = s.title || "Лист";
        chip.appendChild(label);
        chip.addEventListener("click", function (e) {
          e.preventDefault();
          switchLeftSheet(s.id);
        });
        host.appendChild(chip);
      });
      if (!transcriptionHasSummary(transNote) && !transcriptionIsGenerating(transNote)) {
        var makeBtn = document.createElement("button");
        makeBtn.type = "button";
        makeBtn.className = "note-sheet-chip note-sheet-chip--make-summary";
        makeBtn.textContent = "Сделать саммари";
        makeBtn.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          requestTranscriptionSummary();
        });
        host.appendChild(makeBtn);
      }
      var spMap = transcriptionSpeakerMap(transNote);
      var spDetected = !!(transNote && transNote.meta && transNote.meta.speakers_detected);
      if (spMap || spDetected) {
        var spBtn = document.createElement("button");
        spBtn.type = "button";
        spBtn.className = "note-sheet-chip note-sheet-chip--speakers";
        var spOpen = spMap
          ? Object.keys(spMap).filter(function (k) { return !(spMap[k] && spMap[k].confirmed); }).length
          : 0;
        spBtn.textContent = "🗣 Кто есть кто" + (spOpen ? " · " + spOpen : "");
        if (spOpen || !spMap) spBtn.classList.add("is-todo");
        spBtn.setAttribute("aria-haspopup", "dialog");
        spBtn.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          openSpeakerMapMenu(spBtn, noteSheetsNoteId());
        });
        host.appendChild(spBtn);
      }
      if (transcriptSheetActive(transNote) && transcriptHasSpeakers(transNote)) {
        var seg = document.createElement("div");
        seg.className = "note-transcript-view-switch";
        seg.setAttribute("role", "group");
        seg.setAttribute("aria-label", "Вид транскрипта");
        [["text", "Текст"], ["dialog", "Диалог"]].forEach(function (pair) {
          var b = document.createElement("button");
          b.type = "button";
          b.className = "note-sheet-chip" + (transcriptViewMode() === pair[0] ? " is-active" : "");
          b.setAttribute("aria-pressed", transcriptViewMode() === pair[0] ? "true" : "false");
          b.textContent = pair[1];
          b.addEventListener("click", function (e) {
            e.preventDefault();
            e.stopPropagation();
            if (transcriptViewMode() !== pair[0]) setTranscriptViewMode(pair[0]);
          });
          seg.appendChild(b);
        });
        host.appendChild(seg);
      }
      return;
    }
    var extras = extraNoteSheets();
    var showBar = extras.length > 0;
    host.classList.toggle("hidden", !showBar && extras.length === 0);
    if (!showBar) {
      var quiet = document.createElement("button");
      quiet.type = "button";
      quiet.className = "note-sheet-chip note-sheet-chip--add";
      quiet.textContent = "＋";
      quiet.setAttribute("aria-label", "Новый лист, доска или презентация");
      quiet.setAttribute("aria-haspopup", "menu");
      quiet.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        openNewSheetKindMenu(quiet, { openOn: "left" });
      });
      host.appendChild(quiet);
      host.classList.remove("hidden");
      return;
    }
    noteSheetState.sheets.forEach(function (s) {
      var chip = document.createElement("button");
      chip.type = "button";
      chip.className =
        "note-sheet-chip" +
        (isWebSheet(s) ? " is-web" : "") +
        (isBoardSheet(s) ? " is-board" : "") +
        (String(s.id) === String(noteSheetState.leftId) ? " is-active" : "");
      chip.setAttribute("data-sheet-id", String(s.id));
      var label = document.createElement("span");
      label.className = "note-sheet-chip-label";
      label.textContent = s.title || "Лист";
      chip.appendChild(label);
      if (shareLinkForSheet(s.id)) {
        var shareIco = document.createElement("span");
        shareIco.className = "note-sheet-chip-share";
        shareIco.setAttribute("role", "button");
        shareIco.setAttribute("aria-label", "Лист опубликован по ссылке");
        shareIco.title = "Опубликован по ссылке";
        shareIco.innerHTML = SHARE_TAB_ICON;
        shareIco.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          openSheetShareMenu(shareIco, s);
        });
        chip.appendChild(shareIco);
        chip.classList.add("is-shared");
      }
      chip.addEventListener("click", function (e) {
        e.preventDefault();
        if (String(s.id) === String(noteSheetState.leftId) && !(s.is_primary && noteSheetState.primaryLocked)) {
          startNoteSheetRename(chip, s);
          return;
        }
        switchLeftSheet(s.id);
      });
      host.appendChild(chip);
    });
    attachSheetTabsDrag(host);
    var add = document.createElement("button");
    add.type = "button";
    add.className = "note-sheet-chip note-sheet-chip--add";
    add.textContent = "+";
    add.setAttribute("aria-label", "Новый лист, доска или презентация");
    add.setAttribute("aria-haspopup", "menu");
    add.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      openNewSheetKindMenu(add, { openOn: "left" });
    });
    host.appendChild(add);
  }

  var transcriptionSummaryPollTimer = null;

  function confirmYesNoDialog(message) {
    return new Promise(function (resolve) {
      var existing = document.getElementById("leo-prompt-overlay");
      if (existing && existing.parentNode) existing.parentNode.removeChild(existing);
      var ov = document.createElement("div");
      ov.id = "leo-prompt-overlay";
      ov.className = "leo-prompt-overlay";
      ov.innerHTML =
        '<div class="leo-prompt-sheet" role="dialog" aria-modal="true">' +
        '<p class="leo-prompt-message"></p>' +
        '<div class="leo-prompt-actions">' +
        '<button type="button" class="btn-text leo-prompt-cancel">Нет</button>' +
        '<button type="button" class="btn leo-prompt-ok">Да</button>' +
        "</div></div>";
      var msg = ov.querySelector(".leo-prompt-message");
      if (msg) msg.textContent = String(message || "");
      function finish(ok) {
        if (ov.parentNode) ov.parentNode.removeChild(ov);
        document.removeEventListener("keydown", onKey, true);
        resolve(!!ok);
      }
      function onKey(e) {
        if (e.key === "Escape") {
          e.preventDefault();
          finish(false);
        }
        if (e.key === "Enter") {
          e.preventDefault();
          finish(true);
        }
      }
      ov.querySelector(".leo-prompt-cancel").addEventListener("click", function () {
        finish(false);
      });
      ov.querySelector(".leo-prompt-ok").addEventListener("click", function () {
        finish(true);
      });
      ov.addEventListener("click", function (e) {
        if (e.target === ov) finish(false);
      });
      document.addEventListener("keydown", onKey, true);
      document.body.appendChild(ov);
    });
  }

  function noteSheetSkeletonHtml() {
    return (
      '<div class="note-sheet-skeleton" aria-hidden="true" aria-busy="true">' +
      '<div class="note-sheet-skeleton-row" style="width:74%"></div>' +
      '<div class="note-sheet-skeleton-row note-sheet-skeleton-row--tall" style="width:88%"></div>' +
      '<div class="note-sheet-skeleton-row" style="width:62%"></div>' +
      '<div class="note-sheet-skeleton-row note-sheet-skeleton-row--tall" style="width:80%"></div>' +
      '<div class="note-sheet-skeleton-row" style="width:70%"></div>' +
      "</div>"
    );
  }

  function stopTranscriptionSummaryPoll() {
    if (transcriptionSummaryPollTimer) {
      clearTimeout(transcriptionSummaryPollTimer);
      transcriptionSummaryPollTimer = null;
    }
  }

  function pollTranscriptionSummary(noteId) {
    stopTranscriptionSummaryPoll();
    var id = String(noteId || "");
    if (!id) return;
    transcriptionSummaryPollTimer = setTimeout(function () {
      apiFetch("/notes/local/" + encodeURIComponent(id), { method: "GET" })
        .then(function (res) {
          var item = res && res.item;
          if (!item) return;
          prependTranscriptionInCache(item);
          if (transcriptionIsGenerating(item)) {
            pollTranscriptionSummary(id);
            return;
          }
          if (noteSheetsNoteId() === id) {
            openNoteDetail(item, { isLocal: true });
          } else if (notesDataCache) {
            renderNotesPanesFromData(notesDataCache);
          }
        })
        .catch(function () {
          pollTranscriptionSummary(id);
        });
    }, 1600);
  }

  async function requestTranscriptionSummary() {
    var ok = await confirmYesNoDialog(
      "У этого файла еще нет саммари. Хотите его сделать?"
    );
    if (!ok) return;
    var noteId = noteSheetsNoteId();
    if (!noteId) return;
    try {
      var res = await apiFetch(
        "/notes/local/" + encodeURIComponent(String(noteId)) + "/make-summary",
        { method: "POST" }
      );
      var item = res && res.item;
      if (item) {
        prependTranscriptionInCache(item);
        openNoteDetail(item, { isLocal: true });
        pollTranscriptionSummary(noteId);
      }
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  // Основной лист переименовывается так же (PATCH sheets/main); текст его — в самой заметке.
  async function persistPrimarySheetTitle(title) {
    var noteId = noteSheetsNoteId();
    if (!noteId || String(noteId).indexOf("tmp_") === 0) throw new Error("Сначала сохраните заметку");
    var res = await apiFetch("/notes/local/" + encodeURIComponent(String(noteId)) + "/sheets/main", {
      method: "PATCH",
      body: JSON.stringify({ title: title }),
    });
    // Название листа меняет версию заметки — иначе следующее сохранение текста упрётся в «изменена другим».
    var item = res && res.item;
    var moreWrap = document.getElementById("note-editor-more-wrap");
    if (moreWrap && item) {
      if (item.revision) moreWrap._noteRevision = item.revision;
      if (res.note_updated_at) moreWrap._noteUpdatedAt = res.note_updated_at;
    }
    var main = findNoteSheet(NOTE_SHEET_MAIN);
    if (main && item && item.revision) main.revision = item.revision;
    var cached = resolveLocalNoteFromCache({ id: noteId });
    if (cached) cached.primary_sheet_title = title;
  }

  function startNoteSheetRename(chip, sheet) {
    if (!chip || !sheet) return;
    var isPrimary = !!(sheet.is_primary || isPrimarySheetId(sheet.id));
    if (isPrimary && noteSheetState.primaryLocked) return;
    if (chip.classList.contains("is-editing")) return;
    var input = document.createElement("input");
    input.type = "text";
    input.className = "note-sheet-chip-input";
    input.maxLength = 80;
    input.value = sheet.title || "";
    chip.classList.add("is-editing");
    chip.innerHTML = "";
    chip.appendChild(input);
    function fitRenameInput() {
      var len = Math.max(String(input.value || "").length, 4);
      input.style.width = Math.min(280, Math.max(72, len * 12 + 8)) + "px";
    }
    fitRenameInput();
    input.addEventListener("input", fitRenameInput);
    var delBtn = document.createElement("span");
    delBtn.className = "note-sheet-chip-delete";
    delBtn.setAttribute("role", "button");
    delBtn.setAttribute("aria-label", "Удалить лист");
    delBtn.innerHTML =
      '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
      'stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
      '<polyline points="3 6 5 6 21 6"/>' +
      '<path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/>' +
      '<path d="M10 11v6M14 11v6"/>' +
      '<path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/>' +
      "</svg>";
    chip.appendChild(delBtn);
    input.focus();
    input.select();
    var done = false;
    function finish(ok) {
      if (done) return;
      done = true;
      var prevTitle = String(sheet.title || "");
      var next = String(input.value || "").trim() || prevTitle;
      if (next.length > 80) next = next.slice(0, 80).trim() || prevTitle;
      // Вкладка держит объект листа с момента отрисовки, а сохранение (у доски — частое)
      // подменяет его в noteSheetState — имя пишем в текущий объект, иначе уйдёт старое.
      var live = findNoteSheet(sheet.id);
      if (live && live !== sheet) prevTitle = String(live.title || prevTitle);
      if (ok && next !== prevTitle) {
        sheet.title = next;
        if (live) live.title = next;
        if (noteSheetState.sheetTimers[String(sheet.id)]) {
          clearTimeout(noteSheetState.sheetTimers[String(sheet.id)]);
          delete noteSheetState.sheetTimers[String(sheet.id)];
        }
        (isPrimary ? persistPrimarySheetTitle(next) : persistExtraSheet(sheet.id))
          .then(function () {
            renderNoteSheetChips();
            renderNoteKnowledgeMenu();
            if (String(noteSheetState.rightId) === String(sheet.id)) syncNotePaneHeader();
          })
          .catch(function (e) {
            sheet.title = prevTitle;
            var cur = findNoteSheet(sheet.id);
            if (cur) cur.title = prevTitle;
            renderNoteSheetChips();
            renderNoteKnowledgeMenu();
            setNoteEditorSaveHint(e.message || "Не удалось сохранить название листа");
          });
        if (String(noteSheetState.rightId) === String(sheet.id)) syncNotePaneHeader();
      }
      renderNoteSheetChips();
      renderNoteKnowledgeMenu();
    }
    function guardDeletePointer(e) {
      e.preventDefault();
      e.stopPropagation();
    }
    delBtn.addEventListener("pointerdown", guardDeletePointer);
    delBtn.addEventListener("mousedown", guardDeletePointer);
    delBtn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      done = true;
      deleteNoteSheet(sheet);
    });
    input.addEventListener("blur", function () {
      finish(true);
    });
    input.addEventListener("keydown", function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        finish(true);
      }
      if (e.key === "Escape") {
        e.preventDefault();
        finish(false);
      }
    });
  }

  // Основной лист: его место занимает следующий текстовый лист (сервер переносит текст и название).
  async function deletePrimaryNoteSheet(sheet) {
    var noteId = noteSheetsNoteId();
    if (!noteId || String(noteId).indexOf("tmp_") === 0 || noteSheetState.primaryLocked) {
      renderNoteSheetChips();
      return;
    }
    var next = noteSheetState.sheets.filter(function (s) {
      return s && !s.is_primary && !isPrimarySheetId(s.id) && !isWebSheet(s) && !isBoardSheet(s);
    })[0];
    if (!next) {
      renderNoteSheetChips();
      alert("Это единственный текстовый лист — его нельзя удалить. Можно удалить заметку целиком.");
      return;
    }
    var ok = await confirmYesNoDialog(
      "Удалить лист «" + (sheet.title || "Основная") + "»? Основным станет «" + (next.title || "Лист") + "»."
    );
    if (!ok) {
      renderNoteSheetChips();
      return;
    }
    try {
      var body = getNoteEditorBodyEl();
      if (body && typeof body._noteEditorFlush === "function") await body._noteEditorFlush();
      if (noteSheetState.sheetTimers[String(next.id)]) await persistExtraSheet(next.id);
      await apiFetch("/notes/local/" + encodeURIComponent(String(noteId)) + "/sheets/main", { method: "DELETE" });
      var res = await apiFetch("/notes/local/" + encodeURIComponent(String(noteId)), { method: "GET" });
      var item = res && res.item;
      if (item) openLocalNoteDetail(item, { isLocal: true, knowledge: isKnowledgeNoteItem(item) });
    } catch (e) {
      alert((e && e.message) || String(e));
      renderNoteSheetChips();
    }
  }

  async function deleteNoteSheet(sheet) {
    if (!sheet) return;
    if (sheet.is_primary || isPrimarySheetId(sheet.id)) return deletePrimaryNoteSheet(sheet);
    var id = String(sheet.id);
    var noteId = noteSheetsNoteId();
    if (!id || !noteId) return;
    var ok = await confirmYesNoDialog(
      "Удалить лист «" + (sheet.title || "Лист") + "»?"
    );
    if (!ok) {
      renderNoteSheetChips();
      return;
    }
    if (noteSheetState.sheetTimers[id]) {
      clearTimeout(noteSheetState.sheetTimers[id]);
      delete noteSheetState.sheetTimers[id];
    }
    delete noteSheetState.sheetPersists[id];
    var wasLeft = String(noteSheetState.leftId) === id;
    var wasRight =
      noteSheetState.rightMode === "sheet" && String(noteSheetState.rightId) === id;
    noteSheetState.sheets = noteSheetState.sheets.filter(function (s) {
      return String(s.id) !== id;
    });
    if (noteSheetState.leftScroll) delete noteSheetState.leftScroll[id];
    if (Array.isArray(noteSheetState.contextIds)) {
      noteSheetState.contextIds = noteSheetState.contextIds.filter(function (x) {
        return String(x) !== id;
      });
    }
    if (wasRight) setRightPaneMode("discussion");
    if (wasLeft) await switchLeftSheet(NOTE_SHEET_MAIN);
    else renderNoteSheetChips();
    renderNoteKnowledgeMenu();
    previewOpenNoteFromSheets();
    if (isAppOffline() || String(noteId).indexOf("tmp_") === 0) {
      enqueueOfflineOp({
        type: "sheet_delete",
        clientId: id,
        noteId: String(noteId),
        path:
          "/notes/local/" +
          encodeURIComponent(String(noteId)) +
          "/sheets/" +
          encodeURIComponent(id),
        method: "DELETE",
      });
      showOfflineSavedToast();
      return;
    }
    try {
      await apiFetch(
        "/notes/local/" +
          encodeURIComponent(String(noteId)) +
          "/sheets/" +
          encodeURIComponent(id),
        { method: "DELETE" }
      );
    } catch (e) {
      alert(e.message || String(e));
      var note = resolveLocalNoteFromCache({ id: noteId });
      hydrateNoteSheets(note, noteSheetState.primaryBody);
    }
  }

  async function ensureNoteIdForSheets() {
    var id = noteSheetsNoteId();
    if (id && String(id).indexOf("tmp_") !== 0) return id;
    var body = getNoteEditorBodyEl();
    if (body && typeof body._noteEditorFlush === "function") {
      await body._noteEditorFlush();
    }
    return noteSheetsNoteId();
  }

  // Карта «Спикер N → человек» из саммари v2 (assistant/lib/summary_normalize.py).
  function transcriptionSpeakerMap(item) {
    var meta = item && item.meta;
    var map = meta && meta.speaker_map;
    if (!map || typeof map !== "object") return null;
    var labels = Object.keys(map).filter(function (k) { return /^Спикер \d+$/.test(k); });
    if (!labels.length) return null;
    var out = {};
    labels.sort(function (a, b) { return parseInt(a.slice(7), 10) - parseInt(b.slice(7), 10); });
    labels.forEach(function (k) { out[k] = map[k] || {}; });
    return out;
  }

  function closeSpeakerMapMenu() {
    var menu = document.getElementById("note-speaker-map-menu");
    if (menu && menu.parentNode) menu.parentNode.removeChild(menu);
    document.removeEventListener("click", onSpeakerMapMenuDocClick, true);
    document.removeEventListener("keydown", onSpeakerMapMenuKey, true);
  }

  function onSpeakerMapMenuDocClick(e) {
    var menu = document.getElementById("note-speaker-map-menu");
    if (!menu) return;
    if (e.target && menu.contains(e.target)) return;
    if (e.target && e.target.closest && e.target.closest(".note-sheet-chip--speakers, .ntd-name, .is-transcript-sheet p > strong:first-child")) return;
    closeSpeakerMapMenu();
  }

  function onSpeakerMapMenuKey(e) {
    if (e.key === "Escape") {
      e.preventDefault();
      closeSpeakerMapMenu();
    }
  }

  function speakerTalkLabel(sec) {
    var n = Number(sec || 0);
    if (n < 60) return n ? Math.max(1, Math.round(n)) + " с" : "";
    return Math.round(n / 60) + " мин";
  }

  // Имя, которым спикер подписан в транскрипте: подтверждённое имя или «Спикер N».
  function speakerShownName(sp) {
    return sp && sp.confirmed && sp.name ? sp.name : (sp && sp.label) || "";
  }

  function speakerInitials(name, label) {
    var parts = String(name || "").replace(/^@/, "").split(/\s+/).filter(Boolean);
    if (parts.length >= 2) return (parts[0].charAt(0) + parts[1].charAt(0)).toUpperCase();
    if (parts[0] && !/^Спикер$/i.test(parts[0])) return parts[0].slice(0, 2).toUpperCase();
    var m = /(\d+)\s*$/.exec(String(label || name || ""));
    return m ? m[1] : "?";
  }

  function speakerAvatarNode(name, email, label) {
    if (email) return meetingAttendeeAvatarNode({ name: name, email: email });
    var el = document.createElement("span");
    el.className = "note-member-avatar";
    var fb = document.createElement("span");
    fb.className = "note-member-avatar-fallback";
    fb.textContent = speakerInitials(name, label);
    el.appendChild(fb);
    return el;
  }

  // Строка «человек» в едином стиле подсказок участников (аватар, имя, пояснение).
  function speakerPersonRow(opts) {
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className =
      "meeting-attendee-suggest-item meeting-attendee-suggest-item--with-avatar note-speaker-person" +
      (opts.cls ? " " + opts.cls : "");
    if (opts.icon) {
      var ic = document.createElement("span");
      ic.className = "note-member-avatar note-speaker-icon";
      ic.textContent = opts.icon;
      btn.appendChild(ic);
    } else {
      btn.appendChild(speakerAvatarNode(opts.name, opts.email, opts.label));
    }
    var copy = document.createElement("span");
    copy.className = "meeting-attendee-suggest-copy";
    var nm = document.createElement("span");
    nm.className = "meeting-attendee-suggest-name";
    nm.textContent = opts.title;
    copy.appendChild(nm);
    if (opts.meta) {
      var meta = document.createElement("span");
      meta.className = "meeting-attendee-suggest-meta";
      meta.textContent = opts.meta;
      copy.appendChild(meta);
    }
    btn.appendChild(copy);
    if (opts.trail) {
      var tr = document.createElement("span");
      tr.className = "note-speaker-trail";
      tr.textContent = opts.trail;
      btn.appendChild(tr);
    }
    btn.addEventListener("mousedown", function (e) {
      e.preventDefault();
    });
    btn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      opts.onPick();
    });
    return btn;
  }

  function placeSpeakerMapMenu(menu, anchor) {
    if (window.innerWidth < 600) {
      menu.classList.add("is-sheet");
      menu.style.left = "";
      menu.style.top = "";
      return;
    }
    menu.classList.remove("is-sheet");
    var rect = anchor && anchor.getBoundingClientRect ? anchor.getBoundingClientRect() : null;
    var mw = menu.offsetWidth || 360;
    var left = rect ? rect.left : 16;
    var top = rect ? rect.bottom + 6 : 16;
    if (left + mw > window.innerWidth - 8) left = Math.max(8, window.innerWidth - mw - 8);
    if (top + menu.offsetHeight > window.innerHeight - 8) {
      top = Math.max(8, window.innerHeight - menu.offsetHeight - 8);
    }
    menu.style.left = Math.round(left) + "px";
    menu.style.top = Math.round(top) + "px";
  }

  function speakerMapReopen(item, toast) {
    closeSpeakerMapMenu();
    if (item) {
      prependTranscriptionInCache(item);
      openNoteDetail(item, { isLocal: true });
    }
    if (toast) showNoteToast(toast);
  }

  // «Кто есть кто»: список спикеров → выбор человека для одного из них.
  // focus — сразу выбор для спикера с таким label или подписью в транскрипте.
  function openSpeakerMapMenu(anchor, noteId, focus) {
    if (document.getElementById("note-speaker-map-menu")) {
      closeSpeakerMapMenu();
      if (!focus) return;
    }
    if (!noteId) return;
    var base = "/notes/local/" + encodeURIComponent(String(noteId)) + "/speakers";
    var menu = document.createElement("div");
    menu.id = "note-speaker-map-menu";
    menu.className = "note-speaker-pop";
    menu.setAttribute("role", "dialog");
    menu.setAttribute("aria-label", "Кто есть кто");
    var body = document.createElement("div");
    body.className = "note-speaker-pop-body";
    var loading = document.createElement("div");
    loading.className = "note-speaker-pop-hint";
    loading.textContent = "Загружаю спикеров…";
    body.appendChild(loading);
    menu.appendChild(body);
    var host =
      (anchor && anchor.closest && anchor.closest("#note-editor-overlay")) ||
      document.getElementById("note-editor-overlay") ||
      document.body;
    host.appendChild(menu);
    placeSpeakerMapMenu(menu, anchor);
    setTimeout(function () {
      document.addEventListener("click", onSpeakerMapMenuDocClick, true);
      document.addEventListener("keydown", onSpeakerMapMenuKey, true);
    }, 0);

    var view = null;

    function save(sp, name, isMe) {
      body.classList.add("is-busy");
      apiFetch(base, {
        method: "POST",
        body: JSON.stringify({ label: sp.label, name: String(name || "").trim(), is_me: !!isMe }),
      })
        .then(function (res) {
          var item = res && res.item;
          var parts = [];
          if (item && item.transcript_rerendered) parts.push("транскрипте");
          if (item && (item.summary_rerendered || item.summary_renamed)) parts.push("саммари");
          speakerMapReopen(
            item,
            !name
              ? "Имя убрано"
              : parts.length
              ? "«" + name + "» — в " + parts.join(" и ")
              : "Сохранено; текст правили вручную — его не трогаем"
          );
        })
        .catch(function (e) {
          body.classList.remove("is-busy");
          showNoteToast((e && e.message) || "Не удалось сохранить");
        });
    }

    function merge(sp, other) {
      body.classList.add("is-busy");
      apiFetch(base + "/merge", {
        method: "POST",
        body: JSON.stringify({ source: sp.label, target: other.label }),
      })
        .then(function (res) {
          speakerMapReopen(res && res.item, "Реплики «" + speakerShownName(sp) + "» теперь у «" + speakerShownName(other) + "»");
        })
        .catch(function (e) {
          body.classList.remove("is-busy");
          showNoteToast((e && e.message) || "Не удалось объединить");
        });
    }

    function head(title, onBack) {
      var bar = document.createElement("div");
      bar.className = "note-speaker-pop-head";
      if (onBack) {
        var back = document.createElement("button");
        back.type = "button";
        back.className = "focus-card-btn is-icon";
        back.setAttribute("aria-label", "Ко всем спикерам");
        back.textContent = "‹";
        back.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          onBack();
        });
        bar.appendChild(back);
      }
      var t = document.createElement("div");
      t.className = "note-speaker-pop-title";
      t.textContent = title;
      bar.appendChild(t);
      var close = document.createElement("button");
      close.type = "button";
      close.className = "focus-card-btn is-icon";
      close.setAttribute("aria-label", "Закрыть");
      close.textContent = "×";
      close.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        closeSpeakerMapMenu();
      });
      bar.appendChild(close);
      return bar;
    }

    function renderList() {
      body.innerHTML = "";
      body.appendChild(head("Кто есть кто"));
      var hint = document.createElement("div");
      hint.className = "note-speaker-pop-hint";
      hint.textContent =
        "Имя появится в транскрипте, в саммари и у исполнителей задач" +
        (view.guessing ? ". Лео ещё угадывает имена…" : "");
      body.appendChild(hint);
      var list = document.createElement("div");
      list.className = "note-speaker-list";
      view.speakers.forEach(function (sp) {
        var shown = speakerShownName(sp);
        var meta = [];
        if (sp.confirmed && sp.name) meta.push(sp.label);
        if (sp.talk_sec) meta.push(speakerTalkLabel(sp.talk_sec));
        if (sp.is_me) meta.push("это вы");
        else if (!sp.confirmed && sp.name) meta.push("Лео думает: " + sp.name);
        else if (!sp.confirmed) meta.push("не указан");
        var row = speakerPersonRow({
          name: sp.confirmed ? sp.name : "",
          label: sp.label,
          title: shown,
          meta: meta.join(" · "),
          trail: "›",
          cls: sp.confirmed ? "is-done" : "is-open",
          onPick: function () {
            renderPicker(sp, true);
          },
        });
        list.appendChild(row);
      });
      body.appendChild(list);
      placeSpeakerMapMenu(menu, anchor);
    }

    function renderPicker(sp, fromList) {
      body.innerHTML = "";
      var title = speakerShownName(sp) + (sp.talk_sec ? " · " + speakerTalkLabel(sp.talk_sec) : "");
      body.appendChild(head(title, fromList && view.speakers.length > 1 ? renderList : null));

      if (sp.samples && sp.samples.length) {
        var ul = document.createElement("ul");
        ul.className = "note-speaker-samples";
        sp.samples.forEach(function (q) {
          var li = document.createElement("li");
          if (q.t) {
            var t = document.createElement("span");
            t.className = "note-speaker-t";
            t.textContent = q.t;
            li.appendChild(t);
          }
          li.appendChild(document.createTextNode("«" + q.text + "»"));
          ul.appendChild(li);
        });
        body.appendChild(ul);
      }

      var form = document.createElement("div");
      form.className = "tinbox-form note-speaker-search";
      var input = document.createElement("input");
      input.type = "text";
      input.className = "field-input";
      input.maxLength = 80;
      input.autocomplete = "off";
      input.placeholder = "Найти участника или вписать имя";
      input.setAttribute("aria-label", "Кто это");
      form.appendChild(input);
      body.appendChild(form);

      var opts = document.createElement("div");
      opts.className = "note-speaker-list";
      body.appendChild(opts);

      var me = defaultTaskAssignee() || {};
      var others = view.speakers.filter(function (o) {
        return o.label !== sp.label;
      });

      function paint() {
        var q = String(input.value || "").trim();
        var ql = q.toLowerCase();
        opts.innerHTML = "";
        var shown = {};
        function add(row, key) {
          if (key) shown[key.toLowerCase()] = 1;
          opts.appendChild(row);
        }
        if (!q && sp.name && !sp.confirmed) {
          add(
            speakerPersonRow({
              name: sp.name,
              title: sp.name,
              meta: "Догадка Лео" + (sp.evidence ? ": " + sp.evidence : ""),
              trail: "Да",
              cls: "is-guess",
              onPick: function () {
                save(sp, sp.name, false);
              },
            }),
            sp.name
          );
        }
        if (me.name && (!ql || String(me.name).toLowerCase().indexOf(ql) >= 0 || "это я".indexOf(ql) >= 0)) {
          add(
            speakerPersonRow({
              name: me.name,
              email: me.email,
              title: "Это я",
              meta: sp.is_me ? "отмечено · ваши реплики справа в «Диалоге»" : "ваши реплики будут справа в «Диалоге»",
              cls: sp.is_me ? "is-active" : "",
              onPick: function () {
                save(sp, me.name, true);
              },
            }),
            me.name
          );
        }
        var n = 0;
        (view.candidates || []).forEach(function (c) {
          var nm = typeof c === "string" ? c : c.name;
          if (!nm || shown[nm.toLowerCase()] || n >= 8) return;
          var hay = (nm + " " + ((c && c.email) || "")).toLowerCase();
          if (ql && hay.indexOf(ql) < 0) return;
          n++;
          add(
            speakerPersonRow({
              name: nm,
              email: c && c.email,
              title: nm,
              meta: c && c.attendee ? "участник встречи" : sp.confirmed && sp.name === nm ? "сейчас" : "",
              cls: sp.confirmed && sp.name === nm ? "is-active" : "",
              onPick: function () {
                save(sp, nm, false);
              },
            }),
            nm
          );
        });
        if (q && !shown[ql]) {
          add(
            speakerPersonRow({
              icon: "+",
              title: "Добавить «" + q + "»",
              meta: "нового участника — нет в календаре и контактах",
              onPick: function () {
                save(sp, q, false);
              },
            })
          );
        }
        if (!q && sp.confirmed && sp.name) {
          add(
            speakerPersonRow({
              icon: "×",
              title: "Убрать имя",
              meta: "снова «" + sp.label + "»",
              cls: "is-quiet",
              onPick: function () {
                save(sp, "", false);
              },
            })
          );
        }
        if (!q && view.can_merge && others.length) {
          var mh = document.createElement("div");
          mh.className = "note-speaker-pop-section";
          mh.textContent = "Это тот же человек, что…";
          opts.appendChild(mh);
          others.forEach(function (o) {
            opts.appendChild(
              speakerPersonRow({
                name: o.confirmed ? o.name : "",
                label: o.label,
                title: speakerShownName(o),
                meta: (o.confirmed && o.name ? o.label + " · " : "") + "объединить реплики",
                cls: "is-merge",
                onPick: function () {
                  confirmMerge(o);
                },
              })
            );
          });
        }
        placeSpeakerMapMenu(menu, anchor);
      }

      function confirmMerge(o) {
        opts.innerHTML = "";
        var box = document.createElement("div");
        box.className = "note-speaker-confirm";
        var txt = document.createElement("div");
        txt.textContent =
          "Реплики «" + speakerShownName(sp) + "» станут репликами «" + speakerShownName(o) + "». Отменить будет нельзя.";
        box.appendChild(txt);
        var acts = document.createElement("div");
        acts.className = "note-speaker-confirm-actions";
        var no = document.createElement("button");
        no.type = "button";
        no.className = "focus-card-btn";
        no.textContent = "Отмена";
        no.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          paint();
        });
        var yes = document.createElement("button");
        yes.type = "button";
        yes.className = "focus-card-btn is-primary";
        yes.textContent = "Объединить";
        yes.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          merge(sp, o);
        });
        acts.appendChild(no);
        acts.appendChild(yes);
        box.appendChild(acts);
        opts.appendChild(box);
      }

      input.addEventListener("input", paint);
      input.addEventListener("keydown", function (e) {
        if (e.key === "Enter") {
          e.preventDefault();
          var q = String(input.value || "").trim();
          if (q) save(sp, q, false);
        }
      });
      paint();
      if (window.matchMedia && window.matchMedia("(hover: hover)").matches) input.focus();
    }

    refreshCalendarContacts()
      .catch(function () {})
      .then(function () {
        return apiFetch(base);
      })
      .then(function (v) {
        if (!menu.parentNode) return;
        view = v || {};
        view.speakers = view.speakers || [];
        if (!view.speakers.length) {
          body.innerHTML = "";
          body.appendChild(head("Кто есть кто"));
          var one = document.createElement("div");
          one.className = "note-speaker-pop-hint";
          one.textContent = "В этой записи один спикер";
          body.appendChild(one);
          return;
        }
        var target = null;
        if (focus) {
          view.speakers.forEach(function (sp) {
            if (!target && (sp.label === focus || speakerShownName(sp) === focus)) target = sp;
          });
        }
        if (target) renderPicker(target, true);
        else renderList();
      })
      .catch(function (e) {
        body.innerHTML = "";
        body.appendChild(head("Кто есть кто"));
        var err = document.createElement("div");
        err.className = "note-speaker-pop-hint";
        err.textContent = (e && e.message) || "Не удалось загрузить спикеров";
        body.appendChild(err);
      });
  }

  // ---- лист «Транскрипции»: клик по имени спикера и вид «Диалог» ----

  var TRANSCRIPT_VIEW_KEY = "leo.transcriptView";

  function transcriptViewMode() {
    try {
      return localStorage.getItem(TRANSCRIPT_VIEW_KEY) === "dialog" ? "dialog" : "text";
    } catch (e) {
      return "text";
    }
  }

  function setTranscriptViewMode(mode) {
    try {
      localStorage.setItem(TRANSCRIPT_VIEW_KEY, mode);
    } catch (e) {}
    renderNoteSheetChips();
  }

  function transcriptSheetActive(transNote) {
    if (!isTranscriptionNoteItem(transNote)) return false;
    var s = findNoteSheet(noteSheetState.leftId);
    if (!s) return false;
    var title = isPrimarySheetId(s.id) ? transNote.primary_sheet_title || s.title : s.title;
    return String(title || "").trim() === "Транскрипции";
  }

  function transcriptHasSpeakers(transNote) {
    var meta = (transNote && transNote.meta) || {};
    return !!(meta.speakers_detected || transcriptionSpeakerMap(transNote));
  }

  var transcriptSpeakerClicksBound = false;

  function bindTranscriptSpeakerClicks() {
    if (transcriptSpeakerClicksBound) return;
    transcriptSpeakerClicksBound = true;
    document.addEventListener("click", function (e) {
      var strong = e.target && e.target.closest && e.target.closest("#note-editor-overlay .is-transcript-sheet p > strong:first-child");
      if (!strong) return;
      var sel = window.getSelection && window.getSelection();
      if (sel && !sel.isCollapsed) return;
      var name = String(strong.textContent || "").trim();
      if (!name) return;
      openSpeakerMapMenu(strong, noteSheetsNoteId(), name);
    });
  }

  function syncTranscriptSheetView() {
    var pad = document.querySelector("#note-editor-overlay .note-editor-pad--body");
    if (!pad) return;
    var noteId = noteSheetsNoteId();
    var transNote = noteId ? resolveLocalNoteFromCache({ id: noteId }) : null;
    var active = !!noteId && transcriptSheetActive(transNote) && transcriptHasSpeakers(transNote);
    pad.classList.toggle("is-transcript-sheet", active);
    if (active) bindTranscriptSpeakerClicks();
    var dialog = active && transcriptViewMode() === "dialog";
    pad.classList.toggle("is-transcript-dialog", dialog);
    var box = pad.querySelector(":scope > .note-transcript-dialog");
    if (!dialog) {
      if (box) box.remove();
      return;
    }
    var stamp = String(noteId) + ":" + String((transNote && transNote.updated_at) || "");
    if (box && box.getAttribute("data-stamp") === stamp) return;
    if (box) box.remove();
    box = document.createElement("div");
    box.className = "note-transcript-dialog";
    box.setAttribute("data-stamp", stamp);
    var wait = document.createElement("div");
    wait.className = "note-speaker-pop-hint";
    wait.textContent = "Собираю диалог…";
    box.appendChild(wait);
    pad.insertBefore(box, pad.firstChild);
    apiFetch("/notes/local/" + encodeURIComponent(String(noteId)) + "/transcript/dialog")
      .then(function (d) {
        if (!box.parentNode) return;
        renderTranscriptDialog(box, d || {}, noteId);
      })
      .catch(function (e) {
        wait.textContent = (e && e.message) || "Не удалось собрать диалог";
      });
  }

  function renderTranscriptDialog(box, d, noteId) {
    box.innerHTML = "";
    var turns = d.turns || [];
    if (!turns.length) {
      var empty = document.createElement("div");
      empty.className = "note-speaker-pop-hint";
      empty.textContent = "Для этой записи нет реплик по спикерам — она сделана до разбивки на реплики.";
      box.appendChild(empty);
      return;
    }
    if (!d.has_me || d.edited) {
      var tip = document.createElement("div");
      tip.className = "note-transcript-dialog-tip";
      tip.textContent = !d.has_me
        ? "Отметьте себя: нажмите на своё имя → «Это я», и ваши реплики будут справа."
        : "Текст транскрипта правили вручную — здесь исходные реплики.";
      box.appendChild(tip);
    }
    var order = [];
    turns.forEach(function (t) {
      if (order.indexOf(t.label) < 0) order.push(t.label);
    });
    var prevLabel = null;
    turns.forEach(function (t) {
      var row = document.createElement("div");
      row.className = "ntd-row" + (t.me ? " is-me" : "") + (t.label === prevLabel ? " is-cont" : "");
      row.setAttribute("data-spk", String(order.indexOf(t.label) % 6));
      if (!t.me) {
        var av = speakerAvatarNode(t.name !== t.label ? t.name : "", "", t.label);
        av.classList.add("ntd-avatar");
        row.appendChild(av);
      }
      var bubble = document.createElement("div");
      bubble.className = "ntd-bubble";
      var meta = document.createElement("div");
      meta.className = "ntd-meta";
      var who = document.createElement("button");
      who.type = "button";
      who.className = "ntd-name";
      who.textContent = t.me ? "Вы" : t.name;
      who.title = "Кто это?";
      who.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        openSpeakerMapMenu(who, noteId, t.label);
      });
      meta.appendChild(who);
      if (t.t) {
        var ts = document.createElement("span");
        ts.className = "ntd-time";
        ts.textContent = t.t;
        meta.appendChild(ts);
      }
      bubble.appendChild(meta);
      (t.paras || []).forEach(function (p) {
        var para = document.createElement("p");
        para.textContent = p;
        bubble.appendChild(para);
      });
      row.appendChild(bubble);
      box.appendChild(row);
      prevLabel = t.label;
    });
  }

  function closeNewSheetKindMenu() {
    var menu = document.getElementById("note-sheet-kind-menu");
    if (menu && menu.parentNode) menu.parentNode.removeChild(menu);
    document.removeEventListener("click", onNewSheetKindMenuDocClick, true);
    document.removeEventListener("keydown", onNewSheetKindMenuKey, true);
  }

  function onNewSheetKindMenuDocClick(e) {
    var menu = document.getElementById("note-sheet-kind-menu");
    if (!menu) return;
    if (e.target && menu.contains(e.target)) return;
    if (e.target && e.target.closest && e.target.closest(".note-sheet-chip--add")) return;
    closeNewSheetKindMenu();
  }

  function onNewSheetKindMenuKey(e) {
    if (e.key === "Escape") {
      e.preventDefault();
      closeNewSheetKindMenu();
    }
  }

  function openNewSheetKindMenu(anchor, opts) {
    opts = opts || {};
    var existing = document.getElementById("note-sheet-kind-menu");
    if (existing) {
      closeNewSheetKindMenu();
      return;
    }
    var menu = document.createElement("div");
    menu.id = "note-sheet-kind-menu";
    menu.className = "note-sheet-kind-menu";
    menu.setAttribute("role", "menu");

    function addItem(label, hint, kind) {
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "note-sheet-kind-menu-item";
      btn.setAttribute("role", "menuitem");
      var titleEl = document.createElement("span");
      titleEl.className = "note-sheet-kind-menu-title";
      titleEl.textContent = label;
      var hintEl = document.createElement("span");
      hintEl.className = "note-sheet-kind-menu-hint";
      hintEl.textContent = hint;
      btn.appendChild(titleEl);
      btn.appendChild(hintEl);
      btn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        closeNewSheetKindMenu();
        createNoteSheet({ openOn: opts.openOn || "left", kind: kind });
      });
      menu.appendChild(btn);
    }

    addItem("Лист", "Текст и правки", "doc");
    addItem("Доска", "Схемы, блоки и стрелки", "board");
    addItem("Презентация", "Слайды по заметке", "web");
    // В body: панель обсуждения — отдельный слой (z-index 220) поверх окна заметки (100),
    // внутри окна заметки меню уходило под неё.
    document.body.appendChild(menu);

    var rect = anchor && anchor.getBoundingClientRect ? anchor.getBoundingClientRect() : null;
    var mw = menu.offsetWidth || 180;
    var left = rect ? rect.left : 16;
    var top = rect ? rect.bottom + 6 : 16;
    if (left + mw > window.innerWidth - 8) left = Math.max(8, window.innerWidth - mw - 8);
    if (top + menu.offsetHeight > window.innerHeight - 8) {
      top = rect ? Math.max(8, rect.top - menu.offsetHeight - 6) : 16;
    }
    menu.style.left = Math.round(left) + "px";
    menu.style.top = Math.round(top) + "px";

    setTimeout(function () {
      document.addEventListener("click", onNewSheetKindMenuDocClick, true);
      document.addEventListener("keydown", onNewSheetKindMenuKey, true);
    }, 0);
  }

  async function createNoteSheet(opts) {
    opts = opts || {};
    var noteId = await ensureNoteIdForSheets();
    if (!noteId) {
      showNoteToast("Сначала сохраните заметку");
      return;
    }
    var kindRaw = String(opts.kind || "doc").toLowerCase();
    var kind = kindRaw === "web" || kindRaw === "board" ? kindRaw : "doc";
    var title =
      opts.title ||
      (kind === "web"
        ? "Презентация"
        : kind === "board"
          ? "Доска"
          : "Лист " + (extraNoteSheets().length + 2));
    if (isAppOffline() || String(noteId).indexOf("tmp_") === 0) {
      var tmpId = newTempId("tmp_sheet_");
      var local = {
        id: tmpId,
        note_id: noteId,
        title: title,
        body: "",
        description: "",
        kind: kind,
        revision: 1,
        is_primary: false,
      };
      upsertNoteSheet(local);
      enqueueOfflineOp({
        type: "sheet_create",
        clientId: tmpId,
        noteId: String(noteId),
        path: "/notes/local/" + encodeURIComponent(String(noteId)) + "/sheets",
        method: "POST",
        body: { title: local.title, kind: kind },
      });
      renderNoteSheetChips();
      if (opts.openOn === "right") setRightPaneMode("sheet", tmpId);
      else switchLeftSheet(tmpId);
      showOfflineSavedToast();
      return;
    }
    try {
      var res = await apiFetch(
        "/notes/local/" + encodeURIComponent(String(noteId)) + "/sheets",
        { method: "POST", body: JSON.stringify({ title: title, kind: kind }) }
      );
      var item = res && res.item;
      if (!item) return;
      upsertNoteSheet(item);
      renderNoteSheetChips();
      renderNoteKnowledgeMenu();
      if (opts.openOn === "right") setRightPaneMode("sheet", item.id);
      else await switchLeftSheet(item.id);
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  function hydrateNoteSheets(note, primaryBody) {
    destroyLeftBoard();
    destroyRightBoard();
    destroyLeftWebCanvas();
    destroyRightWebCanvas();
    clearCanvasSelections();
    noteSheetState.enabled = !!note;
    // У встречи с саммари основной лист — «Саммари»: по названию сервер отличает саммари от расшифровки.
    noteSheetState.primaryLocked = !!(note && isTranscriptionNoteItem(note) && String(note.primary_sheet_title || "") === "Саммари");
    noteSheetState.primaryBody = primaryBody || (note && (note.body || note.description)) || "";
    noteSheetState.leftId = NOTE_SHEET_MAIN;
    noteSheetState.rightMode = "discussion";
    noteSheetState.rightId = "";
    noteSheetState.rightNote = null;
    noteSheetState.focus = "left";
    noteSheetState.contextExplicit = false;
    noteSheetState.contextIds = null;
    noteSheetState.sheets = [
      {
        id: NOTE_SHEET_MAIN,
        title: (note && note.primary_sheet_title) || "Основная",
        body: noteSheetState.primaryBody,
        description: noteSheetState.primaryBody,
        kind: "doc",
        revision: (note && note.revision) || 1,
        is_primary: true,
      },
    ];
    renderNoteSheetChips();
    syncNotePaneHeader();
    var noteId = note && note.id;
    if (!noteSheetsEnabled() || !noteId || String(noteId).indexOf("tmp_") === 0) return;
    var hydratedAt = Date.now();
    apiFetch("/notes/local/" + encodeURIComponent(String(noteId)) + "/sheets", {
      method: "GET",
    })
      .then(function (data) {
        if (noteSheetsNoteId() !== String(noteId)) return;
        var rows = (data && data.sheets) || [];
        if (rows.length) noteSheetState.sheets = rows;
        var main = findNoteSheet(NOTE_SHEET_MAIN);
        if (main) noteSheetState.primaryBody = main.body || main.description || noteSheetState.primaryBody;
        renderNoteSheetChips();
        syncNotePaneHeader();
        renderNoteKnowledgeMenu();
        var pending = String(noteSheetState.pendingOpenSheetId || "");
        noteSheetState.pendingOpenSheetId = "";
        if (pending && findNoteSheet(pending)) switchLeftSheet(pending);
        else if (
          rows.length &&
          !isPrimarySheetId(rows[0].id) &&
          !rows[0].is_primary &&
          isPrimarySheetId(noteSheetState.leftId) &&
          !(noteCollabState.lastTypedAt > hydratedAt)
        ) {
          // Вкладки переставлены — открываем ту, что пользователь поставил первой.
          switchLeftSheet(String(rows[0].id));
        }
        loadNoteShareLinks(); // иконки шеринга на вкладках
      })
      .catch(function () {
        noteSheetState.pendingOpenSheetId = "";
      });
  }

  function bindNotePaneSwitchOnce() {
    var btn = document.getElementById("note-discussion-title");
    if (!btn || btn._sheetBound) return;
    btn._sheetBound = true;
    btn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      // В обсуждении стрелка у названия — список чатов; на листе — переключатель листов.
      if (document.documentElement.classList.contains("actual-assistant-open")) toggleActualChatsMenu();
      else if (noteSheetState.rightMode === "discussion" && noteChatsEnabled()) toggleNoteChatsMenu();
      else toggleNotePaneSwitchMenu();
    });
    document.addEventListener("click", function (e) {
      var wrap = document.querySelector(".note-pane-switch-wrap");
      if (wrap && e.target && wrap.contains(e.target)) return;
      closeNotePaneSwitchMenu();
    });
  }

  function bindNoteDiscussionOverlayOnce() {
    var ov = document.getElementById("note-discussion-overlay");
    if (!ov || ov._bound) return ov;
    ov._bound = true;
    bindNotePaneSwitchOnce();
    bindDiscussClarifyOnce();
    var closeBtn = document.getElementById("note-discussion-close");
    if (closeBtn) {
      closeBtn.addEventListener("click", function (e) {
        e.preventDefault();
        closeNoteDiscussion();
      });
    }
    var newCtxBtn = document.getElementById("note-discussion-new-ctx");
    if (newCtxBtn && !newCtxBtn._bound) {
      newCtxBtn._bound = true;
      newCtxBtn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        if (noteChatsEnabled()) toggleNotePaneSwitchMenu({ fromRight: true });
        else clearGptDiscussionContext();
      });
      document.addEventListener("click", function (e) {
        var menu = document.getElementById("note-chats-menu");
        if (!menu || menu.classList.contains("hidden")) return;
        if (menu.contains(e.target) || newCtxBtn.contains(e.target)) return;
        if (e.target && e.target.id === "note-chats-backdrop") return;
        closeNoteChatsMenu();
      });
    }
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && isNoteDiscussionOpen()) {
        var chatsMenu = document.getElementById("note-chats-menu");
        if (chatsMenu && !chatsMenu.classList.contains("hidden")) {
          closeNoteChatsMenu();
          e.preventDefault();
          return;
        }
        if (document.getElementById("discuss-media-viewer")) {
          closeDiscussMediaViewer();
          e.preventDefault();
          return;
        }
        if (document.getElementById("note-link-overlay") &&
            !document.getElementById("note-link-overlay").classList.contains("hidden")) {
          return;
        }
        // Esc закрывает открытое меню, а не всё обсуждение.
        var paneMenu = document.getElementById("note-pane-switch-menu");
        if (paneMenu && !paneMenu.classList.contains("hidden")) {
          closeNotePaneSwitchMenu();
          e.preventDefault();
          return;
        }
        if (document.querySelector("#note-paie-reply-form .note-paie-menu:not(.hidden), #note-paie-plus-menu:not(.hidden)")) {
          closeNoteComposerMenus();
          e.preventDefault();
          return;
        }
        if (document.querySelector(".note-discuss-menu:not(.hidden)")) {
          closeNoteAnswerMenu();
          e.preventDefault();
          return;
        }
        if (noteDict && noteDict.target === "composer") {
          cancelNoteDictation();
          e.preventDefault();
          return;
        }
        closeNoteDiscussion();
      }
    });
    if (window.matchMedia) {
      var desk = window.matchMedia("(min-width: 960px)");
      var onDesk = function (e) {
        applyNotePaneWidths();
        if (e.matches) syncDesktopNoteDiscussion();
        else if (isNoteDiscussionOpen()) closeNoteDiscussion(true);
        loadActual();
      };
      if (desk.addEventListener) desk.addEventListener("change", onDesk);
      else if (desk.addListener) desk.addListener(onDesk);
    }
    document.addEventListener(
      "touchmove",
      function (e) {
        if (!isNoteDiscussionOpen() || isDesktopLayout()) return;
        var t = e.target;
        if (!t || !t.closest) {
          e.preventDefault();
          return;
        }
        if (!t.closest("#note-discussion-overlay")) {
          e.preventDefault();
          return;
        }
        if (
          t.closest(
            ".note-discussion-scroll, .notes-project-chips, .note-paie-plus-notes, .note-paie-plus-menu, .note-pane-switch-menu, .note-paie-menu, textarea, input, .note-paie-composer-editor, [contenteditable='true']"
          )
        ) {
          return;
        }
        e.preventDefault();
      },
      { passive: false }
    );
    ov.addEventListener("focusin", function () {
      if (isNoteDiscussionOpen()) updateDiscussionOverlayForKeyboard();
    });
    return ov;
  }

  function syncNoteDiscussionOpenClass() {
    var open = isNoteDiscussionOpen();
    if (open && document.documentElement.classList.contains("notes-split")) {
      setNotesSplitMode("full");
      syncNotesSplitLayout();
    }
    document.documentElement.classList.toggle("note-discussion-open", open);
    requestAnimationFrame(positionAiEditBar);
    syncNoteDiscussBadge();
    var sheet = document.querySelector("#note-discussion-overlay .note-discussion-sheet");
    if (sheet) {
      sheet.setAttribute("aria-modal", open && isDesktopLayout() ? "false" : "true");
    }
    applyNotePaneWidths();
  }

  function shouldKeepNoteDiscussionOpen() {
    var wrap = document.getElementById("note-editor-more-wrap");
    return (
      !noteHistory &&
      isDesktopLayout() &&
      isNoteEditorModalOpen() &&
      !document.documentElement.classList.contains("notes-split") &&
      wrap &&
      wrap._shareKind &&
      wrap._shareId &&
      !wrap._discussionDismissed
    );
  }

  function syncDesktopNoteDiscussion() {
    if (!shouldKeepNoteDiscussionOpen()) return;
    if (isNoteDiscussionOpen()) {
      syncNoteDiscussionOpenClass();
      return;
    }
    openNoteDiscussion({ fromDesktopSync: true, focus: false });
  }

  function closeNoteDiscussion(force) {
    closeNoteChatsMenu();
    stopDiscussionLiveUpdates();
    leaveDiscussPresence();
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!force && isDesktopLayout() && isNoteEditorModalOpen() && wrap) {
      wrap._discussionDismissed = true;
    }
    var ov = document.getElementById("note-discussion-overlay");
    if (ov) {
      ov.classList.add("hidden");
      ov.setAttribute("aria-hidden", "true");
    }
    closeNoteAnswerMenu();
    closeNoteComposerMenus();
    hideDiscussClarify();
    resetDiscussionOverlayViewport();
    if (noteSheetState.rightMode === "note") {
      flushRightForeignNoteBeforeLeave();
      noteSheetState.rightMode = "discussion";
      noteSheetState.rightId = "";
      noteSheetState.rightNote = null;
      destroyRightSheetEditor();
      setNoteSheetFocus("left");
    } else {
      flushSheetEditor("right").catch(function () {});
      if (noteSheetState.rightMode === "sheet") {
        noteSheetState.rightMode = "discussion";
        noteSheetState.rightId = "";
        destroyRightSheetEditor();
        setNoteSheetFocus("left");
      }
    }
    closeNotePaneSwitchMenu();
    syncNotePaneHeader();
    syncNoteDiscussionOpenClass();
    syncAppOverlay();
    syncTelegramNativeBack();
    updateNoteDiscussionCardUnread();
    if (isNoteEditorModalOpen()) updateModalSheetForKeyboard();
    if (notesSubTab === "chats") {
      activeChatThreadId = "";
      restoreDiscussionOverlayHost();
      document.documentElement.classList.remove("chats-split-open");
      clearChatShareWrap();
      renderChatThreadsList();
      if (!leavingChatsTab && isDesktopLayout()) {
        ensureDesktopChatComposer();
      } else {
        var empty = document.getElementById("chat-thread-empty");
        if (empty) setHidden(empty, false);
      }
    }
    if (document.documentElement.classList.contains("actual-assistant-open")) {
      // Чат с Ассистентом с экрана «Актуальное»: закрыли — освобождаем панель.
      // Закрыл сам пользователь — забываем; ушли на другую вкладку — откроем снова при возврате.
      if (!actualAssistantSuspending) rememberActualAssistantChat("");
      document.documentElement.classList.remove("actual-assistant-open");
      activeChatThreadId = "";
      clearChatShareWrap();
      pruneEmptyChatDrafts("");
    }
    syncChatDiscussionChrome();
  }

  // «+» на «Актуальном» → «Ассистент»: чат с ИИ в панели справа (на телефоне — на весь экран).
  var ACTUAL_ASSISTANT_LS = "leo_actual_assistant_chat";
  var actualAssistantSuspending = false;
  var actualAssistantRestoring = false;

  function rememberActualAssistantChat(id) {
    try {
      if (id) localStorage.setItem(ACTUAL_ASSISTANT_LS, String(id));
      else localStorage.removeItem(ACTUAL_ASSISTANT_LS);
    } catch (_) {}
  }

  function rememberedActualAssistantChat() {
    try {
      return localStorage.getItem(ACTUAL_ASSISTANT_LS) || "";
    } catch (_) {
      return "";
    }
  }

  // Открытый (и не закрытый) чат с Ассистентом снова на месте при возврате на «Актуальное».
  async function restoreActualAssistant(attempt) {
    attempt = attempt || 0;
    if (currentTab !== "actual" || actualAssistantRestoring) return;
    if (document.documentElement.classList.contains("actual-assistant-open") && isNoteDiscussionOpen()) return;
    if (isNoteEditorModalOpen()) return;
    var id = rememberedActualAssistantChat();
    if (!id) return;
    actualAssistantRestoring = true;
    try {
      if (!(chatThreadsCache || []).length) await loadChatThreads();
      var thread = (chatThreadsCache || []).filter(function (t) {
        return String(t.id) === String(id);
      })[0];
      if (!thread) {
        // Список чатов ещё грузится (или сеть) — пробуем позже; забываем, только если чата точно нет.
        if ((chatThreadsLoading || !(chatThreadsCache || []).length) && attempt < 8) {
          window.setTimeout(function () {
            restoreActualAssistant(attempt + 1);
          }, 600);
        } else {
          // Был открыт пустой черновик (его убрали при уходе с экрана) — открываем новый чат.
          rememberActualAssistantChat("");
          actualAssistantRestoring = false;
          await openActualAssistant();
        }
        return;
      }
      await openActualAssistant(thread);
    } finally {
      actualAssistantRestoring = false;
    }
  }

  function closeActualChatsMenu() {
    closeNoteChatsMenu();
  }

  function toggleActualChatsMenu() {
    var els = noteChatsDrawerEls();
    var menu = els.menu;
    if (!menu) return;
    if (menu.classList.contains("is-open")) {
      closeNoteChatsMenu();
      return;
    }
    clearTimeout(menu._hideTimer);
    renderActualChatsMenu();
    menu.classList.add("is-dropdown");
    els.backdrop.classList.add("is-dropdown");
    menu.classList.remove("hidden");
    els.backdrop.classList.remove("hidden");
    placeNoteChatsDropdown(menu);
    requestAnimationFrame(function () {
      menu.classList.add("is-open");
      els.backdrop.classList.add("is-open");
    });
    var titleBtn = document.getElementById("note-discussion-title");
    if (titleBtn) {
      titleBtn.classList.add("is-open");
      titleBtn.setAttribute("aria-expanded", "true");
    }
    loadChatThreads()
      .then(function () {
        if (!menu.classList.contains("hidden")) renderActualChatsMenu();
      })
      .catch(function () {});
  }

  function renderActualChatsMenu() {
    var menu = document.getElementById("note-chats-menu");
    if (!menu) return;
    menu.innerHTML = "";
    var head = document.createElement("div");
    head.className = "note-chats-head";
    var headTitle = document.createElement("h2");
    headTitle.className = "note-chats-head-title";
    headTitle.textContent = "Чаты с Ассистентом";
    var closeBtn = document.createElement("button");
    closeBtn.type = "button";
    closeBtn.className = "modal-header-btn note-chats-close";
    closeBtn.setAttribute("aria-label", "Закрыть");
    closeBtn.innerHTML =
      '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M18 6 6 18M6 6l12 12"/></svg>';
    closeBtn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      closeNoteChatsMenu();
    });
    head.appendChild(headTitle);
    head.appendChild(closeBtn);
    menu.appendChild(head);
    var group = document.createElement("div");
    group.className = "note-chats-group";
    var sec = document.createElement("section");
    sec.className = "note-chats-section";
    sec.appendChild(group);
    menu.appendChild(sec);
    function row(label, meta, icon, active, onClick) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "note-pane-switch-item note-chats-item" + (active ? " is-active" : "");
      b.setAttribute("role", "menuitem");
      if (active) b.setAttribute("aria-current", "true");
      b.innerHTML = '<span class="note-chats-item-icon">' + icon + "</span>";
      var text = document.createElement("span");
      text.className = "note-chats-item-text";
      var title = document.createElement("span");
      title.className = "note-chats-item-title";
      title.textContent = label;
      text.appendChild(title);
      if (meta) {
        var m = document.createElement("span");
        m.className = "note-chats-item-meta";
        m.textContent = meta;
        text.appendChild(m);
      }
      b.appendChild(text);
      b.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        closeNoteChatsMenu();
        onClick();
      });
      group.appendChild(b);
    }
    row("Новый чат", "", DISCUSS_ICONS.plus, false, function () {
      openActualAssistant();
    });
    actualChatThreads()
      .slice(0, 30)
      .forEach(function (t) {
        var meta = formatNotesCardDate(t.updated_at || t.created_at);
        row(String(t.title || "Новый чат"), meta, DISCUSS_ICONS.spark, String(t.id) === String(activeChatThreadId), function () {
          openActualAssistant(t);
        });
      });
  }

  async function openActualAssistant(thread, opts) {
    opts = opts || {};
    // Панель «Фокус» только после кнопки «Все» на Актуальном, не при каждом открытии чата.
    if (!opts.keepFocusPanel) focusPanelOpen = false;
    document.documentElement.classList.add("actual-assistant-open");
    try {
      if (thread && thread.id != null) await openChatThread(thread);
      else await createAndOpenChatThread({ origin: "actual" });
    } catch (e) {
      document.documentElement.classList.remove("actual-assistant-open");
      showNoteToast((e && e.message) || "Не удалось открыть Ассистента");
      return;
    }
    if (!isNoteDiscussionOpen()) {
      document.documentElement.classList.remove("actual-assistant-open");
      return;
    }
    rememberActualAssistantChat(activeChatThreadId);
    syncChatDiscussionChrome();
    syncChatDiscussionTitle((document.getElementById("note-discussion-title-label") || {}).textContent || "Чат");
    renderFocusPanel();
    refreshLeoMemoryStatus();
    var ed = noteGptEditor();
    if (ed && !isMobileNoteLayout()) {
      try {
        ed.focus();
      } catch (_) {}
    }
  }

  function highlightDiscussionMessage(id) {
    document.querySelectorAll("#note-discussion-messages .note-discuss-msg.is-topic").forEach(function (n) {
      n.classList.remove("is-topic");
    });
    if (!id) return;
    var el = document.querySelector(
      '#note-discussion-messages [data-comment-id="' + String(id) + '"]'
    );
    if (el) el.classList.add("is-topic");
  }

  function scrollDiscussionToComment(id) {
    if (!id) return;
    var el = document.querySelector(
      '#note-discussion-messages [data-comment-id="' + String(id) + '"]'
    );
    var scroll = document.querySelector("#note-discussion-overlay .note-discussion-scroll");
    if (!el || !scroll) return;
    var er = el.getBoundingClientRect();
    var sr = scroll.getBoundingClientRect();
    scroll.scrollTop += er.top - sr.top - 16;
    highlightDiscussionMessage(id);
  }

  function scrollNoteToQuote(comment) {
    if (!comment || !String(comment.quote || "").trim()) return;
    var api = window.NoteComments;
    var root = noteEditorCommentRoot();
    if (!api || !api.rangeForAnchor || !root) return;
    var range = api.rangeForAnchor(root, comment.quote, comment.prefix, comment.suffix);
    if (!range) return;
    var node = range.startContainer;
    var el = node && (node.nodeType === 1 ? node : node.parentElement);
    if (el && el.scrollIntoView) {
      el.scrollIntoView({ block: "center", behavior: "smooth" });
    }
  }

  function revealNoteDiscussionTopic(comment, opts) {
    opts = opts || {};
    if (!comment) return;
    var panel = document.getElementById("note-editor-comments");
    var comments = (panel && panel._allComments) || [];
    var api = window.NoteComments;
    var rootC = comment;
    if (api && api.topicRoot) rootC = api.topicRoot(comments, comment.id) || comment;
    if (panel && rootC && rootC.id) panel._activeCommentId = rootC.id;
    var wrap = document.getElementById("note-editor-more-wrap");
    paintEditorCommentOverlay(comments, rootC && rootC.id);
    if (opts.fromDiscussion) {
      if (wrap) wrap._discussionPinId = null;
      highlightDiscussionMessage(comment && comment.id);
      scrollNoteToQuote(rootC || comment);
      if (!isDesktopLayout()) closeNoteDiscussion(true);
      return;
    }
    if (wrap) wrap._discussionPinId = rootC && rootC.id;
    openNoteDiscussion({
      focus: false,
      scrollToId: rootC && rootC.id,
    });
  }

  function ruMessageCount(n) {
    var num = Number(n) || 0;
    var n10 = num % 10;
    var n100 = num % 100;
    if (n10 === 1 && n100 !== 11) return num + " сообщение";
    if (n10 >= 2 && n10 <= 4 && (n100 < 12 || n100 > 14)) return num + " сообщения";
    return num + " сообщений";
  }

  function discussionComments(comments) {
    return (comments || []).filter(function (c) {
      return c && c.id;
    });
  }

  function renderNoteDiscussionCard(comments) {
    syncNoteDiscussBadge();
    var col = document.querySelector("#note-editor-modal-body .note-editor-main-column");
    var card = document.getElementById("note-discussion-card");
    var rows = discussionComments(comments);
    if (!col || !rows.length) {
      if (card && card.parentNode) card.parentNode.removeChild(card);
      return;
    }
    if (!card) {
      card = document.createElement("button");
      card.type = "button";
      card.id = "note-discussion-card";
      card.className = "note-discussion-card";
      card.innerHTML =
        '<div><p class="note-discussion-card-title">Обсуждение</p>' +
        '<p class="note-discussion-card-meta"></p></div>' +
        '<span class="note-discussion-card-chevron" aria-hidden="true">›</span>';
      card.addEventListener("click", function (e) {
        e.preventDefault();
        openNoteDiscussion();
      });
      card.addEventListener("touchend", function (e) {
        e.preventDefault();
        openNoteDiscussion();
      });
      col.appendChild(card);
    }
    var meta = card.querySelector(".note-discussion-card-meta");
    if (meta) meta.textContent = ruMessageCount(rows.length);
    updateNoteDiscussionCardUnread();
  }

  function updateNoteDiscussionCardUnread() {
    syncNoteDiscussBadge();
    var card = document.getElementById("note-discussion-card");
    if (!card) return;
    var wrap = document.getElementById("note-editor-more-wrap");
    var on = !!(
      wrap &&
      noteHasDiscussUnread(wrap._shareKind, wrap._shareId) &&
      !isNoteDiscussionOpen()
    );
    card.classList.toggle("has-discuss-unread", on);
  }

  function openNoteDiscussion(opts) {
    // Кнопка «вниз» — при каждом открытии (лента могла быть нарисована, пока обсуждение было закрыто).
    setTimeout(function () {
      if (isNoteDiscussionOpen()) ensureDiscussScrollDownBtn();
    }, 400);
    opts = opts || {};
    if (noteHistory) {
      if (opts.fromDesktopSync) return;
      noteHistory.hadDiscussion = false;
      closeNoteHistory();
    }
    // Список + заметка: обсуждение само не открываем — только по «💬» (тогда заметка разворачивается).
    if (opts.fromDesktopSync && document.documentElement.classList.contains("notes-split")) return;
    bindNoteDiscussionOverlayOnce();
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap || !wrap._shareKind || !wrap._shareId) return;
    var panel = document.getElementById("note-editor-comments");
    var maxId = maxCommentId((panel && panel._allComments) || []);
    if (maxId) markDiscussSeenUpTo(wrap._shareKind, wrap._shareId, maxId);
    else clearDiscussUnread(wrap._shareKind, wrap._shareId);
    ensureNotePaieThread();
    var draftQuote = opts.draft ? String(opts.draft.quote || "").trim() : "";
    var mode = opts.mode;
    if (draftQuote && !mode) {
      mode = noteAskUsesChips(noteAskMode()) ? noteAskMode() : "gpt";
    }
    syncNoteChatsButton();
    if (currentDiscussChatId() !== null && mode) {
      // Комментарий к тексту — в общие «Комментарии», вопрос ИИ — в чат с ИИ.
      if (mode === "comment" && opts.draft) setCurrentDiscussChat(COMMENTS_CHAT_ID, { keepAsk: true });
      else if (mode !== "comment" && isCommentsChatActive()) {
        var lastAi = ((wrap._noteChats || []).filter(function (c) {
          return Number(c.id) > 0;
        })[0] || { id: 0 }).id;
        setCurrentDiscussChat(Number(lastAi), { keepAsk: true });
      }
    }
    if (mode) setNoteAskMode(mode);
    else if (!opts.fromDesktopSync && !opts.draft) setNoteAskMode(noteAskMode() || "gpt");

    var useChips = !!(draftQuote && noteAskUsesChips(noteAskMode()));
    if (draftQuote && !useChips) {
      wrap._commentDraft = {
        quote: draftQuote,
        prefix: opts.draft.prefix || "",
        suffix: opts.draft.suffix || "",
      };
      wrap._commentChairId = opts.chairId || null;
    } else if (useChips || opts.draft) {
      wrap._commentDraft = null;
      wrap._commentChairId = null;
    }
    if (opts.scrollToId) wrap._discussionPinId = opts.scrollToId;
    else if (!opts.fromDesktopSync) wrap._discussionPinId = null;
    if (!opts.fromDesktopSync) wrap._discussionDismissed = false;
    syncNoteComposerCommentTarget();
    var ov = document.getElementById("note-discussion-overlay");
    if (ov) {
      ov.classList.remove("hidden");
      ov.setAttribute("aria-hidden", "false");
    }
    renderNotePaieThread(
      (panel && panel._allComments) || [],
      wrap._shareKind,
      wrap._shareId
    );
    if (useChips) insertGptQuoteChip(draftQuote);
    var input = document.getElementById("note-paie-reply-input");
    var editor = noteGptEditor();
    var focusEl = noteAskUsesComposerEditor(noteAskMode()) ? editor : input;
    var shouldFocus =
      opts.focus === true ||
      (!!opts.draft && !isDesktopLayout() && opts.focus !== false);
    if (focusEl && shouldFocus) {
      try {
        focusEl.focus();
      } catch (_) {}
    }
    var pinId = wrap._discussionPinId || opts.scrollToId;
    if (pinId) {
      scrollDiscussionToComment(pinId);
    } else if (!opts.fromDesktopSync) {
      var scroll = document.querySelector("#note-discussion-overlay .note-discussion-scroll");
      if (scroll) scroll.scrollTop = scroll.scrollHeight;
    }
    if (!opts.keepSheet && (opts.mode || opts.draft || !opts.fromDesktopSync)) {
      if (noteSheetState.rightMode === "sheet") setRightPaneMode("discussion");
    }
    syncNotePaneHeader();
    syncNoteDiscussionOpenClass();
    syncAppOverlay();
    syncTelegramNativeBack();
    syncNoteFormatToolbarForComposer();
    updateModalSheetForKeyboard();
    syncChatDiscussionChrome();
    renderNoteAskModes();
    startDiscussionLiveUpdates();
    startDiscussPresence();
  }

  var discussionLiveTimer = null;
  var discussionLiveInflight = false;
  var discussionLiveLastAt = 0;
  var discussionLiveAgain = false; // сигнал пришёл во время запроса — повторить после него
  var DISCUSSION_LIVE_MS = 2500;
  var DISCUSSION_LIVE_SOCKET_MS = 20000; // при живом сокете — только страховочный опрос
  var discussPresenceTimer = null;

  function discussPresencePath() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap || !wrap._shareKind || !wrap._shareId) return "";
    if (wrap._shareKind !== "local" && wrap._shareKind !== "chat") return "";
    return (
      "/notes/" +
      encodeURIComponent(wrap._shareKind) +
      "/" +
      encodeURIComponent(wrap._shareId) +
      "/discuss-presence"
    );
  }

  function tickDiscussPresence() {
    if (!isNoteDiscussionOpen()) {
      leaveDiscussPresence();
      return;
    }
    var path = discussPresencePath();
    if (!path) return;
    apiFetch(path, { method: "POST", body: "{}" }).catch(function () {});
  }

  function startDiscussPresence() {
    if (!isNoteDiscussionOpen() || !discussPresencePath()) return;
    tickDiscussPresence();
    if (discussPresenceTimer) return;
    discussPresenceTimer = setInterval(tickDiscussPresence, 8000);
  }

  function leaveDiscussPresence() {
    if (discussPresenceTimer) {
      clearInterval(discussPresenceTimer);
      discussPresenceTimer = null;
    }
    var path = discussPresencePath();
    if (!path) return;
    apiFetch(path, { method: "DELETE" }).catch(function () {});
  }

  function stopDiscussionLiveUpdates() {
    if (discussionLiveTimer) {
      clearTimeout(discussionLiveTimer);
      discussionLiveTimer = null;
    }
  }

  function startDiscussionLiveUpdates() {
    stopDiscussionLiveUpdates();
    if (!isNoteDiscussionOpen()) return;
    discussionLiveTimer = setTimeout(tickDiscussionLiveUpdates, DISCUSSION_LIVE_MS);
  }

  function kickDiscussionLiveUpdates(noteId) {
    if (!isNoteDiscussionOpen()) return;
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap || wrap._shareKind !== "local" || String(wrap._shareId) !== String(noteId)) return;
    stopDiscussionLiveUpdates();
    tickDiscussionLiveUpdates(true);
  }

  function tickDiscussionLiveUpdates(force) {
    discussionLiveTimer = null;
    if (!isNoteDiscussionOpen()) return;
    if (document.hidden) {
      startDiscussionLiveUpdates();
      return;
    }
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap || !wrap._shareKind || !wrap._shareId) return;
    if (
      force !== true &&
      wrap._shareKind === "local" &&
      realtimeLive(wrap._shareId) &&
      Date.now() - discussionLiveLastAt < DISCUSSION_LIVE_SOCKET_MS
    ) {
      startDiscussionLiveUpdates();
      return;
    }
    // Не перетирать оптимистичное сообщение и локальный pending во время своей отправки.
    if (document.getElementById("note-discuss-optimistic-user")) {
      startDiscussionLiveUpdates();
      return;
    }
    if (discussionLiveInflight) {
      if (force === true) discussionLiveAgain = true;
      startDiscussionLiveUpdates();
      return;
    }
    discussionLiveInflight = true;
    discussionLiveLastAt = Date.now();
    refreshNoteCommentsList()
      .catch(function () {})
      .finally(function () {
        discussionLiveInflight = false;
        if (!isNoteDiscussionOpen()) return;
        if (discussionLiveAgain) {
          discussionLiveAgain = false;
          stopDiscussionLiveUpdates();
          tickDiscussionLiveUpdates(true);
          return;
        }
        startDiscussionLiveUpdates();
      });
  }

  function ensureNotePaieThread() {
    bindNoteDiscussionOverlayOnce();
    var el = document.getElementById("note-paie-thread");
    if (!el) return null;
    bindNotePaieReplyForm(el);
    setNoteAskMode(noteAskMode());
    return el;
  }

  function clipReplyQuote(text) {
    var raw = String(text || "").replace(/\s+/g, " ").trim();
    if (!raw) return "";
    if (raw.length > 160) return raw.slice(0, 159) + "…";
    return raw;
  }

  function chairReplyDraft(groupEl, draft) {
    if (draft && String(draft.quote || "").trim()) {
      return {
        quote: clipReplyQuote(draft.quote),
        prefix: draft.prefix || "",
        suffix: draft.suffix || "",
      };
    }
    var bodyEl =
      groupEl && groupEl.querySelector
        ? groupEl.querySelector(".note-paie-msg.is-chair .note-comment-body")
        : null;
    var quote = clipReplyQuote(bodyEl && bodyEl.textContent);
    if (!quote) quote = "Ответ CHAIR";
    return { quote: quote, prefix: "", suffix: "" };
  }

  function openChairReply(groupEl, draft) {
    if (!groupEl) return;
    var wrap = document.getElementById("note-editor-more-wrap");
    var chairId = parseInt(groupEl.getAttribute("data-chair-id") || "", 10);
    openNoteDiscussion({
      mode: "paie",
      chairId: chairId || null,
      draft: chairReplyDraft(groupEl, draft),
    });
  }

  function ensureNoteComposerReplyTarget(form) {
    if (!form) return null;
    var el = form.querySelector(".note-paie-reply-target");
    if (el) return el;
    var old = form.querySelector(".note-paie-reply-quote");
    el = document.createElement("div");
    el.className = "note-paie-reply-target hidden";
    el.innerHTML =
      '<span class="note-paie-reply-target-bar" aria-hidden="true"></span>' +
      '<div class="note-paie-reply-target-copy">' +
      '<p class="note-paie-reply-target-who">CHAIR</p>' +
      '<p class="note-paie-reply-target-quote"></p>' +
      "</div>" +
      '<button type="button" class="note-paie-reply-target-clear" aria-label="Отменить ответ">&times;</button>';
    var ta = form.querySelector("#note-paie-reply-input");
    if (old && old.parentNode) old.parentNode.replaceChild(el, old);
    else if (ta) form.insertBefore(el, ta);
    else form.insertBefore(el, form.firstChild);
    var clear = el.querySelector(".note-paie-reply-target-clear");
    if (clear && !clear._bound) {
      clear._bound = true;
      clear.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        clearNoteComposerCommentTarget();
        var input = document.getElementById("note-paie-reply-input");
        if (input) {
          input.placeholder = noteAskPlaceholder(noteAskMode());
          try {
            input.focus();
          } catch (_) {}
        }
      });
    }
    return el;
  }

  function syncNoteComposerCommentTarget() {
    var wrap = document.getElementById("note-editor-more-wrap");
    var form = document.getElementById("note-paie-reply-form");
    var targetEl = ensureNoteComposerReplyTarget(form);
    var quoteEl = targetEl && targetEl.querySelector(".note-paie-reply-target-quote");
    var draft = wrap && wrap._commentDraft;
    var chairId = wrap && wrap._commentChairId;
    var whoEl = targetEl && targetEl.querySelector(".note-paie-reply-target-who");
    var quote = draft && String(draft.quote || "").trim();
    var active = !!quote && !noteAskUsesChips(noteAskMode());
    if (whoEl) {
      if (noteAskMode() === "paie" && chairId) whoEl.textContent = "CHAIR";
      else if (chairId) whoEl.textContent = "Ответ";
      else whoEl.textContent = "Фрагмент";
    }
    if (form) form.classList.toggle("is-replying", active);
    if (targetEl) targetEl.classList.toggle("hidden", !active);
    if (quoteEl) quoteEl.textContent = clipReplyQuote(quote) || "";
    document.querySelectorAll(".note-paie-group").forEach(function (group) {
      var id = parseInt(group.getAttribute("data-chair-id") || "", 10);
      group.classList.toggle("is-reply-target", active && id === chairId);
    });
    var input = document.getElementById("note-paie-reply-input");
    if (input && active) {
      if (noteAskMode() === "comment") {
        input.placeholder = "Комментарий к ответу CHAIR";
      } else if (noteAskMode() === "paie") {
        input.placeholder = "Уточнение к этому ответу CHAIR";
      }
    } else if (input) {
      input.placeholder = noteAskPlaceholder(noteAskMode());
    }
  }

  function clearNoteComposerCommentTarget() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap) {
      wrap._commentChairId = null;
      wrap._commentDraft = null;
      wrap._commentReplyWho = null;
    }
    syncNoteComposerCommentTarget();
  }

  function isAssistantComment(c) {
    var api = window.NoteComments;
    if (!c) return false;
    if (api && api.isPaieComment && api.isPaieComment(c)) return true;
    if (api && api.isGptComment && api.isGptComment(c)) return true;
    if (api && api.isResearchComment && api.isResearchComment(c)) return true;
    if (api && api.isAgentTurn && api.isAgentTurn(c)) return true;
    if (c.is_paie || c.is_gpt || c.is_research || c.is_agent) return true;
    return false;
  }

  function isMineDiscussionComment(c) {
    if (!c || isAssistantComment(c)) return false;
    if (c.is_mine === true) return true;
    if (c.is_mine === false) return false;
    var me = currentTelegramUserId();
    var author = String(c.author_user_id || "").trim();
    return !!(me && author && me === author);
  }

  function discussionAuthorLabel(c) {
    if (isAssistantComment(c)) return shareCommentAuthorLabel(c);
    if (isMineDiscussionComment(c)) return "Вы";
    var name = String((c && c.author_name) || "").trim();
    if (name) return name;
    var uname = String((c && c.author_username) || "").trim();
    if (uname) return "@" + uname;
    return "Пользователь";
  }

  function closeNoteAnswerMenu() {
    document.querySelectorAll(".note-discuss-msg.is-pressed").forEach(function (m) {
      m.classList.remove("is-pressed");
    });
    document.querySelectorAll(".note-discuss-menu").forEach(function (menu) {
      menu.classList.add("hidden");
      menu.classList.remove("is-placed");
      menu.classList.remove("is-sheet");
      menu.style.top = "";
      menu.style.left = "";
      menu.style.right = "";
      menu.style.bottom = "";
    });
    document.querySelectorAll(".note-discuss-more").forEach(function (btn) {
      btn.setAttribute("aria-expanded", "false");
    });
  }

  function positionDiscussAnswerMenu(btn, menu) {
    if (!btn || !menu) return;
    menu.classList.add("is-placed");
    menu.style.top = "0px";
    menu.style.left = "0px";
    menu.style.right = "auto";
    menu.style.bottom = "auto";
    var btnRect = btn.getBoundingClientRect();
    var menuRect = menu.getBoundingClientRect();
    var mw = menuRect.width || 220;
    var mh = menuRect.height || 200;
    var pad = 8;
    var header = document.querySelector("#note-discussion-overlay .note-discussion-header");
    var headerBottom = header ? header.getBoundingClientRect().bottom : 0;
    var topMin = Math.max(pad, headerBottom + 4);
    var vh = window.innerHeight || document.documentElement.clientHeight || 0;
    var vw = window.innerWidth || document.documentElement.clientWidth || 0;
    var spaceAbove = btnRect.top - topMin;
    var spaceBelow = vh - pad - btnRect.bottom;
    var top;
    if (spaceAbove >= mh + 6 || spaceAbove >= spaceBelow) {
      top = btnRect.top - mh - 6;
    } else {
      top = btnRect.bottom + 6;
    }
    if (top < topMin) top = topMin;
    if (top + mh > vh - pad) top = Math.max(topMin, vh - pad - mh);
    var left = btnRect.left;
    var msg = btn.closest && btn.closest(".note-discuss-msg");
    if (msg && msg.classList.contains("is-user")) {
      left = btnRect.right - mw;
    }
    if (left < pad) left = pad;
    if (left + mw > vw - pad) left = Math.max(pad, vw - pad - mw);
    menu.style.top = Math.round(top) + "px";
    menu.style.left = Math.round(left) + "px";
  }

  function discussionCommentById(id) {
    var want = Number(id) || 0;
    if (!want) return null;
    var panel = document.getElementById("note-editor-comments");
    var rows = (panel && panel._allComments) || [];
    for (var i = 0; i < rows.length; i++) {
      if (Number(rows[i] && rows[i].id) === want) return rows[i];
    }
    return null;
  }

  function discussReplyWhoLabel(comment) {
    var parent = discussionCommentById(comment && comment.parent_id);
    if (parent) return discussionAuthorLabel(parent);
    return "Фрагмент";
  }

  function discussionCommentReplyDraft(comment) {
    if (!comment) return null;
    var quote = discussDisplayBody(
      String(comment.body || ""),
      String(comment.quote || "").trim()
    );
    quote = String(quote || "").replace(/\s+/g, " ").trim();
    if (!quote) return null;
    var api = window.NoteComments;
    var source = "reply";
    if (api && api.isResearchComment && api.isResearchComment(comment)) source = "research";
    else if (api && api.isGptComment && api.isGptComment(comment)) source = "gpt";
    else if (isAssistantComment(comment)) source = "paie";
    return {
      quote: quote,
      prefix: "",
      suffix: "",
      source: source,
      commentId: parseInt(comment.id, 10) || 0,
      replyWho: discussionAuthorLabel(comment),
    };
  }

  function showNoteToast(text, opts) {
    opts = opts || {};
    var el = document.getElementById("note-toast");
    if (!el) return;
    el.innerHTML = "";
    if (opts.node) {
      el.appendChild(opts.node);
    } else {
      el.textContent = String(text || "");
    }
    el.classList.toggle("note-toast--action", !!opts.actionable);
    el.classList.remove("hidden");
    if (el._timer) window.clearTimeout(el._timer);
    el._timer = window.setTimeout(function () {
      el.classList.add("hidden");
      el.classList.remove("note-toast--action");
    }, opts.duration || (opts.actionable ? 5600 : 2400));
  }

  function noteAgentSessionKey(kind, itemId) {
    return String(kind || "") + ":" + String(itemId || "");
  }

  function discussUnreadStorageKey(kind, itemId) {
    return "leo_discuss_unread:" + String(kind || "") + ":" + String(itemId || "");
  }

  function discussSeenStorageKey(kind, itemId) {
    return "leo_discuss_seen:" + String(kind || "") + ":" + String(itemId || "");
  }

  function noteHasDiscussUnread(kind, itemId) {
    if (!kind || itemId == null || itemId === "") return false;
    try {
      return localStorage.getItem(discussUnreadStorageKey(kind, itemId)) === "1";
    } catch (_) {
      return false;
    }
  }

  function setDiscussUnread(kind, itemId, on) {
    if (!kind || itemId == null || itemId === "") return;
    try {
      var key = discussUnreadStorageKey(kind, itemId);
      if (on) localStorage.setItem(key, "1");
      else localStorage.removeItem(key);
    } catch (_) {}
    updateNoteDiscussionCardUnread();
  }

  function clearDiscussUnread(kind, itemId) {
    if (!noteHasDiscussUnread(kind, itemId)) return;
    setDiscussUnread(kind, itemId, false);
    refreshDiscussUnreadUi();
  }

  function getDiscussSeenId(kind, itemId) {
    try {
      return parseInt(localStorage.getItem(discussSeenStorageKey(kind, itemId)) || "0", 10) || 0;
    } catch (_) {
      return 0;
    }
  }

  function hasDiscussSeenBaseline(kind, itemId) {
    try {
      return localStorage.getItem(discussSeenStorageKey(kind, itemId)) != null;
    } catch (_) {
      return false;
    }
  }

  function markDiscussSeenUpTo(kind, itemId, commentId) {
    if (!kind || itemId == null || itemId === "") return;
    var id = parseInt(commentId, 10) || 0;
    if (!id) return;
    var prev = getDiscussSeenId(kind, itemId);
    if (id > prev) {
      try {
        localStorage.setItem(discussSeenStorageKey(kind, itemId), String(id));
      } catch (_) {}
    } else if (!hasDiscussSeenBaseline(kind, itemId)) {
      try {
        localStorage.setItem(discussSeenStorageKey(kind, itemId), String(id));
      } catch (_) {}
    }
    if (noteHasDiscussUnread(kind, itemId)) {
      setDiscussUnread(kind, itemId, false);
      refreshDiscussUnreadUi();
    } else {
      updateNoteDiscussionCardUnread();
    }
  }

  function maxCommentId(comments) {
    var max = 0;
    (comments || []).forEach(function (c) {
      var id = parseInt(c && c.id, 10) || 0;
      if (id > max) max = id;
    });
    return max;
  }

  function syncDiscussUnreadFromLatest(kind, itemId, latest) {
    if (!kind || itemId == null || itemId === "") return;
    if (!latest || latest.id == null) return;
    var latestId = parseInt(latest.id, 10) || 0;
    if (!latestId) return;
    if (isViewingNoteDiscussion(kind, itemId)) {
      markDiscussSeenUpTo(kind, itemId, latestId);
      return;
    }
    if (!hasDiscussSeenBaseline(kind, itemId)) {
      try {
        localStorage.setItem(discussSeenStorageKey(kind, itemId), String(latestId));
      } catch (_) {}
      return;
    }
    var seen = getDiscussSeenId(kind, itemId);
    if (latestId <= seen) {
      if (noteHasDiscussUnread(kind, itemId)) setDiscussUnread(kind, itemId, false);
      return;
    }
    var me = currentTelegramUserId();
    var mine =
      !!me &&
      String(latest.author_user_id || "") === String(me) &&
      !latest.is_assistant;
    if (mine) {
      try {
        localStorage.setItem(discussSeenStorageKey(kind, itemId), String(latestId));
      } catch (_) {}
      if (noteHasDiscussUnread(kind, itemId)) setDiscussUnread(kind, itemId, false);
      return;
    }
    setDiscussUnread(kind, itemId, true);
    playDiscussNotifySound();
  }

  function syncDiscussUnreadFromNoteRow(kind, row) {
    if (!row) return;
    var id = row.id != null ? row.id : localNoteIdFrom(row);
    syncDiscussUnreadFromLatest(kind, id, row.discuss_latest);
  }

  function isViewingNoteDiscussion(kind, itemId) {
    return isNoteDiscussionOpen() && isDiscussionTargetActive(kind, itemId);
  }

  function noteTitleForDiscussToast(kind, itemId, fallback) {
    var id = String(itemId || "");
    if (kind === "chat") {
      for (var c = 0; c < (chatThreadsCache || []).length; c++) {
        if (String(chatThreadsCache[c].id) === id) {
          return String(chatThreadsCache[c].title || "чате");
        }
      }
      return fallback || "чате";
    }
    function fromList(list) {
      for (var i = 0; i < (list || []).length; i++) {
        if (String(list[i].id) === id) {
          return (
            sanitizeNoteTitle(list[i].title || list[i].content || list[i].main_topic || "") ||
            String(list[i].title || list[i].content || list[i].main_topic || "")
          );
        }
      }
      return "";
    }
    var title = "";
    if (kind === "digest") {
      try {
        title = getNoteEditorTitle().trim();
      } catch (_) {}
      return title || fallback || "дайджесте";
    }
    if (kind === "journal") {
      title =
        fromList(notesDataCache && notesDataCache.transcriptions) ||
        fromList(notesDataCache && notesDataCache.summaries) ||
        fromList(notesDataCache && notesDataCache.journal);
    } else {
      title =
        fromList(notesDataCache && notesDataCache.local_notes) ||
        fromList(knowledgeDataCache && knowledgeDataCache.notes);
    }
    if (!title) {
      try {
        title = getNoteEditorTitle().trim();
      } catch (_) {}
    }
    return title || fallback || "заметке";
  }

  function beginNoteAgentSession(kind, itemId, mode, title) {
    var key = noteAgentSessionKey(kind, itemId);
    noteAgentSessions[key] = {
      kind: String(kind || ""),
      itemId: String(itemId || ""),
      mode: mode || "gpt",
      title: String(title || ""),
      running: true,
    };
  }

  function endNoteAgentSession(kind, itemId) {
    delete noteAgentSessions[noteAgentSessionKey(kind, itemId)];
  }

  function parseNoteAgentPath(path) {
    var m = String(path || "").match(/^\/notes\/([^/]+)\/([^/]+)\/(paei|research)(?:\?|$)/);
    if (!m) return null;
    return {
      kind: decodeURIComponent(m[1]),
      itemId: decodeURIComponent(m[2]),
      mode: m[3] === "paei" ? "paie" : "research",
    };
  }

  function refreshDiscussUnreadUi() {
    if (notesDataCache) renderNotesPanesFromData(notesDataCache);
    if (knowledgeDataCache) renderKnowledgePaneFromData(knowledgeDataCache);
  }

  function mountDiscussUnreadBadge(parent, kind, itemId, solo) {
    if (!parent || !noteHasDiscussUnread(kind, itemId)) return;
    var dot = document.createElement("span");
    dot.className =
      "note-card-discuss-unread" + (solo ? " note-card-discuss-unread--solo" : "");
    dot.setAttribute("aria-label", "Новый ответ в обсуждении");
    dot.title = "Новый ответ в обсуждении";
    parent.appendChild(dot);
  }

  function openNoteDiscussionFromNotify(kind, itemId, mode) {
    clearDiscussUnread(kind, itemId);
    pendingDiscussOpen = {
      kind: String(kind || ""),
      itemId: String(itemId || ""),
      mode: mode || "gpt",
    };
    if (String(kind) === "journal") {
      openJournalEditorDetail({ id: itemId });
      return;
    }
    var kbNote = null;
    if (knowledgeDataCache && knowledgeDataCache.notes) {
      kbNote = knowledgeDataCache.notes.find(function (n) {
        return String(n.id) === String(itemId);
      });
    }
    if (kbNote) {
      openKnowledgeNoteDetail(kbNote);
      return;
    }
    openNoteDetail({ id: itemId }, { isLocal: true });
  }

  function consumePendingDiscussOpen(kind, itemId) {
    if (!pendingDiscussOpen) return;
    if (
      String(pendingDiscussOpen.kind) !== String(kind) ||
      String(pendingDiscussOpen.itemId) !== String(itemId)
    ) {
      return;
    }
    var mode = pendingDiscussOpen.mode || "gpt";
    pendingDiscussOpen = null;
    window.setTimeout(function () {
      openNoteDiscussion({ mode: mode, focus: true });
    }, 120);
  }

  function showDiscussReplyToast(kind, itemId, mode, title) {
    var node = document.createElement("span");
    node.className = "note-toast-copy";
    node.appendChild(document.createTextNode("Новый ответ в "));
    var link = document.createElement("button");
    link.type = "button";
    link.className = "note-toast-link";
    link.textContent = "обсуждении";
    if (title) link.title = String(title);
    link.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      var el = document.getElementById("note-toast");
      if (el) {
        el.classList.add("hidden");
        if (el._timer) window.clearTimeout(el._timer);
      }
      openNoteDiscussionFromNotify(kind, itemId, mode);
    });
    node.appendChild(link);
    showNoteToast("", { node: node, actionable: true, duration: 6500 });
  }

  var discussNotifySoundAt = 0;

  function playDiscussNotifySound() {
    var now = Date.now();
    if (now - discussNotifySoundAt < 1800) return;
    discussNotifySoundAt = now;
    try {
      if (
        discussionNotifyWebPushEnabled &&
        window.Notification &&
        Notification.permission === "granted"
      ) {
        return;
      }
    } catch (_) {}
    try {
      var Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      if (!window._discussAudioCtx) window._discussAudioCtx = new Ctx();
      var ctx = window._discussAudioCtx;
      if (ctx.state === "suspended") ctx.resume();
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.value = 880;
      gain.gain.setValueAtTime(0.0001, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.08, ctx.currentTime + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.18);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.2);
    } catch (_) {}
  }

  function notifyAgentReplyArrived(kind, itemId, mode, title) {
    endNoteAgentSession(kind, itemId);
    shareHaptic();
    if (isViewingNoteDiscussion(kind, itemId)) {
      refreshNoteCommentsList();
      return;
    }
    playDiscussNotifySound();
    var label = title || noteTitleForDiscussToast(kind, itemId, "");
    setDiscussUnread(kind, itemId, true);
    refreshDiscussUnreadUi();
    showDiscussReplyToast(kind, itemId, mode || "gpt", label);
  }

  function titleFromAnswerMarkdown(md) {
    var lines = String(md || "").split("\n");
    for (var i = 0; i < lines.length; i++) {
      var t = lines[i].trim();
      if (!t) continue;
      if (parseMarkdownTableRow(t)) continue;
      if (/^```/.test(t)) continue;
      var hm = t.match(/^#{1,6}\s+(.*)$/);
      if (hm) t = hm[1].trim();
      t = t
        .replace(/\*\*([^*]+)\*\*/g, "$1")
        .replace(/\*([^*]+)\*/g, "$1")
        .replace(/`([^`]+)`/g, "$1")
        .replace(/^[-*•]\s+/, "")
        .replace(/^\d+[.)]\s+/, "")
        .trim();
      if (!t) continue;
      if (t.length > 80) t = t.slice(0, 79) + "…";
      return t;
    }
    return "Заметка";
  }

  function titleFromAnswerHtml(html) {
    var tmp = document.createElement("div");
    tmp.innerHTML = String(html || "");
    var text = String(tmp.textContent || "")
      .replace(/\s+/g, " ")
      .trim();
    if (!text) return "Заметка";
    if (text.length > 80) text = text.slice(0, 79) + "…";
    return text;
  }

  /**
   * HTML of the current selection inside a rendered GPT bubble.
   * Preserves block structure (lists, headings, paragraphs) that plain quote collapse loses.
   */
  function htmlFromDiscussionSelectionRange(range) {
    if (!range || range.collapsed) return "";
    var div = document.createElement("div");
    try {
      div.appendChild(range.cloneContents());
    } catch (_) {
      return "";
    }
    // Drop discussion-only wrappers; keep table/scroll content.
    div.querySelectorAll(".note-table-scroll").forEach(function (wrap) {
      var parent = wrap.parentNode;
      if (!parent) return;
      while (wrap.firstChild) parent.insertBefore(wrap.firstChild, wrap);
      parent.removeChild(wrap);
    });
    var raw = String(div.innerHTML || "").trim();
    if (!raw) return "";
    var clean = sanitizeSummaryHtml(raw);
    if (!clean || !String(clean).trim()) return "";
    if (!/<(p|h[1-6]|ul|ol|li|blockquote|table|pre|div)\b/i.test(clean)) {
      clean = "<p>" + clean + "</p>";
    }
    return clean;
  }

  function htmlFromAnswerMarkdown(md) {
    var raw = String(md || "").trim();
    if (!raw) return "";
    var html = simpleMarkdownToHtml(raw);
    return html || "<p>" + escapeHtml(raw) + "</p>";
  }

  function appendAnswerHtmlToCurrentNote(html) {
    var clean = String(html || "").trim();
    if (!clean) return false;
    var activeSheet = findNoteSheet(focusedNoteSheetId() || noteSheetState.leftId);
    if (isWebSheet(activeSheet)) {
      showNoteToast("В презентацию вставляйте правки через обсуждение");
      return true;
    }
    if (isBoardSheet(activeSheet)) {
      showNoteToast("На доску ответ не вставляется — откройте текстовый лист");
      return true;
    }
    var inst = getActiveNoteRichEditor();
    if (inst && typeof inst.appendHtml === "function") {
      inst.appendHtml(clean);
      showNoteToast("Добавлено в заметку");
      shareHaptic();
      return true;
    }
    return false;
  }

  function appendAnswerToCurrentNote(text) {
    var raw = String(text || "").trim();
    if (!raw) return;
    var html = htmlFromAnswerMarkdown(raw);
    if (appendAnswerHtmlToCurrentNote(html)) return;
    var inst = getActiveNoteRichEditor();
    if (inst && typeof inst.appendText === "function") {
      inst.appendText(raw);
      showNoteToast("Добавлено в заметку");
      shareHaptic();
      return;
    }
    showNoteToast("Не удалось вставить в заметку");
  }

  async function createNoteFromAnswerHtml(html) {
    var clean = String(html || "").trim();
    if (!clean) return;
    var title = titleFromAnswerHtml(clean);
    var body = { title: title, description: clean, sync_todoist: false };
    try {
      if (isAppOffline()) {
        var tmpId = newTempId("tmp_note_");
        prependLocalInCache({ id: tmpId, title: title, description: clean, body: clean });
        if (notesDataCache) renderNotesPanesFromData(notesDataCache);
        enqueueOfflineOp({
          type: "note_create",
          clientId: tmpId,
          path: "/notes/local",
          method: "POST",
          body: body,
        });
        showOfflineSavedToast("Заметка создана офлайн");
        shareHaptic();
        return;
      }
      var createRes = await apiFetch("/notes/local", {
        method: "POST",
        body: JSON.stringify(body),
      });
      var created = (createRes && createRes.item) || { id: createRes && createRes.id, title: title };
      prependLocalInCache(created);
      if (notesDataCache) renderNotesPanesFromData(notesDataCache);
      showNoteToast("Заметка создана");
      shareHaptic();
    } catch (e) {
      if (isTransientApiError(e)) {
        var tmpId2 = newTempId("tmp_note_");
        prependLocalInCache({ id: tmpId2, title: title, description: clean, body: clean });
        if (notesDataCache) renderNotesPanesFromData(notesDataCache);
        enqueueOfflineOp({
          type: "note_create",
          clientId: tmpId2,
          path: "/notes/local",
          method: "POST",
          body: body,
        });
        showOfflineSavedToast("Заметка создана офлайн");
        shareHaptic();
        return;
      }
      alert(e.message || String(e));
    }
  }

  async function createNoteFromAnswer(text) {
    var raw = String(text || "").trim();
    if (!raw) return;
    var title = titleFromAnswerMarkdown(raw);
    var html = htmlFromAnswerMarkdown(raw);
    await createNoteFromAnswerHtml(html || ("<p>" + escapeHtml(raw) + "</p>"));
  }

  function closeNoteLinkPicker() {
    var ov = document.getElementById("note-link-overlay");
    if (ov) {
      ov.classList.add("hidden");
      ov.setAttribute("aria-hidden", "true");
    }
  }

  function bindNoteLinkPickerOnce() {
    var ov = document.getElementById("note-link-overlay");
    if (!ov || ov._bound) return ov;
    ov._bound = true;
    var backdrop = document.getElementById("note-link-backdrop");
    var cancel = document.getElementById("note-link-cancel");
    var search = document.getElementById("note-link-search");
    if (backdrop) backdrop.addEventListener("click", closeNoteLinkPicker);
    if (cancel) cancel.addEventListener("click", closeNoteLinkPicker);
    if (search) {
      search.addEventListener("input", function () {
        renderNoteLinkList(search.value, ov._answerText || "");
      });
    }
    return ov;
  }

  function noteLinkPreview(item) {
    return notePlainExcerpt(item.description || item.body || "", 80);
  }

  function renderNoteLinkList(query, answerText) {
    var list = document.getElementById("note-link-list");
    if (!list) return;
    var chips = document.getElementById("note-link-project-chips");
    if (chips) {
      renderNotePickerProjectChips(
        chips,
        function () {
          return linkPickerActiveProjectId;
        },
        function (v) {
          linkPickerActiveProjectId = v;
        },
        function () {
          renderNoteLinkList(query, answerText);
        }
      );
    }
    var wrap = document.getElementById("note-editor-more-wrap");
    var currentId = wrap && wrap._shareKind === "local" ? String(wrap._shareId || "") : "";
    var q = String(query || "").trim().toLowerCase();
    var notes = ((notesDataCache && notesDataCache.local_notes) || []).filter(function (n) {
      var id = String((n && n.id) || "");
      if (!id || id === currentId) return false;
      if (!noteMatchesPickerProjectFilter(n, linkPickerActiveProjectId)) return false;
      if (!q) return true;
      var title = String(n.title || n.content || "").toLowerCase();
      var preview = noteLinkPreview(n).toLowerCase();
      return title.indexOf(q) >= 0 || preview.indexOf(q) >= 0;
    });
    list.innerHTML = "";
    if (!notes.length) {
      var empty = document.createElement("p");
      empty.className = "note-link-empty";
      empty.textContent =
        q || linkPickerActiveProjectId ? "Ничего не найдено" : "Других заметок нет";
      list.appendChild(empty);
      return;
    }
    notes.forEach(function (n) {
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "note-link-item";
      var title = document.createElement("p");
      title.className = "note-link-item-title";
      title.textContent = String(n.title || n.content || "Без названия");
      var preview = document.createElement("p");
      preview.className = "note-link-item-preview";
      preview.textContent = noteLinkPreview(n) || " ";
      btn.appendChild(title);
      btn.appendChild(preview);
      btn.addEventListener("click", function () {
        linkAnswerToNote(n.id, answerText);
      });
      list.appendChild(btn);
    });
  }

  async function linkAnswerToNote(noteId, text) {
    var raw = String(text || "").trim();
    var id = localNoteIdFrom({ id: noteId });
    if (!raw || !id) return;
    try {
      await apiFetch("/notes/local/" + encodeURIComponent(String(id)) + "/comments", {
        method: "POST",
        body: JSON.stringify({
          body: raw,
          quote: "",
          prefix: "",
          suffix: "",
          as_role: "gpt",
          chat_id: COMMENTS_CHAT_ID,
        }),
      });
      closeNoteLinkPicker();
      showNoteToast("Ответ добавлен в комментарии заметки");
      shareHaptic();
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  function openNoteLinkPicker(answerText) {
    bindNoteLinkPickerOnce();
    var ov = document.getElementById("note-link-overlay");
    if (!ov) return;
    ov._answerText = String(answerText || "");
    linkPickerActiveProjectId = 0;
    var search = document.getElementById("note-link-search");
    if (search) search.value = "";
    function show() {
      ensureUserTagsLoaded().finally(function () {
        renderNoteLinkList("", ov._answerText);
      });
      ov.classList.remove("hidden");
      ov.setAttribute("aria-hidden", "false");
      if (search) {
        try {
          search.focus();
        } catch (_) {}
      }
    }
    if (notesDataCache && notesDataCache.local_notes) {
      show();
      return;
    }
    apiFetch("/notes?limit=120", { method: "GET" })
      .then(function (data) {
        notesDataCache = data || notesDataCache;
        if (data) writeMiniappCache("notes", data);
        show();
      })
      .catch(function () {
        show();
      });
  }

  function copyAnswerText(text, html) {
    copyTextWithOptionalHtml(String(text || ""), html).then(
      function () {
        showNoteToast("Скопировано");
        shareHaptic();
      },
      function () {
        showNoteToast("Не удалось скопировать");
      }
    );
  }

  function plainTextFromDiscussionSelection(range, html) {
    var rich = String(html || "").trim();
    if (rich) {
      var fromHtml = htmlToPlainText(rich);
      if (fromHtml) return fromHtml;
    }
    var raw = "";
    try {
      raw = range && range.toString ? range.toString() : "";
    } catch (_) {
      raw = "";
    }
    return String(raw || "")
      .replace(/\u00a0/g, " ")
      .replace(/\r\n/g, "\n")
      .replace(/[ \t]+\n/g, "\n")
      .replace(/\n{3,}/g, "\n\n")
      .replace(/^\s+|\s+$/g, "");
  }

  function discussMenuIcon(name) {
    var common =
      'width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"';
    var paths = {
      note:
        '<path d="M15.2 3a2 2 0 0 1 1.4.6l3.8 3.8a2 2 0 0 1 .6 1.4V19a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2z"/><path d="M15 3v6h6"/>',
      task: '<path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>',
      link: '<path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/>',
      copy: '<rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>',
      trash:
        '<polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6M14 11v6"/><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/>',
      clarify:
        '<path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/><path d="M8 9h8M8 13h5"/>',
      reply:
        '<path d="M9 17H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v6"/><path d="M15 13l6 4-6 4v-8z"/>',
      "into-note":
        '<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5"/><path d="M12 11v7M9 15l3 3 3-3"/>',
      "create-note":
        '<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5"/><path d="M12 11v6M9 14h6"/>',
    };
    return (
      '<span class="note-discuss-menu-icon"><svg ' +
      common +
      ">" +
      (paths[name] || "") +
      "</svg></span>"
    );
  }

  function discussMenuItem(action, icon, label, extraClass) {
    return (
      '<button type="button" class="note-discuss-menu-item' +
      (extraClass ? " " + extraClass : "") +
      '" data-answer-action="' +
      action +
      '">' +
      discussMenuIcon(icon) +
      "<span>" +
      label +
      "</span></button>"
    );
  }

  // Задача из сообщения: первая строка — название, весь текст — описание.
  function createTaskFromMessage(text) {
    var plain = String(text || "")
      .replace(/[*_`#>]+/g, "")
      .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
      .trim();
    var first = (plain.split(/\n+/)[0] || "").trim();
    var title = first;
    if (title.length > 120) {
      var cut = title.slice(0, 120);
      var sp = cut.lastIndexOf(" ");
      title = (sp > 60 ? cut.slice(0, sp) : cut) + "…";
    }
    var ev = { summary: title, note_id: currentOpenNoteId() };
    if (plain && plain !== title) ev.description = plain;
    openTaskModal(ev);
  }

  function bindNoteAnswerMenu(btn, menu, comment) {
    if (!btn || !menu) return;
    var text = stripCalMarker(String((comment && comment.body) || ""));
    var commentId = comment && comment.id;
    btn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      var open = menu.classList.contains("hidden");
      closeNoteAnswerMenu();
      if (open) {
        menu.classList.remove("hidden");
        btn.setAttribute("aria-expanded", "true");
        positionDiscussAnswerMenu(btn, menu);
      }
    });
    menu.querySelectorAll("[data-answer-action]").forEach(function (item) {
      item.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var action = item.getAttribute("data-answer-action");
        closeNoteAnswerMenu();
        if (action === "reply") {
          var draft = discussionCommentReplyDraft(comment);
          if (draft) applyDiscussClarify(draft);
        } else if (action === "task") createTaskFromMessage(text);
        else if (action === "into-note") appendAnswerToCurrentNote(text);
        else if (action === "create-note") createNoteFromAnswer(text);
        else if (action === "link") openNoteLinkPicker(text);
        else if (action === "copy") copyAnswerText(text);
        else if (action === "delete") {
          var wrap = document.getElementById("note-editor-more-wrap");
          if (wrap && wrap._shareKind && wrap._shareId && commentId) {
            deleteNoteComment(wrap._shareKind, wrap._shareId, commentId);
          }
        }
      });
    });
  }

  function copyClientRect(r) {
    if (!r) return null;
    return {
      top: r.top,
      left: r.left,
      width: r.width,
      height: r.height,
      bottom: r.bottom,
      right: r.right,
    };
  }

  function snapshotDiscussSelectionRects() {
    var sel = window.getSelection && window.getSelection();
    if (!sel || sel.isCollapsed || sel.rangeCount < 1) return [];
    var range = sel.getRangeAt(0);
    var out = [];
    var rects = range.getClientRects ? range.getClientRects() : [];
    for (var i = 0; i < rects.length; i++) {
      var copied = copyClientRect(rects[i]);
      if (copied && copied.width >= 1 && copied.height >= 1) out.push(copied);
    }
    return out;
  }

  function hideDiscussSelMarks() {
    var el = document.getElementById("note-discuss-sel-marks");
    if (el && el.parentNode) el.parentNode.removeChild(el);
  }

  function showDiscussSelMarks(rects) {
    hideDiscussSelMarks();
    if (!rects || !rects.length) return;
    var wrap = document.createElement("div");
    wrap.id = "note-discuss-sel-marks";
    wrap.className = "note-discuss-sel-marks";
    wrap.setAttribute("aria-hidden", "true");
    for (var i = 0; i < rects.length; i++) {
      var r = rects[i];
      var mark = document.createElement("div");
      mark.className = "note-discuss-sel-mark";
      mark.style.top = Math.round(r.top) + "px";
      mark.style.left = Math.round(r.left) + "px";
      mark.style.width = Math.round(r.width) + "px";
      mark.style.height = Math.round(r.height) + "px";
      wrap.appendChild(mark);
    }
    if (!wrap.firstChild) return;
    document.body.appendChild(wrap);
  }

  function hideDiscussClarify() {
    hideDiscussSelMarks();
    var el = document.getElementById("note-discuss-selection");
    if (el && el.parentNode) el.parentNode.removeChild(el);
  }

  function isDiscussSelectionUiTarget(el) {
    return !!(el && el.closest && el.closest("#note-discuss-selection, #note-discuss-sel-marks"));
  }

  function discussSelectableBubble(el) {
    if (!el || !el.closest) return null;
    // Реплай/цитата: ассистент, другие участники и свои сообщения.
    var msg = el.closest(
      ".note-discuss-msg.is-assistant, .note-discuss-msg.is-other, .note-discuss-msg.is-user"
    );
    if (!msg || msg.classList.contains("is-pending") || msg.classList.contains("is-optimistic")) {
      return null;
    }
    var bubble = el.closest(".note-discuss-bubble");
    if (!bubble || !msg.contains(bubble)) return null;
    return { msg: msg, bubble: bubble };
  }

  function isDiscussAssistantBubbleTarget(el) {
    return !!discussSelectableBubble(el);
  }

  function collapseNativeDiscussionSelection() {
    var sel = window.getSelection && window.getSelection();
    if (sel && sel.removeAllRanges) sel.removeAllRanges();
  }

  function discussSelectionBtn(action, icon, label) {
    return (
      '<button type="button" class="note-discuss-selection-btn" data-selection-action="' +
      action +
      '" aria-label="' +
      label +
      '" title="' +
      label +
      '">' +
      discussMenuIcon(icon) +
      "</button>"
    );
  }

  function clearDiscussionSelection() {
    var sel = window.getSelection && window.getSelection();
    if (sel && sel.removeAllRanges) sel.removeAllRanges();
    hideDiscussClarify();
  }

  function runDiscussSelectionAction(action, draft) {
    if (!draft || !String(draft.quote || "").trim()) {
      hideDiscussClarify();
      return;
    }
    if (action === "clarify") {
      applyDiscussClarify(draft);
      return;
    }
    var quote = String(draft.quote || "").trim();
    var html = String(draft.html || "").trim();
    var plain = String(draft.plain || "").trim() || quote;
    if (action === "copy") copyAnswerText(plain, html);
    else if (action === "into-note") {
      if (html) {
        if (!appendAnswerHtmlToCurrentNote(html)) appendAnswerToCurrentNote(plain);
      } else {
        appendAnswerToCurrentNote(plain);
      }
    } else if (action === "create-note") {
      if (html) createNoteFromAnswerHtml(html);
      else createNoteFromAnswer(plain);
    } else if (action === "task") {
      openTaskModal({ summary: quote, note_id: currentOpenNoteId() });
    }
    clearDiscussionSelection();
  }

  function showDiscussSelectionToolbar(draft) {
    var rect = draft && draft.rect;
    if (!rect) {
      hideDiscussClarify();
      return;
    }
    var bar = document.getElementById("note-discuss-selection");
    if (!bar) {
      bar = document.createElement("div");
      bar.id = "note-discuss-selection";
      bar.className = "note-discuss-selection";
      bar.innerHTML =
        discussSelectionBtn("clarify", "clarify", "Уточнить") +
        discussSelectionBtn("task", "task", "Задача") +
        discussSelectionBtn("copy", "copy", "Копировать") +
        discussSelectionBtn("into-note", "into-note", "В заметку") +
        discussSelectionBtn("create-note", "create-note", "Создать заметку");
      function stopSel(e) {
        e.preventDefault();
        e.stopPropagation();
      }
      function activate(e) {
        e.preventDefault();
        e.stopPropagation();
        if (bar._fired) return;
        var btn = e.target && e.target.closest && e.target.closest("[data-selection-action]");
        if (!btn || !bar.contains(btn)) return;
        bar._fired = true;
        runDiscussSelectionAction(btn.getAttribute("data-selection-action"), bar._draft);
      }
      bar.addEventListener("pointerdown", stopSel);
      bar.addEventListener("mousedown", stopSel);
      bar.addEventListener("touchstart", stopSel, { passive: false });
      bar.addEventListener("pointerup", activate);
      bar.addEventListener("click", activate);
      document.body.appendChild(bar);
    }
    bar._draft = draft;
    bar._fired = false;
    var vw = window.innerWidth;
    var width = bar.offsetWidth || 128;
    var height = bar.offsetHeight || 32;
    var left = rect.left + rect.width / 2 - width / 2;
    var top = rect.top - height - 8;
    if (left < 8) left = 8;
    if (left + width > vw - 8) left = vw - width - 8;
    if (top < 8) top = rect.bottom + 8;
    bar.style.top = Math.round(top) + "px";
    bar.style.left = Math.round(left) + "px";
  }

  function applyDiscussClarify(draft) {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap || !draft || !String(draft.quote || "").trim()) return;
    var quote = String(draft.quote || "").trim();
    var src = String(draft.source || "");
    // Draft нужен и в режиме агента: при отправке/переключении в «Текст» цитата не теряется.
    wrap._commentDraft = {
      quote: quote,
      prefix: draft.prefix || "",
      suffix: draft.suffix || "",
    };
    wrap._commentChairId = draft.commentId || null;
    wrap._commentReplyWho = String(draft.replyWho || "").trim() || null;
    // GPT/Research-баблы → чип + переключение режима.
    // Чужие/свои реплики в режиме агента (GPT / Research / свой) → чип, режим не сбрасываем.
    if (src === "gpt" || src === "research" || noteAskUsesChips(noteAskMode())) {
      if (src === "research") setNoteAskMode("research");
      else if (src === "gpt") setNoteAskMode("gpt");
      syncNoteComposerCommentTarget();
      insertGptQuoteChip(quote);
      var ed = noteGptEditor();
      if (ed) {
        try {
          ed.focus();
        } catch (_) {}
      }
      clearDiscussionSelection();
      return;
    }
    if (src === "paie") setNoteAskMode("paie");
    syncNoteComposerCommentTarget();
    var focusEl = noteAskUsesComposerEditor(noteAskMode())
      ? noteGptEditor()
      : document.getElementById("note-paie-reply-input");
    if (focusEl) {
      try {
        focusEl.focus();
      } catch (_) {}
    }
    clearDiscussionSelection();
  }

  function discussionSelectionDraft() {
    var sel = window.getSelection && window.getSelection();
    if (!sel || sel.isCollapsed || sel.rangeCount < 1) return null;
    var node = sel.anchorNode;
    var el = node && (node.nodeType === 1 ? node : node.parentElement);
    var found = discussSelectableBubble(el);
    if (!found) return null;
    var bubble = found.bubble;
    var msg = found.msg;
    if (sel.focusNode && !bubble.contains(sel.focusNode)) return null;
    var range = sel.getRangeAt(0);
    var html = htmlFromDiscussionSelectionRange(range);
    var plain = plainTextFromDiscussionSelection(range, html);
    var api = window.NoteComments;
    var draft = api && api.selectionAnchor ? api.selectionAnchor(bubble) : null;
    var source = "reply";
    if (msg.classList.contains("is-research")) source = "research";
    else if (msg.classList.contains("is-gpt")) source = "gpt";
    else if (msg.classList.contains("is-assistant")) source = "paie";
    var commentId = parseInt(msg.getAttribute("data-comment-id") || "", 10) || 0;
    if (draft && draft.quote) {
      draft.rect = copyClientRect(draft.rect) || draft.rect;
      draft.html = html;
      draft.plain = plain || draft.quote;
      draft.source = source;
      draft.commentId = commentId;
      return draft;
    }
    var text = String(plain || sel.toString() || "")
      .replace(/\s+/g, " ")
      .trim();
    if (!text && !plain) return null;
    var rect = copyClientRect(range.getBoundingClientRect ? range.getBoundingClientRect() : null);
    return {
      quote: text || String(plain || "").replace(/\s+/g, " ").trim(),
      prefix: "",
      suffix: "",
      rect: rect,
      html: html,
      plain: plain || text,
      source: source,
      commentId: commentId,
    };
  }

  function bindDiscussClarifyOnce() {
    if (document._discussClarifyBound) return;
    document._discussClarifyBound = true;
    function onContextMenu(e) {
      if (!isNoteDiscussionOpen()) return;
      var t = e.target;
      if (isDiscussSelectionUiTarget(t) || isDiscussAssistantBubbleTarget(t)) {
        e.preventDefault();
      }
    }
    function onSelect(e) {
      if (isDiscussSelectionUiTarget(e && e.target)) return;
      if (!isNoteDiscussionOpen()) {
        hideDiscussClarify();
        return;
      }
      var draft = discussionSelectionDraft();
      if (!draft || !draft.rect) return;
      var rects = snapshotDiscussSelectionRects();
      showDiscussSelectionToolbar(draft);
      showDiscussSelMarks(rects);
      collapseNativeDiscussionSelection();
    }
    function onDismiss(e) {
      if (!document.getElementById("note-discuss-selection")) return;
      if (isDiscussSelectionUiTarget(e && e.target)) return;
      hideDiscussClarify();
    }
    // Выделение в бабле — своя подсветка (родное выделение снято, чтобы не было системного меню),
    // поэтому Ctrl+C / Cmd+C копирует то, что выделено подсветкой (как «Копировать» в плашке).
    function onCopyKey(e) {
      if (!(e.metaKey || e.ctrlKey) || e.altKey || e.shiftKey) return;
      if (String(e.key || "").toLowerCase() !== "c" && String(e.key || "").toLowerCase() !== "с" && e.code !== "KeyC") return;
      var bar = document.getElementById("note-discuss-selection");
      var d = bar && bar._draft;
      if (!d || !String(d.quote || d.plain || "").trim()) return;
      var sel = window.getSelection && window.getSelection();
      if (sel && !sel.isCollapsed) return; // есть обычное выделение — пусть копирует браузер
      e.preventDefault();
      copyAnswerText(String(d.plain || d.quote || "").trim(), String(d.html || "").trim());
    }
    document.addEventListener("keydown", onCopyKey, true);
    document.addEventListener("contextmenu", onContextMenu, true);
    document.addEventListener("mouseup", onSelect);
    document.addEventListener("pointerup", onSelect);
    document.addEventListener("keyup", onSelect);
    document.addEventListener(
      "scroll",
      function () {
        hideDiscussClarify();
        closeNoteAnswerMenu();
      },
      true
    );
    document.addEventListener("pointerdown", onDismiss, true);
  }

  // Ответ ИИ, который действовал в календаре, хранит id действий: «[[leo-cal:id,id]]».
  var CAL_MARKER_RE = /\n*\[\[leo-cal:([a-z0-9,]+)\]\]\s*$/i;
  function stripCalMarker(text) {
    return String(text || "").replace(CAL_MARKER_RE, "");
  }
  // Для истории модели: вместо маркера — что уже сделано, чтобы ИИ не повторял действия.
  function calMarkerForHistory(text) {
    var ids = calMarkerIds(text);
    var clean = stripCalMarker(text);
    if (!ids.length) return clean;
    var done = ids
      .map(function (id) {
        var a = calActionsCache[id];
        if (a && a.kind === "focus_item") return focusItemsForHistory(a);
        if (!a || a.missing || String(a.kind || "").indexOf("show_") === 0) return "";
        var st = a.status === "undone" ? " (отменено)" : a.status === "proposed" ? " (предложено)" : "";
        return (a.title || a.kind) + (a.when ? " — " + a.when : "") + st;
      })
      .filter(Boolean);
    return clean + "\n[Уже выполнено, не повторять: " + (done.length ? done.join("; ") : "действия с календарём из этого ответа") + "]";
  }

  function focusItemsForHistory(a) {
    var st = { new: "не разобран", completed: "выполнен", linked: "связан с задачей", converted: "поставлена задача", dismissed: "скрыт", retyped: "тип изменён", snoozed: "отложен" };
    return (a.focus || [])
      .map(function (f) {
        return (
          "пункт Фокуса «" + (f.assignee ? f.assignee + " — " : "") + f.text + (f.deadline ? ", срок " + f.deadline : "") +
          "» (focus key: " + f.key + "; " + (st[f.status] || f.status) + ")"
        );
      })
      .join("; ");
  }

  // ---------------------------------------------------------------- Фокус: карточка разбора пункта в чате
  var focusChatUi = {};
  var FOCUS_TYPE_UI = {
    task: ["taskBox", "Задача"],
    promise: ["taskBox", "Обещание"],
    reminder: ["bell", "Напоминание"],
    decision: ["taskBox", "Решение"],
    thought: ["taskBox", "Мысль"],
  };
  var FOCUS_REASON_LABEL = { not_a_task: "Не задача", not_relevant: "Неактуально", duplicate: "Дубль", recognition_error: "Ошибка распознавания" };
  var FOCUS_STATE_LABEL = { "": "Открыта", open: "Открыта", in_progress: "В работе", done: "Выполнена" };

  function focusUiFor(aid) {
    if (!focusChatUi[aid]) focusChatUi[aid] = { mode: "view", open: "", menu: "", draft: {} };
    return focusChatUi[aid];
  }

  function focusSetUi(aid, patch) {
    Object.assign(focusUiFor(aid), patch || {});
    if (fstackOwns(aid)) {
      renderFocusStack();
      return;
    }
    // Нажатие в карточке — лента остаётся на месте, даже если только что прокручивали в конец.
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap) {
      wrap._forceDiscussScrollBottom = 0;
      wrap._keepDiscussScroll = true;
    }
    refreshDiscussFeedNow();
  }

  function focusAt(daysFromNow, hour, weekday) {
    var d = new Date();
    d.setSeconds(0, 0);
    d.setMinutes(0);
    d.setHours(hour);
    if (weekday != null) {
      var add = (weekday + 7 - d.getDay()) % 7 || 7;
      d.setDate(d.getDate() + add);
    } else {
      d.setDate(d.getDate() + daysFromNow);
    }
    return d;
  }

  function focusWhenLabel(iso) {
    var d = new Date(String(iso || ""));
    if (isNaN(d.getTime())) return "";
    var today = new Date();
    var tm = new Date(today.getFullYear(), today.getMonth(), today.getDate() + 1);
    var day =
      d.toDateString() === tm.toDateString()
        ? "завтра"
        : d.toLocaleDateString("ru-RU", { weekday: "short", day: "numeric", month: "short" });
    return day + " в " + d.toLocaleTimeString("ru-RU", { hour: "2-digit", minute: "2-digit" });
  }

  function focusStatusLine(f) {
    var line = focusStatusLineBase(f);
    // кто разобрал пункт — видно всем участникам встречи
    if (line && f.by && ["completed", "converted", "linked"].indexOf(f.status) >= 0) line = [line[0], line[1] + " · " + f.by];
    return line;
  }

  function focusStatusLineBase(f) {
    if (f.status === "completed") return ["check", "Выполнено" + (f.source && f.source.kind === "note" ? " · отмечено в источнике" : "")];
    if (f.status === "converted") return ["taskBox", "Поставлена задача"];
    if (f.status === "linked") {
      var l = f.link || {};
      return ["link", "Связано: " + (l.title || l.url || "задача")];
    }
    if (f.status === "snoozed" && !(new Date(f.snooze_until).getTime() > Date.now())) return null; // срок прошёл — пункт снова открыт
    if (f.status === "snoozed") return ["clock", (f.type === "reminder" ? "Напомню " : "Вернётся в Фокус ") + focusWhenLabel(f.snooze_until)];
    if (f.status === "dismissed") return ["x", "Скрыто: " + (FOCUS_REASON_LABEL[f.reason] || "неактуально")];
    if (f.status === "retyped") return ["taskBox", "Теперь это " + ((FOCUS_TYPE_UI[f.type] || [])[1] || f.type).toLowerCase() + " · убрано из Фокуса"];
    return null;
  }

  // Новое состояние пункта — во всех карточках чата, где он есть, и в строке Фокуса.
  function focusApplyItem(item) {
    focusSyncChatCaches(item);
    refreshDiscussFeedNow();
    loadFocus(true);
  }

  function focusSyncChatCaches(item) {
    if (!item || !item.key) return;
    Object.keys(calActionsCache).forEach(function (k) {
      var a = calActionsCache[k];
      if (!a || a.kind !== "focus_item" || !a.focus) return;
      a.focus = a.focus.map(function (f) {
        return f.key === item.key ? item : f;
      });
    });
  }

  function focusRunOp(aid, f, body, okText) {
    if (fstackOwns(aid)) return fstackOp(f, body, okText);
    return focusItemOp(f.key, body)
      .then(function (res) {
        if (res && res.item) {
          var ui = focusUiFor(aid);
          ui.mode = "view";
          ui.menu = "";
          ui.draft = {};
          focusApplyItem(res.item);
        }
        if (okText) showNoteToast(okText);
      })
      .catch(function (e) {
        showNoteToast((e && e.message) || "Не получилось");
        refreshDiscussFeedNow();
      });
  }

  function focusEl(tag, cls, text) {
    var el = document.createElement(tag);
    if (cls) el.className = cls;
    if (text != null) el.textContent = text;
    return el;
  }

  function focusBtn(label, cls, fn, icon) {
    var b = focusEl("button", "focus-chat-btn" + (cls ? " " + cls : ""));
    b.type = "button";
    if (icon && DISCUSS_ICONS[icon]) b.innerHTML = DISCUSS_ICONS[icon];
    if (label) b.appendChild(focusEl("span", "", label));
    b.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      fn(b, e);
    });
    return b;
  }

  function focusMenu(items) {
    var m = focusEl("div", "focus-chat-menu");
    items.forEach(function (it) {
      if (it.head) {
        m.appendChild(focusEl("div", "focus-chat-menu-head", it.head));
        return;
      }
      m.appendChild(
        focusBtn(it.label, "focus-chat-menu-item", function (b) {
          b.disabled = true;
          it.fn();
        })
      );
    });
    return m;
  }

  function focusSourceOpenable(src) {
    return !!(src && ((src.kind === "note" && src.id) || src.url));
  }

  function focusOpenSource(src) {
    if (!src) return;
    if (src.kind === "note" && src.id) {
      openMeetingMaterial({ id: src.id, kind: src.note_kind || "note", title: src.title || "" });
    } else if (src.url) {
      openExternal(src.url);
    }
  }

  function focusDatePicker(aid, f, kind) {
    var row = focusEl("div", "focus-chat-date");
    var inp = document.createElement("input");
    inp.type = "datetime-local";
    var d = focusAt(1, 9);
    inp.value = focusLocalIso(d);
    row.appendChild(inp);
    row.appendChild(
      focusBtn(kind === "remind" ? "Напомнить" : "Отложить", "is-primary", function (b) {
        var when = new Date(inp.value);
        if (isNaN(when.getTime()) || when <= new Date()) {
          showNoteToast("Выберите время в будущем");
          return;
        }
        b.disabled = true;
        var body = kind === "remind" ? { op: "retype", type: "reminder", until: when.toISOString() } : { op: "snooze", until: when.toISOString() };
        focusRunOp(aid, f, body);
      })
    );
    row.appendChild(focusBtn("Отмена", "is-ghost", function () {
      focusSetUi(aid, { mode: "view", menu: "" });
    }));
    return row;
  }

  // Срок из разбора («пт», «завтра», «24.10», «2026-10-24») → YYYY-MM-DD для поля даты.
  // baseIso — день, от которого считать «завтра» / «до пятницы» (например, день отчёта чата); по умолчанию сегодня.
  var RU_MONTHS_GEN = ["январ", "феврал", "март", "апрел", "ма", "июн", "июл", "август", "сентябр", "октябр", "ноябр", "декабр"];
  function focusDeadlineIso(raw, baseIso) {
    var t = String(raw || "").trim().toLowerCase().replace(/ё/g, "е");
    var bm = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(baseIso || ""));
    var today = bm ? new Date(+bm[1], +bm[2] - 1, +bm[3]) : new Date();
    function iso(d) {
      return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
    }
    if (!t) return "";
    var m = t.match(/(\d{4})-(\d{2})-(\d{2})/);
    if (m) return m[1] + "-" + m[2] + "-" + m[3];
    m = t.match(/(\d{1,2})\.(\d{1,2})(?:\.(\d{2,4}))?/);
    if (m) {
      var y = m[3] ? Number(m[3].length === 2 ? "20" + m[3] : m[3]) : today.getFullYear();
      var d0 = new Date(y, Number(m[2]) - 1, Number(m[1]));
      if (!m[3] && d0 < new Date(today.getFullYear(), today.getMonth(), today.getDate())) d0.setFullYear(y + 1);
      return isNaN(d0.getTime()) ? "" : iso(d0);
    }
    m = t.match(/(\d{1,2})\s+(январ|феврал|март|апрел|ма[яй]|июн|июл|август|сентябр|октябр|ноябр|декабр)[а-я]*/);
    if (m) {
      var mi = RU_MONTHS_GEN.indexOf(/^ма[яй]$/.test(m[2]) ? "ма" : m[2]);
      var dm = new Date(today.getFullYear(), mi, Number(m[1]));
      if (dm < new Date(today.getFullYear(), today.getMonth(), today.getDate())) dm.setFullYear(today.getFullYear() + 1);
      return mi < 0 || isNaN(dm.getTime()) ? "" : iso(dm);
    }
    if (/сегодня/.test(t)) return iso(today);
    if (/послезавтра/.test(t)) return iso(new Date(today.getFullYear(), today.getMonth(), today.getDate() + 2));
    if (/завтра/.test(t)) return iso(new Date(today.getFullYear(), today.getMonth(), today.getDate() + 1));
    var days = [/^вс|воскр/, /^пн|понед/, /^вт|вторн/, /^ср|сред/, /^чт|четв/, /^пт|пятн/, /^сб|субб/];
    for (var i = 0; i < days.length; i++) {
      if (days[i].test(t.replace(/^(до|к|в|во)\s+/, ""))) {
        var add = (i + 7 - today.getDay()) % 7 || 7;
        return iso(new Date(today.getFullYear(), today.getMonth(), today.getDate() + add));
      }
    }
    return "";
  }

  // Исполнитель из разбора («Мария») → контакт, если нашёлся; иначе — я.
  function focusAssigneeContact(name) {
    var q = String(name || "").trim().toLowerCase();
    if (!q || q === "я") return null;
    var first = q.split(/\s+/)[0];
    var hit = null;
    Object.keys(calendarContactsByEmail).forEach(function (k) {
      var c = calendarContactsByEmail[k];
      if (!c || hit) return;
      var hay = [c.name, c.telegram_username, (c.aliases || []).join(" ")].join(" ").toLowerCase();
      if (first.length >= 3 && hay.indexOf(first.slice(0, Math.max(3, first.length - 2))) >= 0) hit = c;
    });
    return hit;
  }

  // «В задачу»: те же поля, что у задачи, — исполнитель из контактов, срок, комментарий; «Поставить / Отмена».
  function focusTaskForm(aid, f) {
    var ui = focusUiFor(aid);
    var d = ui.draft;
    var tracker = connectedTracker();
    if (tracker && !d.target) d.target = readTaskTarget() === tracker.id ? tracker.id : "orbita";
    if (tracker && d.target === tracker.id) return focusTrackerTaskForm(aid, f, tracker);
    var wrap = focusEl("div", "focus-chat-edit focus-chat-task");
    if (tracker) wrap.appendChild(focusTaskTargetSwitch(aid, d, tracker));
    var grid = focusEl("div", "focus-chat-fields");
    function label(text) {
      grid.appendChild(focusEl("label", "focus-chat-field-label", text));
    }
    label("Задача");
    var title = document.createElement("input");
    title.type = "text";
    title.value = d.title != null ? d.title : f.text || "";
    title.addEventListener("input", function () {
      d.title = title.value;
    });
    grid.appendChild(title);
    label("Исполнитель");
    var assHost = focusEl("div", "focus-chat-assignee");
    grid.appendChild(assHost);
    var contact = d.assignee || focusAssigneeContact(f.assignee);
    var assApi = mountTaskAssignee(
      assHost,
      contact
        ? { user_id: contact.user_id || contact.telegram_user_id || "", email: contact.email || "", name: contact.name || "" }
        : null
    );
    label("Срок");
    var due = document.createElement("input");
    due.type = "date";
    due.value = d.due != null ? d.due : focusDeadlineIso(f.deadline) || focusDeadlineIso("завтра");
    due.addEventListener("input", function () {
      d.due = due.value;
    });
    due.addEventListener("change", function () {
      d.due = due.value;
    });
    grid.appendChild(due);
    label("Комментарий");
    var comment = document.createElement("input");
    comment.type = "text";
    comment.placeholder = "Необязательно";
    comment.value = d.comment != null ? d.comment : f.comment || "";
    comment.addEventListener("input", function () {
      d.comment = comment.value;
    });
    grid.appendChild(comment);
    wrap.appendChild(grid);
    if (f.assignee && !contact) {
      wrap.appendChild(focusEl("p", "focus-chat-hint", "«" + f.assignee + "» нет в контактах — выберите исполнителя или оставьте себе."));
    }
    var acts = focusEl("div", "focus-chat-acts");
    acts.appendChild(
      focusBtn("Поставить", "is-primary", function (b) {
        var who = assApi.getAssignee() || {};
        d.assignee = who;
        focusCreateTask(aid, f, { title: title.value, due: due.value, comment: comment.value, who: who }, b);
      })
    );
    acts.appendChild(focusBtn("Отмена", "is-ghost", function () {
      focusSetUi(aid, { mode: "view", draft: {} });
    }));
    wrap.appendChild(acts);
    return wrap;
  }

  // «Поставить» из пункта: задача в Орбите (весь день или ко времени), пункт — «поставлена задача».
  function focusCreateTask(aid, f, o, b) {
    var text = String(o.title || "").trim();
    if (!text) {
      showNoteToast("Укажите, что сделать");
      return;
    }
    if (!o.due) {
      showNoteToast("Укажите срок");
      return;
    }
    var who = o.who || {};
    var src = f.source || {};
    var desc = [String(o.comment || "").trim(), src.title ? "Из «" + src.title + "»" : ""].filter(Boolean).join("\n");
    var t = String(o.time || "");
    var when = { start: o.due + "T12:00:00", end: o.due + "T13:00:00", all_day: true };
    if (/^\d{2}:\d{2}$/.test(t)) {
      var end = new Date(o.due + "T" + t + ":00");
      end.setHours(end.getHours() + 1);
      when = { start: o.due + "T" + t + ":00", end: focusLocalIso(end) + ":00", all_day: false };
    }
    if (b) b.disabled = true;
    return apiFetch("/calendar/tasks", {
      method: "POST",
      body: JSON.stringify(Object.assign({
        title: text,
        description: desc,
        assignee_user_id: who.user_id || "",
        assignee_email: who.email || "",
        assignee_name: who.name || "",
        note_id: src.kind === "note" && src.id ? String(src.id) : "",
      }, when)),
    })
      .then(function (r) {
        var task = r && r.task;
        if (!task || task.id == null) throw new Error("Не удалось поставить задачу");
        rememberTaskTip(task);
        loadActual({ skipCachePaint: true, silent: true });
        var whoName = who.name && who.user_id !== defaultTaskAssignee().user_id ? " — " + who.name : "";
        return focusRunOp(aid, f, { op: "converted", task_id: task.id }, "Задача поставлена" + whoName);
      })
      .catch(function (e) {
        if (b) b.disabled = false;
        showNoteToast((e && e.message) || "Не удалось поставить задачу");
      });
  }

  function focusTaskTargetSwitch(aid, d, tracker) {
    var host = document.createElement("div");
    host.innerHTML = taskTargetSwitchHtml(d.target || "orbita", tracker);
    var sw = host.firstChild;
    sw.classList.add("focus-task-target");
    bindTaskTargetSwitch(host, d.target || "orbita", function (next) {
      d.target = next;
      focusSetUi(aid, { draft: d });
    });
    return sw;
  }

  // «В задачу» → Битрикс24 (или другой трекер): описание с «Описать по WWA», доска, стадия, исполнитель, срок.
  function focusTrackerTaskForm(aid, f, tracker) {
    var ui = focusUiFor(aid);
    var d = ui.draft;
    var src = f.source || {};
    var noteId = src.kind === "note" && src.id ? String(src.id) : "";
    var wrap = focusEl("div", "focus-chat-edit focus-chat-task focus-chat-task--tracker");
    wrap.appendChild(focusTaskTargetSwitch(aid, d, tracker));
    var grid = focusEl("div", "focus-chat-fields");
    function label(text) {
      grid.appendChild(focusEl("label", "focus-chat-field-label", text));
    }
    label("Задача");
    var title = document.createElement("input");
    title.type = "text";
    title.value = d.title != null ? d.title : f.text || "";
    title.addEventListener("input", function () {
      d.title = title.value;
    });
    grid.appendChild(title);
    label("Описание");
    var descBox = focusEl("div", "focus-tracker-desc");
    var desc = document.createElement("textarea");
    desc.rows = 3;
    desc.placeholder = "Коротко — или «Описать по WWA»";
    desc.value = d.desc != null ? d.desc : f.comment || "";
    desc.addEventListener("input", function () {
      d.desc = desc.value;
      autosizeTrackerDesc(desc);
    });
    var wwaActs = focusEl("div", "focus-tracker-wwa");
    var undo = focusBtn("Вернуть", "is-ghost" + (d.descPrev != null ? "" : " hidden"), function () {
      if (d.descPrev == null) return;
      desc.value = d.descPrev;
      d.desc = d.descPrev;
      d.descPrev = null;
      undo.classList.add("hidden");
      autosizeTrackerDesc(desc);
    });
    var wwa = focusBtn(d.descPrev != null ? "Описать заново" : "Описать по WWA", "", function (b) {
      var t = String(title.value || "").trim();
      var before = String(desc.value || "");
      if (!t && !before.trim()) {
        showNoteToast("Сначала напишите, что нужно сделать");
        return;
      }
      b.disabled = true;
      b.classList.add("is-loading");
      var lbl = b.querySelector("span");
      if (lbl) lbl.textContent = "Описываю…";
      apiFetch("/trackers/describe-wwa", {
        method: "POST",
        body: JSON.stringify({
          title: t,
          description: before,
          note_id: noteId,
          focus_key: f.key || "",
          context: src.item ? String(src.item) : "",
        }),
      })
        .then(function (r) {
          var text = String((r && r.description) || "").trim();
          if (!text) throw new Error("Пустой ответ — попробуйте ещё раз");
          d.descPrev = before;
          d.desc = text;
          if (document.body.contains(desc)) {
            desc.value = text;
            autosizeTrackerDesc(desc);
            undo.classList.remove("hidden");
            if (lbl) lbl.textContent = "Описать заново";
          } else {
            refreshDiscussFeedNow();
          }
        })
        .catch(function (e) {
          if (lbl) lbl.textContent = "Описать по WWA";
          showNoteToast((e && e.message) || "Не получилось описать задачу");
        })
        .then(function () {
          b.disabled = false;
          b.classList.remove("is-loading");
        });
    });
    wwaActs.appendChild(undo);
    wwaActs.appendChild(wwa);
    descBox.appendChild(desc);
    descBox.appendChild(wwaActs);
    grid.appendChild(descBox);
    label("Доска");
    var boardSel = document.createElement("select");
    grid.appendChild(boardSel);
    label("Стадия");
    var stageSel = document.createElement("select");
    grid.appendChild(stageSel);
    label("Исполнитель");
    var resp = document.createElement("input");
    resp.type = "text";
    resp.placeholder = "Я";
    resp.autocomplete = "off";
    resp.value = d.resp != null ? d.resp : f.assignee || "";
    resp.addEventListener("input", function () {
      d.resp = resp.value;
    });
    var respBox = focusEl("div", "focus-tracker-resp");
    var respList = focusEl("div", "tracker-user-list hidden");
    respBox.appendChild(resp);
    respBox.appendChild(respList);
    grid.appendChild(respBox);
    d.respPick = d.respPick || { id: "", name: "" };
    bindTrackerUserPicker(resp, respList, tracker.id, d.respPick);
    label("Срок");
    var due = document.createElement("input");
    due.type = "date";
    due.value = d.due != null ? d.due : focusDeadlineIso(f.deadline) || "";
    due.addEventListener("input", function () {
      d.due = due.value;
    });
    due.addEventListener("change", function () {
      d.due = due.value;
    });
    grid.appendChild(due);
    wrap.appendChild(grid);
    var err = focusEl("p", "focus-chat-hint focus-tracker-err hidden");
    wrap.appendChild(err);
    var defs = tracker.defaults || {};
    bindTrackerBoardStage(
      tracker.id,
      boardSel,
      stageSel,
      {
        board_id: d.board != null ? d.board : defs.board_id,
        board_name: d.boardName != null ? d.boardName : defs.board_name,
        stage_id: d.stage != null ? d.stage : defs.stage_id,
        stage_name: d.stageName != null ? d.stageName : defs.stage_name,
      },
      err
    );
    boardSel.addEventListener("change", function () {
      d.board = boardSel.value;
      d.boardName = selectedOptionText(boardSel);
      d.stage = "";
    });
    stageSel.addEventListener("change", function () {
      d.stage = stageSel.value;
      d.stageName = selectedOptionText(stageSel);
    });
    window.requestAnimationFrame(function () {
      autosizeTrackerDesc(desc);
    });
    var acts = focusEl("div", "focus-chat-acts");
    acts.appendChild(
      focusBtn("Создать в " + tracker.short_title, "is-primary", function (b) {
        var text = String(title.value || "").trim();
        if (!text) {
          showNoteToast("Укажите, что сделать");
          return;
        }
        b.disabled = true;
        apiFetch("/trackers/" + encodeURIComponent(tracker.id) + "/tasks", {
          method: "POST",
          body: JSON.stringify({
            title: text,
            description: String(desc.value || ""),
            board_id: boardSel.value,
            board_name: selectedOptionText(boardSel),
            stage_id: stageSel.value,
            stage_name: selectedOptionText(stageSel),
            responsible: String(resp.value || "").trim(),
            responsible_id: d.respPick && d.respPick.id ? d.respPick.id : "",
            deadline: due.value || "",
            note_id: noteId,
            focus_key: f.key || "",
          }),
        })
          .then(function (r) {
            var ext = (r && r.external) || {};
            showTrackerCreatedToast(tracker, ext);
            // Пункт закрыт ссылкой на задачу в трекере; в заметке — пометка со ссылкой.
            return focusRunOp(aid, f, { op: "link", url: ext.url, title: text }, "");
          })
          .catch(function (e) {
            b.disabled = false;
            err.textContent = (e && e.message) || "Не удалось создать задачу";
            err.classList.remove("hidden");
          });
      })
    );
    acts.appendChild(focusBtn("Отмена", "is-ghost", function () {
      focusSetUi(aid, { mode: "view", draft: {} });
    }));
    wrap.appendChild(acts);
    return wrap;
  }

  var focusTaskSearchCache = null;
  function focusLoadTasks() {
    if (focusTaskSearchCache) return Promise.resolve(focusTaskSearchCache);
    var from = new Date(Date.now() - 45 * 864e5).toISOString().slice(0, 10);
    var to = new Date(Date.now() + 90 * 864e5).toISOString().slice(0, 10);
    return apiFetch("/calendar/tasks?start=" + from + "&end=" + to, { method: "GET" }).then(function (res) {
      focusTaskSearchCache = (res && res.tasks) || [];
      setTimeout(function () {
        focusTaskSearchCache = null;
      }, 60000);
      return focusTaskSearchCache;
    });
  }

  function focusLinkForm(aid, f) {
    var ui = focusUiFor(aid);
    var wrap = focusEl("div", "focus-chat-link");
    var inp = document.createElement("input");
    inp.type = "search";
    inp.className = "focus-chat-search";
    inp.placeholder = "Найти задачу в Орбите или вставить ссылку";
    inp.value = ui.draft.q || "";
    wrap.appendChild(inp);
    var list = focusEl("div", "focus-chat-results");
    wrap.appendChild(list);
    function words(q) {
      return String(q || "").toLowerCase().split(/\s+/).filter(Boolean);
    }
    function render() {
      var q = inp.value.trim();
      ui.draft.q = q;
      list.innerHTML = "";
      if (/^https?:\/\/\S+$/i.test(q)) {
        list.appendChild(
          focusBtn("Связать со ссылкой " + q.replace(/^https?:\/\//i, "").slice(0, 60), "focus-chat-result", function (b) {
            b.disabled = true;
            focusRunOp(aid, f, { op: "link", url: q }, "Связал с задачей");
          }, "link")
        );
        return;
      }
      list.appendChild(focusEl("div", "focus-chat-menu-head", "Задачи Орбиты"));
      focusLoadTasks()
        .then(function (tasks) {
          var w = words(q || f.text).slice(0, 6);
          var scored = tasks
            .filter(function (t) {
              return !t.done;
            })
            .map(function (t) {
              var title = String(t.title || "").toLowerCase();
              var hit = w.filter(function (x) {
                return x.length > 2 && title.indexOf(x.slice(0, 5)) >= 0;
              }).length;
              return [hit, t];
            })
            .filter(function (x) {
              return q ? x[0] > 0 : x[0] > 0;
            })
            .sort(function (a, b) {
              return b[0] - a[0];
            })
            .slice(0, 5);
          scored.forEach(function (x) {
            var t = x[1];
            var who = t.assignee_name || (t.assignee && t.assignee.name) || "";
            list.appendChild(
              focusBtn((t.title || "Задача") + (who ? " · " + who : ""), "focus-chat-result", function (b) {
                b.disabled = true;
                focusRunOp(aid, f, { op: "link", task_id: t.id, title: t.title || "" }, "Связал с задачей");
              }, "taskBox")
            );
          });
          if (!scored.length) list.appendChild(focusEl("div", "focus-chat-hint", q ? "Ничего не нашлось" : "Начните вводить название"));
          list.appendChild(
            focusBtn("Создать задачу «" + String(f.text || "").slice(0, 40) + "»", "focus-chat-result is-ghost", function (b) {
              if (fstackOwns(aid)) {
                focusSetUi(aid, { mode: "task", menu: "", draft: {} });
                return;
              }
              b.disabled = true;
              var prompt =
                "Поставь задачу «" + f.text + "» исполнителю " + (f.assignee || "мне") + (f.deadline ? " на " + f.deadline : "") +
                ". Если исполнителя нет в контактах, поставь мне и скажи.";
              submitNoteGptQuestion(prompt).then(function () {
                focusRunOp(aid, f, { op: "converted" });
              });
            }, "plus")
          );
        })
        .catch(function () {});
    }
    var timer = null;
    inp.addEventListener("input", function () {
      clearTimeout(timer);
      timer = setTimeout(render, 200);
    });
    render();
    var acts = focusEl("div", "focus-chat-acts");
    acts.appendChild(focusBtn("Назад", "is-ghost", function () {
      focusSetUi(aid, { mode: "view", draft: {} });
    }));
    wrap.appendChild(acts);
    return wrap;
  }

  var FOCUS_CHAT_TYPE_ICON = { task: ["taskBox", "blue"], promise: ["people", "blue"], reminder: ["bell", "amber"], decision: ["check", "violet"], thought: ["spark", "violet"] };
  var FOCUS_STATUS_TONE = { completed: ["check", "green"], converted: ["taskBox", "green"], linked: ["link", "blue"], snoozed: ["clock", "amber"], dismissed: ["x", "gray"], retyped: ["spark", "violet"] };

  function focusChatHead(ico, tone, label, sub, extra) {
    var head = focusEl("div", "focus-card-head");
    var tile = focusEl("span", "focus-card-ico is-" + tone);
    tile.innerHTML = DISCUSS_ICONS[ico] || DISCUSS_ICONS.spark;
    head.appendChild(tile);
    var kind = focusEl("span", "focus-card-kind");
    kind.appendChild(focusEl("span", "focus-card-kind-label", label));
    if (sub) kind.appendChild(focusEl("span", "focus-card-kind-due", sub));
    head.appendChild(kind);
    if (extra) head.appendChild(extra);
    return head;
  }

  function focusChatFoot(f) {
    var src = f.source || {};
    var text = src.title || src.label || "";
    if (!text) return null;
    var isLink = focusSourceOpenable(src);
    var foot = focusEl(isLink ? "button" : "div", "focus-card-foot" + (isLink ? " is-link" : ""));
    var ic = focusEl("span", "focus-card-foot-ico");
    ic.innerHTML = DISCUSS_ICONS[src.kind === "chat" ? "chat" : src.note_kind === "transcription" ? "mic" : "note"] || "";
    foot.appendChild(ic);
    foot.appendChild(focusEl("span", "focus-card-foot-text", text));
    if (isLink) {
      foot.type = "button";
      foot.title = src.kind === "chat" ? "Открыть сообщение" : "Открыть источник";
      var chev = focusEl("span", "focus-card-foot-chev");
      chev.innerHTML = DISCUSS_ICONS.right;
      foot.appendChild(chev);
      foot.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        focusOpenSource(src);
      });
    }
    return foot;
  }

  function focusCardBtn(label, cls, fn, icon) {
    var b = focusBtn(label, "", fn, icon);
    b.className = "focus-card-btn" + (cls ? " " + cls : "");
    return b;
  }

  // «Ещё» у пункта: сменить тип или скрыть с причиной (в чате и в стопке «Разобрать»).
  function focusMoreMenuItems(aid, f) {
    var retype = function (t, label) {
      return { label: label, fn: function () { focusRunOp(aid, f, { op: "retype", type: t }, "Тип изменён: " + label.toLowerCase()); } };
    };
    var hide = function (r) {
      return { label: FOCUS_REASON_LABEL[r], fn: function () { focusRunOp(aid, f, { op: "dismiss", reason: r }, "Скрыто: " + FOCUS_REASON_LABEL[r].toLowerCase()); } };
    };
    return [
      { head: "Это не задача, а…" },
      retype("promise", "Обещание"),
      retype("decision", "Решение"),
      { label: "Напоминание", fn: function () { focusSetUi(aid, { mode: "remind_date", menu: "" }); } },
      retype("thought", "Мысль"),
      { head: "Скрыть" },
      hide("not_a_task"),
      hide("not_relevant"),
      hide("duplicate"),
      hide("recognition_error"),
    ];
  }

  function focusSnoozeMenuItems(aid, f) {
    return [
      { head: "Отложить" },
      { label: "Завтра, 9:00", fn: function () { focusRunOp(aid, f, { op: "snooze", until: focusAt(1, 9).toISOString() }, "Вернётся завтра в 9:00"); } },
      { label: "В понедельник, 9:00", fn: function () { focusRunOp(aid, f, { op: "snooze", until: focusAt(0, 9, 1).toISOString() }, "Вернётся в понедельник"); } },
      { label: "Через неделю", fn: function () { focusRunOp(aid, f, { op: "snooze", until: focusAt(7, 9).toISOString() }, "Вернётся через неделю"); } },
      { label: "Выбрать дату…", fn: function () { focusSetUi(aid, { mode: "snooze_date", menu: "" }); } },
    ];
  }

  // Пункт разбора — тот же компонент, что карточка в «Фокусе»: плитка, тип, заголовок, кнопки, футер-источник.
  function focusItemCard(aid, f, opts) {
    opts = opts || {};
    var ui = focusUiFor(aid);
    var card = focusEl("div", "focus-card is-wide focus-chat-card");
    var who = [f.assignee, f.deadline ? "до " + fstackDue(f.deadline) : ""].filter(Boolean).join(" · ");
    var line = focusStatusLine(f);
    if (line) {
      var tone = FOCUS_STATUS_TONE[f.status] || ["check", "green"];
      card.classList.add("is-closed");
      card.appendChild(focusChatHead(tone[0], tone[1], line[1], (opts.num ? opts.num + " · " : "") + who));
      card.appendChild(focusEl("b", "focus-card-title is-muted", f.text));
      var taskId = !f.shared && f.link && f.link.task_id; // задача другого участника — у него
      if ((f.status === "converted" || f.status === "linked") && taskId) {
        // Поставленная / связанная задача: карточка открывает саму задачу.
        card.classList.add("is-openable");
        card.addEventListener("click", function (e) {
          if (e.target && e.target.closest && e.target.closest("button, a, input, .focus-card-foot")) return;
          openTaskFromChip(String(taskId));
        });
      }
      if (opts.mine && !f.shared) {
        var cacts = focusEl("div", "focus-card-acts");
        if ((f.status === "converted" || f.status === "linked") && taskId) {
          cacts.appendChild(focusCardBtn("Открыть задачу", "is-soft", function () {
            openTaskFromChip(String(taskId));
          }, "taskBox"));
        } else if (f.status === "linked" && f.link && f.link.url) {
          cacts.appendChild(focusCardBtn("Открыть", "is-soft", function () {
            openExternal(f.link.url);
          }, "link"));
        }
        cacts.appendChild(focusCardBtn("Отменить", "", function (b) {
          b.disabled = true;
          focusRunOp(aid, f, { op: "undo" }, "Отменено");
        }, "undo"));
        card.appendChild(cacts);
      }
      var cfoot = focusChatFoot(f);
      if (cfoot) card.appendChild(cfoot);
      else card.classList.add("no-foot");
      return card;
    }
    var tui = FOCUS_TYPE_UI[f.type] || FOCUS_TYPE_UI.task;
    var ticon = FOCUS_CHAT_TYPE_ICON[f.type] || FOCUS_CHAT_TYPE_ICON.task;
    var more = null;
    if (opts.mine) {
      more = focusBtn("", "", function () {
        focusSetUi(aid, { menu: ui.menu === "more" ? "" : "more" });
      }, "dots");
      more.className = "focus-card-x focus-card-more" + (ui.menu === "more" ? " is-open" : "");
      more.setAttribute("aria-label", "Ещё");
      more.title = "Ещё";
    }
    card.appendChild(focusChatHead(ticon[0], ticon[1], tui[1] + (opts.num ? " " + opts.num : ""), who, more));
    card.appendChild(focusEl("b", "focus-card-title", f.text));
    if (f.comment || (f.state && f.state !== "open")) {
      card.appendChild(
        focusEl("div", "focus-card-note", [FOCUS_STATE_LABEL[f.state] && f.state !== "open" ? FOCUS_STATE_LABEL[f.state] : "", f.comment].filter(Boolean).join(" · "))
      );
    }
    if (opts.mine && ui.menu === "more") card.appendChild(focusMenu(focusMoreMenuItems(aid, f)));
    if (opts.mine && ui.mode === "task") card.appendChild(focusTaskForm(aid, f));
    else if (opts.mine && ui.mode === "link") card.appendChild(focusLinkForm(aid, f));
    else if (opts.mine && (ui.mode === "snooze_date" || ui.mode === "remind_date")) card.appendChild(focusDatePicker(aid, f, ui.mode === "remind_date" ? "remind" : "snooze"));
    else if (opts.mine) {
      var acts = focusEl("div", "focus-card-acts");
      acts.appendChild(focusCardBtn("Выполнено", "is-primary", function (b) {
        b.disabled = true;
        focusRunOp(aid, f, { op: "done" }, "Отмечено выполненным");
      }, "check"));
      // «В задачу» — форма постановки; шеврон — «Отложить» (завтра, понедельник, через неделю, дата).
      var split = focusEl("span", "focus-card-split");
      split.appendChild(focusCardBtn("В задачу", "is-soft", function () {
        // «В задачу» везде одно и то же — карточка задачи с правкой (как в «Разобрать»).
        openFocusStack({ key: f.card_key || f.key }, "stack", { task: true, items: [f] });
      }));
      var chev = focusCardBtn("", "is-soft focus-card-chev" + (ui.menu === "snooze" ? " is-open" : ""), function () {
        focusSetUi(aid, { menu: ui.menu === "snooze" ? "" : "snooze" });
      }, "down");
      chev.setAttribute("aria-label", "Отложить");
      chev.title = "Отложить";
      split.appendChild(chev);
      acts.appendChild(split);
      acts.appendChild(focusCardBtn("Связать", "is-soft", function () {
        focusSetUi(aid, { mode: "link", menu: "", draft: {} });
      }));
      card.appendChild(acts);
      if (ui.menu === "snooze") card.appendChild(focusMenu(focusSnoozeMenuItems(aid, f)));
    }
    var foot = focusChatFoot(f);
    if (foot) card.appendChild(foot);
    else card.classList.add("no-foot");
    return card;
  }

  // Задачи встречи в чате у нескольких участников: опрашиваем их состояние, пока карточки на экране,
  // — кто-то поставил, выполнил или поправил задачу, у остальных это видно через пару секунд.
  var FOCUS_LIVE_MS = 3000;
  var focusLiveTimer = null;

  function focusLiveIds() {
    return Object.keys(calActionsCache).filter(function (k) {
      var a = calActionsCache[k];
      return a && a.kind === "focus_item" && (a.focus || []).some(function (f) {
        return f.source && f.source.kind === "note";
      });
    }).slice(-50);
  }

  function ensureFocusLive() {
    if (!focusLiveTimer) focusLiveTimer = setTimeout(tickFocusLive, FOCUS_LIVE_MS);
  }

  function tickFocusLive() {
    focusLiveTimer = null;
    if (!document.querySelector(".focus-chat-card")) return; // карточек на экране нет — опрос останавливается
    var ids = focusLiveIds();
    if (!ids.length) return;
    if (document.hidden) {
      ensureFocusLive();
      return;
    }
    apiFetch("/gpt/calendar-actions/status", { method: "POST", body: JSON.stringify({ ids: ids }) })
      .then(function (res) {
        var ae = document.activeElement;
        var typing = ae && ae.closest && ae.closest(".focus-chat-card") && /^(INPUT|TEXTAREA|SELECT)$/.test(ae.tagName);
        var changed = false;
        ((res && res.actions) || []).forEach(function (a) {
          var cur = calActionsCache[a.id];
          if (!a || !a.id || !cur || JSON.stringify(cur.focus || []) === JSON.stringify(a.focus || [])) return;
          if (typing) return; // не сбивать ввод в форме — подтянем следующим тиком
          calActionsCache[a.id] = a;
          changed = true;
        });
        if (changed) refreshDiscussFeedNow();
      })
      .catch(function () {})
      .then(ensureFocusLive);
  }

  // Под пузырём ответа: каждый пункт — отдельная карточка, сразу с действиями.
  function renderFocusChatCard(a) {
    if ((a.focus || []).some(function (f) { return f.source && f.source.kind === "note"; })) ensureFocusLive();
    var items = a.focus || [];
    var box = focusEl("div", "focus-chat");
    if (!items.length) {
      box.appendChild(focusEl("div", "focus-chat-hint", "Пункт уже неактуален"));
      return box;
    }
    items.forEach(function (f, i) {
      var aid = items.length > 1 ? a.id + "|" + f.key : a.id;
      box.appendChild(focusItemCard(aid, f, { mine: a.mine, num: items.length > 1 ? i + 1 + " из " + items.length : "" }));
    });
    var open = items.filter(function (f) {
      return f.status === "new";
    });
    if (a.mine && open.length > 1) {
      var all = focusCardBtn("Отметить все выполненными", "focus-chat-all", function (b) {
        b.disabled = true;
        Promise.all(
          open.map(function (f) {
            return focusItemOp(f.key, { op: "done" }).then(function (res) {
              if (res && res.item) focusApplyItem(res.item);
            });
          })
        )
          .then(function () {
            showNoteToast("Отмечено выполненными: " + open.length);
          })
          .catch(function (e) {
            showNoteToast((e && e.message) || "Не получилось");
          });
      }, "check");
      box.appendChild(all);
    }
    return box;
  }

  function appendFocusChatCards(item, ids) {
    (ids || []).forEach(function (id) {
      var a = calActionsCache[id];
      if (a && !a.missing && a.kind === "focus_item") item.appendChild(renderFocusChatCard(a));
    });
  }

  function calMarkerIds(text) {
    var m = String(text || "").match(CAL_MARKER_RE);
    return m ? m[1].split(",").filter(Boolean) : [];
  }

  function discussDisplayBody(body, quote) {
    var text = stripCalMarker(String(body || ""));
    var q = String(quote || "").trim();
    if (!q || !text) return text;
    // Старые сообщения клали «цитату» прямо в body — убираем из бабла.
    var escaped = q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    var re = new RegExp(
      "^(?:Про текст:\\s*)?[«\"]" + escaped + "[»\"]\\s*(?:\\n+|$)",
      "i"
    );
    return text.replace(re, "").replace(/^\s+/, "");
  }

  function findDiscussReplyTargetId(comment) {
    var pid = Number(comment && comment.parent_id) || 0;
    if (pid > 0) return pid;
    return findDiscussMessageByQuote(splitDiscussQuote((comment && comment.quote) || "").text, comment && comment.id);
  }

  // Сообщение выше по ленте, где есть этот текст (откуда взята цитата); 0 — не нашли.
  function findDiscussMessageByQuote(quoteText, beforeId) {
    var quote = String(quoteText || "")
      .replace(/\s+/g, " ")
      .trim()
      .toLowerCase();
    if (!quote) return 0;
    var myId = Number(beforeId) || 0;
    var panel = document.getElementById("note-editor-comments");
    var rows = discussionComments((panel && panel._allComments) || []);
    var best = 0;
    for (var i = 0; i < rows.length; i++) {
      var row = rows[i];
      var id = Number(row && row.id) || 0;
      if (!id || id === myId || (myId > 0 && id > myId)) continue;
      var body = discussDisplayBody(String((row && row.body) || ""), String((row && row.quote) || "").trim())
        .replace(/\s+/g, " ")
        .trim()
        .toLowerCase();
      if (!body) continue;
      if (body.indexOf(quote) >= 0 || quote.indexOf(body) >= 0) best = id;
    }
    return best;
  }

  // Мигнуть конкретным фрагментом дважды (CSS Highlight API; без него — подсветка блока).
  function flashTextRange(range, fallbackEl) {
    var hasHL = typeof Highlight !== "undefined" && window.CSS && CSS.highlights;
    var steps = [true, false, true, false];
    var i = 0;
    clearTimeout(flashTextRange._t);
    function tick() {
      var on = steps[i++];
      if (hasHL && range) {
        if (on) CSS.highlights.set("leo-flash", new Highlight(range));
        else CSS.highlights.delete("leo-flash");
      } else if (fallbackEl) {
        fallbackEl.classList.toggle("is-flash", !!on);
      }
      if (i < steps.length) flashTextRange._t = setTimeout(tick, on ? 420 : 260);
    }
    tick();
  }

  function jumpToDiscussReplyTarget(replyToId, quote) {
    var id = Number(replyToId) || 0;
    if (!id) return false;
    scrollDiscussionToComment(id);
    var msg = document.querySelector(
      '#note-discussion-messages [data-comment-id="' + String(id) + '"]'
    );
    var bubble = msg && msg.querySelector(".note-discuss-bubble");
    var q = String(quote || "").trim();
    if (!bubble || !q) return true;
    var api = window.NoteComments;
    if (api && api.rangeForAnchor) {
      try {
        var range = api.rangeForAnchor(bubble, q, "", "");
        if (range) {
          var node = range.startContainer;
          var el = node && (node.nodeType === 1 ? node : node.parentElement);
          if (el && el.scrollIntoView) {
            el.scrollIntoView({ block: "center", behavior: "smooth" });
          }
          setTimeout(function () {
            flashTextRange(range, bubble);
          }, 250);
          return true;
        }
      } catch (_) {}
    }
    setTimeout(function () {
      flashTextRange(null, bubble);
    }, 250);
    return true;
  }

  // Реплай на фрагмент заметки: прокрутить заметку к нему и мигнуть выделением.
  function jumpToNoteQuote(comment, quote) {
    var api = window.NoteComments;
    var root = noteEditorCommentRoot();
    var q = String(quote || "").trim();
    if (!api || !api.rangeForAnchor || !root || !q) return false;
    var range = null;
    try {
      range = api.rangeForAnchor(root, q, (comment && comment.prefix) || "", (comment && comment.suffix) || "");
    } catch (_) {}
    if (!range) {
      showNoteToast("Этого фрагмента в заметке уже нет");
      return false;
    }
    if (isMobileNoteLayout() && isNoteDiscussionOpen()) closeNoteDiscussion();
    var node = range.startContainer;
    var el = node && (node.nodeType === 1 ? node : node.parentElement);
    if (el && el.scrollIntoView) el.scrollIntoView({ block: "center", behavior: "smooth" });
    setTimeout(function () {
      flashTextRange(range, el);
    }, 350);
    return true;
  }

  function appendDiscussReplyQuote(host, quote, who, replyToId) {
    var q = String(quote || "").trim();
    if (!host || !q) return;
    var reply = document.createElement("div");
    reply.className = "note-discuss-reply" + (replyToId ? " is-nav" : "");
    reply.setAttribute("aria-label", "Ответ на цитату");
    if (replyToId) {
      reply.setAttribute("role", "button");
      reply.setAttribute("tabindex", "0");
      reply.setAttribute("data-reply-to", String(replyToId));
      reply.title = "Перейти к сообщению";
    }
    var bar = document.createElement("span");
    bar.className = "note-discuss-reply-bar";
    bar.setAttribute("aria-hidden", "true");
    var copy = document.createElement("div");
    copy.className = "note-discuss-reply-copy";
    var whoEl = document.createElement("p");
    whoEl.className = "note-discuss-reply-who";
    whoEl.textContent = who || "Фрагмент";
    var quoteEl = document.createElement("p");
    quoteEl.className = "note-discuss-reply-quote";
    quoteEl.textContent = q;
    copy.appendChild(whoEl);
    copy.appendChild(quoteEl);
    reply.appendChild(bar);
    reply.appendChild(copy);
    if (replyToId) {
      function go(e) {
        e.preventDefault();
        e.stopPropagation();
        jumpToDiscussReplyTarget(replyToId, q);
      }
      reply.addEventListener("click", go);
      reply.addEventListener("keydown", function (e) {
        if (e.key === "Enter" || e.key === " ") go(e);
      });
    }
    host.appendChild(reply);
  }

  function renderDiscussionMessage(c) {
    var item = document.createElement("article");
    var assistant = isAssistantComment(c);
    var mine = !assistant && isMineDiscussionComment(c);
    var api = window.NoteComments;
    var isGpt = !!(api && api.isGptComment && api.isGptComment(c));
    var isResearch = !!(api && api.isResearchComment && api.isResearchComment(c));
    item.className =
      "note-discuss-msg " +
      (assistant ? "is-assistant" : mine ? "is-user" : "is-other") +
      (isGpt ? " is-gpt" : "") +
      (isResearch ? " is-research" : "");
    item.setAttribute("data-comment-id", String(c.id));
    var role = document.createElement("p");
    role.className = "note-discuss-role";
    var authorLabel = discussionAuthorLabel(c);
    if (isGpt) {
      var em = document.createElement("em");
      em.textContent = "Ассистент";
      role.appendChild(em);
      if (authorLabel && !/^gpt$/i.test(authorLabel)) role.appendChild(document.createTextNode(" · " + authorLabel));
    } else if (isResearch) {
      var emR = document.createElement("em");
      emR.textContent = "Исследование";
      role.appendChild(emR);
    } else {
      role.textContent = authorLabel;
    }
    item.appendChild(role);
    // Аватар: у ИИ — фиолетовый ✨, у коллег — буква имени.
    if (assistant || !mine) {
      var av = document.createElement("span");
      av.className = "note-discuss-av" + (assistant ? " is-ai" : "");
      if (assistant) av.innerHTML = DISCUSS_ICONS.spark;
      else {
        var nm = String(authorLabel || "?").replace(/^@/, "");
        av.textContent = (nm.charAt(0) || "?").toUpperCase();
        var hue = 0;
        for (var hi = 0; hi < nm.length; hi++) hue = (hue * 31 + nm.charCodeAt(hi)) % 360;
        av.style.background = "hsl(" + hue + " 55% 42%)";
      }
      item.appendChild(av);
    }
    var quoteSplit = splitDiscussQuote((c && c.quote) || "");
    var quoteText = String(quoteSplit.text || "").trim();
    var bodyText = discussDisplayBody(String((c && c.body) || ""), quoteText);
    var attachments = (c && c.attachments) || [];
    var hideClipBody = bodyText.trim() === "📎" && attachments.length;
    var bubble = document.createElement("div");
    bubble.className = "note-discuss-bubble";
    // Реплай внутри бабла (как в Telegram). У ассистента quote — контекст модели, не UI-реплай.
    if (!assistant) {
      appendDiscussCanvasChips(bubble, quoteSplit.canvas);
      if (quoteText) {
        var replyTarget = findDiscussReplyTargetId(c);
        appendDiscussReplyQuote(
          bubble,
          quoteText,
          discussReplyWhoLabel(c),
          replyTarget
        );
        // Цитата из заметки (не из сообщения): клик ведёт к фрагменту в заметке.
        if (!replyTarget) {
          var noteReply = bubble.lastElementChild;
          if (noteReply && noteReply.classList.contains("note-discuss-reply")) {
            noteReply.classList.add("is-nav");
            noteReply.setAttribute("role", "button");
            noteReply.setAttribute("tabindex", "0");
            noteReply.title = "Показать в заметке";
            noteReply.addEventListener("click", function (e) {
              e.preventDefault();
              e.stopPropagation();
              jumpToNoteQuote(c, quoteText);
            });
          }
        }
      }
    }
    if (assistant && bodyText.trim() && !hideClipBody) {
      bubble.className = "note-discuss-bubble note-discuss-bubble--md journal-summary-html";
      var mdBody = document.createElement("div");
      mdBody.className = "note-discuss-bubble-body";
      mdBody.innerHTML = wrapTablesForScroll(simpleMarkdownToHtml(bodyText));
      bubble.appendChild(mdBody);
    } else if (!hideClipBody && bodyText.trim() && isThreadedDiscussBody(bodyText)) {
      appendDiscussThreadedBody(bubble, bodyText, true, c);
    } else if (!hideClipBody && bodyText.trim()) {
      var textBody = document.createElement("div");
      textBody.className = "note-discuss-bubble-body";
      fillDiscussBodyBlocks(textBody, bodyText);
      bubble.appendChild(textBody);
    }
    renderDiscussAttachments(bubble, attachments);
    if (assistant && c && c.id) appendAiEditsInfo(bubble, c.id);
    if (assistant) appendCalendarActions(bubble, calMarkerIds(c && c.body));
    // Телефон: аватар, «Ассистент» и модель — шапкой внутри бабла (аватар слева съедал ширину ответа).
    if (assistant && bubble.childNodes.length) {
      var head = document.createElement("div");
      head.className = "note-discuss-bubble-head";
      var headAv = document.createElement("span");
      headAv.className = "note-discuss-av is-ai";
      headAv.innerHTML = DISCUSS_ICONS.spark;
      var headText = document.createElement("span");
      headText.className = "note-discuss-bubble-who";
      var headName = document.createElement("b");
      headName.textContent = isGpt ? "Ассистент" : isResearch ? "Исследование" : authorLabel || "Ассистент";
      headText.appendChild(headName);
      var headModel = isGpt && authorLabel && !/^gpt$/i.test(authorLabel) ? authorLabel : "";
      if (headModel) {
        var headSub = document.createElement("small");
        headSub.textContent = headModel;
        headText.appendChild(headSub);
      }
      head.appendChild(headAv);
      head.appendChild(headText);
      bubble.insertBefore(head, bubble.firstChild);
    }
    if (bubble.childNodes.length) item.appendChild(bubble);
    if (assistant) appendFocusChatCards(item, calMarkerIds(c && c.body));
    // Строка под сообщением: время и «···» напротив него.
    var meta = document.createElement("div");
    meta.className = "note-discuss-meta";
    var ts = Date.parse((c && c.created_at) || "");
    if (ts) {
      var time = document.createElement("span");
      time.className = "note-discuss-time";
      time.textContent = new Date(ts).toLocaleTimeString("ru-RU", { hour: "2-digit", minute: "2-digit" });
      meta.appendChild(time);
    }
    item.appendChild(meta);
    if (String((c && c.body) || "").trim() || attachments.length) {
      var actions = document.createElement("div");
      actions.className = "note-discuss-actions";
      var more = document.createElement("button");
      more.type = "button";
      more.className = "note-discuss-more";
      more.setAttribute("aria-label", "Ещё");
      more.title = "Ещё";
      more.setAttribute("aria-expanded", "false");
      more.innerHTML = DISCUSS_ICONS.dots;
      var menu = document.createElement("div");
      menu.className = "note-discuss-menu hidden";
      menu.innerHTML =
        discussMenuItem("reply", "reply", "Ответить") +
        discussMenuItem("task", "task", "Создать задачу") +
        discussMenuItem("into-note", "note", "В заметку") +
        discussMenuItem("create-note", "note", "Создать заметку") +
        discussMenuItem("link", "link", "Связать с заметкой") +
        discussMenuItem("copy", "copy", "Копировать") +
        discussMenuItem("delete", "trash", "Удалить", "note-discuss-menu-item--danger");
      actions.appendChild(more);
      actions.appendChild(menu);
      bindNoteAnswerMenu(more, menu, c);
      meta.appendChild(actions);
      bindDiscussLongPress(item, more, menu);
    }
    item.addEventListener("click", function (e) {
      var link = e.target && e.target.closest && e.target.closest("a[href]");
      if (link) {
        var href = String(link.getAttribute("href") || "").trim();
        var inAppNoteId = inAppNoteIdFromHref(href);
        if (inAppNoteId) {
          e.preventDefault();
          e.stopPropagation();
          openNoteByIdInApp(inAppNoteId);
          return;
        }
        if (/^https?:\/\//i.test(href) || /^tg:\/\//i.test(href)) {
          e.preventDefault();
          e.stopPropagation();
          openExternal(href);
        }
        return;
      }
      if (
        e.target &&
        e.target.closest &&
        e.target.closest(".note-discuss-more, .note-discuss-menu, .note-discuss-reply, #note-discuss-selection")
      ) {
        return;
      }
      // Поля и кнопки карточек под ответом (Фокус: «В задачу», «Связать»…) — не «показать тему»:
      // на телефоне это закрывало чат при касании поля.
      if (
        e.target &&
        e.target.closest &&
        e.target.closest("input, textarea, select, button, label, .focus-chat, .meeting-attendee-suggest")
      ) {
        return;
      }
      var sel = window.getSelection && window.getSelection();
      if (sel && !sel.isCollapsed) return;
      // Отдельный чат (Ассистент на «Актуальном» и т.п.) — показывать в заметке нечего; на телефоне
      // тап по сообщению закрывал чат.
      var dw = discussWrap();
      if (dw && dw._shareKind === "chat") return;
      revealNoteDiscussionTopic(c, { fromDiscussion: true });
    });
    return item;
  }

  // Телефон: долгое нажатие на сообщение — шторка с действиями.
  function bindDiscussLongPress(item, more, menu) {
    var timer = null;
    var sx = 0;
    var sy = 0;
    item.addEventListener(
      "touchstart",
      function (e) {
        if (e.touches.length !== 1) return;
        if (e.target.closest && e.target.closest("a, button, input, textarea, select, label, .note-discuss-edits, .focus-chat")) return;
        sx = e.touches[0].clientX;
        sy = e.touches[0].clientY;
        clearTimeout(timer);
        timer = setTimeout(function () {
          timer = null;
          item._longPressed = true;
          try {
            if (navigator.vibrate) navigator.vibrate(10);
            if (window.Telegram && Telegram.WebApp && Telegram.WebApp.HapticFeedback) {
              Telegram.WebApp.HapticFeedback.impactOccurred("medium");
            }
          } catch (_) {}
          closeNoteAnswerMenu();
          menu.classList.add("is-sheet");
          menu.classList.remove("hidden");
          more.setAttribute("aria-expanded", "true");
          item.classList.add("is-pressed");
        }, 450);
      },
      { passive: true }
    );
    function cancel(e) {
      if (!timer) return;
      if (e && e.touches && e.touches[0]) {
        var dx = Math.abs(e.touches[0].clientX - sx);
        var dy = Math.abs(e.touches[0].clientY - sy);
        if (dx < 8 && dy < 8) return;
      }
      clearTimeout(timer);
      timer = null;
    }
    item.addEventListener("touchmove", cancel, { passive: true });
    item.addEventListener("touchend", function () {
      cancel();
    });
    item.addEventListener("contextmenu", function (e) {
      if (item._longPressed) e.preventDefault();
    });
    item.addEventListener(
      "click",
      function (e) {
        if (!item._longPressed) return;
        item._longPressed = false;
        e.preventDefault();
        e.stopPropagation();
      },
      true
    );
  }

  function discussDayLabel(ts) {
    var d = new Date(ts);
    var today = new Date();
    var y = new Date();
    y.setDate(today.getDate() - 1);
    if (d.toDateString() === today.toDateString()) return "Сегодня";
    if (d.toDateString() === y.toDateString()) return "Вчера";
    return d.toLocaleDateString("ru-RU", d.getFullYear() === today.getFullYear()
      ? { day: "numeric", month: "long" }
      : { day: "numeric", month: "long", year: "numeric" });
  }

  function discussAuthorKey(c) {
    if (isAssistantComment(c)) return "ai:" + String((c && c.author_name) || "") + ":" + String((c && c.prefix) || "");
    if (isMineDiscussionComment(c)) return "me";
    return "u:" + String((c && (c.author_user_id || c.author_username || c.author_name)) || "?");
  }

  // Пустой чат: подсказки по заметке — нажатие подставляет запрос в поле.
  function renderDiscussEmptyState(chatNow) {
    var box = document.createElement("div");
    box.className = "note-discussion-empty note-discuss-empty";
    if (chatNow === COMMENTS_CHAT_ID) {
      box.innerHTML = '<span class="note-discuss-empty-ico is-people">' + DISCUSS_ICONS.people + "</span>";
      var h = document.createElement("h4");
      h.textContent = "Комментариев пока нет";
      var p = document.createElement("p");
      p.textContent = "Их видят все участники заметки. ИИ здесь не отвечает.";
      box.appendChild(h);
      box.appendChild(p);
      return box;
    }
    box.innerHTML = '<span class="note-discuss-empty-ico">' + DISCUSS_ICONS.spark + "</span>";
    var title = document.createElement("h4");
    var wrapKind = document.getElementById("note-editor-more-wrap");
    var isChatThread = !!(wrapKind && wrapKind._shareKind === "chat");
    if (isChatThread) {
      // Отдельный чат с Ассистентом (из «Сохранённое → Чаты» или «+» на «Актуальном»).
      title.textContent = "Чем помочь?";
      var hintChat = document.createElement("p");
      hintChat.textContent = "Ассистент видит ваш календарь, задачи и контакты — может найти время, поставить встречу или задачу.";
      box.appendChild(title);
      box.appendChild(hintChat);
      if (
        document.documentElement.classList.contains("actual-assistant-open") &&
        focusItems.length &&
        !focusPanelOpen
      ) {
        // Короткие чипы, пока полный список «Фокуса» не раскрыт в этой же ленте.
        var focusChips = document.createElement("div");
        focusChips.className = "note-discuss-sugg note-discuss-sugg--focus";
        focusItems.slice(0, 3).forEach(function (it) {
          var fb = document.createElement("button");
          fb.type = "button";
          var tt = String(it.title || "");
          fb.textContent = (it.tag ? it.tag.split(" ")[0] + " " : "") + (tt.length > 48 ? tt.slice(0, 47) + "…" : tt);
          fb.addEventListener("click", function (e) {
            e.preventDefault();
            e.stopPropagation();
            askAboutFocus(it);
          });
          focusChips.appendChild(fb);
        });
        box.appendChild(focusChips);
      }
      var chatChips = document.createElement("div");
      chatChips.className = "note-discuss-sugg";
      ["Что у меня сегодня?", "Найди время для встречи", "Поставь задачу", "На что ушло время на этой неделе?"].forEach(function (t) {
        var b = document.createElement("button");
        b.type = "button";
        b.textContent = t;
        b.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          var ed = noteGptEditor();
          if (!ed) return;
          ed.textContent = /^(Найди время|Поставь задачу)/.test(t) ? t + " " : t;
          try {
            syncGptEditorEmpty(ed);
            autosizeNoteComposer(ed);
            ed.focus();
            var sel = window.getSelection();
            var range = document.createRange();
            range.selectNodeContents(ed);
            range.collapse(false);
            sel.removeAllRanges();
            sel.addRange(range);
          } catch (_) {}
          syncNotePaieReplyForm();
        });
        chatChips.appendChild(b);
      });
      box.appendChild(chatChips);
      return box;
    }
    title.textContent = "Спросите про эту заметку";
    var hint = document.createElement("p");
    var wrap = document.getElementById("note-editor-more-wrap");
    var shared =
      chatNow === 0
        ? !(wrap && wrap._newChatVisibility === "private")
        : chatNow !== null && (noteChatById(chatNow) || {}).visibility !== "private";
    hint.textContent =
      "ИИ видит текст и таблицы заметки и может их править." + (shared ? " Чат видят все участники." : "");
    box.appendChild(title);
    box.appendChild(hint);
    var html = "";
    try {
      var left = getLeftNoteRichEditor();
      html = left && typeof left.getHtml === "function" ? left.getHtml() : "";
    } catch (_) {}
    var sugg = ["Сделай саммари", "Найди задачи и сроки", "Что упущено?"];
    if (/<table/i.test(html)) sugg.push("Проверь цифры в таблице");
    else sugg.push("Предложи следующие шаги");
    sugg.push("Нарисуй схему на доске");
    var chips = document.createElement("div");
    chips.className = "note-discuss-sugg";
    sugg.forEach(function (t) {
      var b = document.createElement("button");
      b.type = "button";
      b.textContent = t;
      b.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        var ed = noteGptEditor();
        if (!ed) return;
        ed.textContent = t;
        try {
          syncGptEditorEmpty(ed);
          autosizeNoteComposer(ed);
        } catch (_) {}
        try {
          ed.focus();
          var sel = window.getSelection();
          var range = document.createRange();
          range.selectNodeContents(ed);
          range.collapse(false);
          sel.removeAllRanges();
          sel.addRange(range);
        } catch (_) {}
        syncNotePaieReplyForm();
      });
      chips.appendChild(b);
    });
    box.appendChild(chips);
    void wrap;
    return box;
  }

  function renderNotePaieThread(comments, kind, itemId) {
    var wrap = document.getElementById("note-editor-more-wrap");
    var running = !!(wrap && wrap._paeiRunning);
    ensureNotePaieThread();
    var list = document.getElementById("note-discussion-messages");
    var form = document.getElementById("note-paie-reply-form");
    var status = document.getElementById("note-editor-paei-status");
    var statusOn = !!(status && !status.classList.contains("hidden"));
    var chatNow = currentDiscussChatId();
    var rows = discussionComments(comments).filter(inCurrentDiscussChat).slice().sort(function (a, b) {
      var at = Date.parse(a && a.created_at) || 0;
      var bt = Date.parse(b && b.created_at) || 0;
      if (at !== bt) return at - bt;
      return Number(a.id || 0) - Number(b.id || 0);
    });
    if (chatNow && isNoteDiscussionOpen()) markNoteChatSeen(chatNow, rows);
    syncNoteChatsButton();
    var gptBusy = !!(wrap && wrap._gptBusy);
    var researchRunning = !!(wrap && wrap._researchRunning);
    var fp =
      "chat:" +
      String(chatNow) +
      "|" +
      String(kind || "") +
      ":" +
      String(itemId || "") +
      "|" +
      rows
        .map(function (c) {
          return (
            String(c && c.id) +
            ":" +
            String((c && c.body) || "").length +
            ":" +
            String((c && c.quote) || "").length +
            ":" +
            String((c && c.parent_id) || "")
          );
        })
        .join("|") +
      "|g:" +
      (gptBusy ? String(wrap._gptPhase || "1") : "0") +
      "|p:" +
      (running ? "1" : "0") +
      "|r:" +
      (researchRunning ? "1" : "0") +
      "|s:" +
      (statusOn ? "1" : "0");
    if (list && list._renderFp === fp && list.childNodes.length) {
      if (form) {
        form.classList.remove("hidden");
        syncNotePaieReplyForm(running);
        syncNoteComposerCommentTarget();
      }
      // Лента уже нарисована (комментарии пришли, пока обсуждение было закрыто) — кнопку «вниз»
      // всё равно ставим, иначе её не было вовсе.
      if (isNoteDiscussionOpen()) ensureDiscussScrollDownBtn();
      return;
    }
    // Не рисовать чужой тред поверх текущего чата/заметки.
    if (kind && itemId && wrap && !isDiscussionTargetActive(kind, itemId)) {
      return;
    }
    // Пользователь печатает в поле карточки (форма «В задачу») — не пересоздаём ленту под ним:
    // на телефоне поле теряло фокус, клавиатура пряталась, и ввод сбрасывался. Дорисуем после.
    var activeEl = document.activeElement;
    if (
      list &&
      activeEl &&
      activeEl !== document.body &&
      list.contains(activeEl) &&
      /^(INPUT|TEXTAREA|SELECT)$/.test(activeEl.tagName)
    ) {
      if (!list._deferredRender) {
        list._deferredRender = true;
        activeEl.addEventListener(
          "blur",
          function () {
            setTimeout(function () {
              list._deferredRender = false;
              var nowActive = document.activeElement;
              if (nowActive && list.contains(nowActive) && /^(INPUT|TEXTAREA|SELECT)$/.test(nowActive.tagName)) {
                list._deferredRender = true;
                nowActive.addEventListener("blur", function () {
                  list._deferredRender = false;
                  refreshDiscussFeedNow();
                }, { once: true });
                return;
              }
              refreshDiscussFeedNow();
            }, 350); // после blur — дать дойти клику по кнопке формы («Поставить»), не пересоздать её раньше
          },
          { once: true }
        );
      }
      list._renderFp = null;
      return;
    }
    var scroll = document.querySelector("#note-discussion-overlay .note-discussion-scroll");
    var stickBottom = true;
    var prevTop = 0;
    // Флаг живёт недолго: он для контента, догружающегося сразу после открытия/отправки, — а не для
    // перерисовки от кнопки в карточке («…», «В задачу») спустя время (иначе лента прыгала вниз).
    var forceBottom = !!(wrap && wrap._forceDiscussScrollBottom && Date.now() < wrap._forceDiscussScrollBottom);
    if (scroll) {
      prevTop = scroll.scrollTop;
      stickBottom =
        forceBottom ||
        scroll.scrollHeight - scroll.scrollTop - scroll.clientHeight < 120;
    }
    if (forceBottom && wrap) wrap._forceDiscussScrollBottom = false;
    if (wrap && wrap._keepDiscussScroll) {
      wrap._keepDiscussScroll = false;
      if (!forceBottom) stickBottom = false;
    }
    if (list) {
      list._renderFp = fp;
      list.innerHTML = "";
      if (
        !rows.length &&
        !statusOn &&
        !running &&
        !gptBusy &&
        !researchRunning &&
        // При «Все» карточки Фокуса уже в ленте — empty-state с саджестами не нужен.
        !focusPanelOpen
      ) {
        list.appendChild(renderDiscussEmptyState(chatNow));
      } else {
        var cut = gptContextCutId();
        var prevDay = "";
        var prevRow = null;
        rows.forEach(function (c, idx) {
          var ts = Date.parse((c && c.created_at) || "") || 0;
          if (ts) {
            var dayKey = new Date(ts).toDateString();
            if (dayKey !== prevDay) {
              var day = document.createElement("div");
              day.className = "note-discuss-day";
              day.textContent = discussDayLabel(ts);
              list.appendChild(day);
              prevDay = dayKey;
              prevRow = null;
            }
          }
          var msg = renderDiscussionMessage(c);
          // Подряд от одного автора (в пределах 10 минут) — без повторного имени и аватара.
          if (prevRow && discussAuthorKey(prevRow) === discussAuthorKey(c)) {
            var pts = Date.parse((prevRow && prevRow.created_at) || "") || 0;
            if (!ts || !pts || ts - pts < 10 * 60 * 1000) msg.classList.add("is-cont");
          }
          prevRow = c;
          if (cut && Number(c.id) <= cut) msg.classList.add("is-ctx-stale");
          list.appendChild(msg);
          var next = rows[idx + 1];
          if (cut && Number(c.id) <= cut && (!next || Number(next.id) > cut)) {
            list.appendChild(renderGptContextDivider());
          }
        });
        if (gptBusy) {
          list.appendChild(renderGptPendingStatus(wrap._gptPhase));
        }
      }
    }
    if (form) {
      form.classList.remove("hidden");
      syncNotePaieReplyForm(running);
      syncNoteComposerCommentTarget();
    }
    renderNoteDiscussionCard(comments);
    refreshNoteEditorTocExtras();
    if (isNoteDiscussionOpen()) {
      var pinId = wrap && wrap._discussionPinId;
      if (pinId && !gptBusy) scrollDiscussionToComment(pinId);
      else if (stickBottom) scrollDiscussionToEnd(true);
      else if (scroll) scroll.scrollTop = prevTop;
      ensureDiscussScrollDownBtn();
    }
    void kind;
    void itemId;
  }

  function noteHasDiscussion(comments) {
    var api = window.NoteComments;
    if (api && api.hasDiscussion) return api.hasDiscussion(comments || []);
    return false;
  }

  function appendNoteDiscussionToc(tocEl, onNavigate) {
    if (!tocEl) return;
    var panel = document.getElementById("note-editor-comments");
    var comments = (panel && panel._allComments) || [];
    if (!noteHasDiscussion(comments)) return;
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "note-editor-toc-item note-editor-toc-item--level-1";
    btn.setAttribute("data-toc-discussion", "1");
    btn.textContent = "Обсуждение";
    btn.addEventListener("click", function () {
      openNoteDiscussion();
      if (typeof onNavigate === "function") onNavigate();
    });
    tocEl.appendChild(btn);
  }

  function refreshNoteEditorTocExtras() {
    var tocEl = document.querySelector("#note-editor-overlay .note-editor-toc-list");
    if (tocEl && typeof tocEl._refreshToc === "function") tocEl._refreshToc();
  }

  function noteKnowledgeStorageKey() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap || !wrap._shareKind || !wrap._shareId) return "";
    return "leo_note_kb:" + wrap._shareKind + ":" + wrap._shareId;
  }

  function noteKnowledgeIdsStorageKey() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap || !wrap._shareKind || !wrap._shareId) return "";
    return "leo_note_kb_ids:" + wrap._shareKind + ":" + wrap._shareId;
  }

  function knowledgeNotesList() {
    return (knowledgeDataCache && knowledgeDataCache.notes) || [];
  }

  function allKnowledgeNoteIds() {
    return knowledgeNotesList()
      .map(function (n) {
        return n && n.id != null ? String(n.id) : "";
      })
      .filter(Boolean);
  }

  function readStoredKnowledgeNoteIds() {
    var idsKey = noteKnowledgeIdsStorageKey();
    if (idsKey) {
      try {
        var raw = localStorage.getItem(idsKey);
        if (raw != null && raw !== "") {
          var parsed = JSON.parse(raw);
          if (Array.isArray(parsed)) {
            return {
              explicit: true,
              ids: parsed
                .map(function (id) {
                  return String(id || "").trim();
                })
                .filter(Boolean),
            };
          }
        }
      } catch (_) {}
    }
    var oldKey = noteKnowledgeStorageKey();
    if (oldKey) {
      try {
        var legacy = localStorage.getItem(oldKey);
        if (legacy === "0") return { explicit: true, ids: [] };
        if (legacy === "1") return { explicit: false, ids: [] };
      } catch (_) {}
    }
    return { explicit: false, ids: [] };
  }

  function noteKnowledgeNoteIds() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap && Array.isArray(wrap._knowledgeNoteIds)) return wrap._knowledgeNoteIds.slice();
    var stored = readStoredKnowledgeNoteIds();
    if (stored.explicit) return stored.ids.slice();
    // По умолчанию БЗ выключена, пока пользователь сам ничего не выбрал.
    return [];
  }

  function setNoteKnowledgeNoteIds(ids) {
    var next = (ids || [])
      .map(function (id) {
        return String(id || "").trim();
      })
      .filter(Boolean);
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap) wrap._knowledgeNoteIds = next;
    var idsKey = noteKnowledgeIdsStorageKey();
    if (idsKey) {
      try {
        localStorage.setItem(idsKey, JSON.stringify(next));
      } catch (_) {}
    }
    var oldKey = noteKnowledgeStorageKey();
    if (oldKey) {
      try {
        localStorage.setItem(oldKey, next.length ? "1" : "0");
      } catch (_) {}
    }
    syncNoteKnowledgeToggle();
    renderNoteKnowledgeMenu();
  }

  function toggleNoteKnowledgeNoteId(id) {
    id = String(id || "").trim();
    if (!id) return;
    var current = noteKnowledgeNoteIds();
    var next =
      current.indexOf(id) >= 0
        ? current.filter(function (x) {
            return x !== id;
          })
        : current.concat([id]);
    setNoteKnowledgeNoteIds(next);
  }

  function noteUsesKnowledge() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap && Array.isArray(wrap._knowledgeNoteIds)) return wrap._knowledgeNoteIds.length > 0;
    var stored = readStoredKnowledgeNoteIds();
    if (stored.explicit) return stored.ids.length > 0;
    return false;
  }

  function discussionKnowledgeFields() {
    var ids = noteKnowledgeNoteIds();
    var ctx = noteAskMode() === "comment" ? [] : discussContextNoteIds();
    return {
      use_knowledge: ids.length > 0,
      knowledge_note_ids: ids,
      sheet_ids: selectedContextSheetIds(),
      context_note_ids: ctx.length ? ctx : undefined,
    };
  }

  function ensureDiscussionKnowledgeNotes() {
    if (knowledgeDataCache && Array.isArray(knowledgeDataCache.notes)) {
      return Promise.resolve(knowledgeDataCache.notes);
    }
    return Promise.resolve(loadKnowledgeNotes())
      .then(function () {
        return (knowledgeDataCache && knowledgeDataCache.notes) || [];
      })
      .catch(function () {
        return [];
      });
  }

  function knowledgeNoteMenuTitle(n) {
    return (
      sanitizeNoteTitle((n && (n.title || n.content)) || "") ||
      ((n && (n.title || n.content)) || "(без названия)")
    );
  }

  function knowledgeNotesByProject() {
    var groups = [];
    var index = {};
    knowledgeNotesList().forEach(function (n) {
      var project = noteProjectOf(n);
      var key = project && project.id != null ? String(project.id) : "";
      var title = project && (project.name || project.title)
        ? String(project.name || project.title)
        : "Без проекта";
      if (!index[key]) {
        index[key] = { key: key, title: title, notes: [] };
        groups.push(index[key]);
      }
      index[key].notes.push(n);
    });
    groups.sort(function (a, b) {
      if (!a.key) return 1;
      if (!b.key) return -1;
      return String(a.title).localeCompare(String(b.title), "ru");
    });
    return groups;
  }

  function kbGroupIsOpen(key, hasSelected) {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap && wrap._kbOpenGroups && Object.prototype.hasOwnProperty.call(wrap._kbOpenGroups, key)) {
      return !!wrap._kbOpenGroups[key];
    }
    return !!hasSelected;
  }

  function setKbGroupOpen(key, open) {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap) return;
    if (!wrap._kbOpenGroups) wrap._kbOpenGroups = {};
    wrap._kbOpenGroups[key] = !!open;
  }

  function setNoteKnowledgeProjectSelection(ids, selected) {
    var want = {};
    (ids || []).forEach(function (id) {
      var sid = String(id || "").trim();
      if (sid) want[sid] = true;
    });
    var next = noteKnowledgeNoteIds().filter(function (id) {
      return !want[id];
    });
    if (selected) {
      Object.keys(want).forEach(function (id) {
        next.push(id);
      });
    }
    setNoteKnowledgeNoteIds(next);
  }

  function appendContextMenuSection(list, label) {
    var head = document.createElement("p");
    head.className = "note-paie-menu-section";
    head.textContent = label;
    list.appendChild(head);
  }

  function makeContextCheckbox(checked, indeterminate) {
    var box = document.createElement("span");
    box.className =
      "note-paie-kb-check" +
      (checked ? " is-on" : "") +
      (indeterminate ? " is-mixed" : "");
    box.setAttribute("aria-hidden", "true");
    return box;
  }

  function appendContextCheckRow(list, title, on, onClick) {
    var row = document.createElement("button");
    row.type = "button";
    row.className = "note-paie-menu-item note-paie-kb-item";
    row.setAttribute("role", "menuitemcheckbox");
    row.setAttribute("aria-checked", on ? "true" : "false");
    row.appendChild(makeContextCheckbox(on, false));
    var name = document.createElement("span");
    name.className = "note-paie-kb-item-title";
    name.textContent = title;
    row.appendChild(name);
    row.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      onClick();
    });
    list.appendChild(row);
  }

  function appendKnowledgeProjectGroup(list, group, selected) {
    var ids = group.notes
      .map(function (n) {
        return n && n.id != null ? String(n.id) : "";
      })
      .filter(Boolean);
    var selectedCount = ids.filter(function (id) {
      return !!selected[id];
    }).length;
    var allOn = ids.length > 0 && selectedCount === ids.length;
    var someOn = selectedCount > 0 && selectedCount < ids.length;
    var open = kbGroupIsOpen(group.key, selectedCount > 0);
    var wrap = document.createElement("div");
    wrap.className = "note-paie-kb-group" + (open ? " is-open" : "");
    var head = document.createElement("div");
    head.className = "note-paie-kb-group-head";
    var checkBtn = document.createElement("button");
    checkBtn.type = "button";
    checkBtn.className = "note-paie-kb-group-check";
    checkBtn.setAttribute("aria-label", allOn ? "Снять выбор проекта" : "Выбрать весь проект");
    var box = makeContextCheckbox(allOn, someOn);
    checkBtn.appendChild(box);
    checkBtn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      setNoteKnowledgeProjectSelection(ids, !allOn);
      if (!allOn) setKbGroupOpen(group.key, true);
    });
    var toggle = document.createElement("button");
    toggle.type = "button";
    toggle.className = "note-paie-kb-group-toggle";
    toggle.setAttribute("aria-expanded", open ? "true" : "false");
    var name = document.createElement("span");
    name.className = "note-paie-kb-item-title";
    name.textContent = group.title;
    var chevron = document.createElement("span");
    chevron.className = "note-paie-kb-group-chevron";
    chevron.setAttribute("aria-hidden", "true");
    chevron.innerHTML =
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>';
    toggle.appendChild(name);
    toggle.appendChild(chevron);
    toggle.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      var next = !kbGroupIsOpen(group.key, selectedCount > 0);
      setKbGroupOpen(group.key, next);
      renderNoteKnowledgeMenu();
    });
    head.appendChild(checkBtn);
    head.appendChild(toggle);
    wrap.appendChild(head);
    var body = document.createElement("div");
    body.className = "note-paie-kb-group-body";
    if (!open) body.classList.add("hidden");
    group.notes.forEach(function (n) {
      var id = n && n.id != null ? String(n.id) : "";
      if (!id) return;
      appendContextCheckRow(body, knowledgeNoteMenuTitle(n), !!selected[id], function () {
        toggleNoteKnowledgeNoteId(id);
      });
    });
    wrap.appendChild(body);
    list.appendChild(wrap);
  }

  function toggleNoteSheetContextId(id) {
    id = String(id || "").trim();
    if (!id) return;
    var current = selectedContextSheetIds();
    var next =
      current.indexOf(id) >= 0
        ? current.filter(function (x) {
            return x !== id;
          })
        : current.concat([id]);
    noteSheetState.contextExplicit = true;
    noteSheetState.contextIds = next;
    renderNoteKnowledgeMenu();
    syncNoteKnowledgeToggle();
  }

  function renderNoteKnowledgeMenu() {
    var form = document.getElementById("note-paie-reply-form");
    var list = form && form.querySelector(".note-paie-menu--kb .note-paie-menu-list");
    if (!list) return;
    list.innerHTML = "";
    if (noteSheetsEnabled() && noteSheetState.sheets.length) {
      appendContextMenuSection(list, "Листы заметки");
      var selectedSheets = {};
      selectedContextSheetIds().forEach(function (id) {
        selectedSheets[id] = true;
      });
      noteSheetState.sheets.forEach(function (s) {
        var sid = String(s.id);
        appendContextCheckRow(list, s.title || "Лист", !!selectedSheets[sid], function () {
          toggleNoteSheetContextId(sid);
        });
      });
    }
    appendContextMenuSection(list, "База знаний");
    var notes = knowledgeNotesList();
    if (!notes.length) {
      var empty = document.createElement("p");
      empty.className = "note-paie-menu-empty";
      empty.textContent = knowledgeDataCache ? "Нет документов в базе знаний" : "Загрузка…";
      list.appendChild(empty);
      return;
    }
    var selected = {};
    noteKnowledgeNoteIds().forEach(function (id) {
      selected[id] = true;
    });
    knowledgeNotesByProject().forEach(function (group) {
      appendKnowledgeProjectGroup(list, group, selected);
    });
  }

  function syncNoteKnowledgeToggle() {
    var form = document.getElementById("note-paie-reply-form");
    var btn = form && form.querySelector(".note-paie-kb-toggle");
    if (!btn) return;
    var on = noteUsesKnowledge() || selectedContextSheetIds().length > 0;
    var menu = form.querySelector(".note-paie-menu--kb");
    var open = !!(menu && !menu.classList.contains("hidden"));
    btn.classList.toggle("is-on", on);
    btn.classList.toggle("is-open", open);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.setAttribute("aria-expanded", open ? "true" : "false");
    btn.title = on
      ? "Контекст: листы и база знаний"
      : "Контекст: ничего не выбрано";
  }

  function bindNoteKnowledgeToggle(form) {
    var btn = form && form.querySelector(".note-paie-kb-toggle");
    var menu = form && form.querySelector(".note-paie-menu--kb");
    if (!btn || btn._bound) {
      syncNoteKnowledgeToggle();
      return;
    }
    btn._bound = true;
    btn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      var open = menu && menu.classList.contains("hidden");
      closeNoteComposerMenus(open ? menu : null);
      if (menu && open) {
        menu.classList.remove("hidden");
        btn.classList.add("is-open");
        btn.setAttribute("aria-expanded", "true");
        renderNoteKnowledgeMenu();
        ensureDiscussionKnowledgeNotes().then(function () {
          renderNoteKnowledgeMenu();
          syncNoteKnowledgeToggle();
        });
      }
      syncNoteKnowledgeToggle();
      syncNoteFormatToolbarForComposer();
    });
    syncNoteKnowledgeToggle();
  }

  function noteAskMode() {
    var wrap = document.getElementById("note-editor-more-wrap");
    var mode = wrap && wrap._askMode;
    if (mode === "paie" || mode === "comment" || mode === "research" || mode === "gpt") {
      return mode;
    }
    if (isCustomAskMode(mode)) return mode;
    return "gpt";
  }

  function setNoteAskMode(mode) {
    var wrap = document.getElementById("note-editor-more-wrap");
    var prev = wrap && wrap._askMode;
    var next =
      mode === "paie" || mode === "comment" || mode === "research" || mode === "gpt"
        ? mode
        : isCustomAskMode(mode)
          ? mode
          : "gpt";
    // В «Комментариях» пишут только текст; в чатах с ИИ режима «без ИИ» больше нет.
    if (isCommentsChatActive()) next = "comment";
    else if (next === "comment" && noteChatsEnabled()) next = "gpt";
    var modeChanged = next !== prev;
    if (wrap) wrap._askMode = next;
    // Не сбрасывать выбранную модель при каждом ensureNotePaieThread —
    // только при реальной смене режима (gpt ↔ свой агент ↔ comment…).
    if (modeChanged) {
      if (isCustomAskMode(next)) {
        var custom = findUserAgent(next);
        composerAgentModel = (custom && custom.model) || "";
      } else if (next === "gpt") {
        try {
          composerAgentModel = String(localStorage.getItem(GPT_MODEL_LS) || "").trim();
        } catch (_) {
          composerAgentModel = composerAgentModel || "";
        }
      } else if (next === "research") {
        var researchAgent = findUserAgent("research");
        try {
          composerAgentModel =
            String(localStorage.getItem(RESEARCH_MODEL_LS) || "").trim() ||
            (researchAgent && researchAgent.model) ||
            "";
        } catch (_) {
          composerAgentModel = (researchAgent && researchAgent.model) || "";
        }
      } else if (next === "paie") {
        var paieAgent = findUserAgent("paie");
        try {
          composerAgentModel =
            String(localStorage.getItem(PAIE_MODEL_LS) || "").trim() ||
            (paieAgent && paieAgent.model) ||
            "";
        } catch (_) {
          composerAgentModel = (paieAgent && paieAgent.model) || "";
        }
      } else {
        composerAgentModel = "";
      }
    }
    var current = noteAskMode();
    var form = document.getElementById("note-paie-reply-form");
    var el = document.getElementById("note-paie-thread");
    if (el) {
      el.querySelectorAll(".note-paie-mode, .note-paie-mode-menu [data-mode]").forEach(function (btn) {
        btn.classList.toggle("is-active", btn.getAttribute("data-mode") === current);
      });
    }
    if (form) {
      form.classList.toggle("is-gpt-mode", isChatAskMode(current));
      form.classList.toggle("is-paie-mode", current === "paie");
      form.classList.toggle("is-research-mode", current === "research");
      form.classList.toggle("is-comment-mode", current === "comment");
      syncComposerModeChip();
      if (current === "comment") showPlusMenuPage("root");
    }
    var input = document.getElementById("note-paie-reply-input");
    if (input) {
      input.placeholder = noteAskPlaceholder(current);
      autosizeNoteComposer(input);
    }
    var editor = noteGptEditor();
    if (editor) {
      editor.setAttribute("data-placeholder", noteAskPlaceholder(current));
      syncGptEditorEmpty(editor);
      autosizeNoteComposer(editor);
    }
    syncNoteComposerCommentTarget();
    if (isChatAskMode(current) || current === "research") loadGptModels();
    else if (current === "paie") loadPaieModels();
    else closeNoteComposerMenus();
    syncGptModelButton();
    syncNotePaieReplyForm();
  }

  function sheetPlainText(sheet) {
    if (!sheet) return "";
    if (isBoardSheet(sheet)) {
      var bj = String(sheet.body || sheet.description || "");
      if (String(noteSheetState.leftId) === String(sheet.id) && noteSheetState.leftBoard) bj = noteSheetState.leftBoard.getJson();
      else if (String(noteSheetState.rightId) === String(sheet.id) && noteSheetState.rightBoard) bj = noteSheetState.rightBoard.getJson();
      // Не только текст блоков: формы, цвета и связи — чтобы Лео понимал, что нарисовано.
      return window.LeoBoard ? window.LeoBoard.describe(bj) : "";
    }
    if (isPrimarySheetId(sheet.id) && isPrimarySheetId(noteSheetState.leftId)) {
      var root = noteEditorCommentRoot();
      if (root) return String(root.innerText || root.textContent || "").trim();
    }
    if (String(noteSheetState.leftId) === String(sheet.id)) {
      var left = getLeftNoteRichEditor();
      if (left && left.getHtml) {
        var node = document.createElement("div");
        node.innerHTML = left.getHtml();
        return String(node.innerText || node.textContent || "").trim();
      }
    }
    if (String(noteSheetState.rightId) === String(sheet.id) && noteSheetState.rightEditor) {
      var nodeR = document.createElement("div");
      nodeR.innerHTML = noteSheetState.rightEditor.getHtml
        ? noteSheetState.rightEditor.getHtml()
        : "";
      return String(nodeR.innerText || nodeR.textContent || "").trim();
    }
    var raw = String(sheet.body || sheet.description || "");
    var tmp = document.createElement("div");
    tmp.innerHTML = raw;
    return String(tmp.innerText || tmp.textContent || raw.replace(/<[^>]+>/g, "")).trim();
  }

  function packSelectedSheetsText(budget) {
    var lim = budget || 8000;
    var ids = selectedContextSheetIds();
    var focus = focusedNoteSheetId();
    var rows = [];
    ids.forEach(function (id) {
      var sheet = findNoteSheet(id);
      if (!sheet) return;
      var body;
      if (isWebSheet(sheet)) {
        var html = "";
        if (String(noteSheetState.leftId) === String(sheet.id) && noteSheetState.leftWebCanvas) {
          html = noteSheetState.leftWebCanvas.getHtml() || "";
        } else if (
          String(noteSheetState.rightId) === String(sheet.id) &&
          noteSheetState.rightWebCanvas
        ) {
          html = noteSheetState.rightWebCanvas.getHtml() || "";
        } else {
          html = String(sheet.body || sheet.description || "");
        }
        if (html.length > 12000) html = html.slice(0, 11999) + "…";
        body =
          "[web-canvas kind=web sheet_id=" +
          String(sheet.id) +
          "]\n" +
          html;
      } else {
        body = sheetPlainText(sheet);
      }
      rows.push({ id: String(sheet.id), title: sheet.title || "Лист", body: body });
    });
    if (!rows.length) return "";
    var focusRow = null;
    var rest = [];
    rows.forEach(function (row) {
      if (row.id === focus && !focusRow) focusRow = row;
      else rest.push(row);
    });
    if (!focusRow) {
      focusRow = rows[0];
      rest = rows.slice(1);
    }
    var focusBudget = rest.length ? Math.floor(lim * 0.7) : lim;
    var restBudget = Math.max(120, lim - focusBudget);
    function block(row, size) {
      var body = String(row.body || "");
      if (body.length > size) body = body.slice(0, size - 1) + "…";
      return "[" + (row.title || "Лист") + "]\n" + body;
    }
    var parts = [block(focusRow, focusBudget)];
    if (rest.length) {
      var each = Math.max(80, Math.floor(restBudget / rest.length));
      rest.forEach(function (row) {
        parts.push(block(row, each));
      });
    }
    var text = parts.join("\n\n");
    if (text.length > lim) text = text.slice(0, lim - 1) + "…";
    return text;
  }

  function activeNoteGptContext() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap && wrap._shareKind === "chat") {
      return { title: "", text: "", sheet_ids: [] };
    }
    var title = "";
    var titleEl = document.getElementById("note-editor-title-input");
    if (titleEl) title = String(titleEl.value || "").trim();
    var body = packSelectedSheetsText(8000);
    if (!body) {
      var root = noteEditorCommentRoot();
      body = root ? String(root.innerText || root.textContent || "").trim() : "";
      if (body.length > 8000) body = body.slice(0, 7999) + "…";
    }
    return { title: title, text: body, sheet_ids: selectedContextSheetIds() };
  }

  var GPT_COMMENT_BODY_MAX = 24000;
  var GPT_HISTORY_MAX_TURNS = 16;
  var GPT_HISTORY_MAX_CHARS = 18000;

  // ---- Чаты обсуждения заметки ----
  // У заметки несколько чатов с ИИ (видимость «Только я» / «Все участники») и общий
  // чат «Комментарии» (id -1). wrap._chatId: >0 — чат с ИИ, -1 — «Комментарии»,
  // 0 — новый чат, который создаётся на сервере при первом сообщении.
  var COMMENTS_CHAT_ID = -1;

  function discussWrap() {
    return document.getElementById("note-editor-more-wrap");
  }

  function noteChatsEnabled() {
    var wrap = discussWrap();
    return !!(
      wrap &&
      wrap._shareKind === "local" &&
      wrap._shareId &&
      String(wrap._shareId).indexOf("tmp_") !== 0
    );
  }

  function noteChatsBase() {
    var wrap = discussWrap();
    return "/notes/" + encodeURIComponent(wrap._shareKind) + "/" + encodeURIComponent(wrap._shareId) + "/chats";
  }

  function noteChatKey() {
    var wrap = discussWrap();
    return wrap ? String(wrap._shareKind || "") + ":" + String(wrap._shareId || "") : "";
  }

  function currentDiscussChatId() {
    var wrap = discussWrap();
    if (!noteChatsEnabled() || wrap._chatsFor !== noteChatKey()) return null;
    var id = Number(wrap._chatId);
    return isFinite(id) ? id : 0;
  }

  function isCommentsChatActive() {
    return currentDiscussChatId() === COMMENTS_CHAT_ID;
  }

  // Поля запроса, привязывающие сообщение к текущему чату.
  function discussChatFields() {
    var id = currentDiscussChatId();
    return id === COMMENTS_CHAT_ID || id > 0 ? { chat_id: id } : {};
  }

  // Сообщение в новый чат: сначала создаём чат на сервере.
  async function ensureDiscussChat() {
    var wrap = discussWrap();
    var id = currentDiscussChatId();
    if (id === null || id === COMMENTS_CHAT_ID || id > 0) return id;
    var res = await apiFetch(noteChatsBase(), {
      method: "POST",
      body: JSON.stringify({ visibility: wrap._newChatVisibility || "private" }),
    });
    var chat = res && res.chat;
    if (!chat || !chat.id) throw new Error("Не удалось создать чат");
    wrap._noteChats = [chat].concat(wrap._noteChats || []);
    wrap._newChatVisibility = "";
    // Без перерисовки: в ленте уже стоит отправляемое сообщение.
    setCurrentDiscussChat(Number(chat.id), { keepAsk: true, noRender: true });
    return Number(chat.id);
  }

  function inCurrentDiscussChat(c) {
    var id = currentDiscussChatId();
    if (id === null) return true;
    if (!id) return false;
    return Number(c && c.chat_id) === id;
  }

  function noteChatById(id) {
    var wrap = discussWrap();
    var list = (wrap && wrap._noteChats) || [];
    for (var i = 0; i < list.length; i++) {
      if (Number(list[i].id) === Number(id)) return list[i];
    }
    return null;
  }

  function noteChatTitle(chat) {
    if (!chat) return "Новый чат";
    if (Number(chat.id) === COMMENTS_CHAT_ID) return "Комментарии";
    var t = String(chat.title || "").trim() || String(chat.first_message || "").trim();
    if (!t) return "Новый чат";
    return t.length > 48 ? t.slice(0, 47) + "…" : t;
  }

  function currentDiscussChatTitle() {
    var id = currentDiscussChatId();
    if (id === null) return "";
    if (id === 0) return "Новый чат";
    return noteChatTitle(noteChatById(id));
  }

  function rememberDiscussChat(id) {
    try {
      localStorage.setItem("leo_note_chat:" + noteChatKey(), String(id));
    } catch (_) {}
  }

  function rememberedDiscussChat() {
    try {
      var n = parseInt(localStorage.getItem("leo_note_chat:" + noteChatKey()) || "", 10);
      return isFinite(n) ? n : null;
    } catch (_) {
      return null;
    }
  }

  function rerenderDiscussionFeed() {
    var wrap = discussWrap();
    var panel = document.getElementById("note-editor-comments");
    if (!wrap || !wrap._shareKind || !wrap._shareId) return;
    renderNotePaieThread((panel && panel._allComments) || [], wrap._shareKind, wrap._shareId);
  }

  function setCurrentDiscussChat(id, opts) {
    opts = opts || {};
    var wrap = discussWrap();
    if (!wrap || !noteChatsEnabled()) return;
    var prev = currentDiscussChatId();
    wrap._chatsFor = noteChatKey();
    wrap._chatId = Number(id) || 0;
    if (wrap._chatId) rememberDiscussChat(wrap._chatId);
    var form = document.getElementById("note-paie-reply-form");
    if (form) form.classList.toggle("is-comments-chat", wrap._chatId === COMMENTS_CHAT_ID);
    if (!opts.keepAsk) {
      if (wrap._chatId === COMMENTS_CHAT_ID) setNoteAskMode("comment");
      else if (prev === COMMENTS_CHAT_ID && noteAskMode() === "comment") setNoteAskMode("gpt");
    }
    syncNotePaneHeader();
    syncNoteChatsButton();
    if (opts.noRender) return;
    if (prev !== wrap._chatId) {
      var list = document.getElementById("note-discussion-messages");
      if (list) list._renderFp = "";
      if (wrap) wrap._forceDiscussScrollBottom = Date.now() + 1500;
    }
    rerenderDiscussionFeed();
  }

  function syncNoteChatsButton() {
    var btn = document.getElementById("note-discussion-new-ctx");
    if (!btn) return;
    var on = noteChatsEnabled();
    btn.classList.toggle("is-chats", on);
    // Чаты открываются из названия; кнопка справа — листы заметки.
    var label = on ? "Листы заметки" : "Новый контекст GPT";
    var unread = on ? noteChatsUnreadTotal() : 0;
    var badge = btn.querySelector(".note-chats-badge");
    if (badge) badge.classList.add("hidden");
    var title = document.getElementById("note-discussion-title");
    var titleBadge = title && title.querySelector(".note-title-unread");
    if (title && unread && !titleBadge) {
      titleBadge = document.createElement("span");
      titleBadge.className = "note-title-unread";
      titleBadge.setAttribute("aria-hidden", "true");
      var chev = title.querySelector(".note-pane-switch-chevron");
      if (chev && chev.parentNode) chev.parentNode.insertBefore(titleBadge, chev);
      else title.appendChild(titleBadge);
    }
    if (titleBadge) {
      titleBadge.textContent = unread > 99 ? "99+" : String(unread);
      titleBadge.classList.toggle("hidden", !unread || noteSheetState.rightMode !== "discussion");
    }
    if (title) title.setAttribute("aria-label", unread ? "Чаты: непрочитанных " + unread : "Чаты");
    btn.setAttribute("aria-label", label);
    btn.title = label;
  }

  // ---- Непрочитанные по чатам ----
  // Отметки «прочитано до сообщения N» хранятся на сервере (общие для всех устройств)
  // и приходят в списке чатов как last_seen_id; локально держим только свежие отметки,
  // ещё не вернувшиеся с сервера.
  function noteChatSeenId(chatId) {
    var wrap = discussWrap();
    if (!wrap || !wrap._noteChats || wrap._chatsFor !== noteChatKey()) return Infinity;
    var chat = noteChatById(chatId);
    var fromServer = chat && chat.last_seen_id != null ? Number(chat.last_seen_id) || 0 : 0;
    var local = (wrap._chatSeen && wrap._chatSeen[noteChatKey() + ":" + chatId]) || 0;
    return Math.max(fromServer, local);
  }

  function markNoteChatSeen(chatId, rows) {
    var wrap = discussWrap();
    var max = maxCommentId(rows || []);
    if (!wrap || !max || max <= noteChatSeenId(chatId)) return;
    var key = noteChatKey();
    wrap._chatSeen = wrap._chatSeen || {};
    wrap._chatSeen[key + ":" + chatId] = max;
    // Пачкой: при открытии чата лента может перерисоваться несколько раз подряд.
    wrap._chatSeenQueue = wrap._chatSeenQueue || {};
    wrap._chatSeenQueue[key + "|" + chatId] = max;
    clearTimeout(wrap._chatSeenTimer);
    wrap._chatSeenTimer = setTimeout(flushNoteChatSeen, 600);
  }

  function flushNoteChatSeen() {
    var wrap = discussWrap();
    var queue = (wrap && wrap._chatSeenQueue) || {};
    if (wrap) wrap._chatSeenQueue = {};
    Object.keys(queue).forEach(function (k) {
      var parts = k.split("|");
      var item = parts[0].split(":");
      apiFetch(
        "/notes/" + encodeURIComponent(item[0]) + "/" + encodeURIComponent(item.slice(1).join(":")) +
          "/chats/" + encodeURIComponent(parts[1]) + "/read",
        { method: "POST", body: JSON.stringify({ last_id: queue[k] }) }
      ).catch(function () {});
    });
  }

  // {chatId: число новых сообщений от других участников и ИИ}
  function noteChatsUnread() {
    var out = {};
    if (!noteChatsEnabled()) return out;
    var panel = document.getElementById("note-editor-comments");
    discussionComments((panel && panel._allComments) || []).forEach(function (c) {
      var chat = Number(c.chat_id);
      if (!chat || isMineDiscussionComment(c)) return;
      if (Number(c.id) > noteChatSeenId(chat)) out[chat] = (out[chat] || 0) + 1;
    });
    return out;
  }

  function noteChatsUnreadTotal() {
    var map = noteChatsUnread();
    var cur = currentDiscussChatId();
    var total = 0;
    Object.keys(map).forEach(function (id) {
      if (Number(id) !== cur || !isNoteDiscussionOpen()) total += map[id];
    });
    return total;
  }

  // Чаты заметки + выбор текущего. Сброс контекста GPT из браузера (до чатов)
  // один раз превращается в отдельный чат.
  async function loadNoteChats(kind, itemId) {
    var wrap = discussWrap();
    if (!wrap || String(kind) !== "local") return;
    var key = String(kind) + ":" + String(itemId);
    var data = await apiFetch(
      "/notes/" + encodeURIComponent(kind) + "/" + encodeURIComponent(itemId) + "/chats",
      { method: "GET" }
    );
    var live = discussWrap();
    if (!live || noteChatKey() !== key) return false;
    var chats = (data && data.chats) || [];
    var cut = gptContextCutId();
    if (cut > 0) {
      setGptContextCutId(0);
      var legacy = chats.filter(function (c) {
        return c && c.legacy;
      })[0];
      if (legacy) {
        try {
          var split = await apiFetch(
            "/notes/" + encodeURIComponent(kind) + "/" + encodeURIComponent(itemId) + "/chats/" + legacy.id + "/split",
            { method: "POST", body: JSON.stringify({ after_id: cut }) }
          );
          if (split && split.chat) return loadNoteChats(kind, itemId);
        } catch (_) {}
      }
    }
    live._noteChats = chats;
    var first = live._chatsFor !== key;
    if (first) {
      var want = rememberedDiscussChat();
      var ok =
        want === COMMENTS_CHAT_ID ||
        chats.some(function (c) {
          return Number(c.id) === want;
        });
      var aiChats = chats.filter(function (c) {
        return Number(c.id) > 0;
      });
      var pick = ok ? want : aiChats.length ? Number(aiChats[0].id) : 0;
      setCurrentDiscussChat(pick);
    } else {
      syncNotePaneHeader();
    }
    return true;
  }

  // Меню чатов — панель справа во всю высоту экрана. Переносим её в body, чтобы
  // она перекрывала и оверлей обсуждения на телефоне, и правую колонку на десктопе.
  function noteChatsDrawerEls() {
    var menu = document.getElementById("note-chats-menu");
    var backdrop = document.getElementById("note-chats-backdrop");
    if (menu && menu.parentNode !== document.body) document.body.appendChild(menu);
    if (!backdrop) {
      backdrop = document.createElement("div");
      backdrop.id = "note-chats-backdrop";
      backdrop.className = "note-chats-backdrop hidden";
      backdrop.addEventListener("click", function () {
        closeNoteChatsMenu();
      });
      document.body.appendChild(backdrop);
    }
    return { menu: menu, backdrop: backdrop };
  }

  function closeNoteChatsMenu() {
    var menu = document.getElementById("note-chats-menu");
    var backdrop = document.getElementById("note-chats-backdrop");
    var btn = document.getElementById("note-discussion-new-ctx");
    if (btn) btn.setAttribute("aria-expanded", "false");
    var titleBtn = document.getElementById("note-discussion-title");
    if (titleBtn && noteSheetState.rightMode === "discussion") {
      titleBtn.classList.remove("is-open");
      titleBtn.setAttribute("aria-expanded", "false");
    }
    if (!menu || menu.classList.contains("hidden")) return;
    menu.classList.remove("is-open");
    if (backdrop) backdrop.classList.remove("is-open");
    clearTimeout(menu._hideTimer);
    menu._hideTimer = setTimeout(function () {
      menu.classList.add("hidden");
      if (backdrop) backdrop.classList.add("hidden");
    }, 240);
  }

  function noteChatMeta(chat) {
    var parts = [];
    var n = Number(chat.message_count) || 0;
    if (n) parts.push(n + " " + (n % 10 === 1 && n % 100 !== 11 ? "сообщение" : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14) ? "сообщения" : "сообщений"));
    var t = Date.parse(chat.last_at || "");
    if (t) {
      parts.push(
        new Date(t).toLocaleDateString("ru-RU", { day: "numeric", month: "short" })
      );
    }
    return parts.join(" · ");
  }

  var NOTE_CHAT_ICONS = {
    shared:
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>',
    private:
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="11" width="16" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/></svg>',
    comments:
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>',
  };

  function renderNoteChatsMenu() {
    var menu = document.getElementById("note-chats-menu");
    var wrap = discussWrap();
    if (!menu || !wrap) return;
    menu.innerHTML = "";
    var cur = currentDiscussChatId();
    var chats = wrap._noteChats || [];
    var unread = noteChatsUnread();

    var head = document.createElement("div");
    head.className = "note-chats-head";
    var headTitle = document.createElement("h2");
    headTitle.className = "note-chats-head-title";
    headTitle.textContent = "Чаты";
    var closeBtn = document.createElement("button");
    closeBtn.type = "button";
    closeBtn.className = "modal-header-btn note-chats-close";
    closeBtn.setAttribute("aria-label", "Закрыть");
    closeBtn.innerHTML =
      '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M18 6 6 18M6 6l12 12"/></svg>';
    closeBtn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      closeNoteChatsMenu();
    });
    head.appendChild(headTitle);
    head.appendChild(closeBtn);
    menu.appendChild(head);

    function section(icon, label, hint) {
      var sec = document.createElement("section");
      sec.className = "note-chats-section";
      if (label) {
        var h = document.createElement("div");
        h.className = "note-chats-section-head";
        h.innerHTML = icon ? '<span class="note-chats-section-icon">' + icon + "</span>" : "";
        var txt = document.createElement("div");
        var l = document.createElement("div");
        l.className = "note-chats-section-title";
        l.textContent = label;
        txt.appendChild(l);
        if (hint) {
          var p = document.createElement("div");
          p.className = "note-chats-section-hint";
          p.textContent = hint;
          txt.appendChild(p);
        }
        h.appendChild(txt);
        sec.appendChild(h);
        // Чаты раздела — отдельной карточкой под заголовком.
        var group = document.createElement("div");
        group.className = "note-chats-group";
        sec.appendChild(group);
        menu.appendChild(sec);
        return group;
      }
      menu.appendChild(sec);
      return sec;
    }
    function itemRow(parent, chat, icon) {
      var active = Number(chat.id) === cur;
      var b = document.createElement("button");
      b.type = "button";
      b.className = "note-pane-switch-item note-chats-item" + (active ? " is-active" : "");
      b.setAttribute("role", "menuitem");
      if (active) b.setAttribute("aria-current", "true");
      b.innerHTML = '<span class="note-chats-item-icon">' + icon + "</span>";
      var text = document.createElement("span");
      text.className = "note-chats-item-text";
      var title = document.createElement("span");
      title.className = "note-chats-item-title";
      title.textContent = noteChatTitle(chat);
      text.appendChild(title);
      var metaText = noteChatMeta(chat);
      if (Number(chat.id) > 0 && chat.visibility === "shared" && !chat.is_mine) {
        metaText = (metaText ? metaText + " · " : "") + "от участника";
      }
      if (metaText) {
        var meta = document.createElement("span");
        meta.className = "note-chats-item-meta";
        meta.textContent = metaText;
        text.appendChild(meta);
      }
      b.appendChild(text);
      var unreadN = active ? 0 : unread[Number(chat.id)] || 0;
      if (unreadN) {
        var n = document.createElement("span");
        n.className = "note-chats-badge note-chats-item-badge";
        n.textContent = unreadN > 99 ? "99+" : String(unreadN);
        n.setAttribute("aria-label", "Новых сообщений: " + unreadN);
        b.appendChild(n);
      }
      b.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        closeNoteChatsMenu();
        setCurrentDiscussChat(Number(chat.id));
      });
      // «…» — переименовать / удалить (только свои чаты с ИИ; «Комментарии» не трогаем).
      if (Number(chat.id) > 0 && chat.is_mine) {
        var row = document.createElement("div");
        row.className = "note-chats-row";
        row.appendChild(b);
        var more = document.createElement("button");
        more.type = "button";
        more.className = "note-chats-more";
        more.setAttribute("aria-label", "Действия с чатом");
        more.setAttribute("aria-haspopup", "menu");
        more.innerHTML =
          '<svg width="16" height="16" viewBox="0 0 20 20" aria-hidden="true"><circle cx="4" cy="10" r="1.7" fill="currentColor"/><circle cx="10" cy="10" r="1.7" fill="currentColor"/><circle cx="16" cy="10" r="1.7" fill="currentColor"/></svg>';
        more.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          openNoteChatActions(row, chat);
        });
        row.appendChild(more);
        parent.appendChild(row);
        return;
      }
      parent.appendChild(b);
    }

    var newSec = section("", "", "");
    var newBtn = document.createElement("button");
    newBtn.type = "button";
    newBtn.className = "note-pane-switch-item note-chats-new" + (cur === 0 ? " is-active" : "");
    newBtn.textContent = "+ Новый чат";
    newBtn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      closeNoteChatsMenu();
      if (cur !== 0) setCurrentDiscussChat(0);
      // Уже в новом (пустом) чате — просто ставим курсор в поле ввода.
      var ed = noteGptEditor();
      if (ed && !isMobileNoteLayout()) {
        try {
          ed.focus();
        } catch (_) {}
      }
      if (cur === 0) showNoteToast("Это новый чат — напишите первое сообщение");
    });
    newSec.appendChild(newBtn);

    var shared = section(NOTE_CHAT_ICONS.shared, "Общие", "Видят все участники заметки");
    var comments = chats.filter(function (c) {
      return Number(c.id) === COMMENTS_CHAT_ID;
    })[0] || { id: COMMENTS_CHAT_ID, title: "Комментарии" };
    itemRow(shared, comments, NOTE_CHAT_ICONS.comments);
    chats
      .filter(function (c) {
        return Number(c.id) > 0 && c.visibility === "shared";
      })
      .forEach(function (c) {
        itemRow(shared, c, NOTE_CHAT_ICONS.shared);
      });

    var mine = section(NOTE_CHAT_ICONS.private, "Личные", "Видите только вы");
    var privateChats = chats.filter(function (c) {
      return Number(c.id) > 0 && c.visibility === "private";
    });
    if (privateChats.length) {
      privateChats.forEach(function (c) {
        itemRow(mine, c, NOTE_CHAT_ICONS.private);
      });
    } else {
      var none = document.createElement("p");
      none.className = "note-chats-empty";
      none.textContent = "Личных чатов пока нет";
      mine.appendChild(none);
    }

    // Карточка доступа текущего чата.
    var current = cur > 0 ? noteChatById(cur) : null;
    if (cur !== 0 && !current) return;
    var card = document.createElement("section");
    card.className = "note-chats-access";
    var cardText = document.createElement("p");
    cardText.className = "note-chats-access-text";
    if (cur === 0) {
      cardText.textContent = "Новый чат будет";
      card.appendChild(cardText);
      var seg = document.createElement("div");
      seg.className = "note-chats-visibility-seg";
      seg.setAttribute("role", "group");
      seg.setAttribute("aria-label", "Доступ к новому чату");
      var vis = wrap._newChatVisibility || "private";
      [
        ["private", "Личным", NOTE_CHAT_ICONS.private],
        ["shared", "Общим", NOTE_CHAT_ICONS.shared],
      ].forEach(function (opt) {
        var b = document.createElement("button");
        b.type = "button";
        b.innerHTML = opt[2];
        b.appendChild(document.createTextNode(opt[1]));
        b.setAttribute("aria-pressed", String(vis === opt[0]));
        b.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          setNoteChatVisibility(0, opt[0]);
        });
        seg.appendChild(b);
      });
      card.appendChild(seg);
    } else if (current.can_edit) {
      var isShared = current.visibility === "shared";
      cardText.textContent = isShared
        ? "Этот чат общий — его видят все участники заметки"
        : "Этот чат личный — его видите только вы";
      card.appendChild(cardText);
      var toggle = document.createElement("button");
      toggle.type = "button";
      toggle.className = "note-chats-access-btn";
      toggle.innerHTML = isShared ? NOTE_CHAT_ICONS.private : NOTE_CHAT_ICONS.shared;
      toggle.appendChild(document.createTextNode(isShared ? "Сделать личным" : "Сделать общим"));
      toggle.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        setNoteChatVisibility(cur, isShared ? "private" : "shared");
      });
      card.appendChild(toggle);
    } else {
      cardText.textContent = "Общий чат другого участника. Доступ меняет его автор";
      card.appendChild(cardText);
    }
    menu.appendChild(card);
  }

  function closeNoteChatActions() {
    document.querySelectorAll(".note-chats-actions").forEach(function (m) {
      m.remove();
    });
  }

  function openNoteChatActions(row, chat) {
    var open = row.querySelector(".note-chats-actions");
    closeNoteChatActions();
    if (open) return;
    var pop = document.createElement("div");
    pop.className = "note-chats-actions";
    pop.setAttribute("role", "menu");
    var acts = [["rename", "Переименовать"]];
    if (chat && chat.can_edit !== false) {
      acts.push(["visibility", chat.visibility === "private" ? "Сделать общим" : "Сделать личным"]);
    }
    acts.push(["delete", "Удалить"]);
    acts.forEach(function (it) {
      var b = document.createElement("button");
      b.type = "button";
      b.setAttribute("role", "menuitem");
      b.className = "note-chats-actions-item" + (it[0] === "delete" ? " is-danger" : "");
      b.textContent = it[1];
      b.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        closeNoteChatActions();
        if (it[0] === "rename") startNoteChatRename(row, chat);
        else if (it[0] === "visibility") {
          setNoteChatVisibility(chat.id, chat.visibility === "private" ? "shared" : "private");
        } else deleteNoteChat(chat);
      });
      pop.appendChild(b);
    });
    row.appendChild(pop);
    // В выпадающем списке чатов — fixed, чтобы не обрезалось прокруткой списка.
    var moreBtn = row.querySelector(".note-chats-more");
    if (moreBtn) {
      var br = moreBtn.getBoundingClientRect();
      pop.style.position = "fixed";
      pop.style.zIndex = "420";
      pop.style.right = Math.max(8, Math.round(window.innerWidth - br.right)) + "px";
      pop.style.left = "auto";
      var below = br.bottom + 4;
      pop.style.top = Math.round(below) + "px";
      requestAnimationFrame(function () {
        var h = pop.offsetHeight;
        if (below + h > window.innerHeight - 8) pop.style.top = Math.max(8, Math.round(br.top - h - 4)) + "px";
      });
    }
    setTimeout(function () {
      document.addEventListener(
        "click",
        function onDoc(ev) {
          if (!pop.contains(ev.target)) closeNoteChatActions();
          document.removeEventListener("click", onDoc, true);
        },
        true
      );
    }, 0);
  }

  // Переименование прямо в строке списка (window.prompt в Telegram на телефоне ненадёжен).
  function startNoteChatRename(row, chat) {
    var form = document.createElement("form");
    form.className = "note-chats-rename";
    var input = document.createElement("input");
    input.type = "text";
    input.className = "field-input note-chats-rename-input";
    input.maxLength = 80;
    input.value = String(chat.title || "").trim() || noteChatTitle(chat);
    input.setAttribute("aria-label", "Название чата");
    var ok = document.createElement("button");
    ok.type = "submit";
    ok.className = "note-chats-rename-ok";
    ok.textContent = "Готово";
    form.appendChild(input);
    form.appendChild(ok);
    var done = false;
    function finish(save) {
      if (done) return;
      done = true;
      var title = input.value.trim();
      if (save && title && title !== String(chat.title || "").trim()) renameNoteChat(chat, title);
      else renderNoteChatsMenu();
    }
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      finish(true);
    });
    form.addEventListener("click", function (e) {
      e.stopPropagation();
    });
    input.addEventListener("keydown", function (e) {
      if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        finish(false);
      }
    });
    input.addEventListener("blur", function () {
      setTimeout(function () {
        if (!form.contains(document.activeElement)) finish(true);
      }, 150);
    });
    row.innerHTML = "";
    row.appendChild(form);
    input.focus();
    input.select();
  }

  async function renameNoteChat(chat, title) {
    var wrap = discussWrap();
    try {
      var res = await apiFetch(noteChatsBase() + "/" + encodeURIComponent(String(chat.id)), {
        method: "PATCH",
        body: JSON.stringify({ title: title }),
      });
      var saved = res && res.chat;
      if (wrap && saved) {
        wrap._noteChats = (wrap._noteChats || []).map(function (c) {
          return Number(c.id) === Number(saved.id) ? Object.assign({}, c, { title: saved.title }) : c;
        });
        syncNotePaneHeader();
      }
      showNoteToast("Чат переименован");
    } catch (e) {
      showNoteToast((e && e.message) || "Не удалось переименовать чат");
    }
    renderNoteChatsMenu();
  }

  async function deleteNoteChat(chat) {
    var wrap = discussWrap();
    var ok = await confirmDialog("Удалить чат «" + noteChatTitle(chat) + "» со всеми сообщениями? Это нельзя отменить.");
    if (!ok) return;
    try {
      await apiFetch(noteChatsBase() + "/" + encodeURIComponent(String(chat.id)), { method: "DELETE" });
      if (wrap) {
        wrap._noteChats = (wrap._noteChats || []).filter(function (c) {
          return Number(c.id) !== Number(chat.id);
        });
      }
      if (currentDiscussChatId() === Number(chat.id)) setCurrentDiscussChat(0);
      syncNotePaneHeader();
      showNoteToast("Чат удалён");
    } catch (e) {
      showNoteToast((e && e.message) || "Не удалось удалить чат");
    }
    renderNoteChatsMenu();
  }

  async function setNoteChatVisibility(chatId, visibility) {
    var wrap = discussWrap();
    if (!wrap) return;
    if (!chatId) {
      wrap._newChatVisibility = visibility;
      renderNoteChatsMenu();
      return;
    }
    try {
      var res = await apiFetch(noteChatsBase() + "/" + encodeURIComponent(String(chatId)), {
        method: "PATCH",
        body: JSON.stringify({ visibility: visibility }),
      });
      var chat = res && res.chat;
      if (chat) {
        // В ответе нет статистики (число сообщений, первое сообщение) — берём только доступ.
        wrap._noteChats = (wrap._noteChats || []).map(function (c) {
          return Number(c.id) === Number(chat.id)
            ? Object.assign({}, c, { visibility: chat.visibility, title: chat.title })
            : c;
        });
        syncNotePaneHeader();
      }
      renderNoteChatsMenu();
      showNoteToast(visibility === "shared" ? "Чат виден всем участникам заметки" : "Чат виден только вам");
    } catch (e) {
      showNoteToast((e && e.message) || "Не удалось изменить доступ");
    }
  }

  // Список чатов — выпадающим меню под названием, в пределах панели обсуждения.
  function placeNoteChatsDropdown(menu) {
    var title = document.getElementById("note-discussion-title");
    var sheet = document.querySelector("#note-discussion-overlay .note-discussion-sheet");
    var head = document.querySelector("#note-discussion-overlay .note-discussion-header");
    if (!menu || !title || !sheet) return;
    var sr = sheet.getBoundingClientRect();
    var tr = title.getBoundingClientRect();
    var hr = head ? head.getBoundingClientRect() : tr;
    var w = Math.min(340, sr.width - 16);
    var left = tr.left + tr.width / 2 - w / 2;
    left = Math.max(sr.left + 8, Math.min(left, sr.right - w - 8));
    menu.style.width = Math.round(w) + "px";
    menu.style.left = Math.round(left) + "px";
    menu.style.top = Math.round(hr.bottom + 6) + "px";
    menu.style.maxHeight = Math.max(200, Math.round(window.innerHeight - hr.bottom - 24)) + "px";
    title.classList.add("is-open");
    title.setAttribute("aria-expanded", "true");
  }

  function toggleNoteChatsMenu() {
    var els = noteChatsDrawerEls();
    var menu = els.menu;
    var btn = document.getElementById("note-discussion-new-ctx");
    if (!menu) return;
    var open = !menu.classList.contains("is-open");
    closeNotePaneSwitchMenu();
    if (!open) {
      closeNoteChatsMenu();
      return;
    }
    clearTimeout(menu._hideTimer);
    renderNoteChatsMenu();
    menu.classList.add("is-dropdown");
    els.backdrop.classList.add("is-dropdown");
    menu.classList.remove("hidden");
    els.backdrop.classList.remove("hidden");
    placeNoteChatsDropdown(menu);
    // Следующий кадр — чтобы сработал переход выезда.
    requestAnimationFrame(function () {
      menu.classList.add("is-open");
      els.backdrop.classList.add("is-open");
    });
    if (btn) btn.setAttribute("aria-expanded", "true");
    var wrap = discussWrap();
    if (wrap && wrap._shareKind && wrap._shareId) {
      loadNoteChats(wrap._shareKind, wrap._shareId)
        .then(function () {
          if (!menu.classList.contains("hidden")) renderNoteChatsMenu();
        })
        .catch(function () {});
    }
  }

  function gptContextCutKey() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap || !wrap._shareKind || !wrap._shareId) return "";
    return "leo_gpt_ctx_cut:" + wrap._shareKind + ":" + wrap._shareId;
  }

  function gptContextCutId() {
    try {
      var n = parseInt(localStorage.getItem(gptContextCutKey()) || "", 10);
      if (isFinite(n) && n > 0) return n;
    } catch (_) {}
    return 0;
  }

  function setGptContextCutId(id) {
    var key = gptContextCutKey();
    if (!key) return;
    try {
      if (id > 0) localStorage.setItem(key, String(id));
      else localStorage.removeItem(key);
    } catch (_) {}
  }

  function clipGptCommentBody(text) {
    var s = String(text || "");
    if (s.length <= GPT_COMMENT_BODY_MAX) return s;
    return s.slice(0, GPT_COMMENT_BODY_MAX - 1) + "…";
  }

  function gptPhaseLabel(phase) {
    if (phase === "sending") return "Отправляю…";
    if (phase === "saving") return "Сохраняю ответ…";
    return "Думает…";
  }

  function renderGptPendingStatus(phase) {
    var item = document.createElement("article");
    item.id = "note-discuss-pending";
    item.className = "note-discuss-msg is-assistant is-pending";
    item.setAttribute("aria-live", "polite");
    var role = document.createElement("p");
    role.className = "note-discuss-role";
    var mode = noteAskMode();
    if (mode === "gpt" || !mode) {
      role.textContent = gptModelShortName(selectedGptModelId()) || "GPT";
    } else {
      var agent = findUserAgent(mode);
      role.textContent = (agent && agent.title) || "Агент";
    }
    var bubble = document.createElement("div");
    bubble.className = "note-discuss-bubble note-discuss-bubble--pending";
    bubble.innerHTML =
      '<span class="note-discuss-pending-dots" aria-hidden="true"><i></i><i></i><i></i></span>';
    var label = document.createElement("span");
    label.className = "note-discuss-pending-label";
    label.textContent = gptPhaseLabel(phase);
    bubble.appendChild(label);
    item.appendChild(role);
    item.appendChild(bubble);
    return item;
  }

  function renderGptContextDivider() {
    var el = document.createElement("div");
    el.className = "note-discuss-ctx-cut";
    el.innerHTML = "<span>Новый контекст</span>";
    return el;
  }

  // fromRender: вызов из самой перерисовки — флаг «вниз при следующей» не взводим, иначе он
  // становится вечным и любая перерисовка (кнопка в карточке) уводит ленту в конец.
  function scrollDiscussionToEnd(fromRender) {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap && fromRender !== true) wrap._forceDiscussScrollBottom = Date.now() + 1500;
    function go() {
      var scroll = document.querySelector("#note-discussion-overlay .note-discussion-scroll");
      if (!scroll) return;
      scroll.scrollTop = scroll.scrollHeight;
    }
    go();
    if (typeof requestAnimationFrame === "function") {
      requestAnimationFrame(function () {
        go();
        requestAnimationFrame(go);
      });
    }
    setTimeout(go, 50);
    setTimeout(go, 180);
    setTimeout(go, 400);
  }

  function setGptDiscussPhase(phase) {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (wrap) wrap._gptPhase = phase || "thinking";
    var label = document.querySelector("#note-discuss-pending .note-discuss-pending-label");
    if (label) {
      label.textContent = gptPhaseLabel(wrap && wrap._gptPhase);
      return;
    }
    var list = document.getElementById("note-discussion-messages");
    if (!list || !wrap || !wrap._gptBusy) return;
    var empty = list.querySelector(".note-discussion-empty");
    if (empty) empty.remove();
    list.appendChild(renderGptPendingStatus(wrap._gptPhase));
    scrollDiscussionToEnd();
  }

  function appendOptimisticUserMessage(text, quote, canvasSelections) {
    var list = document.getElementById("note-discussion-messages");
    if (!list) return;
    var empty = list.querySelector(".note-discussion-empty");
    if (empty) empty.remove();
    var old = document.getElementById("note-discuss-optimistic-user");
    if (old && old.parentNode) old.parentNode.removeChild(old);
    var item = document.createElement("article");
    item.id = "note-discuss-optimistic-user";
    item.className = "note-discuss-msg is-user is-optimistic";
    var role = document.createElement("p");
    role.className = "note-discuss-role";
    role.textContent = "Вы";
    item.appendChild(role);
    var split = splitDiscussQuote(quote);
    var quoteText = String(split.text || "").trim();
    var canvasRows =
      Array.isArray(canvasSelections) && canvasSelections.length
        ? canvasSelections
        : split.canvas;
    var bodyText = discussDisplayBody(String(text || ""), quoteText);
    var wrap = document.getElementById("note-editor-more-wrap");
    var replyWho =
      (wrap && wrap._commentReplyWho) ||
      discussReplyWhoLabel({ parent_id: wrap && wrap._commentChairId }) ||
      "Фрагмент";
    var bubble = document.createElement("div");
    bubble.className = "note-discuss-bubble";
    appendDiscussCanvasChips(bubble, canvasRows);
    if (quoteText) {
      appendDiscussReplyQuote(
        bubble,
        quoteText,
        replyWho,
        wrap && wrap._commentChairId ? Number(wrap._commentChairId) || 0 : 0
      );
    }
    if (bodyText && isThreadedDiscussBody(bodyText)) {
      appendDiscussThreadedBody(bubble, bodyText, false);
    } else if (bodyText) {
      var textBody = document.createElement("div");
      textBody.className = "note-discuss-bubble-body";
      // До ответа сервера — та же вёрстка, что после (заголовки, списки).
      fillDiscussBodyBlocks(textBody, bodyText);
      bubble.appendChild(textBody);
    }
    if (bubble.childNodes.length) item.appendChild(bubble);
    renderPendingAttachThumbs(item);
    var meta = document.createElement("p");
    meta.className = "note-discuss-send-state";
    meta.textContent = "Отправляю…";
    item.appendChild(meta);
    list.appendChild(item);
    scrollDiscussionToEnd();
  }

  function markOptimisticUserSent() {
    var meta = document.querySelector("#note-discuss-optimistic-user .note-discuss-send-state");
    if (meta) meta.textContent = "Отправлено";
  }

  function gptHistoryFromComments(comments, agentId) {
    var api = window.NoteComments;
    var cut = gptContextCutId();
    var customId = agentId && agentId !== "gpt" ? String(agentId) : "";
    var prior = discussionComments(comments || [])
      .filter(function (c) {
        if (!c) return false;
        if (currentDiscussChatId() !== null) {
          if (!inCurrentDiscussChat(c)) return false;
        } else if (Number(c.id) <= cut) return false;
        if (customId) {
          return api && api.agentIdOf ? api.agentIdOf(c) === customId : String(c.prefix || "") === "__agent__:" + customId;
        }
        if (api && api.isAgentTurn && api.isAgentTurn(c)) return false;
        return true;
      })
      .slice()
      .sort(function (a, b) {
        var at = Date.parse(a && a.created_at) || 0;
        var bt = Date.parse(b && b.created_at) || 0;
        if (at !== bt) return at - bt;
        return Number(a.id || 0) - Number(b.id || 0);
      });
    var history = [];
    prior.forEach(function (c) {
      var content = calMarkerForHistory(String((c && c.body) || "")).trim();
      var names = ((c && c.attachments) || [])
        .map(function (a) {
          return a && a.name;
        })
        .filter(Boolean);
      if (names.length) {
        content = (content && content !== "📎" ? content + "\n" : "") + "[вложения: " + names.join(", ") + "]";
      }
      if (!content) return;
      var quote = String(splitDiscussQuote((c && c.quote) || "").text || "").trim();
      if (quote && content.indexOf("«") === -1) content = "Про текст: «" + quote + "»\n\n" + content;
      if (content.length > 6000) content = content.slice(0, 5999) + "…";
      if (customId) {
        var agentUname = String((c && c.author_username) || "").trim().toLowerCase();
        history.push({
          role: agentUname === "agent" ? "assistant" : "user",
          content: content,
        });
        return;
      }
      if (api && api.isGptComment && api.isGptComment(c)) {
        history.push({ role: "assistant", content: content });
        return;
      }
      if (api && api.isResearchTurn && api.isResearchTurn(c)) {
        return;
      }
      if (api && api.isPaieComment && api.isPaieComment(c)) {
        history.push({ role: "user", content: "CHAIR:\n" + content });
        return;
      }
      var who = discussionHistoryAuthorLabel(c);
      history.push({
        role: "user",
        content: who ? who + ":\n" + content : content,
      });
    });
    if (history.length > GPT_HISTORY_MAX_TURNS) {
      history = history.slice(-GPT_HISTORY_MAX_TURNS);
    }
    var total = 0;
    var i;
    for (i = history.length - 1; i >= 0; i--) {
      total += String((history[i] && history[i].content) || "").length;
      if (total > GPT_HISTORY_MAX_CHARS) {
        history = history.slice(i + 1);
        break;
      }
    }
    return history;
  }

  async function clearGptDiscussionContext() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap || wrap._gptBusy) return;
    var panel = document.getElementById("note-editor-comments");
    var rows = discussionComments((panel && panel._allComments) || []);
    if (!rows.length) {
      showNoteToast("Пока нет сообщений");
      return;
    }
    var ok = await confirmDialog(
      "Начать новый контекст для GPT? Старые сообщения останутся в ленте, но модель их больше не увидит."
    );
    if (!ok) return;
    var maxId = 0;
    rows.forEach(function (c) {
      var n = Number(c && c.id) || 0;
      if (n > maxId) maxId = n;
    });
    setGptContextCutId(maxId);
    renderNotePaieThread(
      (panel && panel._allComments) || [],
      wrap._shareKind,
      wrap._shareId
    );
    showNoteToast("Контекст очищен");
  }

  async function submitNoteGptQuestion(text) {
    var wrap = document.getElementById("note-editor-more-wrap");
    var packed = serializeGptComposer();
    var quotes = packed.quotes || [];
    var body = packed.text || String(text || "").trim();
    var draftQuote = wrap && wrap._commentDraft ? String(wrap._commentDraft.quote || "").trim() : "";
    var canvasSnapshot = snapshotCanvasSelections();
    var textQuote = quotes.join("\n").trim() || draftQuote;
    var canvasQuote = encodeCanvasSelectionsQuote(canvasSnapshot);
    var quote = [textQuote, canvasQuote].filter(Boolean).join("\n");
    if (!body && canvasSnapshot.length) body = "Поправь выделенный блок";
    var replyToId = wrap && wrap._commentChairId ? Number(wrap._commentChairId) || null : null;
    var pending = discussPendingFiles();
    var contextIds = discussContextNoteIds();
    if (
      !wrap ||
      !wrap._shareKind ||
      !wrap._shareId ||
      wrap._gptBusy ||
      (!body && !pending.length && !contextIds.length)
    )
      return;
    var kind = wrap._shareKind;
    var itemId = wrap._shareId;
    var sessionTitle = noteTitleForDiscussToast(kind, itemId, getNoteEditorTitle().trim() || "");
    var panel = document.getElementById("note-editor-comments");
    var agentId = isCustomAskMode(noteAskMode()) ? noteAskMode() : "gpt";
    var agentPrefix = agentId === "gpt" ? "__gpt__" : "__agent__:" + agentId;
    var histComments = [];
    if (
      panel &&
      String(panel._commentsKind || "") === String(kind) &&
      String(panel._commentsItemId || "") === String(itemId)
    ) {
      histComments = panel._allComments || [];
    }
    var history = gptHistoryFromComments(histComments, agentId);
    var noteCtxEarly = activeNoteGptContext();
    var kbEarly = discussionKnowledgeFields();
    wrap._gptBusy = true;
    wrap._gptPhase = "sending";
    var gptReq = { stopped: false };
    wrap._gptReq = gptReq;
    function releaseGptBusy() {
      var lw = document.getElementById("note-editor-more-wrap");
      if (lw && String(lw._shareId) === String(itemId) && lw._gptReq === gptReq) {
        lw._gptBusy = false;
        lw._gptPhase = "";
        lw._gptReq = null;
      }
    }
    var editRec = null;
    wrap._discussionPinId = null;
    beginNoteAgentSession(kind, itemId, agentId === "gpt" ? "gpt" : agentId, sessionTitle);
    syncNotePaieReplyForm(true);
    appendOptimisticUserMessage(body, quote, canvasSnapshot);
    clearCanvasSelections();
    wrap._commentDraft = null;
    wrap._commentChairId = null;
    wrap._commentReplyWho = null;
    setGptDiscussPhase("sending");
    try {
      await ensureDiscussChat();
      var fileIds = await uploadDiscussPendingFiles(kind, itemId);
      clearDiscussPendingFiles();
      clearDiscussPendingContextNotes();
      var saved = await apiFetch(
        "/notes/" + encodeURIComponent(kind) + "/" + encodeURIComponent(itemId) + "/comments",
        {
          method: "POST",
          body: JSON.stringify(
            Object.assign(
              {
                body: body,
                quote: quote,
                prefix: agentPrefix,
                suffix: "",
                parent_id: replyToId || null,
                file_ids: fileIds,
              },
              discussChatFields()
            )
          ),
        }
      );
      if (saved && saved.thread) upsertChatThreadCache(saved.thread);
      var input = document.getElementById("note-paie-reply-input");
      if (input) input.value = "";
      clearGptComposer();
      var parentId = saved && saved.comment && saved.comment.id;
      markOptimisticUserSent();
      scrollDiscussionToEnd();
      if (isDiscussionTargetActive(kind, itemId)) setGptDiscussPhase("thinking");
      if (isDiscussionTargetActive(kind, itemId)) await refreshNoteCommentsList();
      if (isDiscussionTargetActive(kind, itemId)) setGptDiscussPhase("thinking");
      scrollDiscussionToEnd();
      await ensureDiscussionKnowledgeNotes();
      var kb = isDiscussionTargetActive(kind, itemId)
        ? discussionKnowledgeFields()
        : kbEarly;
      if (!kb.knowledge_note_ids || !kb.knowledge_note_ids.length) kb = kbEarly;
      var noteCtx = noteCtxEarly;
      if (isDiscussionTargetActive(kind, itemId)) {
        try {
          var liveCtx = activeNoteGptContext();
          if (liveCtx && (liveCtx.text || liveCtx.title)) noteCtx = liveCtx;
        } catch (_) {}
      }
      // Для чатов не подмешиваем текст заметки — только история этого треда.
      if (kind === "chat") {
        noteCtx = { title: "", text: "", sheet_ids: [] };
      }
      var canvasSelections = canvasSnapshot.map(function (s) {
        return {
          sheet_id: s.sheetId,
          leo_id: s.leoId,
          label: s.label,
          snippet: s.snippet,
        };
      });
      var openBoard = kind === "local" ? openBoardForYjs() : null;
      var openCanvasSheetId =
        activeWebCanvasSheetId() ||
        (canvasSelections[0] && canvasSelections[0].sheet_id) ||
        "";
      var docView = kind === "local" && isDiscussionTargetActive(kind, itemId) ? buildOpenDocView() : null;
      var res = await apiFetch("/gpt/chat", {
        method: "POST",
        body: JSON.stringify({
          message: body,
          note_title: noteCtx.title,
          note_text: noteCtx.text,
          quote: textQuote || undefined,
          quotes: quotes.length ? quotes : undefined,
          use_knowledge: kb.use_knowledge,
          knowledge_note_ids: kb.knowledge_note_ids,
          sheet_ids: noteCtx.sheet_ids,
          history: history,
          model: selectedGptModelId() || undefined,
          agent_id: agentId,
          file_ids: fileIds,
          item_kind: kind,
          item_id: itemId,
          context_note_ids: contextIds.length ? contextIds : undefined,
          canvas_selections: canvasSelections.length ? canvasSelections : undefined,
          canvas_sheet_id: openCanvasSheetId || undefined,
          canvas_theme: preferredDeckTheme() || undefined,
          board_sheet_id: openBoard ? openBoard.sheetId : undefined,
          doc_view: docView ? docView.view : undefined,
          doc_sheet_id: docView ? docView.sheet_id : undefined,
        }),
      });
      if (gptReq.stopped) {
        var stopErr = new Error("stopped");
        stopErr.leoStopped = true;
        throw stopErr;
      }
      if (res && res.note_edits && isDiscussionTargetActive(kind, itemId)) {
        try {
          editRec = applyNoteAiEdits(res.note_edits);
        } catch (err) {
          console.warn("applyNoteAiEdits", err);
          showNoteToast("Не удалось применить правки ИИ");
        }
      }
      if (res && res.canvas && res.canvas.length) {
        await applyCanvasChatResult(res.canvas);
      } else if (res && res.canvas_error) {
        showNoteToast("Не получилось — попробуйте попросить короче");
      }
      var ans = String((res && res.answer) || "").trim();
      var bullets = (res && res.bullets) || [];
      if (bullets.length) {
        ans +=
          "\n\n" +
          bullets
            .map(function (x) {
              return "• " + x;
            })
            .join("\n");
      }
      var gptFileIds = ((res && res.files) || [])
        .map(function (f) {
          return f && f.id;
        })
        .filter(Boolean);
      if (!ans) ans = gptFileIds.length ? "📎" : "—";
      var calActs = (res && res.calendar_actions) || [];
      if (calActs.length) {
        rememberCalendarActions(calActs);
        var calMarker = "\n\n[[leo-cal:" + calActs.map(function (a) { return a.id; }).join(",") + "]]";
        ans = clipGptCommentBody(ans).slice(0, GPT_COMMENT_BODY_MAX - calMarker.length - 2).replace(/\s+$/, "") + calMarker;
        try {
          if (typeof loadActual === "function") loadActual({ silent: true });
        } catch (_) {}
      }
      setGptDiscussPhase("saving");
      var gptSaved = await apiFetch(
        "/notes/" + encodeURIComponent(kind) + "/" + encodeURIComponent(itemId) + "/comments",
        {
          method: "POST",
          body: JSON.stringify({
            body: calActs.length ? ans : clipGptCommentBody(ans),
            quote: quote,
            prefix: agentPrefix,
            suffix: "",
            parent_id: parentId || null,
            as_role: agentId === "gpt" ? "gpt" : "agent:" + agentId,
            model: agentId === "gpt" ? String((res && res.model) || selectedGptModelId() || "") : undefined,
            file_ids: gptFileIds,
            chat_id: discussChatFields().chat_id,
          }),
        }
      );
      if (gptSaved && gptSaved.thread) upsertChatThreadCache(gptSaved.thread);
      if (editRec && gptSaved && gptSaved.comment && gptSaved.comment.id) {
        rememberAiEditRecord(gptSaved.comment.id, editRec);
      }
      releaseGptBusy();
      notifyAgentReplyArrived(kind, itemId, agentId === "gpt" ? "gpt" : agentId, sessionTitle);
      clearNoteComposerCommentTarget();
      if (isViewingNoteDiscussion(kind, itemId)) await refreshNoteCommentsList();
    } catch (e) {
      endNoteAgentSession(kind, itemId);
      var liveErr = document.getElementById("note-editor-more-wrap");
      releaseGptBusy();
      if (e && e.leoStopped) {
        if (isViewingNoteDiscussion(kind, itemId)) await refreshNoteCommentsList();
        return;
      }
      if (isViewingNoteDiscussion(kind, itemId) || (liveErr && String(liveErr._shareId) === String(itemId))) {
        alert(e.message || String(e));
        await refreshNoteCommentsList();
      } else {
        showNoteToast(e.message || "Не удалось получить ответ агента");
      }
    } finally {
      var liveFinally = document.getElementById("note-editor-more-wrap");
      var mine = !!(liveFinally && liveFinally._gptReq === gptReq);
      releaseGptBusy();
      if (mine || !(liveFinally && liveFinally._gptBusy)) {
        var leftover = document.getElementById("note-discuss-pending");
        if (leftover && leftover.parentNode) leftover.parentNode.removeChild(leftover);
      }
      syncNotePaieReplyForm();
    }
  }

  // «■»: ответ ИИ больше не ждём — правки не применяются, ответ не сохраняется.
  function stopNoteGptAnswer() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap || !wrap._gptBusy) return;
    if (wrap._gptReq) wrap._gptReq.stopped = true;
    wrap._gptBusy = false;
    wrap._gptPhase = "";
    wrap._gptReq = null;
    var pend = document.getElementById("note-discuss-pending");
    if (pend && pend.parentNode) pend.parentNode.removeChild(pend);
    var list = document.getElementById("note-discussion-messages");
    if (list) list._renderFp = null;
    syncNotePaieReplyForm();
    showNoteToast("Ответ остановлен");
  }

  async function submitNoteFooterComment(text) {
    var wrap = document.getElementById("note-editor-more-wrap");
    var packed = serializeGptComposer(noteGptEditor());
    var body = String((packed && packed.text) || text || "").trim();
    var chipQuote = ((packed && packed.quotes) || []).join("\n").trim();
    var pending = discussPendingFiles();
    if (!wrap || !wrap._shareKind || !wrap._shareId || (!body && !pending.length)) return;
    var api = window.NoteComments;
    var chairId = wrap._commentChairId;
    var draft =
      wrap._commentDraft ||
      (api && api.selectionAnchor ? api.selectionAnchor(noteEditorCommentRoot()) : null);
    var quote = chipQuote || (draft && draft.quote) || "";
    wrap._discussionPinId = null;
    var input = document.getElementById("note-paie-reply-input");
    appendOptimisticUserMessage(body, quote);
    try {
      await ensureDiscussChat();
      var fileIds = await uploadDiscussPendingFiles(wrap._shareKind, wrap._shareId);
      clearDiscussPendingContextNotes();
      var footSaved = await apiFetch(
        "/notes/" +
          encodeURIComponent(wrap._shareKind) +
          "/" +
          encodeURIComponent(wrap._shareId) +
          "/comments",
        {
          method: "POST",
          body: JSON.stringify(
            Object.assign(
              {
                body: body,
                quote: quote,
                prefix: (draft && draft.prefix) || "",
                suffix: (draft && draft.suffix) || "",
                parent_id: chairId || null,
                file_ids: fileIds,
              },
              discussChatFields()
            )
          ),
        }
      );
      if (footSaved && footSaved.thread) upsertChatThreadCache(footSaved.thread);
      if (input) input.value = "";
      clearGptComposer();
      clearDiscussPendingFiles();
      clearNoteComposerCommentTarget();
      shareHaptic();
      markOptimisticUserSent();
      scrollDiscussionToEnd();
      await refreshNoteCommentsList();
      scrollDiscussionToEnd();
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  async function postNoteChairAnswerComment(kind, itemId, chairId, text, draft) {
    var body = String(text || "").trim();
    if (!body) return;
    try {
      await apiFetch(
        "/notes/" + encodeURIComponent(kind) + "/" + encodeURIComponent(itemId) + "/comments",
        {
          method: "POST",
          body: JSON.stringify({
            body: body,
            quote: (draft && draft.quote) || "",
            prefix: (draft && draft.prefix) || "",
            suffix: (draft && draft.suffix) || "",
            parent_id: chairId,
            chat_id: discussChatFields().chat_id,
          }),
        }
      );
      var listEl = document.querySelector("#note-editor-comments .note-comments-list");
      await loadNoteComments(kind, itemId, listEl);
    } catch (e) {
      alert(e.message || String(e));
    }
  }

  function syncNotePaieReplyForm(running) {
    var wrap = document.getElementById("note-editor-more-wrap");
    var panel = document.getElementById("note-editor-comments");
    var api = window.NoteComments;
    var paieRunning = running != null ? !!running : !!(wrap && wrap._paeiRunning);
    var gptBusy = !!(wrap && wrap._gptBusy);
    var researchRunning = !!(wrap && wrap._researchRunning);
    var busy = paieRunning || gptBusy || researchRunning;
    var input = document.getElementById("note-paie-reply-input");
    var submit = document.getElementById("note-paie-reply-submit");
    var newCtxBtn = document.getElementById("note-discussion-new-ctx");
    if (newCtxBtn) newCtxBtn.disabled = busy;
    var hasChair = !!(
      api &&
      api.paieThreadRootId &&
      api.paieThreadRootId((panel && panel._allComments) || [])
    );
    if (input) input.disabled = busy;
    var editor = noteGptEditor();
    if (editor) {
      editor.setAttribute("contenteditable", busy ? "false" : "true");
      editor.classList.toggle("is-disabled", busy);
      editor.setAttribute("aria-disabled", busy ? "true" : "false");
    }
    var attachBtn = document.getElementById("note-paie-attach");
    if (attachBtn) attachBtn.disabled = busy;
    var modeEl = document.getElementById("note-paie-thread");
    if (modeEl) {
      modeEl
        .querySelectorAll(
          ".note-paie-mode, .note-paie-mode-compact, .note-paie-model-btn, .note-paie-kb-toggle, .note-paie-attach"
        )
        .forEach(function (btn) {
          btn.disabled = busy;
        });
    }
    if (submit) {
      var hasText = noteAskUsesComposerEditor(noteAskMode())
        ? !gptComposerIsEmpty(editor)
        : !!(input && String(input.value || "").trim());
      var hasFiles =
        discussPendingFiles().length > 0 ||
        (noteAskMode() !== "comment" && discussContextNoteIds().length > 0);
      var hasCanvasSel =
        isChatAskMode(noteAskMode()) && (noteSheetState.canvasSelections || []).length > 0;
      var canLaunchPaie = noteAskMode() === "paie" && !hasChair;
      var canLaunchResearch = noteAskMode() === "research";
      var ready =
        !busy && (hasText || hasFiles || hasCanvasSel || canLaunchPaie || canLaunchResearch);
      // Пока ИИ отвечает — кнопка «■» останавливает ответ.
      submit.disabled = !ready && !gptBusy;
      submit.classList.toggle("is-ready", ready);
      submit.classList.toggle("is-stop", gptBusy);
      var label = "Отправить";
      if (gptBusy) label = "Остановить ответ";
      else if (paieRunning) label = "CHAIR отвечает…";
      else if (researchRunning) label = "Research ищет…";
      else if (isChatAskMode(noteAskMode())) label = "Спросить " + noteAskModeLabel(noteAskMode());
      else if (noteAskMode() === "research") label = hasText ? "Спросить Research" : "Запустить Research";
      else if (noteAskMode() === "comment") label = "Отправить";
      else label = hasChair ? "Спросить CHAIR" : "Запустить PAIE";
      submit.setAttribute("aria-label", label);
    }
  }

  function setNotePaeiStatus(text, progress) {
    var el = document.getElementById("note-editor-paei-status");
    if (!el) {
      var thread = ensureNotePaieThread();
      el = thread ? document.getElementById("note-editor-paei-status") : null;
    }
    if (!el) return;
    var wrap = document.getElementById("note-editor-more-wrap");
    var panel = document.getElementById("note-editor-comments");
    var label = (progress && progress.label) || text || "";
    if (looksLikeHtmlError(label)) {
      label = "Сервер временно недоступен. Попробуйте запустить PAIE ещё раз.";
      progress = null;
    }
    if (!label) {
      el.classList.add("hidden");
      el.innerHTML = "";
      renderNotePaieThread(
        (panel && panel._allComments) || (panel && panel._paieComments) || [],
        wrap && wrap._shareKind,
        wrap && wrap._shareId
      );
      return;
    }
    var pct = progress && progress.pct != null ? Number(progress.pct) : 12;
    if (isNaN(pct)) pct = 12;
    pct = Math.max(4, Math.min(100, pct));
    el.classList.remove("hidden");
    el.innerHTML =
      '<span class="note-paei-progress-label"></span>' +
      '<span class="note-paei-progress-track"><span class="note-paei-progress-fill"></span></span>';
    el.querySelector(".note-paei-progress-label").textContent = label;
    el.querySelector(".note-paei-progress-fill").style.width = pct + "%";
    var threadEl = document.getElementById("note-paie-thread");
    if (threadEl) threadEl.classList.remove("hidden");
    syncNotePaieReplyForm();
  }

  function notePaeiPath() {
    var wrap = document.getElementById("note-editor-more-wrap");
    if (!wrap || !wrap._shareKind || !wrap._shareId) return "";
    return (
      "/notes/" +
      encodeURIComponent(wrap._shareKind) +
      "/" +
      encodeURIComponent(wrap._shareId) +
      "/paei"
    );
  }

  function refreshNoteCommentsList() {
    var wrap = document.getElementById("note-editor-more-wrap");
    var listEl = document.querySelector("#note-editor-comments .note-comments-list");
    if (!wrap || !listEl) return Promise.resolve();
    return loadNoteComments(wrap._shareKind, wrap._shareId, listEl);
  }

  function pollNotePaei(path) {
    var meta = parseNoteAgentPath(path);
    var pollKey = meta ? noteAgentSessionKey(meta.kind, meta.itemId) + ":paei" : path;
    if (noteAgentPollers[pollKey]) return;
    noteAgentPollers[pollKey] = true;
    var tries = 0;
    function finishPoll() {
      delete noteAgentPollers[pollKey];
    }
    function tick() {
      var live = document.getElementById("note-editor-more-wrap");
      var sameNote = !!(live && notePaeiPath() === path);
      apiFetch(path, { method: "GET" })
        .then(function (data) {
          var status = (data && data.status) || "idle";
          if (status === "running") {
            tries += 1;
            if (sameNote) {
              setNotePaeiStatus(
                (data.progress && data.progress.label) || "PAIE разбирает заметку…",
                data.progress
              );
            }
            if (tries > 180) {
              if (sameNote) {
                live._paeiRunning = false;
                setNotePaeiStatus("PAIE всё ещё работает. Обновите заметку чуть позже.");
              }
              if (meta) endNoteAgentSession(meta.kind, meta.itemId);
              finishPoll();
              return;
            }
            setTimeout(tick, 2500);
            return;
          }
          if (sameNote) live._paeiRunning = false;
          if (status === "error") {
            if (sameNote) {
              setNotePaeiStatus((data && data.error) || "Не удалось завершить PAIE");
            } else if (meta) {
              showNoteToast((data && data.error) || "Не удалось завершить PAIE");
            }
            if (meta) endNoteAgentSession(meta.kind, meta.itemId);
            finishPoll();
            return;
          }
          if (status === "done") {
            if (sameNote) setNotePaeiStatus("");
            if (meta) {
              var title =
                (noteAgentSessions[noteAgentSessionKey(meta.kind, meta.itemId)] || {}).title ||
                "";
              notifyAgentReplyArrived(meta.kind, meta.itemId, "paie", title);
            } else if (sameNote) {
              shareHaptic();
              refreshNoteCommentsList();
            }
            finishPoll();
            return;
          }
          if (sameNote) setNotePaeiStatus("PAIE прервался. Запустите ещё раз.");
          if (meta) endNoteAgentSession(meta.kind, meta.itemId);
          finishPoll();
        })
        .catch(function (e) {
          tries += 1;
          var code = e && e.status;
          var transient = code === 502 || code === 503 || code === 504 || !code;
          if (transient && tries <= 24) {
            if (sameNote) {
              setNotePaeiStatus("Сервер временно недоступен, пробую снова…", {
                label: "Сервер временно недоступен, пробую снова…",
                pct: 16,
              });
            }
            setTimeout(tick, 3000);
            return;
          }
          if (tries > 8) {
            if (sameNote) {
              live._paeiRunning = false;
              setNotePaeiStatus(e.message || "Не удалось проверить статус PAIE");
            } else {
              showNoteToast(e.message || "Не удалось проверить статус PAIE");
            }
            if (meta) endNoteAgentSession(meta.kind, meta.itemId);
            finishPoll();
            return;
          }
          setTimeout(tick, 2500);
        });
    }
    setTimeout(tick, 2500);
  }

  function startNotePaei() {
    var wrap = document.getElementById("note-editor-more-wrap");
    var path = notePaeiPath();
    if (!wrap || !path || wrap._paeiRunning) return;
    var kind = wrap._shareKind;
    var itemId = wrap._shareId;
    var sessionTitle = noteTitleForDiscussToast(kind, itemId, getNoteEditorTitle().trim() || "");
    wrap._paeiRunning = true;
    beginNoteAgentSession(kind, itemId, "paie", sessionTitle);
    syncNoteCommentsPanel();
    ensureNotePaieThread();
    openNoteDiscussion({ mode: "paie" });
    setNotePaeiStatus("Анализ заметки…", { label: "Анализ заметки…", pct: 10 });
    ensureDiscussionKnowledgeNotes()
      .then(ensureDiscussChat)
      .then(function () {
        return apiFetch(path, {
          method: "POST",
          body: JSON.stringify(
            Object.assign(
              { model: selectedPaieModelId() },
              discussionKnowledgeFields(),
              discussChatFields()
            )
          ),
        });
      })
      .then(function (data) {
        clearDiscussPendingContextNotes();
        var status = (data && data.status) || "running";
        var live = document.getElementById("note-editor-more-wrap");
        var sameNote = !!(live && String(live._shareId) === String(itemId));
        if (status === "done") {
          if (sameNote) {
            live._paeiRunning = false;
            setNotePaeiStatus("");
          }
          notifyAgentReplyArrived(kind, itemId, "paie", sessionTitle);
          return;
        }
        if (status === "error") {
          if (sameNote) {
            live._paeiRunning = false;
            setNotePaeiStatus((data && data.error) || "Не удалось запустить PAIE");
          } else {
            showNoteToast((data && data.error) || "Не удалось запустить PAIE");
          }
          endNoteAgentSession(kind, itemId);
          return;
        }
        if (sameNote && data && data.progress) {
          setNotePaeiStatus(data.progress.label, data.progress);
        }
        pollNotePaei(path);
      })
      .catch(function (e) {
        var live = document.getElementById("note-editor-more-wrap");
        if (live && String(live._shareId) === String(itemId)) {
          live._paeiRunning = false;
          setNotePaeiStatus(e.message || "Не удалось запустить PAIE");
        } else {
          showNoteToast(e.message || "Не удалось запустить PAIE");
        }
        endNoteAgentSession(kind, itemId);
      })
      .finally(function () {
        syncNotePaieReplyForm();
      });
  }

  function submitNotePaieReply(text) {
    var wrap = document.getElementById("note-editor-more-wrap");
    var path = notePaeiPath();
    var body = String(text || "").trim();
    if (!wrap || !path || wrap._paeiRunning) return;
    var panel = document.getElementById("note-editor-comments");
    var api = window.NoteComments;
    var rootId =
      api && api.paieThreadRootId
        ? api.paieThreadRootId((panel && panel._allComments) || [])
        : null;
    if (!rootId) {
      if (body) {
        submitNoteFooterComment(body).then(function () {
          startNotePaei();
        });
        return;
      }
      startNotePaei();
      return;
    }
    if (!body) return;
    var draft = wrap._commentDraft;
    var replyToId = wrap._commentChairId || null;
    var kind = wrap._shareKind;
    var itemId = wrap._shareId;
    var sessionTitle = noteTitleForDiscussToast(kind, itemId, getNoteEditorTitle().trim() || "");
    wrap._paeiRunning = true;
    beginNoteAgentSession(kind, itemId, "paie", sessionTitle);
    ensureNotePaieThread();
    setNotePaeiStatus("CHAIR читает уточнение…", {
      label: "CHAIR читает уточнение…",
      pct: 12,
    });
    var input = document.getElementById("note-paie-reply-input");
    var submit = document.getElementById("note-paie-reply-submit");
    if (input) input.disabled = true;
    if (submit) {
      submit.disabled = true;
      submit.classList.remove("is-ready");
      submit.setAttribute("aria-label", "CHAIR отвечает…");
    }
    ensureDiscussionKnowledgeNotes()
      .then(ensureDiscussChat)
      .then(function () {
        return apiFetch(path, {
          method: "POST",
          body: JSON.stringify(
            Object.assign(
              {
                reply: body,
                parent_id: rootId,
                reply_to_id: replyToId,
                quote: (draft && draft.quote) || "",
                model: selectedPaieModelId(),
              },
              discussionKnowledgeFields(),
              discussChatFields()
            )
          ),
        });
      })
      .then(function (data) {
        if (input) input.value = "";
        clearNoteComposerCommentTarget();
        clearDiscussPendingContextNotes();
        refreshNoteCommentsList();
        var status = (data && data.status) || "running";
        var live = document.getElementById("note-editor-more-wrap");
        var sameNote = !!(live && String(live._shareId) === String(itemId));
        if (status === "done") {
          if (sameNote) {
            live._paeiRunning = false;
            setNotePaeiStatus("");
          }
          notifyAgentReplyArrived(kind, itemId, "paie", sessionTitle);
          return;
        }
        if (status === "error") {
          if (sameNote) {
            live._paeiRunning = false;
            setNotePaeiStatus((data && data.error) || "Не удалось отправить уточнение");
          } else {
            showNoteToast((data && data.error) || "Не удалось отправить уточнение");
          }
          endNoteAgentSession(kind, itemId);
          return;
        }
        if (sameNote && data && data.progress) {
          setNotePaeiStatus(data.progress.label, data.progress);
        }
        pollNotePaei(path);
      })
      .catch(function (e) {
        var live = document.getElementById("note-editor-more-wrap");
        if (live && String(live._shareId) === String(itemId)) {
          live._paeiRunning = false;
          setNotePaeiStatus(e.message || "Не удалось отправить уточнение");
          renderNotePaieThread(
            (panel && panel._allComments) || (panel && panel._paieComments) || [],
            kind,
            itemId
          );
        } else {
          showNoteToast(e.message || "Не удалось отправить уточнение");
        }
        endNoteAgentSession(kind, itemId);
      })
      .finally(function () {
        syncNotePaieReplyForm();
      });
  }

